#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} NFAPI_CRC_ARRAY_T;

NFAPI_CRC_ARRAY_T* create_nfa_crc_array() {
    NFAPI_CRC_ARRAY_T* array = (NFAPI_CRC_ARRAY_T*)malloc(sizeof(NFAPI_CRC_ARRAY_T));
    if (!array) return NULL;
    array->data = NULL;
    array->size = 0;
    array->capacity = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void destroy_nfa_crc_array(NFAPI_CRC_ARRAY_T* array) {
    if (array) {
        pthread_mutex_lock(&array->mutex);
        free(array->data);
        pthread_mutex_unlock(&array->mutex);
        pthread_mutex_destroy(&array->mutex);
        free(array);
    }
}

int add_to_nfa_crc_array(NFAPI_CRC_ARRAY_T* array, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity == 0 ? 16 : array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&array->mutex);
            return -1; // Memory allocation failed
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }
    array->data[array->size++] = item;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int update_nfa_crc_array(NFAPI_CRC_ARRAY_T* array, uint32_t tag, NFAPI_CRC_INDICATION_PDU_T new_item) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].RX_UE_INFORMATION_TAG == tag) {
            array->data[i] = new_item;
            pthread_mutex_unlock(&array->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&array->mutex);
    return -1; // Tag not found
}

int main() {
    NFAPI_CRC_ARRAY_T* crc_array = create_nfa_crc_array();
    if (!crc_array) {
        fprintf(stderr, "Failed to create NFAPI CRC array\n");
        return 1;
    }

    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T item = {0};
    for (size_t i = 0; i < 20; ++i) {
        item.RX_UE_INFORMATION_TAG = rand() % 1000;
        item.RNTI = rand() % 65536;
        item.CRCFLAG = rand() % 2;
        if (add_to_nfa_crc_array(crc_array, item) != 0) {
            fprintf(stderr, "Failed to add item to NFAPI CRC array\n");
            destroy_nfa_crc_array(crc_array);
            return 1;
        }
    }

    // Example update
    item.RX_UE_INFORMATION_TAG = 500;
    if (update_nfa_crc_array(crc_array, 500, item) != 0) {
        fprintf(stderr, "Failed to update item in NFAPI CRC array\n");
    }

    destroy_nfa_crc_array(crc_array);
    return 0;
}
