#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int value;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record *records;
    size_t capacity;
    size_t count;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *array = (DynamicArray *)malloc(sizeof(DynamicArray));
    if (!array) {
        fprintf(stderr, "Memory allocation failed for DynamicArray\n");
        return NULL;
    }

    array->offsets = (long *)calloc(initial_capacity, sizeof(long));
    array->keys = (int *)calloc(initial_capacity, sizeof(int));
    array->records = (Record *)malloc(initial_capacity * sizeof(Record));
    if (!array->offsets || !array->keys || !array->records) {
        fprintf(stderr, "Memory allocation failed for arrays\n");
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->count = 0;

    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    if (array->offsets) free(array->offsets);
    if (array->keys) free(array->keys);
    if (array->records) free(array->records);
    free(array);
}

int add_record(DynamicArray *array, int key, Record record) {
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        long *new_offsets = (long *)realloc(array->offsets, new_capacity * sizeof(long));
        int *new_keys = (int *)realloc(array->keys, new_capacity * sizeof(int));
        Record *new_records = (Record *)realloc(array->records, new_capacity * sizeof(Record));

        if (!new_offsets || !new_keys || !new_records) {
            fprintf(stderr, "Memory reallocation failed for arrays\n");
            return -1;
        }

        array->offsets = new_offsets;
        array->keys = new_keys;
        array->records = new_records;
        array->capacity = new_capacity;
    }

    array->offsets[array->count] = (long)array->records + (array->count * sizeof(Record));
    array->keys[array->count] = key;
    array->records[array->count++] = record;

    return 0;
}

Record* get_record_by_index(DynamicArray *array, size_t index) {
    if (index >= array->count) {
        fprintf(stderr, "Index out of bounds\n");
        return NULL;
    }
    return &array->records[index];
}

Record* get_record_by_key(DynamicArray *array, int key) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->keys[i] == key) {
            return &array->records[i];
        }
    }
    fprintf(stderr, "Key not found\n");
    return NULL;
}
