#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>

#define MAX_LOG_LINE_LENGTH 1024
#define DNS_CACHE_SIZE 100

typedef struct {
    char hostname[256];
    char ip_address[16];
} DnsCacheEntry;

DnsCacheEntry dns_cache[DNS_CACHE_SIZE];
int dns_cache_count = 0;

char* resolve_hostname(const char* hostname) {
    for (int i = 0; i < dns_cache_count; i++) {
        if (strcmp(dns_cache[i].hostname, hostname) == 0) {
            return dns_cache[i].ip_address;
        }
    }

    struct addrinfo hints, *res, *p;
    int status;
    char ipstr[INET6_ADDRSTRLEN];

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        char *ipver;

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
            ipver = "IPv4";
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
            ipver = "IPv6";
        }

        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        printf("  %s: %s\n", ipver, ipstr);

        strcpy(dns_cache[dns_cache_count].hostname, hostname);
        strcpy(dns_cache[dns_cache_count].ip_address, ipstr);
        dns_cache_count++;
        if (dns_cache_count >= DNS_CACHE_SIZE) {
            dns_cache_count = 0;
        }
        break; // only use the first one
    }

    freeaddrinfo(res); // free the linked list

    return ipstr;
}

void process_log_entry(const char* log_line, FILE* output_file) {
    char buffer[MAX_LOG_LINE_LENGTH];
    strcpy(buffer, log_line);

    char* token = strtok(buffer, " ");
    int field_count = 0;
    double total = 0;

    while (token != NULL) {
        if (field_count >= 2 && isdigit(token[0])) {
            total += atof(token);
        }
        field_count++;
        token = strtok(NULL, " ");
    }

    if (field_count >= 3) {
        double average = total / (field_count - 2);
        fprintf(output_file, "%s Average: %.2f\n", log_line, average);
    } else {
        fprintf(output_file, "%s\n", log_line);
    }
}

int main() {
    FILE* output_file = fopen("summary_report.txt", "w");
    if (output_file == NULL) {
        perror("Error opening summary_report.txt");
        return EXIT_FAILURE;
    }

    // Simulate reading log entries from multiple sources
    const char* log_entries[] = {
        "192.168.1.1 2023-04-01 12:00:00 INFO Connection successful",
        "google.com 2023-04-01 12:05:00 ERROR Connection failed",
        "example.com 2023-04-01 12:10:00 INFO Received data 1234 5678"
    };

    for (int i = 0; i < 3; i++) {
        char* log_line = (char*)malloc(strlen(log_entries[i]) + 1);
        if (log_line == NULL) {
            perror("Memory allocation failed");
            fclose(output_file);
            return EXIT_FAILURE;
        }
        strcpy(log_line, log_entries[i]);

        // Resolve hostname and process log entry
        char* ip_address = resolve_hostname(strtok(log_line, " "));
        if (ip_address != NULL) {
            fprintf(output_file, "IP Address: %s ", ip_address);
        }

        process_log_entry(log_line, output_file);

        free(log_line); // Free dynamically allocated memory for log entry
    }

    fclose(output_file);
    return EXIT_SUCCESS;
}
