#include <stdio.h>
#include <stdlib.h>

#define MAX_INPUT_SIZE 1024

void print_progress(int processed, int total) {
    printf("Processed %d out of %d\r", processed, total);
}

int find_max(long *array, int size) {
    long max = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

double calculate_average(long *array, int size) {
    double sum = 0.0;
    for (int i = 0; i < size; i++) {
        sum += array[i];
    }
    return sum / size;
}

int read_and_analyze_file(const char *filename, long **result_array, int max_size) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return -1;
    }

    *result_array = (long *)malloc(max_size * sizeof(long));
    if (!*result_array) {
        perror("Memory allocation failed");
        fclose(file);
        return -1;
    }

    int size = 0;
    long value;
    while (fscanf(file, "%ld", &value) == 1 && size < max_size) {
        (*result_array)[size++] = value;
        print_progress(size, max_size);
    }

    if (ferror(file)) {
        perror("Error reading file");
        free(*result_array);
        fclose(file);
        return -1;
    }

    fclose(file);

    long max_value = find_max(*result_array, size);
    double average_value = calculate_average(*result_array, size);

    printf("\nMax Value: %ld\nAverage Value: %.2f\n", max_value, average_value);

    return 0;
}

int main() {
    const char *filename = "input.txt";
    long *array;
    int result = read_and_analyze_file(filename, &array, MAX_INPUT_SIZE);
    if (result == 0) {
        free(array);
    }
    return result;
}
