#include <stdio.h>
#include <stdarg.h>
#include <time.h>
#include <pthread.h>

#define LOG_DEBUG 1
#define LOG_INFO 2
#define LOG_WARNING 3
#define LOG_ERROR 4

typedef struct {
    int threshold;
    FILE *log_file;
    pthread_mutex_t mutex;
} Logger;

Logger logger;

void init_logger(int threshold, const char *log_file_path) {
    logger.threshold = threshold;
    logger.log_file = fopen(log_file_path, "a");
    if (logger.log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&logger.mutex, NULL);
}

void log_message(int severity, const char *format, ...) {
    va_list args;
    va_start(args, format);

    pthread_mutex_lock(&logger.mutex);

    if (severity >= logger.threshold) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        fprintf(logger.log_file, "[%d-%02d-%02d %02d:%02d:%02d] ", 
                tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec);

        switch (severity) {
            case LOG_DEBUG:
                fprintf(logger.log_file, "DEBUG: ");
                break;
            case LOG_INFO:
                fprintf(logger.log_file, "INFO: ");
                break;
            case LOG_WARNING:
                fprintf(logger.log_file, "WARNING: ");
                break;
            case LOG_ERROR:
                fprintf(logger.log_file, "ERROR: ");
                break;
        }

        vfprintf(logger.log_file, format, args);
        fprintf(logger.log_file, "\n");
    }

    pthread_mutex_unlock(&logger.mutex);

    va_end(args);
}

void close_logger() {
    fclose(logger.log_file);
    pthread_mutex_destroy(&logger.mutex);
}
```

This code provides a basic implementation of a logging system in C with support for multiple severity levels and configurable thresholds. It uses variable argument lists to handle different log formats and employs threading synchronization to ensure thread safety. The system logs messages to a specified file and includes timestamps, making it suitable for both local and remote storage and retrieval.']

