            ["ssh", device_info["username"], "@" + device_info["ip"], "-o", "StrictHostKeyChecking=no", "cat > /etc/network/config && reboot"],
            input=open(config_file).read(),
            check=True
        )
    except subprocess.CalledProcessError as e:
        logging.error(f"Failed to apply config on {device_info['ip']}: {e}")
        raise Exception(f"Failed to apply configuration on {device_info['ip']}")

def rollback_config(device_info):
    try:
        subprocess.run(
            ["ssh", device_info["username"], "@" + device_info["ip"], "-o", "StrictHostKeyChecking=no", "rm /etc/network/config && reboot"],
            check=True
        )
    except subprocess.CalledProcessError as e:
        logging.error(f"Failed to rollback config on {device_info['ip']}: {e}")
        raise Exception(f"Failed to rollback configuration on {device_info['ip']}")

