public class PokemonCompatibilityReportGenerator {

    public String generateCompatibilityReport(String pokemonId) {
        try {
            // Type Determination
            List<String> types = getPokemonTypes(pokemonId);
            if (types.isEmpty()) {
                throw new RuntimeException("No type information found for the Pokemon.");
            }

            String primaryType = types.get(0);
            String secondaryType = types.size() > 1 ? types.get(1) : null;

            // Name Retrieval
            String name = getPokemonName(pokemonId);
            if (name == null || name.isEmpty()) {
