#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_SEMAPHORES 200

typedef struct {
    sem_t *semaphores[MAX_SEMAPHORES];
    int semaphore_count;
} SemaphoreManager;

SemaphoreManager *create_semaphore_manager() {
    SemaphoreManager *manager = (SemaphoreManager *)malloc(sizeof(SemaphoreManager));
    manager->semaphore_count = 0;
    return manager;
}

void destroy_semaphore_manager(SemaphoreManager *manager) {
    for (int i = 0; i < manager->semaphore_count; i++) {
        sem_destroy(manager->semaphores[i]);
        free(manager->semaphores[i]);
    }
    free(manager);
}

sem_t *create_semaphore(int value, SemaphoreManager *manager) {
    if (manager->semaphore_count >= MAX_SEMAPHORES) {
        printf("Semaphore limit reached\n");
        return NULL;
    }
    sem_t *sem = (sem_t *)malloc(sizeof(sem_t));
    if (sem_init(sem, 0, value) == -1) {
        perror("Failed to initialize semaphore");
        free(sem);
        return NULL;
    }
    manager->semaphores[manager->semaphore_count++] = sem;
    return sem;
}

void destroy_semaphore(sem_t *sem, SemaphoreManager *manager) {
    for (int i = 0; i < manager->semaphore_count; i++) {
        if (manager->semaphores[i] == sem) {
            sem_destroy(manager->semaphores[i]);
            free(manager->semaphores[i]);
            manager->semaphores[i] = manager->semaphores[--manager->semaphore_count];
            break;
        }
    }
}

int get_semaphore_value(sem_t *sem) {
    int value;
    sem_getvalue(sem, &value);
    return value;
}

void semaphore_operation(sem_t *sem, int operation_type) {
    if (operation_type == 1) {
        sem_wait(sem); // Wait
    } else {
        sem_post(sem); // Signal
    }
}

void handle_semaphore_timeout(sem_t *sem, time_t timeout) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += timeout;
    if (sem_timedwait(sem, &ts) == -1 && errno == ETIMEDOUT) {
        printf("Semaphore operation timed out\n");
    }
}

int main() {
    SemaphoreManager *manager = create_semaphore_manager();
    sem_t *sem = create_semaphore(2, manager);

    semaphore_operation(sem, 1); // Wait
    handle_semaphore_timeout(sem, 5); // Handle timeout with 5 seconds

    printf("Semaphore value: %d\n", get_semaphore_value(sem));

    destroy_semaphore(sem, manager);
    destroy_semaphore_manager(manager);
    return 0;
}
```

This code provides a basic framework for managing semaphores in C. It includes functions to create and destroy semaphore managers, create and destroy semaphores, retrieve semaphore values, perform semaphore operations (wait and signal), and handle timeouts gracefully. The `handle_semaphore_timeout` function demonstrates how to manage timeout scenarios using `sem_timedwait`.']

