#include <vector>
#include <mutex>
#include <queue>
#include <chrono>

class LRUVector {
private:
    std::vector<int> vec;
    std::mutex mtx;
    std::queue<int> lruQueue;
    int maxSize;

public:
    LRUVector(int max_size) : maxSize(max_size) {}

    void insert_or_append(int value, int target) {
        std::lock_guard<std::mutex> lock(mtx);

        if (std::find(vec.begin(), vec.end(), target) != vec.end()) {
            // Insert after the first occurrence of the target
            auto pos = std::find(vec.begin(), vec.end(), target);
            vec.insert(pos + 1, value);
        } else {
            // Append to the end
            vec.push_back(value);
        }

        if (vec.size() > maxSize) {
            // Remove LRU element
            int lruValue = lruQueue.front();
            lruQueue.pop();
            auto pos = std::find(vec.begin(), vec.end(), lruValue);
            if (pos != vec.end()) {
                vec.erase(pos);
            }
        }

        // Simulate real-time performance constraint
        auto start = std::chrono::high_resolution_clock::now();
        while ((std::chrono::high_resolution_clock::now() - start) < std::chrono::milliseconds(10)) {}
    }

    int size() const {
        return vec.size();
    }
};
