namespace RandomService {

class Instance {
public:
    explicit Instance(uint32_t seed) : generator(seed), distribution() {}

    int32_t getRandomInt(int32_t min, int32_t max) {
        if (min > max) throw std::invalid_argument("Invalid range");
        return distribution(generator);
    }

    double getRandomDouble(double min, double max) {
        if (min > max) throw std::invalid_argument("Invalid range");
        return distribution(generator);
    }

private:
    std::mt19937 generator;
    std::uniform_int_distribution<int32_t> distribution;
};

class Service {
public:
    void addInstance(uint32_t seed) {
        instances.push_back(std::make_unique<Instance>(seed));
    }

    int32_t getRandomInt(int32_t min, int32_t max) {
        if (min > max) throw std::invalid_argument("Invalid range");
        std::lock_guard<std::mutex> lock(mutex);
        return instances.back()->getRandomInt(min, max);
    }

    double getRandomDouble(double min, double max) {
        if (min > max) throw std::invalid_argument("Invalid range");
        std::lock_guard<std::mutex> lock(mutex);
        return instances.back()->getRandomDouble(min, max);
    }

private:
    std::vector<std::unique_ptr<Instance>> instances;
    std::mutex mutex;
};

} // namespace RandomService

int main() {
    RandomService::Service service;
    service.addInstance(42);

    for (int i = 0; i < 10; ++i) {
        std::cout << "Random Int: " << service.getRandomInt(1, 100) << std::endl;
        std::cout << "Random Double: " << service.getRandomDouble(0.0, 1.0) << std::endl;
    }

    return 0;
}
