using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Diagnostics;

public class BatchSqlInsertOptimizer
{
    public static (int SuccessfulOperations, int FailedOperations, double AverageTimePerOperation) OptimizeBatchInserts<T>(List<T> rows, SqlConnection connection, string tableName)
    {
        var successfulOps = 0;
        var failedOps = 0;
        var stopwatch = Stopwatch.StartNew();

        using (var transaction = connection.BeginTransaction())
        {
            try
            {
                foreach (var row in rows)
                {
                    var sqlParams = GetSqlParameters(row);
                    InsertRow(connection, transaction, tableName, sqlParams);
                    successfulOps++;
                }

                transaction.Commit();
            }
            catch (Exception ex)
            {
                failedOps++;
                // Log the exception details
                Console.WriteLine($"Failed to insert row: {ex.Message}");
            }
            finally
            {
                stopwatch.Stop();
            }
        }

        var averageTimePerOperation = successfulOps > 0 ? stopwatch.Elapsed.TotalMilliseconds / successfulOps : 0;
        return (successfulOps, failedOps, averageTimePerOperation);
    }

    private static SqlParameter[] GetSqlParameters<T>(T row)
    {
        // Implement logic to create and return SQL parameters based on the row object
        throw new NotImplementedException();
    }

    private static void InsertRow(SqlConnection connection, SqlTransaction transaction, string tableName, SqlParameter[] sqlParams)
    {
        using (var command = new SqlCommand($"INSERT INTO {tableName} VALUES (@p1, @p2, @p3)", connection, transaction))
        {
            command.Parameters.AddRange(sqlParams);
            command.ExecuteNonQuery();
        }
    }
}
```

