using Microsoft.AspNetCore.Mvc;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

[ApiController]
[Route("api/resources")]
public class ResourceController : ControllerBase
{
    private readonly ApplicationDbContext _context;

    public ResourceController(ApplicationDbContext context)
    {
        _context = context;
    }

    [HttpPut("{id}")]
    public async Task<IActionResult> UpdateResource(int id, [FromBody] Resource resource)
    {
        if (!ModelState.IsValid)
        {
            return BadRequest(ModelState);
        }

        var existingResource = await _context.Resources.FindAsync(id);

        if (existingResource == null)
        {
            return NotFound();
        }

        // Validate resource data against schema
        if (!IsValidResource(resource))
        {
            return BadRequest("Invalid resource data");
        }

        // Update resource with concurrency control
        try
        {
            existingResource.Name = resource.Name;
            existingResource.Description = resource.Description;
            _context.Entry(existingResource).State = EntityState.Modified;
            await _context.SaveChangesAsync();
        }
        catch (DbUpdateConcurrencyException)
        {
            if (!ResourceExists(id))
            {
                return NotFound();
            }
            else
            {
                throw;
            }
        }

        // Send notification to external service
        await NotifyResourceUpdate(existingResource);

        // Log update operation
        LogOperation("Update", existingResource);

        return Ok(existingResource);
    }

    [HttpDelete("{id}")]
    public async Task<IActionResult> DeleteResource(int id)
    {
        var resource = await _context.Resources.FindAsync(id);
        if (resource == null)
        {
            return NotFound();
        }

        // Archive resource
        _context.ArchiveResources.Add(new ArchiveResource { ResourceId = id, UpdateTime = DateTime.UtcNow });
        await _context.SaveChangesAsync();

        // Send notification to external service
