using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Xml.XPath;

public class DirectoryManager
{
    private string applicationRootPath;

    public DirectoryManager(string rootPath)
    {
        applicationRootPath = rootPath;
    }

    public object ParseXmlAndGetElement(XPathDocument xmlDoc, string elementName)
    {
        var nodes = xmlDoc.CreateNavigator().Select("//" + elementName);
        if (nodes.Count() == 0)
        {
            LogWarning("No elements found with the specified name.");
            return null;
        }
        else if (nodes.Count() > 1)
        {
            LogNotice($"Multiple elements found with the specified name. Returning all elements.");
            var nodeList = new List<XPathNavigator>();
            foreach (var node in nodes)
            {
                nodeList.Add(node);
            }
            return nodeList;
        }
        else
        {
            return nodes.Current;
        }
    }

    public string CreateUniqueDirectory()
    {
        string directoryName = GetTimestamp();
        string uniquePath = Path.Combine(applicationRootPath, directoryName);

        while (Directory.Exists(uniquePath))
        {
            directoryName = GetTimestamp() + "_" + Guid.NewGuid().ToString("N").Substring(0, 5);
            uniquePath = Path.Combine(applicationRootPath, directoryName);
        }

        Directory.CreateDirectory(uniquePath);
        LogInfo($"Directory created: {uniquePath}");

        AdjustPermissions(uniquePath);

        UpdateConfigFile(uniquePath);

        return uniquePath;
    }

    private string GetTimestamp()
    {
        return DateTime.Now.ToString("yyyyMMddHHmmssfff");
    }

    private void LogWarning(string message)
    {
        Console.WriteLine($"WARNING: {message}");
    }

    private void LogNotice(string message)
    {
        Console.WriteLine($"NOTICE: {message}");
    }

    private void LogInfo(string message)
    {
        Console.WriteLine($"INFO: {message}");
    }

    private void AdjustPermissions(string directoryPath)
    {
        try
        {
            var security = Directory.GetAccessControl(directoryPath);
            var currentIdentity = System.Security.Principal.WindowsIdentity.GetCurrent();
            var principal = new System.Security.Principal.WindowsPrincipal(currentIdentity);

            if (!security.AreAccessRulesProtected && !principal.IsInRole(System.Security.Principal.WindowsBuiltInRole.Administrator))
            {
                security.ModifyAccessRule(new FileSystemAccessRule(
                    currentIdentity,
                    FileSystemRights.ReadWrite,
                    InheritanceFlags.ObjectInherit | InheritanceFlags.ContainerInherit,
                    PropagationFlags.None,
                    AccessControlType.Allow
                ));
                Directory.SetAccessControl(directoryPath, security);
            }
        }
        catch (Exception ex)
        {
            LogWarning($"Failed to adjust permissions: {ex.Message}");
        }
    }

    private void UpdateConfigFile(string directoryPath)
    {
        try
        {
            string configFilePath = Path.Combine(applicationRootPath, "config.xml");
            XmlDocument configXml = new XmlDocument();
            if (File.Exists(configFilePath))
            {
                configXml.Load(configFilePath);
            }
            else
            {
                configXml.AppendChild(configXml.CreateElement("Configuration"));
            }

            XmlElement dirElement = configXml.DocumentElement.SelectSingleNode("//Directories") as XmlElement;
            if (dirElement == null)
            {
                dirElement = configXml.CreateElement("Directories");
                configXml.DocumentElement.AppendChild(dirElement);
            }

            XmlElement newDirElement = configXml.CreateElement("Directory");
            newDirElement.SetAttribute("Path", directoryPath);
            dirElement.AppendChild(newDirElement);

            configXml.Save(configFilePath);
            LogInfo($"Configuration file updated with new directory path: {directoryPath}");
        }
        catch (Exception ex)
        {
            LogWarning($"Failed to update configuration file: {ex.Message}");
        }
    }
}
