            if (isset($_REQUEST['sub_action']) && $_REQUEST['sub_action'] === 'delete') {
                return $this->deleteUser($_REQUEST);
            } elseif (isset($_REQUEST['id'])) {
                if ($user = $this->getUser($_REQUEST)) {
                    return $this->updateUser($user, $_REQUEST);
                }
            } else {
                return $this->createUser($_REQUEST);
            }
        } catch (Exception $e) {
            $this->logger->error('Error managing user account: ' . $e->getMessage());
            return json_encode(['message' => 'error', 'data' => null]);
        }
