    private function deleteUser($_REQUEST) {
        if ($this->Validate($_REQUEST)) {
            $sql = "DELETE FROM users WHERE id = :id";
            $stmt = $this->db->prepare($sql);
            $stmt->execute(['id' => $_REQUEST['id']]);
            return json_encode(['message' => 'success', 'data' => null]);
        }
    }

    private function getUser($_REQUEST) {
        $sql = "SELECT * FROM users WHERE id = :id";
        $stmt = $this->db->prepare($sql);
        $stmt->execute(['id' => $_REQUEST['id']]);
        return $stmt->fetch();
    }

    private function updateUser($user, $_REQUEST) {
        if ($this->Validate($_REQUEST)) {
