            $stmt->execute(['id' => $_REQUEST['id'], 'name' => $_REQUEST['name'], 'email' => $_REQUEST['email'], 'password' => $_REQUEST['password']]);
            return json_encode(['message' => 'success', 'data' => $user]);
        }
