    [HttpPost("update")]
    public async Task<IActionResult> UpdateElement(
        string sectionId,
        string elementId,
        string newHtmlContent,
        string userId
    )
    {
        // Validate input parameters
        if (string.IsNullOrEmpty(sectionId) || !IsValidSectionId(sectionId))
            return BadRequest("Invalid section ID");

        if (string.IsNullOrEmpty(elementId) || !IsValidElementId(elementId))
            return BadRequest("Invalid element ID");

        if (string.IsNullOrEmpty(newHtmlContent))
            return BadRequest("New HTML content cannot be empty");

        // Implement rate limiting
        if (!await TryRateLimit(userId))
            return StatusCode(429, "Too Many Requests");

        // Sanitize updated HTML content
        newHtmlContent = SanitizeHtml(newHtmlContent);

        try
        {
            // Log the request for auditing purposes
            _logger.LogInformation("UpdateElement called by {UserId} on section {SectionId}, element {ElementId}", userId, sectionId, elementId);

            // Perform partial update to minimize server load and improve responsiveness
            var updatedContent = await UpdateElementAsync(sectionId, elementId, newHtmlContent);

            // Integrate with a notification service to inform dependent systems of changes
            await NotifyDependentSystems(sectionId, elementId);

            return Ok(updatedContent);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to update element");
            return StatusCode(500, "Internal Server Error");
        }
    }

    private async Task<string> UpdateElementAsync(string sectionId, string elementId, string newHtmlContent)
    {
        // Simulate updating the HTML content
        // Replace with actual implementation using a database or similar storage mechanism
        await Task.Delay(100); // Simulate I/O delay

        return $"<div id='{elementId}' class='section-{sectionId}'>{newHtmlContent}</div>";
    }

    private async Task NotifyDependentSystems(string sectionId, string elementId)
    {
        // Simulate notifying dependent systems
        // Replace with actual implementation using a message queue or similar service
        await Task.Delay(50); // Simulate I/O delay
    }

    private bool IsValidSectionId(string sectionId)
    {
        // Implement validation logic for section ID format
        return Regex.IsMatch(sectionId, @"^[a-zA-Z0-9]{3,20}$");
    }

    private bool IsValidElementId(string elementId)
    {
        // Implement validation logic for element ID format
        return Regex.IsMatch(elementId, @"^[a-zA-Z0-9]{3,20}$");
    }

    private string SanitizeHtml(string htmlContent)
    {
        // Implement HTML sanitization logic to ensure consistent and safe rendering
        // Replace with a library like HtmlSanitizer or similar
        var sanitizedContent = HttpUtility.HtmlEncode(htmlContent);
        return Regex.Replace(sanitizedContent, "<script.*?>.*?</script>", string.Empty, RegexOptions.IgnoreCase | RegexOptions.Singleline);
    }

    private async Task<bool> TryRateLimit(string userId)
    {
        if (RequestRateLimits.TryGetValue(userId, out DateTime lastRequestTime) && DateTime.UtcNow - lastRequestTime < TimeSpan.FromSeconds(RateLimitIntervalSeconds))
            return false;

        RequestRateLimits[userId] = DateTime.UtcNow;
        return true;
    }
}
