// Import necessary modules
const fs = require('fs').promises;
const path = require('path');
const Ajv = require('ajv');

// Define the module structure
module.exports = {
  processDirectory: async (directoryPath, schemaPath, maxSizeThreshold, maxRetries, prioritizeSpeed) => {
    const ajv = new Ajv({ allErrors: true });
    let validator = null;

    try {
      // Load and compile the JSON schema
      const schemaContent = await fs.readFile(schemaPath, 'utf8');
      validator = ajv.compile(JSON.parse(schemaContent));

      // Initialize variables for error handling and retry logic
      const errors = [];
      const retries = new Map();

      // Function to read a file with retries
      const readFileWithRetry = async (filePath) => {
        let attempt = 0;
        while (attempt < maxRetries) {
          try {
            return await fs.readFile(filePath, 'utf8');
          } catch (error) {
            if (++attempt === maxRetries) throw error;
          }
        }
      };

      // Process each file concurrently
      const files = await fs.readdir(directoryPath);
      for (const file of files) {
        const filePath = path.join(directoryPath, file);
        try {
          const content = await readFileWithRetry(filePath);

          // Check file size
          if (content.length > maxSizeThreshold) {
            console.warn(`File ${file} exceeds the size threshold.`);
          }

          // Validate file content
          if (!validator(content)) {
            errors.push({ filePath, errors: validator.errors });
          } else {
            // Process the file based on priority
            if (prioritizeSpeed) {
              await processFileFast(content);
            } else {
              await processFileAccurately(content);
            }
          }
        } catch (error) {
          console.error(`Error processing ${file}:`, error);
        }
      }

      // Log errors and return results
      logErrors(errors);
      return { totalFiles: files.length, processedFiles: files.length - errors.length };
    } catch (error) {
      console.error('Failed to process directory:', error);
      throw error;
    }
  }
};

