function runTests(label, f, testCases = []) {
    const initialBlueslipState = JSON.stringify(blueslip);

    function sandboxedTest(testFunction) {
        return () => {
            const start = Date.now();
            blueslip.reset(); // Reset blueslip to initial state for each test
            testFunction();
            const duration = Date.now() - start;
            console.log(`${label}: ${testFunction.name} took ${duration}ms`);
        };
    }

    async function runConcurrently(tests) {
        const promises = tests.map(sandboxedTest).map((test) => new Promise(resolve => {
            setTimeout(() => resolve(test()), 0); // Run concurrently
        }));
        await Promise.all(promises);
    }

    try {
        console.log(`Starting ${label} tests`);
        sandboxedTest(f)();
        await runConcurrently(testCases.map(t => t.f));
    } catch (error) {
        console.error(`${label}: Test failed`, error);
    } finally {
        blueslip.restore(JSON.parse(initialBlueslipState)); // Restore blueslip after all tests
        console.log(`Finished ${label} tests`);
    }
}
