function appendScriptsToFooter(scripts) {
    const scriptElements = [];
    const scriptMap = new Map();
    let htmlString = '';

    // Create or get the footer element
    let footerElement = document.querySelector('footer');
    if (!footerElement) {
        footerElement = document.createElement('footer');
        document.body.appendChild(footerElement);
    }

    // Preprocess scripts to create a map and script elements
    scripts.forEach(script => {
        const id = `script-${Math.random().toString(36).substr(2, 9)}`;
        script.id = id;
        scriptElements.push(`<script id="${id}">${script.source}</script>`);
        scriptMap.set(id, script);
    });

    // Helper function to check if a script can be executed
    const canExecuteScript = (scriptId) => {
        const script = scriptMap.get(scriptId);
        return !script.dependencies.some(dep => !document.getElementById(`${dep}-executed`));
    };

    // Append scripts in the correct order
    while (scriptElements.length > 0) {
        for (let i = 0; i < scriptElements.length; i++) {
            const element = scriptElements[i];
            const idMatch = element.match(/id="([^"]+)"/);
            if (idMatch && canExecuteScript(idMatch[1])) {
                footerElement.insertAdjacentHTML('beforeend', element);
                document.getElementById(`${idMatch[1]}-executed`).checked = true;
                scriptElements.splice(i, 1);
                i--;
            }
        }

        // If no scripts can be executed and there are still elements, it's a circular dependency
        if (scriptElements.length > 0) {
            throw new Error('Circular dependency detected');
        }
    }

    // Convert footer element to HTML string
    const tempDiv = document.createElement('div');
    tempDiv.appendChild(footerElement.cloneNode(true));
    htmlString = tempDiv.innerHTML;

    return htmlString;
}
