["```javascript
class DOMTraverser {
    constructor(maxDepth = 10, maxCacheSize = 100) {
        this.maxDepth = maxDepth;
        this.maxCacheSize = maxCacheSize;
        this.cache = new Map();
    }

    traverse(node, selector, options = {}, depth = 0) {
        if (!node || depth > this.maxDepth) return [];

        const { tagName, classSelector, limit } = options;
        let results = [];
        let cacheKey = `${selector}-${depth}`;

        // Check cache
        if (this.cache.has(cacheKey)) {
            return this.cache.get(cacheKey);
        }

        // Traverse child nodes
        node.childNodes.forEach(child => {
            const matchesTag = !tagName || child.tagName === tagName;
            const matchesClass = !classSelector || child.classList.contains(classSelector);

            if (matchesTag && matchesClass) {
                results.push(child);
                if (results.length >= limit) return; // Stop early if limit reached
            }

            if (child.children.length > 0) {
                results = results.concat(this.traverse(child, selector, options, depth + 1));
                if (results.length >= limit) return; // Stop early if limit reached
            }
        });

        // Cache the result for future use
        if (this.cache.size >= this.maxCacheSize) {
            this.cache.delete(this.cache.keys().next().value); // Remove oldest entry
        }
        this.cache.set(cacheKey, results);

        return results;
    }

    clearCache() {
        this.cache.clear();
    }
}

// Example usage:
const traverser = new DOMTraverser(5, 50);
const elements = traverser.traverse(document.body, 'div', { classSelector: 'example', limit: 10 });
console.log(elements);
