function isValidFilename(filename) {
  const regex = /\d+/; // Regex to check for at least one numeric sequence
  return regex.test(filename);
}

// Function to generate C code based on filename
function generateCCode(filename) {
  if (!isValidFilename(filename)) {
    throw new Error('Invalid filename: No numeric sequence found.');
  }

  const match = filename.match(/\d+/); // Extract the numeric sequence
  const extension = match[0];
  const fileType = '.txt'; // Specify the file type

  return `
  #include <stdio.h>

  void modifyFilename() {
    char newFilename[] = "${filename.slice(0, -extension.length)}${fileType}";
    printf("New filename: %s\\n", newFilename);
  }
  `;
}

// Function to load and execute the C code
