import java.util.concurrent.*;
import java.util.*;

class ConnectionManager {
    private final ExecutorService executorService;
    private final ConcurrentMap<String, Future<?>> activeConnections;
    private final ScheduledExecutorService monitorService;

    public ConnectionManager(int maxThreads) {
        this.executorService = Executors.newFixedThreadPool(maxThreads);
        this.activeConnections = new ConcurrentHashMap<>();
        this.monitorService = Executors.newSingleThreadScheduledExecutor();

        // Schedule periodic monitoring
        monitorService.scheduleAtFixedRate(this::monitorConnections, 10, 10, TimeUnit.SECONDS);
    }

    public void connect(String serviceUrl) {
        Future<?> future = executorService.submit(() -> {
            try {
                // Simulate connection logic
                System.out.println("Connecting to " + serviceUrl);
                Thread.sleep(2000); // Simulating delay
                System.out.println("Connected to " + serviceUrl);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });

        activeConnections.put(serviceUrl, future);
    }

    public void disconnect(String serviceUrl) {
        Future<?> future = activeConnections.get(serviceUrl);
        if (future != null) {
            future.cancel(true);
            activeConnections.remove(serviceUrl);
        }
    }

    private void monitorConnections() {
        // Logic to detect anomalies and adjust resources
        System.out.println("Monitoring connections...");
        int activeCount = activeConnections.size();
        if (activeCount > 50 && executorService instanceof ThreadPoolExecutor) {
            ThreadPoolExecutor poolExecutor = (ThreadPoolExecutor) executorService;
            int newPoolSize = Math.min(activeCount * 2, 100);
            poolExecutor.setCorePoolSize(newPoolSize);
            poolExecutor.setMaximumPoolSize(newPoolSize);
        }
    }

    public void shutdown() {
        executorService.shutdown();
        monitorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
            if (!monitorService.awaitTermination(60, TimeUnit.SECONDS)) {
                monitorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
            monitorService.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }

    public static void main(String[] args) {
        ConnectionManager manager = new ConnectionManager(50);

        for (int i = 1; i <= 120; i++) {
            String serviceUrl = "service" + i;
            manager.connect(serviceUrl);
        }

        // Simulate graceful degradation
        try {
            Thread.sleep(30000); // Simulating time passing
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        manager.shutdown();
    }
}
```

This code provides a basic structure for a connection manager in Java. It uses an `ExecutorService` to manage threads and a `ConcurrentMap` to keep track of active connections. The `monitorConnections` method is scheduled to periodically check the load and adjust the thread pool size if necessary. Note that this is a simplified example and does not include all the features mentioned, such as integrating with an external monitoring service or handling temporary failures gracefully.']

