    private final Map<String, Bitmap> cache;
    private static final float DEFAULT_MAX_MEMORY_PERCENTAGE = 0.3f;

    public ThemeBitmapCache() {
        this(Runtime.getRuntime().maxMemory(), (int) (Runtime.getRuntime().maxMemory() * DEFAULT_MAX_MEMORY_PERCENTAGE));
    }

    public ThemeBitmapCache(int maxMemory, int cacheSize) {
        this.maxMemory = maxMemory;
        this.cache = new LinkedHashMap<>(cacheSize, 0.75f, true);
    }

    public Bitmap get(String key) {
        return cache.get(key);
    }

    public void put(String key, Bitmap bitmap) {
        final int prevSize = calculateInMemorySize(bitmap);
        cache.put(key, bitmap);

        // Check LRU
        trimCache();
    }

    private void trimCache() {
        while (calculateInMemorySize() > maxMemory) {
            Map.Entry<String, Bitmap> toEvict = cache.entrySet().iterator().next();
            cache.remove(toEvict.getKey());
        }
    }

    private int calculateInMemorySize(Bitmap bitmap) {
        // Simplified calculation. Actual implementation may vary based on actual memory usage
        return bitmap.getByteCount();
    }
}
