import java.util.*;
import java.util.concurrent.*;

public class ServiceOrchestrationFramework {
    private static final int MAX_SERVICES = 500;
    private Map<Integer, Microservice> services;
    private ExecutorService executor;
    private BlockingQueue<Microservice> queue;

    public ServiceOrchestrationFramework() {
        services = new HashMap<>();
        executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        queue = new LinkedBlockingQueue<>();
    }

    public void addMicroservice(Microservice service) throws Exception {
        if (services.size() >= MAX_SERVICES) throw new Exception("Service limit reached");
        services.put(service.getId(), service);
        scheduleService(service);
    }

    private void scheduleService(Microservice service) {
        executor.submit(() -> {
            try {
                while (!Thread.currentThread().isInterrupted()) {
                    if (queue.isEmpty() || !queue.peek().isActive()) {
                        service.start();
                    } else {
                        Thread.sleep(100); // Check every 100ms
                    }
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });
    }

    public void startService(int id) throws Exception {
        Microservice service = services.get(id);
        if (service == null) throw new Exception("Service not found");
        queue.add(service);
        service.start();
    }

    public void stopService(int id) throws Exception {
        Microservice service = services.get(id);
        if (service == null) throw new Exception("Service not found");
        service.stop();
        queue.remove(service);
    }

    public static void main(String[] args) {
        ServiceOrchestrationFramework framework = new ServiceOrchestrationFramework();

        try {
            for (int i = 1; i <= MAX_SERVICES; i++) {
                framework.addMicroservice(new Microservice(i));
            }
        } catch (Exception e) {
            System.err.println(e.getMessage());
        }

        // Simulate service start and stop
        try {
            Thread.sleep(5000);
            framework.stopService(1);
            Thread.sleep(2000);
            framework.startService(1);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

class Microservice implements Runnable {
    private int id;
    private boolean active;

    public Microservice(int id) {
        this.id = id;
        this.active = false;
    }

    public int getId() {
        return id;
    }

    public boolean isActive() {
        return active;
    }

    @Override
    public void run() {
        while (!Thread.currentThread().isInterrupted()) {
            try {
                if (active) {
                    performService();
                }
                Thread.sleep(100); // Perform service every 100ms
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    public void start() throws Exception {
        // Start the microservice logic
        active = true;
        System.out.println("Service " + id + " started");
    }

    public void stop() throws Exception {
        // Stop the microservice logic
        active = false;
        System.out.println("Service " + id + " stopped");
    }

    private void performService() {
        // Perform service operations
        System.out.println("Service " + id + " performing operations");
    }
}
