<?php

// Set environment variables
function loadEnvironmentVariables($env) {
    $configFile = ".env.$env";
    if (file_exists($configFile)) {
        $lines = file($configFile, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES);
        foreach ($lines as $line) {
            list($key, $value) = explode('=', $line, 2);
            putenv("$key=$value");
        }
    }
}

// Load vendor autoloader
function loadVendorAutoloader() {
    if (file_exists('vendor/autoload.php')) {
        require 'vendor/autoload.php';
        spl_autoload_register();
    } else {
        die("Vendor autoload file not found.");
    }
}

// Configure application
function loadConfiguration($env) {
    $configFile = "config.$env.json";
    if (file_exists($configFile)) {
        return json_decode(file_get_contents($configFile), true);
    } elseif (file_exists("config.$env.yml")) {
        require 'vendor/autoload.php';
        $yaml = new \Symfony\Component\Yaml\Yaml();
        return $yaml->parseFile("config.$env.yml");
    }
    die("Configuration file not found.");
}

// Setup logging
function setupLogging($logDir) {
    if (!is_dir($logDir)) {
        mkdir($logDir, 0775, true);
    }
    $logFile = "$logDir/app.log";
    return new Monolog\Logger('app', [new Monolog\Handler\StreamHandler($logFile)]);
}

// Manage resource usage
function manageResourceUsage() {
    ini_set('memory_limit', '256M');
    register_shutdown_function(function() {
        if (memory_get_usage(true) > 200 * 1024 * 1024) {
            error_log("High memory usage detected: " . memory_get_usage(true));
        }
    });
}

