use hyper::{Client, Request, Body, Method};
use hyper_tls::HttpsConnector;
use tokio::time::{self, Duration};
use std::collections::HashMap;

#[derive(Clone)]
pub struct HttpClient {
    client: Client<HttpsConnector>,
    base_url: String,
    headers: HashMap<String, String>,
    timeout: Option<Duration>,
    proxy: Option<String>,
}

impl HttpClient {
    pub fn new(base_url: &str) -> Self {
        let https = HttpsConnector::new();
        HttpClient {
            client: Client::builder().build(https),
            base_url: base_url.to_string(),
            headers: HashMap::new(),
            timeout: None,
            proxy: None,
        }
    }

    pub fn set_header(&mut self, key: &str, value: &str) {
        self.headers.insert(key.to_string(), value.to_string());
    }

    pub fn set_timeout(&mut self, duration: Duration) {
        self.timeout = Some(duration);
    }

    pub fn set_proxy(&mut self, proxy_url: &str) {
        self.proxy = Some(proxy_url.to_string());
    }

    pub async fn request(
        &self,
        method: Method,
        path: &str,
        body: Option<&Body>,
    ) -> Result<hyper::Response<Body>, hyper::Error> {
        let mut uri = url::Url::parse(&self.base_url).unwrap();
        uri.set_path(path);

        let mut request = Request::builder()
            .method(method)
            .uri(uri.to_string())
            .body(body.cloned().unwrap_or(Body::empty()))?;

        for (key, value) in &self.headers {
            request.headers_mut().insert(key.clone(), value.parse().unwrap());
        }

        if let Some(timeout) = self.timeout {
            time::timeout(timeout, async move { self.client.request(request).await })
                .await?
        } else {
            self.client.request(request).await
        }
    }

    pub async fn get(&self, path: &str) -> Result<hyper::Response<Body>, hyper::Error> {
        self.request(Method::GET, path, None).await
    }

    // Add other HTTP methods (POST, PUT, DELETE, etc.) here with similar signatures.
}

#[tokio::main]
async fn main() {
    let mut client = HttpClient::new("https://api.example.com");
    client.set_header("Authorization", "Bearer token");
    client.set_timeout(Duration::from_secs(5));

    match client.get("/data").await {
        Ok(response) => println!("Response: {:?}", response),
        Err(e) => eprintln!("Error: {:?}", e),
    }
}
```

