use std::process::{Command, Stdio};
use std::time::{Instant, SystemTime};
use log::{error, info, warn};

fn main() {
    // Parse command-line arguments
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: cargo_build_tool <project_path> [--release]");
        std::process::exit(1);
    }
    let project_path = &args[1];
    let release = args.contains(&"--release".to_string());

    // Initialize logging
    log4rs::init_file("logging.yml", Default::default()).unwrap();

    // Measure compilation time and peak memory usage
    let start_time = Instant::now();
    let build_result = if release {
        run_build(project_path, Some("--release"))
    } else {
        run_build(project_path, None)
    };
    let duration = start_time.elapsed().as_secs_f32();

    // Log build information
    match &build_result {
        Ok(exit_code) => info!("Build successful with exit code: {}", exit_code),
        Err(e) => error!("Build failed: {}", e),
    }
    warn!("Compilation time: {} seconds", duration);

    // Return the exit code of the build process
    if let Some(exit_code) = build_result {
        std::process::exit(exit_code);
    } else {
        std::process::exit(1);
    }
}

fn run_build(project_path: &str, flags: Option<&str>) -> Result<i32, String> {
    // Run the build command
    let mut child = Command::new("cargo")
        .args(&["build", "-p", project_path])
        .args(flags.unwrap_or(""))
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .map_err(|e| format!("Failed to start build process: {}", e))?;

    // Wait for the build process to complete
    let status = child.wait().map_err(|e| format!("Failed to wait for build process: {}", e))?;
    if !status.success() {
        return Err(format!("Build failed with exit code: {}", status.code().unwrap_or(1)));
    }

    Ok(status.code().unwrap())
}
