function fetchAndCombineCertificates(oauthRequest) {
    const { privateKeyUrl, certificateUrl, retries = 3, timeout = 5000, backoff = 1000 } = oauthRequest;
    let pauseStream = false;

    return new Promise((resolve, reject) => {
        function fetchData(url, attempt = 0) {
            if (pauseStream) return;

            fetch(url)
                .then(response => response.text())
                .then(data => {
                    if (!data) {
                        if (attempt < retries) {
                            setTimeout(() => fetchData(url, attempt + 1), backoff);
                        } else {
                            reject(new Error('Failed to fetch data after multiple attempts'));
                        }
                    } else {
                        resolve(data);
                    }
                })
                .catch(error => {
                    if (attempt < retries) {
                        setTimeout(() => fetchData(url, attempt + 1), backoff);
                    } else {
                        reject(error);
                    }
                });
        }

        Promise.all([fetchData(privateKeyUrl), fetchData(certificateUrl)])
            .then(([privateKey, certificate]) => {
                resolve(`-----BEGIN PRIVATE KEY-----\n${privateKey}\n-----END PRIVATE KEY-----\n-----BEGIN CERTIFICATE-----\n${certificate}\n-----END CERTIFICATE-----`);
            })
            .catch(reject);
    });

    fetchAndCombineCertificates.pause = () => pauseStream = true;
    fetchAndCombineCertificates.resume = () => pauseStream = false;
}
