typedef struct {
    int *states;
    int num_states;
    pthread_mutex_t lock;
} FSA;

void* construct_subsequence(int *states, int num_states, FSA *fsa, int last_state) {
    if (last_state >= num_states || last_state < 0) {
        return NULL; // Error: Invalid last state
    }

    int subsequence_size = num_states - last_state;
    int *subsequence = malloc(subsequence_size * sizeof(int));
    if (subsequence == NULL) {
        return NULL; // Error: Memory allocation failed
    }

    pthread_mutex_lock(&fsa->lock);
    for (int i = 0; i < subsequence_size; i++) {
        subsequence[i] = states[last_state + i];
    }
    fsa->states[last_state].next = subsequence;
    pthread_mutex_unlock(&fsa->lock);

    return subsequence;
}
