    Octree(float featureSize, int maxLeafNodes, int maxDepth, int minPointsPerNode)
        : featureSize(featureSize), maxDepth(maxDepth), minPointsPerNode(minPointsPerNode), maxPointsPerNode(0) {
        // Calculate max points per node based on the number of leaf nodes
        maxPointsPerNode = maxLeafNodes / (1 << (3 * maxDepth));
        root = new OctreeNode();
    }

    ~Octree() { delete root; }

    void insert(Point* point) {
        if (!root) return;
        root->insert(point, featureSize, maxDepth);
    }

