        children[index]->insert(point, featureSize / 2.0f, maxDepth, depth + 1);
    }
    points.clear();
}

bool OctTreeNode::merge(const float featureSize, const int minPointsPerNode) {
    if (isLeaf || points.size() >= minPointsPerNode || depth == 0) return false;
    for (int i = 0; i < 8; ++i) {
        if (children[i] && children[i]->points.size() > minPointsPerNode) {
            return false;
        }
