package packetprocessor

import (
	"sync"
	"time"
)

type Packet struct {
	ID        int
	Timestamp time.Time
	Size      int
}

type FilterConfig struct {
	PacketAgeLimit  time.Duration
	PacketSizeLimit int
	BandwidthLimit  float64
}

type PacketProcessor struct {
	config   FilterConfig
	packets  []Packet
	mu       sync.Mutex
	queue    chan Packet
	wg       sync.WaitGroup
	shutdown chan struct{}
	done     chan struct{}
}

func NewPacketProcessor(config FilterConfig) *PacketProcessor {
	return &PacketProcessor{
		config:   config,
		packets:  make([]Packet, 0),
		queue:    make(chan Packet, 10000),
		shutdown: make(chan struct{}),
		done:     make(chan struct{}),
	}
}

func (pp *PacketProcessor) Start() {
	pp.wg.Add(2)
	go pp.processPackets()
	go pp.monitorQueue()
}

func (pp *PacketProcessor) Stop() {
	close(pp.shutdown)
	pp.wg.Wait()
	close(pp.done)
}

func (pp *PacketProcessor) ProcessPacket(packet Packet) {
	select {
	case pp.queue <- packet:
	default:
		// Queue is full, drop the packet
	}
}

func (pp *PacketProcessor) processPackets() {
	defer pp.wg.Done()

	for {
		select {
		case packet := <-pp.queue:
			if pp.shouldFilter(packet) {
				pp.mu.Lock()
				pp.packets = append(pp.packets, packet)
				pp.mu.Unlock()
			}
		case <-pp.shutdown:
			return
		}
	}
}

func (pp *PacketProcessor) monitorQueue() {
	defer pp.wg.Done()

	ticker := time.NewTicker(50 * time.Millisecond)
	defer ticker.Stop()

	for {
		select {
		case <-ticker.C:
			pp.aggregatePackets()
		case <-pp.shutdown:
			return
		}
	}
}

func (pp *PacketProcessor) shouldFilter(packet Packet) bool {
	currentTime := time.Now()
	packetAge := currentTime.Sub(packet.Timestamp)

	if packetAge > pp.config.PacketAgeLimit || packet.Size > pp.config.PacketSizeLimit {
		return true
	}

	bandwidthUsage, err := getRealtimeBandwidthUsage() // Assume this function fetches the bandwidth limit dynamically
	if err != nil {
		logError("Failed to fetch bandwidth usage:", err)
		return false
	}

	if bandwidthUsage > pp.config.BandwidthLimit {
		return true
	}

	return false
}

func (pp *PacketProcessor) aggregatePackets() {
	pp.mu.Lock()
	defer pp.mu.Unlock()

	for _, packet := range pp.packets {
		logPacket(packet)
	}
	pp.packets = []Packet{}
}

func logPacket(packet Packet) {
	// Implement logging mechanism here
}

func getRealtimeBandwidthUsage() (float64, error) {
	// Implement logic to fetch real-time bandwidth usage from external data source
	return 0.0, nil
}

func logError(message string, err error) {
	// Implement error logging mechanism here
}
