#include <iostream>
#include <vector>
#include <mutex>
#include <atomic>
#include <random>
#include <chrono>

enum class LogLevel { DEBUG, INFO, WARNING, ERROR };

class Logger {
public:
    static void log(LogLevel level, const std::string& message) {
        // Implement logging based on the log level
        switch (level) {
            case LogLevel::DEBUG: std::cout << "[DEBUG] " << message << std::endl; break;
            case LogLevel::INFO: std::cout << "[INFO] " << message << std::endl; break;
            case LogLevel::WARNING: std::cout << "[WARNING] " << message << std::endl; break;
            case LogLevel::ERROR: std::cout << "[ERROR] " << message << std::endl; break;
        }
    }
};

class CharacterAttackSystem {
private:
    struct Attack {
        int damage;
        std::chrono::time_point<std::chrono::system_clock> lastUsed;
    };

    std::vector<Attack> attacks;
    std::mutex attackMutex;
    std::atomic<int> lastSelectedAttackId;

public:
    CharacterAttackSystem() : attacks(3), lastSelectedAttackId(0) {
        // Initialize attacks with different damage profiles
        attacks[0] = {5, std::chrono::system_clock::now()};
        attacks[1] = {10, std::chrono::system_clock::now()};
        attacks[2] = {15, std::chrono::system_clock::now()};
    }

    void performAttack(int characterId) {
        std::lock_guard<std::mutex> lock(attackMutex);
        auto now = std::chrono::system_clock::now();
        int selectedAttackId = lastSelectedAttackId.load(std::memory_order_relaxed);

        // Check if the attack can be performed
        while (selectedAttackId != -1 && attacks[selectedAttackId].lastUsed + std::chrono::seconds(12) > now) {
            // Wait for the cooldown to expire
            std::this_thread::sleep_for(std::chrono::milliseconds(50));
            selectedAttackId = lastSelectedAttackId.load(std::memory_order_relaxed);
        }

        if (selectedAttackId == -1) {
            // Randomly select an attack
            std::random_device rd;
            std::mt19937 gen(rd());
            std::uniform_int_distribution<> dis(0, 2);
            selectedAttackId = dis(gen);
        }

        attacks[selectedAttackId].lastUsed = now;
        lastSelectedAttackId.store(selectedAttackId, std::memory_order_relaxed);

        // Log the attack
        Logger::log(LogLevel::INFO, "Character " + std::to_string(characterId) + " performed attack " + std::to_string(selectedAttackId));
    }
};

int main() {
    CharacterAttackSystem attackSystem;

    for (int i = 0; i < 100; ++i) {
        attackSystem.performAttack(i);
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
    }

    return 0;
}
```

This code snippet provides a basic implementation of the `CharacterAttackSystem` class. The class uses a mutex to ensure thread safety when managing attack cooldowns and selecting attacks, while an atomic variable is used for efficient read and write operations of the last selected attack ID. The logging mechanism is implemented using a simple static method that outputs messages based on the log level. The main function demonstrates how to use the `CharacterAttackSystem` class by performing attacks from multiple threads.']

