using System;

public class DynamicValueGenerator
{
    private float minValue;
    private float maxValue;

    public DynamicValueGenerator(float initialValueMin = 0, float initialValueMax = 0)
    {
        MinValue = initialValueMin;
        MaxValue = initialValueMax;
    }

    public float MinValue { get; set; }
    public float MaxValue { get; set; }

    public float GenerateRandomFloatInclusive()
    {
        if (minValue > maxValue)
        {
            return 0f; // Handle invalid range by returning a default value
        }
        Random random = new Random();
        return (float)random.NextDouble() * (maxValue - minValue + 1) + minValue;
    }

    public float GenerateRandomFloatExclusive()
    {
        if (minValue >= maxValue)
        {
            return 0f; // Handle invalid range by returning a default value
        }
        Random random = new Random();
        return (float)random.NextDouble() * (maxValue - minValue) + minValue;
    }

    public int GenerateRandomIntInclusive()
    {
        if ((int)minValue > (int)maxValue)
        {
            return 0; // Handle invalid range by returning a default value
        }
        Random random = new Random();
        return random.Next((int)minValue, (int)(maxValue + 1));
    }

    public int GenerateRandomIntExclusive()
    {
        if ((int)minValue >= (int)maxValue)
        {
            return 0; // Handle invalid range by returning a default value
        }
        Random random = new Random();
        return random.Next((int)(minValue + 1), (int)maxValue);
    }

    public override string ToString()
    {
        if (MinValue == MaxValue)
        {
            return $"Range[{MinValue}]";
        }
        return MinValue < MaxValue ? $"Range[{MinValue}..{MaxValue}]" : $"Range({MinValue}..{MaxValue})";
    }
}
