const fetchValidationService = require('external-validation-service');

async function reduceArrayModularized(array) {
  const results = [];
  for (let i = 0; i < array.length; i++) {
    try {
      const isValid = await validateElement(array[i]);
      if (isValid) {
        results.push(array[i]);
      }
    } catch (error) {
      console.error(`Error processing element at index ${i}:`, error);
    }
  }
  return results;
}

async function validateElement(element) {
  try {
    const response = await fetchValidationService.validate(element);
    return response.isValid;
  } catch (error) {
    throw new Error(`Validation failed for element: ${element}`);
  }
}

// Example usage:
(async () => {
  const array = [1, '2', null, 3.5, 'invalid', 4];
  try {
    const validElements = await reduceArrayModularized(array);
    console.log('Valid elements:', validElements);
  } catch (error) {
    console.error('Error during reduction:', error);
  }
})();
