int initialize_config_manager(const char *json_path) {
    FILE *file = fopen(json_path, "r");
    if (!file) {
        perror("Failed to open JSON file");
        return -1;
    }

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    char *json_buffer = (char *)malloc(file_size + 1);
    if (!json_buffer) {
        perror("Failed to allocate memory for JSON buffer");
        fclose(file);
        return -2;
    }

    size_t bytes_read = fread(json_buffer, 1, file_size, file);
    fclose(file);

    if (bytes_read != file_size) {
        perror("Error reading JSON file");
        free(json_buffer);
        return -3;
    }
    json_buffer[file_size] = '\0';

    struct json_object *config_json = json_tokener_parse(json_buffer);
    if (!config_json) {
        fprintf(stderr, "Failed to parse JSON\n");
        free(json_buffer);
        return -4;
    }

    int num_entries = 0;
    if (json_is_array(config_json)) {
        num_entries = json_array_length((struct json_object *)config_json);
    } else {
        fprintf(stderr, "Invalid JSON structure\n");
        json_object_put(config_json);
        free(json_buffer);
        return -5;
