// Function to calculate the number of digits in a string
int countDigits(const char* str) {
    int count = 0;
    for (int i = 0; str[i]; ++i) {
        if (str[i] >= '0' && str[i] <= '9') {
            count++;
        }
    }
    return count;
}

// Simple hash function to generate a checksum
unsigned long generateChecksum(const char* filename, const time_t* creationDate, const time_t* lastModifiedDate) {
    unsigned long hash = 5381;
    for (int i = 0; filename[i]; ++i) {
        hash = ((hash << 5) + hash) + filename[i];
    }
    if (creationDate) {
        hash += *creationDate;
    }
    if (lastModifiedDate) {
        hash += *lastModifiedDate;
    }
    return hash % 1000000000; // Ensure the checksum is within a manageable range
}

// Function to generate a new filename based on input constraints
void generateNewFilename(const char* originalFilename, const time_t* creationDate, const time_t* lastModifiedDate, const char* fileType, char* newFilename) {
    int digitCount = countDigits(originalFilename);
    unsigned long checksum = generateChecksum(originalFilename, creationDate, lastModifiedDate);

    // Construct the new filename
    snprintf(newFilename, 257, "%s-%d-%lu.%s", originalFilename, digitCount, checksum, fileType);
}

int main() {
    time_t creationTime = time(NULL);
    time_t modifiedTime = time(NULL);

    char newFilename[256];
    generateNewFilename("document-2023-01-01.txt", &creationTime, &modifiedTime, "docx", newFilename);

    printf("New Filename: %s\n", newFilename);
    return 0;
}
```

