#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <limits.h>

#define MAX_COMMAND_LENGTH 256

int execute_command_async(const char *command) {
    pid_t pid;
    int status;

    if ((pid = fork()) == -1) {
        perror("fork");
        return 0;
    }

    if (pid == 0) {
        // Child process
        execlp("/bin/sh", "sh", "-c", command, NULL);
        perror("execlp"); // If execlp returns, it failed
        _exit(EXIT_FAILURE); // Exit the child process on failure
    } else {
        // Parent process
        if (waitpid(pid, &status, WNOHANG) == -1) {
            perror("waitpid");
            return 0;
        }

        if (!WIFEXITED(status)) {
            printf("Command is running in the background.\n");
            return 1;
        } else {
            printf("Command exited with status %d\n", WEXITSTATUS(status));
            return 1; // Return success regardless of exit code
        }
    }

    return 0; // Fallback, should never reach here
}

int main() {
    const char *command = "sleep 10"; // Example command

    if (execute_command_async(command)) {
        printf("Command executed successfully in the background.\n");
    } else {
        printf("Failed to execute command asynchronously.\n");
    }

    return 0;
}
```

