    public static void IntegrateAndStartSite(string directoryPath, string siteName)
    {
        try
        {
            if (!Directory.Exists(directoryPath))
            {
                Console.WriteLine("Directory does not exist.");
                return;
            }

            string webConfigPath = Path.Combine(directoryPath, "web.config");
            string serverXmlPath = Path.Combine(directoryPath, "server.xml");

            if (!File.Exists(webConfigPath) || !File.Exists(serverXmlPath))
            {
                Console.WriteLine("Missing essential configuration files.");
                return;
            }

            if (!CanExecute(directoryPath))
            {
                AdjustPermissions(directoryPath);
                if (!CanExecute(directoryPath))
                {
                    Console.WriteLine("Failed to adjust permissions. Unable to start site.");
                    return;
                }
            }

            ProcessStartInfo processInfo = new ProcessStartInfo
            {
                FileName = "dotnet",
                Arguments = $"run --project {siteName}",
                WorkingDirectory = directoryPath,
                RedirectStandardOutput = true,
                UseShellExecute = false,
                CreateNoWindow = true
            };

            using (Process process = new Process { StartInfo = processInfo })
            {
                process.Start();
                string output = process.StandardOutput.ReadToEnd();
                Console.WriteLine(output);

                if (!process.WaitForExit(30000)) // 30 seconds timeout
                {
                    process.Kill();
                    Console.WriteLine("Site did not start within the timeout. Killed.");
                }
            }

            Console.WriteLine("Site started successfully.");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }

    private static bool CanExecute(string directoryPath)
    {
        try
        {
            File.CreateTempFileName(Path.Combine(directoryPath, "temp"));
            return true;
        }
        catch
        {
            return false;
        }
    }

