#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>

typedef struct {
    char *title;
} Connection;

typedef struct {
    char *encrypted_message;
    int key[3];
    unsigned char iv[EVP_MAX_IV_LENGTH];
} MessageData;

typedef enum {
    ERR_EMPTY_MESSAGE = -1,
    ERR_NULL_CONNECTION = -2,
    ERR_EMPTY_TITLE = -3,
    ERR_NULL_CALLBACK = -4,
    ERR_DECRYPTION_FAILED = -5
} ErrorCode;

int processSecureMessage(MessageData *msg, Connection *conn, int (*callback)(const char *)) {
    if (msg->encrypted_message == NULL || msg->encrypted_message[0] == '\0') {
        return ERR_EMPTY_MESSAGE;
    }
    if (conn == NULL) {
        return ERR_NULL_CONNECTION;
    }
    if (conn->title == NULL || conn->title[0] == '\0') {
        return ERR_EMPTY_TITLE;
    }
    if (callback == NULL) {
        return ERR_NULL_CALLBACK;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        return ERR_DECRYPTION_FAILED;
    }

    if (1 != EVP_DecryptInit_ex(ctx, EVP_des_ede3_cbc(), NULL, msg->key, msg->iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return ERR_DECRYPTION_FAILED;
    }

    char decrypted[256];
    int len, final_len;
    if (1 != EVP_DecryptUpdate(ctx, decrypted, &len, (unsigned char *)msg->encrypted_message, strlen(msg->encrypted_message))) {
        EVP_CIPHER_CTX_free(ctx);
        return ERR_DECRYPTION_FAILED;
    }
    final_len = len;

    if (1 != EVP_DecryptFinal_ex(ctx, decrypted + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        return ERR_DECRYPTION_FAILED;
    }
    final_len += len;

    decrypted[final_len] = '\0';

    int result = callback(decrypted);
    EVP_CIPHER_CTX_free(ctx);

    if (result != 0) {
        return result;
    }

    return 0;
}
