using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class Base64TripleDESDecoder
{
    private static readonly string LogPrefix = "Base64TripleDESDecoder: ";

    public static string Decrypt(string base64EncodedMessage, string hexKey, string hexIV)
    {
        if (string.IsNullOrEmpty(base64EncodedMessage) || !IsHexadecimal(hexKey) || !IsHexadecimal(hexIV))
        {
            LogError("Invalid input format.");
            return "INVALID_INPUT";
        }

        byte[] key = Convert.FromHexString(hexKey);
        byte[] iv = Convert.FromHexString(hexIV);

        if (key.Length != 24 || iv.Length != 8)
        {
            LogError("Key and IV must be exactly 24 and 8 bytes long, respectively.");
            return "INVALID_KEY_OR_IV";
        }

        try
        {
            byte[] decodedBytes = Convert.FromBase64String(base64EncodedMessage);
            using (TripleDES des = TripleDES.Create())
            {
                des.Key = key;
                des.IV = iv;
                des.Mode = CipherMode.CBC;
                des.Padding = PaddingMode.PKCS7;

                using (MemoryStream msDecrypt = new MemoryStream(decodedBytes))
                {
                    using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, des.CreateDecryptor(), CryptoStreamMode.Read))
                    {
                        using (StreamReader srDecrypt = new StreamReader(csDecrypt))
                        {
                            return srDecrypt.ReadToEnd();
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            LogError($"Decryption failed: {ex.Message}");
            return "DECRYPTION_FAILED";
        }
    }

    private static bool IsHexadecimal(string input)
    {
        try
        {
            Convert.FromHexString(input);
            return true;
        }
        catch
        {
            return false;
        }
    }

    private static void LogError(string message)
    {
        // Implement error logging here, e.g., writing to a file or sending to an external system.
        Console.WriteLine(LogPrefix + message);
    }
}
```

