using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class AesCbcDecryptor
{
    private readonly byte[] _key;
    private readonly IEncryptionService _encryptionService;

    public AesCbcDecryptor(byte[] key, IEncryptionService encryptionService)
    {
        _key = key;
        _encryptionService = encryptionService;
    }

    public async Task<byte[]> DecryptSegmentAsync(byte[] ciphertext, byte[] iv, byte[] hmacTag)
    {
        using (Aes aes = Aes.Create())
        {
            aes.Key = _key;
            aes.IV = iv;
            aes.Mode = CipherMode.CBC;
            aes.Padding = PaddingMode.PKCS7;

            ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV);

            using (MemoryStream msDecrypt = new MemoryStream(ciphertext))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    using (MemoryStream msOutput = new MemoryStream())
                    {
                        await csDecrypt.CopyToAsync(msOutput);
                        byte[] decryptedData = msOutput.ToArray();

                        // Verify HMAC-SHA256 tag
                        if (!VerifyHmac(decryptedData, hmacTag, _key))
                        {
                            throw new InvalidOperationException("HMAC verification failed.");
                        }

                        return decryptedData;
                    }
                }
            }
        }
    }

    private bool VerifyHmac(byte[] data, byte[] hmacTag, byte[] key)
    {
        using (HMACSHA256 hmac = HMACSHA256.Create())
        {
            hmac.Key = key;
            byte[] computedHmac = hmac.ComputeHash(data);
            return computedHmac.SequenceEqual(hmacTag);
        }
    }
}

public interface IEncryptionService
{
    byte[] GetKey();
    byte[] GetIv();
}

// Example usage:
