    {
        byte[] key = new EncryptionService().GetKey();
        IEncryptionService encryptionService = new EncryptionService();

        AesCbcDecryptor decryptor = new AesCbcDecryptor(key, encryptionService);

        // Example ciphertext segments
        byte[][] ciphertextSegments = { ... };
        byte[][] ivs = { ... };
        byte[][] hmacTags = { ... };

        foreach (var segment in ciphertextSegments)
        {
            try
            {
                byte[] decryptedData = await decryptor.DecryptSegmentAsync(segment, ivs[0], hmacTags[0]);
                // Process decrypted data
            }
            catch (Exception ex)
            {
                // Log exception for debugging purposes
                Console.WriteLine(ex.Message);
            }
        }
    }
}
