import java.io.*;
import java.lang.reflect.InvocationTargetException;
import java.util.Map;

public class DynamicDeserializer {

    public static <T> T deserialize(byte[] data, Class<T> clazz) throws IOException, ClassNotFoundException, NoSuchMethodException, IllegalAccessException, InvocationTargetException {
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(data))) {
            return clazz.getDeclaredConstructor().newInstance();
        } catch (InstantiationException e) {
            throw new IllegalArgumentException("Class must have a no-arg constructor", e);
        }
    }

    public static void main(String[] args) {
        try {
            byte[] data = getSerializedData(); // Assume this method retrieves serialized data
            MyClass obj = deserialize(data, MyClass.class);
            System.out.println(obj);
        } catch (IOException | ClassNotFoundException | NoSuchMethodException | IllegalAccessException | InvocationTargetException e) {
            e.printStackTrace();
        }
    }

    private static byte[] getSerializedData() throws IOException {
        // Simulate getting serialized data from a source
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        ObjectOutputStream oos = new ObjectOutputStream(baos);
        MyClass obj = new MyClass("example");
        oos.writeObject(obj);
        oos.close();
        return baos.toByteArray();
    }
}

class MyClass implements Serializable {
    private String value;

    public MyClass(String value) {
        this.value = value;
    }

    @Override
    public String toString() {
        return "MyClass{" +
                "value='" + value + '\'' +
                '}';
    }
}
