    uint16_t RNTI;
    uint8_t CRCFLAG;
    pthread_mutex_t mutex;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T** initialize_dynamic_array(size_t N) {
    NFAPI_CRC_INDICATION_PDU_T** array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    for (size_t i = 0; i < N; ++i) {
        array[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pthread_mutex_init(&array[i]->mutex, NULL);
        array[i]->RX_UE_INFORMATION_TAG = rand();
        array[i]->RNTI = rand() % 1024;
        array[i]->CRCFLAG = rand() % 2;
    }
    return array;
}

void add_or_update_element(NFAPI_CRC_INDICATION_PDU_T** array, size_t N, uint32_t RX_UE_INFORMATION_TAG, uint8_t new_crcflag) {
    for (size_t i = 0; i < N; ++i) {
        pthread_mutex_lock(&array[i]->mutex);
        if (array[i]->RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            array[i]->CRCFLAG = new_crcflag;
            pthread_mutex_unlock(&array[i]->mutex);
            return;
        }
        pthread_mutex_unlock(&array[i]->mutex);
    }
    // Handle duplicate or missing tag gracefully
}

void free_dynamic_array(NFAPI_CRC_INDICATION_PDU_T** array, size_t N) {
    for (size_t i = 0; i < N; ++i) {
        pthread_mutex_destroy(&array[i]->mutex);
        free(array[i]);
    }
    free(array);
}
