const fs = require('fs');
const path = require('path');

function uploadFiles(urls, callback) {
    const uploadedUrls = [];
    let completedUploads = 0;

    urls.forEach(url => {
        const fileName = path.basename(new URL(url).pathname);
        const filePath = path.join(__dirname, fileName);

        fetch(url)
            .then(response => response.blob())
            .then(blob => fs.promises.writeFile(filePath, blob))
            .then(() => {
                uploadedUrls.push(fileName);
                completedUploads++;
                if (completedUploads === urls.length) {
                    callback(uploadedUrls);
                }
            })
            .catch(error => {
                console.error(`Failed to upload ${url}:`, error);
                completedUploads++;
                if (completedUploads === urls.length) {
                    callback(uploadedUrls);
                }
            });
    });
}

// Example usage:
const fileUrls = [
    'https://example.com/file1.txt',
    'https://example.com/file2.txt'
];
uploadFiles(fileUrls, uploadedUrls => {
    console.log('Uploaded files:', uploadedUrls);
});
