    if args.len() != 2 {
        error!("Usage: {} <api_url>", args[0]);
        return;
    }

    let api_url = &args[1];
    let client = Client::new();

    match fetch_data(&client, api_url).await {
        Ok(data) => info!("Data fetched successfully: {:?}", data),
        Err(e) => error!("Failed to fetch data: {}", e),
    }
}

async fn fetch_data(client: &Client, url: &str) -> Result<Vec<Data>, reqwest::Error> {
    let response = client.get(url).send().await?;
    if response.status().is_success() {
        response.json().await
    } else {
        Err(reqwest::Error::new(
            reqwest::error::ErrorKind::Other,
            format!("HTTP error: {}", response.status()),
        ))
    }
}
