use std::env;
use std::fs::{self, DirBuilder};
use std::path::Path;
use std::sync::Mutex;
use std::thread;
use tokio::time::{sleep, Duration};

static LOCK: Mutex<()> = Mutex::new(());

async fn create_directory_with_retry(
    dir_name: &str,
    prefix: Option<&str>,
    retry_limit: u32,
) -> Result<(), Box<dyn std::error::Error>> {
    let mut retries = 0;
    loop {
        if let Ok(_) = LOCK.lock() {
            if let Some(prefix) = prefix {
                let full_dir_name = format!("{}{}", prefix, dir_name);
                let path = Path::new(&full_dir_name);

                if !path.exists() {
                    DirBuilder::new().create(path)?;
                    env::set_var("DEPLOY_DIR", &full_dir_name)?;

                    // Simulate external API call
                    log_directory_creation(full_dir_name).await?;
                    return Ok(());
                } else {
                    println!("Directory already exists: {}", full_dir_name);
                }
            } else {
                println!("Prefix is required");
            }

            break;
        } else if retries < retry_limit {
            retries += 1;
            sleep(Duration::from_secs(1)).await;
        } else {
            return Err("Failed to create directory after retries".into());
        }
    }
}

async fn log_directory_creation(dir_name: String) -> Result<(), Box<dyn std::error::Error>> {
    // Simulate external API call
    println!("Directory created successfully: {}", dir_name);
    Ok(())
}

fn main() {
    let _guard = LOCK.lock().unwrap();
    tokio::runtime::Runtime::new().unwrap().block_on(async {
        create_directory_with_retry("my_dir", Some("_deploy"), 3).await.unwrap();
    });
}
