        class_name = data.get('type')
        if class_name in DynamicClassCreator.class_registry:
            cls = DynamicClassCreator.class_registry[class_name]
            return cls(**data)
        raise ValueError(f"Unknown class type: {class_name}")

class JSONParser(BaseJSONParser):
    def parse(self, json_data):
        try:
            data = json.loads(json_data)
            return self._parse_dict(data)

        except json.JSONDecodeError as e:
            raise ValueError("Malformed JSON input") from e

    def generate(self, obj):
        if isinstance(obj, dict):
            return {key: self.generate(value) for key, value in obj.items()}
        elif isinstance(obj, list):
            return [self.generate(item) for item in obj]
        elif hasattr(obj, '__dict__'):
            return {**obj.__dict__, 'type': obj.__class__.__name__}
        else:
            return obj

    def _parse_dict(self, data):
        if 'type' in data and DynamicClassCreator.class_registry[data['type']]:
            return DynamicClassCreator.create_instance(data)
        return {key: self._parse_value(value) for key, value in data.items()}

    def _parse_value(self, value):
        if isinstance(value, dict):
            return self._parse_dict(value)
        elif isinstance(value, list):
            return [self._parse_value(item) for item in value]
        else:
            return value

# Example usage
class User:
    def __init__(self, name, age):
        self.name = name
        self.age = age

DynamicClassCreator.register_class('User', User)

parser = JSONParser()
json_data = '{"type": "User", "name": "John Doe", "age": 30}'
user_obj = parser.parse(json_data)
print(user_obj)  # Output: <__main__.User object at 0x...>

new_json_data = parser.generate(user_obj)
print(new_json_data)  # Output: {'type': 'User', 'name': 'John Doe', 'age': 30}
```']

