    pthread_mutex_lock(&algo_lock);
    if (strcmp(algo_name, "AES") == 0) init_aes();
    else if (strcmp(algo_name, "Camellia") == 0) init_camellia();
    else if (strcmp(algo_name, "MD5") == 0) init_md5();
