AudioInfo processWAVFile(const char* filePath) {
    FILE* file = fopen(filePath, "rb");
    if (!file) {
        printf("Error opening file.\n");
        return (AudioInfo){0};
    }

    WAVHeader header;
    fread(&header, sizeof(WAVHeader), 1, file);

    AudioInfo info;
    info.numChannels = header.numChannels;
    info.sampleRate = header.sampleRate;
    info.bitDepth = header.bitsPerSample;

    // Validate audio format and metadata
    if (strcmp(header.chunkID, "RIFF") != 0 || strcmp(header.format, "WAVE") != 0 ||
        strcmp(header.subchunk1ID, "fmt ") != 0 || strcmp(header.subchunk2ID, "data") != 0) {
        printf("Invalid WAV file header.\n");
        fclose(file);
        return (AudioInfo){0};
    }

    if (header.audioFormat != 1) { // PCM format
        printf("Unsupported audio format.\n");
        fclose(file);
        return (AudioInfo){0};
    }

    if (!(header.bitsPerSample == 8 || header.bitsPerSample == 16 || header.bitsPerSample == 24 || header.bitsPerSample == 32)) {
        printf("Unsupported bit depth.\n");
        fclose(file);
        return (AudioInfo){0};
    }

    fclose(file);

    // Additional processing for high-bitrate, high-sample-rate files can be done here
    // ...

    return info;
}
