use openssl::{
    ssl::{SslMethod, SslConnectorBuilder},
    pkcs12::Pkcs12,
    error::ErrorStack,
};
use reqwest::{
    Client,
    client::Builder,
    Error as ReqwestError,
};
use std::{
    sync::Arc,
    thread,
};

struct HttpClient {
    client: Client,
    tls_config: Option<TlsConfig>,
}

#[derive(Clone)]
struct TlsConfig {
    connector: SslConnectorBuilder,
}

impl HttpClient {
    async fn new(tls_config: Option<TlsConfig>) -> Result<Self, ReqwestError> {
        let builder = Builder::new();
        if let Some(config) = tls_config {
            builder.connector(config.connector.build());
        }
        Ok(HttpClient {
            client: builder.build(),
            tls_config,
        })
    }

    async fn request(
        &self,
        method: reqwest::Method,
        url: &str,
        body: Option<reqwest::Body>,
    ) -> Result<reqwest::Response, ReqwestError> {
        self.client.request(method, url).body(body).send().await
    }
}

impl TlsConfig {
    fn new(disable_cert_validation: bool) -> Self {
        let mut builder = SslConnectorBuilder::new(SslMethod::tls()).unwrap();
        if disable_cert_validation {
            builder.danger_accept_invalid_certs(true);
        }
        TlsConfig { connector: builder }
    }

    async fn from_p12(p12_data: &[u8], password: &str) -> Result<Self, ErrorStack> {
        let pkcs12 = Pkcs12::from_der(p12_data, password)?;
        let mut store = pkcs12.to_pem()?;
        let cert = store.remove_first_cert();
        let key = store.remove_private_key();

        let mut builder = SslConnectorBuilder::new(SslMethod::tls()).unwrap();
        builder.set_certificate(cert.as_ref());
        builder.set_private_key(key.as_ref());

        Ok(TlsConfig { connector: builder })
    }
}

fn main() {
    let tls_config = TlsConfig::new(true);
    let client = Arc::new(HttpClient::new(Some(tls_config)).unwrap());

    let url = "https://example.com";
    let body = Some(reqwest::Body::from("Hello, world!"));

    let handle = thread::spawn({
        let client = client.clone();
        move || {
            if let Ok(response) = client.request(reqwest::Method::POST, url, body).await {
                println!("Response status: {}", response.status());
            }
        }
    });

    handle.join().unwrap();
}
