typedef struct {
    int RB_ID;
    unsigned long SN;
    PDCP_SN_STATE state;
} LTE_PDCP_RX_BUFFER_T;

typedef struct {
    LTE_PDCP_RX_BUFFER_T* buffers;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} LTE_PDCP_RX_BUFFER_MANAGER;

LTE_PDCP_RX_BUFFER_MANAGER* lte_pdcp_rx_buffer_manager_init(size_t initial_capacity) {
    LTE_PDCP_RX_BUFFER_MANAGER* manager = (LTE_PDCP_RX_BUFFER_MANAGER*)malloc(sizeof(LTE_PDCP_RX_BUFFER_MANAGER));
    if (!manager) return NULL;

    manager->buffers = (LTE_PDCP_RX_BUFFER_T*)calloc(initial_capacity, sizeof(LTE_PDCP_RX_BUFFER_T));
    if (!manager->buffers) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->mutex, NULL);

    return manager;
}

void lte_pdcp_rx_buffer_manager_free(LTE_PDCP_RX_BUFFER_MANAGER* manager) {
    if (manager) {
        free(manager->buffers);
        pthread_mutex_destroy(&manager->mutex);
        free(manager);
    }
}

int lte_pdcp_rx_buffer_manager_add(LTE_PDCP_RX_BUFFER_MANAGER* manager, LTE_PDCP_RX_BUFFER_T buffer) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        LTE_PDCP_RX_BUFFER_T* new_buffers = (LTE_PDCP_RX_BUFFER_T*)realloc(manager->buffers, new_capacity * sizeof(LTE_PDCP_RX_BUFFER_T));
        if (!new_buffers) {
            pthread_mutex_unlock(&manager->mutex);
            return -1;
        }
        manager->buffers = new_buffers;
        manager->capacity = new_capacity;
    }

    manager->buffers[manager->size++] = buffer;

    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

int lte_pdcp_rx_buffer_manager_update(LTE_PDCP_RX_BUFFER_MANAGER* manager, int rb_id, LTE_PDCP_RX_BUFFER_T new_buffer) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->buffers[i].RB_ID == rb_id) {
            manager->buffers[i] = new_buffer;
            pthread_mutex_unlock(&manager->mutex);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->mutex);
    return -1;
}

LTE_PDCP_RX_BUFFER_T* lte_pdcp_rx_buffer_manager_get(LTE_PDCP_RX_BUFFER_MANAGER* manager, int rb_id) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->buffers[i].RB_ID == rb_id) {
            LTE_PDCP_RX_BUFFER_T* buffer = &manager->buffers[i];
            pthread_mutex_unlock(&manager->mutex);
            return buffer;
        }
    }

    pthread_mutex_unlock(&manager->mutex);
    return NULL;
}
