public class FileProcessor {

    private final Path inputPath;
    private final Path outputPath;
    private final ExecutorService executorService;

    public FileProcessor(Path inputPath, Path outputPath) {
        this.inputPath = inputPath;
        this.outputPath = outputPath;
        this.executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    }

    public void processFile() throws IOException, InterruptedException, ExecutionException {
        try (BufferedReader reader = Files.newBufferedReader(inputPath);
             BufferedWriter writer = Files.newBufferedWriter(outputPath)) {

            List<CompletableFuture<Void>> futures = new ArrayList<>();

            String line;
            while ((line = reader.readLine()) != null) {
                CompletableFuture<Void> future = CompletableFuture.runAsync(() -> processLine(line, writer), executorService);
                futures.add(future);
            }

            CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).get();
        } finally {
            executorService.shutdown();
        }
    }

    private void processLine(String line, BufferedWriter writer) {
        try {
            String transformed = applyCustomTransformation(line);
            writer.write(transformed);
            writer.newLine();
        } catch (IOException e) {
            System.err.println("Error processing line: " + e.getMessage());
        }
    }

    private String applyCustomTransformation(String line) {
        // Implement your custom transformation logic here
        return line.toUpperCase(); // Example transformation
    }

    public static void main(String[] args) {
        Path inputPath = Paths.get("input.txt");
        Path outputPath = Paths.get("output.txt");

        try {
            FileProcessor processor = new FileProcessor(inputPath, outputPath);
            processor.processFile();
            System.out.println("File processing completed successfully.");
        } catch (IOException | InterruptedException | ExecutionException e) {
            System.err.println("Error during file processing: " + e.getMessage());
        }
    }
}
