#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>

#define BUFFER_SIZE 1024

typedef enum {
    SUCCESS,
    FAILURE
} Status;

void runCommandInBackground(const char *command, const char **args) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        exit(EXIT_FAILURE);
    } else if (pid == 0) {
        execvp(command, args);
        perror("execvp");
        _exit(EXIT_FAILURE);
    }
}

Status generatePEMCertificate(const char *privateKeyPath, const char *certificatePath) {
    char pemFilePath[BUFFER_SIZE];
    snprintf(pemFilePath, BUFFER_SIZE, "merged_certificate.pem");

    FILE *privateFile = fopen(privateKeyPath, "r");
    if (!privateFile) {
        perror("Failed to open private key file");
        return FAILURE;
    }

    FILE *certFile = fopen(certificatePath, "r");
    if (!certFile) {
        perror("Failed to open certificate file");
        fclose(privateFile);
        return FAILURE;
    }

    FILE *pemFile = fopen(pemFilePath, "w");
    if (!pemFile) {
        perror("Failed to create PEM file");
        fclose(privateFile);
        fclose(certFile);
        return FAILURE;
    }

    char buffer[BUFFER_SIZE];
    while (fgets(buffer, BUFFER_SIZE, privateFile)) {
        fputs(buffer, pemFile);
    }
    fclose(privateFile);

    while (fgets(buffer, BUFFER_SIZE, certFile)) {
        fputs(buffer, pemFile);
    }
    fclose(certFile);
    fclose(pemFile);

    return SUCCESS;
}

int main() {
    const char *privateKeyPath = "path_to_private_key";
    const char *certificatePath = "path_to_certificate";

    Status status = generatePEMCertificate(privateKeyPath, certificatePath);
    if (status == SUCCESS) {
        printf("Certificate generated successfully.\n");
    } else {
        printf("Failed to generate certificate.\n");
    }

    const char *command = "critical_system_operation";
    const char *args[] = {command, NULL};

    runCommandInBackground(command, args);

    return 0;
}
