// Define a dynamic list of states using an integer array and a count
class StateList {
public:
    std::unique_ptr<int[]> states;
    size_t stateCount;

    StateList(size_t count) : stateCount(count) {
        states = std::make_unique<int[]>(count);
    }

    ~StateList() {}

    void setState(int index, int value) {
        if (index < stateCount) {
            states[index] = value;
        }
    }

    int getState(int index) const {
        if (index < stateCount) {
            return states[index];
        }
        return -1; // Invalid index
    }
};

// Mock for InterfaceTable class with a simplified FindVmUuidFromMetadataIp method
class MockInterfaceTable : public InterfaceTable {
public:
    std::mutex lock;

    void setMockData(const std::string& metadataIp, const std::string& vmUuid) {
        std::lock_guard<std::mutex> guard(lock);
        mockData[metadataIp] = vmUuid;
    }

    bool FindVmUuidFromMetadataIp(const std::string& metadata_ip,
                                    std::string* vm_uuid) override {
        std::lock_guard<std::mutex> guard(lock);
        auto it = mockData.find(metadata_ip);
        if (it != mockData.end()) {
            *vm_uuid = it->second;
            return true;
        }
        return false;
    }

private:
    std::map<std::string, std::string> mockData;
};

// Sandesh client that uses the StateList and MockInterfaceTable
class SandeshClient {
public:
    SandeshClient(StateList& stateList, MockInterfaceTable& interfaceTable)
        : stateList(stateList), interfaceTable(interfaceTable) {}

    void issueGetRequest(const std::string& metadataIp) {
        if (interfaceTable.FindVmUuidFromMetadataIp(metadataIp, &vmUuid)) {
            // Simulate GET request logic here
            std::cout << "GET request issued to VM UUID: " << vmUuid << std::endl;
        } else {
            std::cerr << "Failed to find VM UUID for metadata IP" << std::endl;
        }
    }

private:
    StateList& stateList;
    MockInterfaceTable& interfaceTable;
    std::string vmUuid;
};

int main() {
    const size_t stateCount = 10;
    StateList stateList(stateCount);
    MockInterfaceTable interfaceTable;

    // Initialize the mock data
    interfaceTable.setMockData("192.168.1.1", "vm123");
    interfaceTable.setMockData("192.168.1.2", "vm456");

    SandeshClient sandeshClient(stateList, interfaceTable);

    // Issue GET requests in multiple threads to simulate concurrency
    std::vector<std::thread> threads;
    for (int i = 0; i < 5; ++i) {
        threads.emplace_back([&sandeshClient]() {
            sandeshClient.issueGetRequest("192.168.1." + std::to_string(rand() % 254));
        });
    }

    // Join all threads
    for (auto& thread : threads) {
        thread.join();
    }

    return 0;
}
