NFAPI_CRC_INDICATION_PDU_T* allocate_PDUs(uint32_t initial_size, float resize_threshold, float notification_threshold) {
    static NFAPI_CRC_INDICATION_PDU_T* pdus = NULL;
    static uint32_t capacity = 0;
    static uint32_t size = 0;

    if (pdus == NULL) {
        pdus = malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdus == NULL) {
            return NULL; // Memory allocation failed
        }
        capacity = initial_size;
    }

    if ((float)size / capacity > resize_threshold) {
        NFAPI_CRC_INDICATION_PDU_T* new_pdus = realloc(pdus, capacity * 2 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_pdus == NULL) {
            return pdus; // Realloc failed, use existing memory
        }
        pdus = new_pdus;
        capacity *= 2;
    }

    for (; size < capacity; ++size) {
        pdus[size].ue_info.RNTI = rand() % 1024; // Random RNTI
        pdus[size].CRCFLAG = (rand() % 2 == 0); // Random CRC flag
        time(&pdus[size].timestamp); // Current timestamp
    }

    if ((float)size / capacity > notification_threshold) {
        printf("Memory usage critical: %u of %u PDUs allocated\n", size, capacity);
    }

    return pdus;
}
