#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct DynamicArrayNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct DynamicArrayNode* next;
} DynamicArrayNode;

typedef struct {
    DynamicArrayNode* head;
    pthread_mutex_t mutex;
    uint32_t active_count;
} DynamicArray;

DynamicArray* dynamic_array_init() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;
    array->head = NULL;
    pthread_mutex_init(&array->mutex, NULL);
    array->active_count = 0;
    return array;
}

void dynamic_array_add(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&array->mutex);
    DynamicArrayNode* new_node = (DynamicArrayNode*)malloc(sizeof(DynamicArrayNode));
    if (!new_node) {
        pthread_mutex_unlock(&array->mutex);
        return;
    }
    memcpy(&new_node->data, &data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = array->head;
    array->head = new_node;
    array->active_count++;
    pthread_mutex_unlock(&array->mutex);
}

void dynamic_array_update_by_tag(DynamicArray* array, uint32_t tag, NFAPI_CRC_INDICATION_PDU_T new_data) {
    pthread_mutex_lock(&array->mutex);
    DynamicArrayNode* current = array->head;
    while (current != NULL) {
        if (current->data.RX_UE_INFORMATION_TAG == tag) {
            memcpy(&current->data, &new_data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&array->mutex);
}

void dynamic_array_serialize(DynamicArray* array, FILE* file) {
    pthread_mutex_lock(&array->mutex);
    fwrite(&array->active_count, sizeof(uint32_t), 1, file);
    DynamicArrayNode* current = array->head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }
    pthread_mutex_unlock(&array->mutex);
}

void dynamic_array_deserialize(DynamicArray* array, FILE* file) {
    pthread_mutex_lock(&array->mutex);
    uint32_t count;
    fread(&count, sizeof(uint32_t), 1, file);
    for (uint32_t i = 0; i < count; i++) {
        NFAPI_CRC_INDICATION_PDU_T data;
        fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        dynamic_array_add(array, data);
    }
    pthread_mutex_unlock(&array->mutex);
}

void dynamic_array_free(DynamicArray* array) {
    DynamicArrayNode* current = array->head;
    while (current != NULL) {
        DynamicArrayNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&array->mutex);
    free(array);
}
