    int *array = NULL;
    size_t array_size = 0;
    size_t current_size = 0;
    int max_value = INT_MIN;
    srand(time(NULL));

    while (1) {
        int value;
        if (scanf("%d", &value) != 1) {
            break;
        }
        if (array_size == current_size) {
            array_size *= 2;
            array = realloc(array, array_size * sizeof(int));
            if (!array) {
                fprintf(stderr, "Memory allocation failed\n");
                exit(EXIT_FAILURE);
            }
        }
        array[current_size++] = value;
        max_value = (value > max_value) ? value : max_value;
    }

    if (current_size == 0) {
        printf("Empty input list\n");
        free(array);
        return;
    }

    printf("Largest integer: %d\n", max_value);

