#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>

#define MAX_PENDING_QUERIES 10
#define TIMEOUT_SECONDS 5

typedef struct {
    char *hostname;
    int dns_server_priority;
    int retry_count;
} DNSQuery;

DNSQuery query_queue[MAX_PENDING_QUERIES];
int front = 0, rear = -1;

pthread_mutex_t queue_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t queue_not_full = PTHREAD_COND_INITIALIZER;
pthread_cond_t queue_not_empty = PTHREAD_COND_INITIALIZER;

void enqueue_query(DNSQuery *query) {
    pthread_mutex_lock(&queue_lock);
    while (rear == MAX_PENDING_QUERIES - 1) {
        pthread_cond_wait(&queue_not_full, &queue_lock);
    }
    if (rear == -1) front = 0;
    rear++;
    query_queue[rear] = *query;
    pthread_cond_signal(&queue_not_empty);
    pthread_mutex_unlock(&queue_lock);
}

DNSQuery dequeue_query() {
    DNSQuery query;
    pthread_mutex_lock(&queue_lock);
    while (front > rear) {
        pthread_cond_wait(&queue_not_empty, &queue_lock);
    }
    query = query_queue[front];
    front++;
    if (front > rear) {
        front = rear = -1;
    }
    pthread_cond_signal(&queue_not_full);
    pthread_mutex_unlock(&queue_lock);
    return query;
}

void *dns_query_thread(void *arg) {
    DNSQuery query = *(DNSQuery *)arg;
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(query.hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        char ipstr[INET6_ADDRSTRLEN];

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        printf("  %s\n", ipstr);
    }

    freeaddrinfo(res); // free the linked list
    return NULL;
}

void *dns_query_handler(void *arg) {
    while (1) {
        DNSQuery query = dequeue_query();
        pthread_t thread_id;
        pthread_create(&thread_id, NULL, dns_query_thread, &query);
        pthread_detach(thread_id);
    }
    return NULL;
}

int main() {
    pthread_t handler_thread;

    pthread_create(&handler_thread, NULL, dns_query_handler, NULL);

    DNSQuery query1 = {"example.com", 1, 3};
    DNSQuery query2 = {"google.com", 2, 5};

    enqueue_query(&query1);
    enqueue_query(&query2);

    pthread_join(handler_thread, NULL);

    return 0;
}
```

This code provides a basic framework for a multi-threaded DNS resolver. It uses a queue to manage pending queries and worker threads to handle each query concurrently. The `enqueue_query` function adds a new query to the queue, while the `dequeue_query` function removes a query from the front of the queue.

The `dns_query_thread` function is responsible for performing the actual DNS resolution using the standard library functions like `getaddrinfo`. It handles both IPv4 and IPv6 addresses and prints the resolved IP addresses.

The `main` function creates a handler thread that continuously processes queries from the queue. New queries are added to the queue using the `enqueue_query` function.

Please note that this code is a starting point and does not include all the features described in the task, such as error handling, logging, fallback mechanisms, resource management, and priority handling. You will need to implement these features based on your specific requirements.']

