        frames[i].SNR = RSRP_RANGE + rand_r(&seed) % SNR_RANGE;
        frames[i].RSRP = SNR_RANGE + rand_r(&seed) % RSRP_RANGE;
        frames[i].RSRQ = -35 + rand_r(&seed) % RSRQ_RANGE;
        frames[i].CHANNEL_QUALITY = (rand_r(&seed) % 100);
        pthread_mutex_unlock(&lock);
    }

    pthread_mutex_destroy(&lock);

    return frames;
