#define MAX_UE_CONTEXTS 1024

typedef struct {
    int ue_id;
    // Configuration parameters for different radio bearers
    // ...
    float lqi;  // Link Quality Indicator
    // Optional extended features
    // ...
} UEContext;

typedef struct {
    UEContext contexts[MAX_UE_CONTEXTS];
    size_t count;
    pthread_mutex_t lock;
} UEDatabase;

void init_uedatabase(UEDatabase *db) {
    db->count = 0;
    pthread_mutex_init(&db->lock, NULL);
}

int add_or_update_ue_context(UEDatabase *db, int ue_id, float lqi) {
    pthread_mutex_lock(&db->lock);
    for (size_t i = 0; i < db->count; ++i) {
        if (db->contexts[i].ue_id == ue_id) {
            // Update existing UE context
            db->contexts[i].lqi = lqi;
            pthread_mutex_unlock(&db->lock);
            return 0;
        }
    }
    if (db->count >= MAX_UE_CONTEXTS) {
        pthread_mutex_unlock(&db->lock);
        return -1;  // Database overflow
    }
    // Add new UE context
    db->contexts[db->count].ue_id = ue_id;
    db->contexts[db->count].lqi = lqi;
    ++db->count;
    pthread_mutex_unlock(&db->lock);
    return 0;
}

float get_lqi(UEDatabase *db, int ue_id) {
    pthread_mutex_lock(&db->lock);
    for (size_t i = 0; i < db->count; ++i) {
        if (db->contexts[i].ue_id == ue_id) {
            float lqi = db->contexts[i].lqi;
            pthread_mutex_unlock(&db->lock);
            return lqi;
        }
    }
    pthread_mutex_unlock(&db->lock);
    return -1.0f;  // UE context not found
}

void cleanup_uedatabase(UEDatabase *db) {
    pthread_mutex_destroy(&db->lock);
}
