    list->length = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
}

void add_crc_indication(NFAPI_CRC_INDICATION_LIST_T *list, int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&list->lock);
    if (list->length == list->capacity) {
        // Double the capacity
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_data == NULL) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&list->lock);
            exit(EXIT_FAILURE);
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }
    list->data[list->length].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    list->data[list->length].RNTI = RNTI;
    list->data[list->length].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    list->length++;
    pthread_mutex_unlock(&list->lock);
}

void update_crc_indication(NFAPI_CRC_INDICATION_LIST_T *list, int RX_UE_INFORMATION_TAG, int new_RNTI) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->length; ++i) {
        if (list->data[i].RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            list->data[i].RNTI = new_RNTI;
            pthread_mutex_unlock(&list->lock);
            return;
        }
    }
    // Handle not found
    pthread_mutex_unlock(&list->lock);
}

void free_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T *list) {
    pthread_mutex_lock(&list->lock);
    free(list->data);
    list->length = 0;
    list->capacity = 0;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
