import java.io.*;
import java.net.URL;
import java.util.concurrent.*;
import java.util.logging.*;

public class CommandExecutor {
    private static final Logger logger = Logger.getLogger(CommandExecutor.class.getName());
    private ExecutorService executorService;
    private CachingMechanism cachingMechanism;

    public CommandExecutor(int poolSize, boolean useInMemoryCache) {
        this.executorService = Executors.newFixedThreadPool(poolSize);
        if (useInMemoryCache) {
            this.cachingMechanism = new InMemoryCachingMechanism();
        } else {
            this.cachingMechanism = new PersistentStorageCachingMechanism("cache.db");
        }
    }

    public void executeCommand(String command, String outputFilename) throws IOException, InterruptedException {
        Callable<String> task = () -> {
            Process process = Runtime.getRuntime().exec(command);
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
                 BufferedWriter writer = new BufferedWriter(new FileWriter(outputFilename))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    writer.write(line + "\n");
                }
            }
            return outputFilename;
        };

        Future<String> future = executorService.submit(task);
        try {
            String result = future.get();
            logger.info("Command executed successfully: " + result);
        } catch (ExecutionException e) {
            logger.severe("Error executing command: " + e.getCause());
            throw new RuntimeException(e.getCause());
        }
    }

    public void shutdown() {
        executorService.shutdown();
    }
}

interface CachingMechanism {
    String get(String key) throws IOException;
    void put(String key, String value) throws IOException;
}

class InMemoryCachingMechanism implements CachingMechanism {
    private final ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();

    @Override
    public String get(String key) throws IOException {
        return cache.get(key);
    }

    @Override
    public void put(String key, String value) throws IOException {
        cache.put(key, value);
    }
}

