    RSA *rsa = RSA_new();
    BIGNUM *e = BN_new();
    BN_set_word(e, RSA_F4);

    if (!RSA_generate_key_ex(rsa, 2048, e, NULL)) {
        RSA_free(rsa);
        BN_free(e);
        return NULL;
    }

    BN_free(e);
    return rsa;
}

