['### C Function for NFAPI CRC Indication Management

```c
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct Node* next;
} Node;

typedef struct {
    pthread_mutex_t lock;
    Node* head;
} CRC_Indication_List;

void init_crc_list(CRC_Indication_List* list) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
}

int add_crc_indication(CRC_Indication_List* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return 1;
    }
    memcpy(&new_node->pdu, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int update_crc_indication(CRC_Indication_List* list, RX_UE_INFORMATION_TAG rx_ue_tag, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        if (current->pdu.rx_ue_tag == rx_ue_tag) {
            memcpy(&current->pdu, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return -1;
}

void free_crc_list(CRC_Indication_List* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
