### JavaScript Function for Uploading Files from URLs

```javascript
const axios = require('axios');
const fs = require('fs');
const path = require('path');

async function uploadFiles(urls, outputDir) {
    const results = [];

    for (let url of urls) {
        try {
            let response = await axios({
                method: 'get',
                url: url,
                responseType: 'stream'
            });

            let filename = path.basename(url);
            let outputPath = path.join(outputDir, filename);

            let writer = fs.createWriteStream(outputPath);
            response.data.pipe(writer);

            await new Promise((resolve, reject) => {
                writer.on('finish', resolve);
                writer.on('error', reject);
            });

            results.push({ url: url, outputUrl: outputPath });
        } catch (error) {
            console.error(`Failed to upload file from ${url}:`, error.message);
            results.push({ url: url, error: error.message });
        }
    }

    return results;
}
```

