#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_ITEMS 10000
#define MIN_AGE 18
#define MAX_AGE 65
#define MIN_BALANCE 0.0
#define MAX_BALANCE 1000000.0

typedef struct {
    char* name;
    int age;
    double balance;
} item;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

item* create_item(const char* name, int age, double balance) {
    item* i = (item*)malloc(sizeof(item));
    if (i == NULL) return NULL;
    i->name = strdup(name);
    i->age = age;
    i->balance = balance;
    return i;
}

void destroy_item(item* i) {
    free(i->name);
    free(i);
}

int validate_age(int age) {
    return age >= MIN_AGE && age <= MAX_AGE;
}

double validate_balance(double balance) {
    if (balance < MIN_BALANCE) return MIN_BALANCE;
    if (balance > MAX_BALANCE) return MAX_BALANCE;
    return balance;
}

item** create_item_collection(int count, const char* names[], int ages[], double balances[]) {
    pthread_mutex_lock(&mutex);
    item** collection = (item**)malloc(count * sizeof(item*));
    if (collection == NULL) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    for (int i = 0; i < count; i++) {
        int age = ages[i];
        double balance = balances[i];
        if (!validate_age(age) || balance != validate_balance(balance)) {
            destroy_item_collection(collection, i);
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
        collection[i] = create_item(names[i], age, balance);
        if (collection[i] == NULL) {
            destroy_item_collection(collection, i);
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
    }
    pthread_mutex_unlock(&mutex);
    return collection;
}

void destroy_item_collection(item** collection, int count) {
    for (int i = 0; i < count; i++) {
        destroy_item(collection[i]);
    }
    free(collection);
}
