#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct NFapiCrcIndicationPdu {
    int rxUeInformationTag;
    int rnti;
    int crcFlag;
    struct NFapiCrcIndicationPdu *next;
} NFapiCrcIndicationPdu;

typedef struct {
    pthread_mutex_t lock;
    NFapiCrcIndicationPdu *head;
} NFAPI_CRC_INDICATION_PDU_LIST;

void initList(NFAPI_CRC_INDICATION_PDU_LIST *list) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
}

int addEntry(NFAPI_CRC_INDICATION_PDU_LIST *list, int rxUeInformationTag, int rnti, int crcFlag) {
    pthread_mutex_lock(&list->lock);
    NFapiCrcIndicationPdu *current = list->head;
    while (current != NULL) {
        if (current->rnti == rnti) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Duplicate RNTI
        }
        current = current->next;
    }
    NFapiCrcIndicationPdu *newEntry = (NFapiCrcIndicationPdu *)malloc(sizeof(NFapiCrcIndicationPdu));
    if (newEntry == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failed
    }
    newEntry->rxUeInformationTag = rxUeInformationTag;
    newEntry->rnti = rnti;
    newEntry->crcFlag = crcFlag;
    newEntry->next = list->head;
    list->head = newEntry;
    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

NFapiCrcIndicationPdu *findEntry(NFAPI_CRC_INDICATION_PDU_LIST *list, int rnti) {
    pthread_mutex_lock(&list->lock);
    NFapiCrcIndicationPdu *current = list->head;
    while (current != NULL) {
        if (current->rnti == rnti) {
            pthread_mutex_unlock(&list->lock);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL; // Not found
}

void updateEntry(NFAPI_CRC_INDICATION_PDU_LIST *list, int rnti, int rxUeInformationTag) {
    NFapiCrcIndicationPdu *entry = findEntry(list, rnti);
    if (entry != NULL) {
        entry->rxUeInformationTag += rxUeInformationTag;
    }
}

void freeList(NFAPI_CRC_INDICATION_PDU_LIST *list) {
    pthread_mutex_lock(&list->lock);
    NFapiCrcIndicationPdu *current = list->head;
    while (current != NULL) {
        NFapiCrcIndicationPdu *next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
