int process_input() {
    int *array = NULL;
    size_t array_size = 0;
    size_t capacity = 1024; // Initial capacity

    // Dynamically allocate memory for the integer array
    array = (int *)malloc(capacity * sizeof(int));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    int value;
    while (scanf("%d", &value) != EOF) {
        // Handle integer overflow
        if (value > INT_MAX || value < INT_MIN) {
            fprintf(stderr, "Integer overflow detected\n");
            free(array);
            return -1;
        }

        // Resize the array if necessary
        if (array_size == capacity) {
            capacity *= 2;
            int *new_array = (int *)realloc(array, capacity * sizeof(int));
            if (new_array == NULL) {
                fprintf(stderr, "Memory reallocation failed\n");
                free(array);
                return -1;
            }
            array = new_array;
        }

        // Add the value to the array
        array[array_size++] = value;
    }

    // Find and print the largest integer in the array
    if (array_size > 0) {
        int max_value = INT_MIN;
        for (size_t i = 0; i < array_size; i++) {
            if ((long long)max_value + array[i] > INT_MAX) {
                fprintf(stderr, "Integer overflow detected while finding maximum value\n");
                free(array);
                return -1;
            }
            if (array[i] > max_value) {
                max_value = array[i];
            }
        }
        printf("Largest integer: %d\n", max_value);
    }

    // Free the allocated memory for the integer array
    free(array);

    return 0;
}

int main() {
    process_input();
    return 0;
}
