#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ARRAY_SIZE 1000
#define MEMORY_THRESHOLD 1024 * 1024 // 1 MB

typedef struct {
    int RNTI;
    RX_PACKET_INFO* packetInfo;
} NFAPI_MESSAGE_PDU_T;

typedef struct memory_pool {
    void* pool;
    size_t block_size;
    size_t num_blocks;
    size_t used_blocks;
    pthread_mutex_t lock;
} MEMORY_POOL;

NFAPI_MESSAGE_PDU_T** array;
size_t current_size;
size_t max_size;
MEMORY_POOL pool;

void init_memory_pool(size_t block_size, size_t num_blocks) {
    pool.pool = malloc(block_size * num_blocks);
    if (pool.pool == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    pool.block_size = block_size;
    pool.num_blocks = num_blocks;
    pool.used_blocks = 0;
    pthread_mutex_init(&pool.lock, NULL);
}

void* allocate_from_pool() {
    void* block;
    pthread_mutex_lock(&pool.lock);
    if (pool.used_blocks >= pool.num_blocks) {
        fprintf(stderr, "Memory pool exhausted\n");
        exit(1);
    }
    block = ((char*)pool.pool) + pool.block_size * pool.used_blocks;
    pool.used_blocks++;
    pthread_mutex_unlock(&pool.lock);
    return block;
}

void deallocate_to_pool(void* block) {
    pthread_mutex_lock(&pool.lock);
    size_t index = ((char*)block - (char*)pool.pool) / pool.block_size;
    if (index >= pool.num_blocks || index < 0) {
        fprintf(stderr, "Invalid block pointer\n");
        exit(1);
    }
    pool.used_blocks--;
    pthread_mutex_unlock(&pool.lock);
}

int insert_element(RX_UE_INFORMATION_TAG tag, int RNTI, RX_PACKET_INFO* packetInfo) {
    if (current_size >= max_size || memory_used() + sizeof(NFAPI_MESSAGE_PDU_T) > MEMORY_THRESHOLD) {
        return -1; // Array or memory limit exceeded
    }
    NFAPI_MESSAGE_PDU_T* newElement = allocate_from_pool();
    newElement->tag = tag;
    newElement->RNTI = RNTI;
    newElement->packetInfo = packetInfo;
    array[current_size++] = newElement;
    return 0;
}

int delete_element(size_t index) {
    if (index >= current_size) {
        return -1; // Invalid index
    }
    deallocate_to_pool(array[index]->packetInfo);
    free(array[index]);
    for (size_t i = index; i < current_size - 1; i++) {
        array[i] = array[i + 1];
    }
    current_size--;
    return 0;
}

int modify_element(size_t index, RX_UE_INFORMATION_TAG newTag, int newRNTI, RX_PACKET_INFO* newPacketInfo) {
    if (index >= current_size || memory_used() + sizeof(RX_PACKET_INFO) > MEMORY_THRESHOLD) {
        return -1; // Invalid index or memory limit exceeded
    }
    deallocate_to_pool(array[index]->packetInfo);
    array[index]->tag = newTag;
    array[index]->RNTI = newRNTI;
    array[index]->packetInfo = newPacketInfo;
    return 0;
}

size_t memory_used() {
    size_t totalMemory = current_size * sizeof(NFAPI_MESSAGE_PDU_T) + pool.used_blocks * pool.block_size;
    return totalMemory;
}

// Add additional functions for external data handling, error checking, and system scalability
