PacketArray* packetArrayCreate(size_t initialCapacity, size_t maxPayloadSize) {
    PacketArray *array = (PacketArray*)malloc(sizeof(PacketArray));
    if (!array) {
        fprintf(stderr, "Memory allocation failed for PacketArray.\n");
        return NULL;
    }
    array->headers = (PacketHeader**)malloc(initialCapacity * sizeof(PacketHeader*));
    if (!array->headers) {
        free(array);
        fprintf(stderr, "Memory allocation failed for headers.\n");
        return NULL;
    }
    array->count = 0;
    array->capacity = initialCapacity;
    array->maxPayloadSize = maxPayloadSize;
    return array;
}

void packetArrayAdd(PacketArray *array, PayloadType type, long timestamp, const char *payloadData, size_t payloadSize) {
    if (array->count >= array->capacity) {
        size_t newCapacity = array->capacity ? array->capacity * 2 : 1;
        PacketHeader **newHeaders = (PacketHeader**)realloc(array->headers, newCapacity * sizeof(PacketHeader*));
        if (!newHeaders) {
            fprintf(stderr, "Memory reallocation failed for headers.\n");
            return;
        }
        array->headers = newHeaders;
        array->capacity = newCapacity;
    }

    PacketHeader *header = (PacketHeader*)malloc(sizeof(PacketHeader));
    if (!header) {
        fprintf(stderr, "Memory allocation failed for PacketHeader.\n");
        return;
    }

    header->type = type;
    header->timestamp = timestamp;
    header->payloadSize = payloadSize;

    header->payloadData = (char*)malloc(payloadSize);
    if (!header->payloadData) {
        free(header);
        fprintf(stderr, "Memory allocation failed for payload data.\n");
        return;
    }
    memcpy(header->payloadData, payloadData, payloadSize);

    array->headers[array->count++] = header;

    if (payloadSize > array->maxPayloadSize) {
        fprintf(stderr, "Payload size exceeds maximum allowed: %zu\n", payloadSize);
        packetArrayRemoveLast(array);
    }
}

void packetArrayIterate(PacketArray *array, void (*checkFunction)(PacketHeader*)) {
    for (size_t i = 0; i < array->count; ++i) {
        checkFunction(array->headers[i]);
    }
}

void packetArrayFree(PacketArray *array) {
    if (!array) return;

    for (size_t i = 0; i < array->count; ++i) {
        PacketHeader *header = array->headers[i];
        free(header->payloadData);
        free(header);
    }

    free(array->headers);
    free(array);
}

void exampleCheckFunction(PacketHeader *header) {
    // Example check: Ensure payload size is within a reasonable range
    if (header->payloadSize < 10 || header->payloadSize > 1000) {
        fprintf(stderr, "Payload size out of acceptable range for type %d\n", header->type);
    }
}

