        pdus[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdus[i] == NULL) {
            // Handle memory allocation error
            free(pdus);  // Free previously allocated structures
            pthread_mutex_unlock(&mutex);
            return;
