} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    int count;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->head = NULL;
    array->count = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    Node* current = array->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int add_element(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&array->mutex);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        pthread_mutex_unlock(&array->mutex);
        return -1; // Memory allocation failed
    }
    new_node->data = data;
    new_node->next = array->head;
    array->head = new_node;
    array->count++;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int remove_element(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&array->mutex);
    Node* current = array->head;
    Node* previous = NULL;
    while (current != NULL) {
        if (memcmp(&current->data, &data, sizeof(NFAPI_CRC_INDICATION_PDU_T)) == 0) {
            if (previous == NULL) {
                array->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            array->count--;
            pthread_mutex_unlock(&array->mutex);
            return 0; // Element found and removed
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&array->mutex);
    return -1; // Element not found
}

void iterate_dynamic_array(DynamicArray* array, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&array->mutex);
    Node* current = array->head;
    while (current != NULL) {
        callback(current->data);
        current = current->next;
    }
    pthread_mutex_unlock(&array->mutex);
}
