NFAPI_MESSAGE_T** initialize_napi_messages(int N, int threshold) {
    NFAPI_MESSAGE_T** messages = (NFAPI_MESSAGE_T**)malloc(N * sizeof(NFAPI_MESSAGE_T*));
    if (!messages) return NULL;

    for (int i = 0; i < N; i++) {
        messages[i] = (NFAPI_MESSAGE_T*)malloc(sizeof(NFAPI_MESSAGE_T));
        if (!messages[i]) {
            // Free previously allocated memory
            for (int j = 0; j < i; j++) free(messages[j]);
            free(messages);
            return NULL;
        }

        messages[i]->type = NFAPI_MESSAGE_TYPE_RX_FRAME;
        messages[i]->rx_frame = (NFAPI_RX_FRAME_T*)malloc(sizeof(NFAPI_RX_FRAME_T));
        if (!messages[i]->rx_frame) {
            // Free previously allocated memory
            for (int j = 0; j <= i; j++) free(messages[j]->rx_frame);
            free(messages[i]);
            for (int j = 0; j < i; j++) free(messages[j]);
            free(messages);
            return NULL;
        }

        messages[i]->raw_rf_data = (uint8_t*)malloc(1024 * sizeof(uint8_t)); // Example size
        if (!messages[i]->raw_rf_data) {
            // Free previously allocated memory
            for (int j = 0; j <= i; j++) free(messages[j]->raw_rf_data);
            free(messages[i]->rx_frame);
            free(messages[i]);
            for (int j = 0; j < i; j++) free(messages[j]->rx_frame);
            free(messages[j]);
            free(messages);
            return NULL;
        }

        // Initialize message fields
    }

    return messages;
}

void destroy_napi_messages(NFAPI_MESSAGE_T** messages, int N) {
    for (int i = 0; i < N; i++) {
        free(messages[i]->raw_rf_data);
        free(messages[i]->rx_frame);
        free(messages[i]);
    }
    free(messages);
}

void* process_message(void* arg) {
    // Process message logic
    return NULL;
}

int main() {
    int N = 10; // Number of messages
    int threshold = -95; // Signal strength threshold

    NFAPI_MESSAGE_T** messages = initialize_napi_messages(N, threshold);
    if (!messages) {
        perror("Failed to allocate memory for messages");
        return EXIT_FAILURE;
    }

    pthread_t threads[N];
    for (int i = 0; i < N; i++) {
        if (pthread_create(&threads[i], NULL, process_message, messages[i])) {
            perror("Failed to create thread");
            destroy_napi_messages(messages, N);
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < N; i++) {
        pthread_join(threads[i], NULL);
    }

    destroy_napi_messages(messages, N);

    return EXIT_SUCCESS;
}
