#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    int id;
    float throughput;
    float errorRate;
} NetworkReport;

typedef struct Node {
    NetworkReport data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t mutex;
} DynamicArray;

void initDynamicArray(DynamicArray* array) {
    array->head = NULL;
    array->tail = NULL;
    pthread_mutex_init(&array->mutex, NULL);
}

void addReport(DynamicArray* array, NetworkReport report) {
    pthread_mutex_lock(&array->mutex);
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = report;
    newNode->next = NULL;

    if (array->head == NULL) {
        array->head = newNode;
        array->tail = newNode;
    } else {
        array->tail->next = newNode;
        array->tail = newNode;
    }
    pthread_mutex_unlock(&array->mutex);
}

void updateReport(DynamicArray* array, int id, NetworkReport newReport) {
    pthread_mutex_lock(&array->mutex);
    Node* current = array->head;

    while (current != NULL && current->data.id != id) {
        current = current->next;
    }

    if (current != NULL) {
        current->data = newReport;
    }
    pthread_mutex_unlock(&array->mutex);
}

Node* getReportsByTimestampRange(DynamicArray* array, time_t start, time_t end) {
    Node* resultHead = NULL;
    Node* resultTail = NULL;

    pthread_mutex_lock(&array->mutex);
    Node* current = array->head;

    while (current != NULL) {
        if (current->data.timestamp >= start && current->data.timestamp <= end) {
            Node* newNode = (Node*)malloc(sizeof(Node));
            newNode->data = current->data;
            newNode->next = NULL;

            if (resultHead == NULL) {
                resultHead = newNode;
                resultTail = newNode;
            } else {
                resultTail->next = newNode;
                resultTail = newNode;
            }
        }
        current = current->next;
    }

    pthread_mutex_unlock(&array->mutex);
    return resultHead;
}

void freeDynamicArray(DynamicArray* array) {
    Node* current = array->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&array->mutex);
}
