#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU;

typedef struct {
    NFAPI_CRC_INDICATION_PDU *head;
    pthread_mutex_t mutex;
} CRC_LIST;

CRC_LIST* create_crc_list() {
    CRC_LIST* list = (CRC_LIST*)malloc(sizeof(CRC_LIST));
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

int insert_into_crc_list(CRC_LIST* list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    if (RNTI <= 0 || RNTI > 65535) {
        printf("Invalid RNTI value: %d\n", RNTI);
        return -1;
    }

    pthread_mutex_lock(&list->mutex);

    NFAPI_CRC_INDICATION_PDU *current = list->head;
    while (current != NULL) {
        if (current->RNTI == RNTI) {
            printf("Duplicate RNTI: %d\n", RNTI);
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }
        current = current->next;
    }

    NFAPI_CRC_INDICATION_PDU *new_node = (NFAPI_CRC_INDICATION_PDU*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
    new_node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->RNTI = RNTI;
    new_node->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void iterate_and_update_crc(CRC_LIST* list, int (*update_function)(NFAPI_CRC_INDICATION_PDU*, void*), void* data) {
    pthread_mutex_lock(&list->mutex);

    NFAPI_CRC_INDICATION_PDU *current = list->head;
    while (current != NULL) {
        update_function(current, data);
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
}

void free_crc_list(CRC_LIST* list) {
    pthread_mutex_lock(&list->mutex);

    NFAPI_CRC_INDICATION_PDU *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU *temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;

    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

// Example usage
int update_crc(NFAPI_CRC_INDICATION_PDU* node, void* data) {
    int signal_strength = *(int*)data;
    if (signal_strength < 20) { // Assuming threshold of 20 for weak signals
        node->CRC_INDICATION_REL8_TAG = 0; // Update CRC flag based on signal strength
    }
    return 0;
}
