#define MAX_EVENTS 10000

typedef struct Event {
    long timestamp;
    int cellID;
    int signalStrength;
    int qualityIndicators;
} Event;

Event events[MAX_EVENTS];
int eventCount = 0;
pthread_mutex_t mutex;

int addEvent(long timestamp, int cellID, int signalStrength, int qualityIndicators) {
    pthread_mutex_lock(&mutex);
    if (eventCount >= MAX_EVENTS) {
        pthread_mutex_unlock(&mutex);
        return -1; // Error: Event buffer full
    }
    events[eventCount].timestamp = timestamp;
    events[eventCount].cellID = cellID;
    events[eventCount].signalStrength = signalStrength;
    events[eventCount].qualityIndicators = qualityIndicators;
    eventCount++;
    pthread_mutex_unlock(&mutex);
    return 0; // Success
}

int updateEvent(int cellID, long timestamp, int signalStrength, int qualityIndicators) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < eventCount; i++) {
        if (events[i].cellID == cellID) {
            events[i].timestamp = timestamp;
            events[i].signalStrength = signalStrength;
            events[i].qualityIndicators = qualityIndicators;
            pthread_mutex_unlock(&mutex);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&mutex);
    return -1; // Error: Event not found
}

Event* getLatestEvent(int cellID) {
    pthread_mutex_lock(&mutex);
    for (int i = eventCount - 1; i >= 0; i--) {
        if (events[i].cellID == cellID) {
            pthread_mutex_unlock(&mutex);
            return &events[i];
        }
    }
    pthread_mutex_unlock(&mutex);
    return NULL; // Error: Event not found
}

void* databaseWorker(void* arg) {
