        printf("Latest event for cellID 1: Timestamp=%ld, SignalStrength=%d, QualityIndicators=%d\n",
               latestEvent->timestamp, latestEvent->signalStrength, latestEvent->qualityIndicators);
    }

    pthread_join(dbThread, NULL);
    return 0;
}
