typedef struct ListElement {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListElement* next;
} ListElement;

typedef struct {
    ListElement* head;
    pthread_mutex_t mutex;
    size_t max_size;
} SafeList;

void init_safe_list(SafeList* list, size_t max_size) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    list->max_size = max_size;
}

void destroy_safe_list(SafeList* list) {
    while (list->head != NULL) {
        ListElement* temp = list->head;
        list->head = list->head->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->mutex);
}

int insert_to_safe_list(SafeList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    if (list_size(list) >= list->max_size) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // List is full
    }
    ListElement* new_element = malloc(sizeof(ListElement));
    if (new_element == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return -2; // Memory allocation failed
    }
    new_element->data = data;
    new_element->next = list->head;
    list->head = new_element;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

size_t list_size(SafeList* list) {
    size_t count = 0;
    ListElement* current = list->head;
    while (current != NULL) {
        count++;
        current = current->next;
    }
    return count;
}

void log_operation(const char* operation, time_t timestamp, size_t element_count) {
