#define MAX_DEVICES 1024
#define MAX_PACKETS 512

typedef struct {
    time_t timestamp;
    int device_id;
    double throughput[MAX_PACKETS];
} NetworkDeviceStats;

NetworkDeviceStats device_stats[MAX_DEVICES];
int device_count = 0;

void update_device_stats(int device_id, double *throughput, int packet_count) {
    for (int i = 0; i < device_count; i++) {
        if (device_stats[i].device_id == device_id) {
            memcpy(device_stats[i].throughput, throughput, packet_count * sizeof(double));
            return;
        }
    }
    if (device_count < MAX_DEVICES) {
        device_stats[device_count].timestamp = time(NULL);
        device_stats[device_count].device_id = device_id;
        memcpy(device_stats[device_count].throughput, throughput, packet_count * sizeof(double));
        device_count++;
    }
}

void clear_old_entries(time_t cutoff_time) {
    for (int i = 0; i < device_count; i++) {
        if (device_stats[i].timestamp < cutoff_time) {
            for (int j = i; j < device_count - 1; j++) {
                device_stats[j] = device_stats[j + 1];
            }
            device_count--;
            i--; // Adjust index after removal
        }
    }
}
