NFAPI_CRC_INDICATION_PDU_T* generate_NFAPDU_list(int *size, int compress) {
    srand(time(0));
    int max_size = MAX_ENTRIES;
    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!list) {
        return NULL; // Memory allocation failed
    }

    unsigned short prev_RNTI = 65536; // Initial value outside the valid range
    for (int i = 0; i < max_size; ++i) {
        list[i].RX_UE_INFORMATION_TAG = i + 1;
        do {
            list[i].RNTI = rand() % 65536; // Random RNTI in the valid range
        } while (list[i].RNTI == prev_RNTI);
        prev_RNTI = list[i].RNTI;
        list[i].CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0; // Random CRCFLAG
    }

    *size = max_size;

    if (compress && *size > MAX_ENTRIES / 2) {
        NFAPI_CRC_INDICATION_PDU_T *compressed_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_ENTRIES / 2 * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!compressed_list) {
            free(list);
            return NULL; // Memory allocation failed
        }

        int compressed_size = 0;
        for (int i = 1; i < max_size; ++i) {
            if (list[i].RNTI != list[i - 1].RNTI) {
                compressed_list[compressed_size++] = list[i];
            }
        }

        *size = compressed_size;
        free(list);
        return compressed_list;
    } else {
        return list;
    }
}

int main() {
