    struct Event *next;
} Event;

Event* events[MAX_EVENTS];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void add_event(int cell_id, long timestamp, float signal_strength, float quality_indicators, int rx_ue_information_tag, int rnti, int crc_flag) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_EVENTS; i++) {
        if (events[i] == NULL) {
            Event* new_event = (Event*)malloc(sizeof(Event));
            new_event->cell_id = cell_id;
            new_event->timestamp = timestamp;
            new_event->signal_strength = signal_strength;
            new_event->quality_indicators = quality_indicators;
            new_event->pdu.rx_ue_information_tag = rx_ue_information_tag;
            new_event->pdu.rnti = rnti;
            new_event->pdu.crc_flag = crc_flag;
            new_event->next = NULL;
            events[i] = new_event;
            pthread_mutex_unlock(&mutex);
            return;
        }
    }
    // Handle event overflow
    printf("Event overflow, cannot add more events.\n");
    pthread_mutex_unlock(&mutex);
}

void update_event(int cell_id, long timestamp, float signal_strength, float quality_indicators, int rx_ue_information_tag, int rnti, int crc_flag) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_EVENTS; i++) {
        if (events[i] != NULL && events[i]->cell_id == cell_id) {
            events[i]->timestamp = timestamp;
            events[i]->signal_strength = signal_strength;
            events[i]->quality_indicators = quality_indicators;
            events[i]->pdu.rx_ue_information_tag = rx_ue_information_tag;
            events[i]->pdu.rnti = rnti;
            events[i]->pdu.crc_flag = crc_flag;
            pthread_mutex_unlock(&mutex);
            return;
        }
    }
    // Handle event not found
    printf("Event for cell ID %d not found.\n", cell_id);
    pthread_mutex_unlock(&mutex);
}

Event* get_latest_event(int cell_id) {
    pthread_mutex_lock(&mutex);
    Event* latest_event = NULL;
    long max_timestamp = 0;
    for (int i = 0; i < MAX_EVENTS; i++) {
        if (events[i] != NULL && events[i]->cell_id == cell_id && events[i]->timestamp > max_timestamp) {
            latest_event = events[i];
            max_timestamp = events[i]->timestamp;
        }
    }
    pthread_mutex_unlock(&mutex);
    return latest_event;
}

