#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct LTE_RRC_NAS_Transaction {
    int transaction_id;
    int nas_message_type;
    size_t nas_payload_size;
} LTE_RRC_NAS_Transaction;

typedef struct DynamicArray {
    LTE_RRC_NAS_Transaction *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *array = malloc(sizeof(DynamicArray));
    if (array == NULL) return NULL;

    array->data = realloc(NULL, initial_capacity * sizeof(LTE_RRC_NAS_Transaction));
    if (array->data == NULL) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    if (array != NULL) {
        pthread_mutex_destroy(&array->lock);
        free(array->data);
        free(array);
    }
}

int add_transaction(DynamicArray *array, LTE_RRC_NAS_Transaction transaction) {
    pthread_mutex_lock(&array->lock);

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        LTE_RRC_NAS_Transaction *new_data = realloc(array->data, new_capacity * sizeof(LTE_RRC_NAS_Transaction));

        if (new_data == NULL) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failure
        }

        array->data = new_data;
        array->capacity = new_capacity;
    }

    array->data[array->size++] = transaction;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

int get_transaction(DynamicArray *array, int transaction_id, LTE_RRC_NAS_Transaction *result) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].transaction_id == transaction_id) {
            *result = array->data[i];
            pthread_mutex_unlock(&array->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&array->lock);
    return -1; // Transaction not found
}

int remove_transaction(DynamicArray *array, int transaction_id) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].transaction_id == transaction_id) {
            while (i + 1 < array->size) {
                array->data[i] = array->data[i + 1];
                ++i;
            }
            --array->size;

            // Resize the array to half of its current capacity if it's less than a quarter full
            if (array->size <= array->capacity / 4) {
                size_t new_capacity = array->capacity / 2;
                LTE_RRC_NAS_Transaction *new_data = realloc(array->data, new_capacity * sizeof(LTE_RRC_NAS_Transaction));

                if (new_data == NULL) {
                    pthread_mutex_unlock(&array->lock);
                    return -1; // Memory allocation failure
                }

                array->data = new_data;
                array->capacity = new_capacity;
            }

            pthread_mutex_unlock(&array->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&array->lock);
    return -1; // Transaction not found
}
```

This code provides a thread-safe implementation of a dynamic array for managing `LTE_RRC_NAS_Transaction` structures. It includes functions for creating, destroying, adding, retrieving, and removing transactions while ensuring efficient memory usage and concurrent access safety. The use of mutexes ensures that only one thread can modify the array at a time, preventing race conditions and deadlocks."]

