    MeasurementListNode** current = &head;

    for (int i = 0; i < count; i++) {
        LTE_MEASUREMENT_REPORT_T report = reports[i];
        if (i > 0 && abs(report.CELL_ID - current[-1]->report.CELL_ID) < MIN_CELL_ID_DIFF) {
            report.CELL_ID += MIN_CELL_ID_DIFF;
        }
        LTE_MEASUREMENT_DATA data = { rand() % 100 }; // Generate random measurement value
