#define MAX_CONNECTIONS 500

typedef struct {
    int connection_id;
    char src_ip[16];
    char dest_ip[16];
    int src_port;
    int dest_port;
    time_t start_time;
    time_t end_time;
    double packet_loss_rate;
    double throughput;
    double latency;
} TCP_CONNECTION_RECORD;

typedef struct {
    TCP_CONNECTION_RECORD records[MAX_CONNECTIONS];
    int count;
} ConnectionManager;

ConnectionManager* create_connection_manager() {
    ConnectionManager* manager = (ConnectionManager*)malloc(sizeof(ConnectionManager));
    if (manager) {
        memset(manager, 0, sizeof(ConnectionManager));
    }
    return manager;
}

int add_or_update_connection(ConnectionManager* manager, TCP_CONNECTION_RECORD record) {
    for (int i = 0; i < manager->count; i++) {
        if (manager->records[i].connection_id == record.connection_id) {
            manager->records[i] = record;
            return 1; // Updated
        }
    }
    if (manager->count < MAX_CONNECTIONS) {
        manager->records[manager->count++] = record;
        return 2; // Added new
    }
    return 0; // No space left
}

TCP_CONNECTION_RECORD* get_most_recent_stats(ConnectionManager* manager, char* src_ip, char* dest_ip) {
    TCP_CONNECTION_RECORD* most_recent = NULL;
    for (int i = 0; i < manager->count; i++) {
        if (strcmp(manager->records[i].src_ip, src_ip) == 0 && strcmp(manager->records[i].dest_ip, dest_ip) == 0) {
            if (!most_recent || manager->records[i].end_time > most_recent->end_time) {
                most_recent = &manager->records[i];
            }
        }
    }
    return most_recent;
}

void destroy_connection_manager(ConnectionManager* manager) {
    free(manager);
}
