typedef struct {
    MAC_RX_STATS_T* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArrayT;

DynamicArrayT* dynamic_array_create() {
    DynamicArrayT* array = (DynamicArrayT*)malloc(sizeof(DynamicArrayT));
    if (!array) return NULL;

    array->data = NULL;
    array->capacity = 0;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

int dynamic_array_append(DynamicArrayT* array, MAC_RX_STATS_T item) {
    pthread_mutex_lock(&array->lock);
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 10;
        MAC_RX_STATS_T* new_data = (MAC_RX_STATS_T*)realloc(array->data, new_capacity * sizeof(MAC_RX_STATS_T));
        if (!new_data) {
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }
    array->data[array->size++] = item;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

void dynamic_array_free(DynamicArrayT* array) {
    if (array) {
        pthread_mutex_destroy(&array->lock);
        free(array->data);
        free(array);
    }
}
