#include <stdio.h>
#include <stdlib.h>

typedef struct NFAPI_RRC_MESSAGE_T {
    int cellIdentity;
    void* sRBsToAddMod;
    void* sRBsToRelease;
    struct NFAPI_RRC_MESSAGE_T* prev;
    struct NFAPI_RRC_MESSAGE_T* next;
} NFAPI_RRC_MESSAGE_T;

typedef struct DoublyLinkedList {
    NFAPI_RRC_MESSAGE_T* head;
    NFAPI_RRC_MESSAGE_T* tail;
    int size;
} DoublyLinkedList;

DoublyLinkedList* createList() {
    DoublyLinkedList* list = (DoublyLinkedList*)custom_malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    list->size = 0;
    return list;
}

void freeList(DoublyLinkedList* list) {
    NFAPI_RRC_MESSAGE_T* current = list->head;
    while (current != NULL) {
        NFAPI_RRC_MESSAGE_T* next = current->next;
        custom_free(current->sRBsToAddMod);
        custom_free(current->sRBsToRelease);
        custom_free(current);
        current = next;
    }
    custom_free(list);
}

NFAPI_RRC_MESSAGE_T* createNode(int cellIdentity, void* sRBsToAddMod, void* sRBsToRelease) {
    NFAPI_RRC_MESSAGE_T* node = (NFAPI_RRC_MESSAGE_T*)custom_malloc(sizeof(NFAPI_RRC_MESSAGE_T));
    if (!node) return NULL;
    node->cellIdentity = cellIdentity;
    node->sRBsToAddMod = sRBsToAddMod;
    node->sRBsToRelease = sRBsToRelease;
    node->prev = node->next = NULL;
    return node;
}

int insertNode(DoublyLinkedList* list, int cellIdentity, void* sRBsToAddMod, void* sRBsToRelease) {
    if (list == NULL || containsNode(list, cellIdentity)) {
        return -1; // Node already exists or list is invalid
    }
    NFAPI_RRC_MESSAGE_T* newNode = createNode(cellIdentity, sRBsToAddMod, sRBsToRelease);
    if (newNode == NULL) {
        return -2; // Memory allocation failed
    }
    if (list->tail == NULL) {
        list->head = list->tail = newNode;
    } else {
        list->tail->next = newNode;
        newNode->prev = list->tail;
        list->tail = newNode;
    }
    list->size++;
    return 0;
}

int deleteNode(DoublyLinkedList* list, int cellIdentity) {
    if (list == NULL || !containsNode(list, cellIdentity)) {
        return -1; // Node not found or list is invalid
    }
    NFAPI_RRC_MESSAGE_T* current = list->head;
    while (current != NULL && current->cellIdentity != cellIdentity) {
        current = current->next;
    }
    if (current->prev == NULL) {
        list->head = current->next;
    } else {
        current->prev->next = current->next;
    }
    if (current->next == NULL) {
        list->tail = current->prev;
    } else {
        current->next->prev = current->prev;
    }
    custom_free(current->sRBsToAddMod);
    custom_free(current->sRBsToRelease);
    custom_free(current);
    list->size--;
    return 0;
}

int containsNode(DoublyLinkedList* list, int cellIdentity) {
    NFAPI_RRC_MESSAGE_T* current = list->head;
    while (current != NULL) {
        if (current->cellIdentity == cellIdentity) {
            return 1;
        }
        current = current->next;
    }
    return 0;
}

// Custom memory allocation and synchronization functions
void* custom_malloc(size_t size);
void custom_free(void* ptr);

// Unit tests for the implementation
void runTests();
