#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int timestamp;
    int device_id;
    double throughput;
} NetworkStats;

typedef struct Node {
    NetworkStats data;
    struct Node* next;
} ListNode;

typedef struct {
    ListNode* head;
    pthread_mutex_t lock;
} NetworkStatList;

void initNetworkStatList(NetworkStatList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void addOrUpdateStats(NetworkStatList* list, int timestamp, int device_id, double throughput) {
    pthread_mutex_lock(&list->lock);
    ListNode* current = list->head;
    while (current != NULL) {
        if (current->data.device_id == device_id) {
            current->data.timestamp = timestamp;
            current->data.throughput = throughput;
            pthread_mutex_unlock(&list->lock);
            return;
        }
        current = current->next;
    }
    ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
    if (newNode == NULL) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    newNode->data.timestamp = timestamp;
    newNode->data.device_id = device_id;
    newNode->data.throughput = throughput;
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
}

void clearOldStats(NetworkStatList* list, int maxAge) {
    pthread_mutex_lock(&list->lock);
    ListNode* current = list->head;
    ListNode* prev = NULL;
    while (current != NULL) {
        if ((current->data.timestamp - maxAge) > 0) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            current = prev->next;
        } else {
            prev = current;
            current = current->next;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void printStats(NetworkStatList* list) {
    pthread_mutex_lock(&list->lock);
    ListNode* current = list->head;
    while (current != NULL) {
        printf("Timestamp: %d, Device ID: %d, Throughput: %.2f\n",
               current->data.timestamp,
               current->data.device_id,
               current->data.throughput);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void destroyNetworkStatList(NetworkStatList* list) {
    pthread_mutex_lock(&list->lock);
    ListNode* current = list->head;
    while (current != NULL) {
        ListNode* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
