typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

EVP_CIPHER* generateNfapiPdus(NFAPI_CRC_INDICATION_PDU_T** pdus, int numPDUs, unsigned int seed) {
    EVP_CIPHER* ciphers[numPDUs];
    srand(seed);

    for (int i = 0; i < numPDUs; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pdu->RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu->RNTI = rand() % 1000;
        pdu->CRC_INDICATION_REL8_TAG = rand() % 2;

        int mode = rand() % 5; // 0: NULL, 1: ECB, 2: EDE, 3: EDE3, 4: CFB
        switch (mode) {
            case 0:
                ciphers[i] = EVP_enc_null();
                break;
            case 1:
                ciphers[i] = EVP_des_ecb();
                break;
            case 2:
                ciphers[i] = EVP_des_ede();
                break;
            case 3:
                ciphers[i] = EVP_des_ede3();
                break;
            default:
                ciphers[i] = EVP_cfb128();
                break;
        }
    }

    *pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numPDUs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memcpy(*pdus, pdus, numPDUs * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < numPDUs; i++) {
        free(pdus[i]);
    }

    return ciphers[0]; // Return the cipher used for the first PDU
}
