#include <openssl/des.h>

#define MAX_INSTANCES 1000

typedef struct {
    int unique_id;
    time_t timestamp;
    RX_UE_INFORMATION_TAG ue_info_tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T instances[MAX_INSTANCES];
    int instance_count;
    int max_instances;
    pthread_mutex_t lock;
} NFAPI_CRYPTO_MODULE_T;

NFAPI_CRYPTO_MODULE_T crypto_module = {0};

void generate_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->unique_id = crypto_module.instance_count++;
    pdu->timestamp = time(NULL);
    // Randomize RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    pdu->ue_info_tag = rand();
    pdu->rnti = (uint16_t)rand();
    pdu->crc_ind_rel8_tag = rand();
    // Set a random CRCFLAG
    pdu->crcflag = rand() % 2;
}

void init_crypto_module(int max_instances) {
    crypto_module.max_instances = max_instances;
    pthread_mutex_init(&crypto_module.lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu() {
    if (crypto_module.instance_count >= crypto_module.max_instances) {
        // Log error and handle gracefully
        return NULL;
    }

