    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* generateNFAPIPDUs(void* args) {
    int numPDUs = *(int*)args;
    NFAPI_CRC_INDICATION_PDU_T* PDUs = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numPDUs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!PDUs) {
        return (void*)-1; // Memory allocation failed
    }

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);
    pthread_mutex_lock(&mutex);

    uint16_t prevRNTI = 0;
    for (int i = 0; i < numPDUs; i++) {
        PDUs[i].RX_UE_INFORMATION_TAG = i + 1;
        do {
            PDUs[i].RNTI = rand() % 65534 + 1; // Generate random RNTI
        } while (PDUs[i].RNTI == prevRNTI); // Ensure no two consecutive PDUs have the same RNTI
        prevRNTI = PDUs[i].RNTI;
        PDUs[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    }

    pthread_mutex_unlock(&mutex);
    free(args);

    return (void*)PDUs;
}

int main() {
    int numPDUs = 10000;
    void* result = generateNFAPIPDUs((void*)&numPDUs);
    if ((long)result == -1) {
        // Handle memory allocation failure
    } else {
        // Process PDUs and serialize to byte buffer
        free(result); // Free allocated memory
    }

    return 0;
}
