void initialize_crc_indication_list(CRC_INDICATION_LIST_T* list, size_t initial_capacity) {
    list->list = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list->list == NULL) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

void add_crc_indication(CRC_INDICATION_LIST_T* list, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list->mutex);
    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_list = realloc(list->list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_list == NULL) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&list->mutex);
            exit(EXIT_FAILURE);
        }
        list->list = new_list;
        list->capacity = new_capacity;
    }
    memcpy(&list->list[list->count], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->count++;
    pthread_mutex_unlock(&list->mutex);
}

