#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_populate_list(int N, int *successful_allocations) {
    NFAPI_CRC_INDICATION_PDU_T* list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list == NULL) {
        printf("Memory allocation failed\n");
        *successful_allocations = 0;
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    for (int i = 0; i < N; i++) {
        pthread_mutex_lock(&mutex);
        while ((i + 1) % 100 == 0 && list[i - 1].CRC_INDICATION_REL8_TAG == 0) {
            pthread_cond_wait(&cond, &mutex);
        }
        pthread_mutex_unlock(&mutex);

        list[i].RX_UE_INFORMATION_TAG = i;
        list[i].RNTI = i * 2;
        list[i].CRC_INDICATION_REL8_TAG = rand() % 2;

        if (i < N - 1) {
            pthread_mutex_lock(&mutex);
            list[i + 1].CRC_INDICATION_REL8_TAG = list[i].CRC_INDICATION_REL8_TAG;
            pthread_cond_signal(&cond);
            pthread_mutex_unlock(&mutex);
        }
    }

    *successful_allocations = N;
    return list;
}

int main() {
    int N = 5000;
    int successful_allocations;

    clock_t start, end;
    double cpu_time_used;

    start = clock();
    NFAPI_CRC_INDICATION_PDU_T* list = create_populate_list(N, &successful_allocations);
    end = clock();

    if (list != NULL) {
        free(list);
    }

    cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC;
    printf("Time taken: %f seconds\n", cpu_time_used);

    return 0;
}
