typedef struct {
    time_t TIME_STAMP;
    int CELL_ID;
    int RX_SIGNAL_LEVEL;
} PHY_STATS_RECORD;

PHY_STATS_RECORD* phy_stats_record_list = NULL;
int allocated_elements = 0;
int total_allocated_memory = 0;

void init_phy_stats_record(int num_records) {
    if (num_records > MAX_ELEMENTS || num_records <= 0) {
        fprintf(stderr, "Invalid number of records\n");
        return;
    }

    size_t required_memory = num_records * sizeof(PHY_STATS_RECORD);
    if (required_memory > MEMORY_LIMIT) {
        fprintf(stderr, "Memory allocation exceeds limit\n");
        return;
    }

    PHY_STATS_RECORD* new_list = realloc(phy_stats_record_list, required_memory);
    if (!new_list) {
        fprintf(stderr, "Failed to allocate memory\n");
        return;
    }

    phy_stats_record_list = new_list;
    allocated_elements = num_records;

    srand(time(NULL));
    for (int i = 0; i < allocated_elements; ++i) {
        phy_stats_record_list[i].TIME_STAMP = time(NULL);
        phy_stats_record_list[i].CELL_ID = rand() % 1000; // Example range
        phy_stats_record_list[i].RX_SIGNAL_LEVEL = rand() % 50 + 20; // Example range
    }
}

void compress_and_archive_records(int days_to_keep) {
    if (allocated_elements == 0) return;

    time_t now = time(NULL);
    for (int i = allocated_elements - 1; i >= 0; --i) {
        if (now - phy_stats_record_list[i].TIME_STAMP > days_to_keep * 24 * 60 * 60) {
            memmove(&phy_stats_record_list[i], &phy_stats_record_list[i + 1],
                    (allocated_elements - i - 1) * sizeof(PHY_STATS_RECORD));
            allocated_elements--;
        } else {
            break;
        }
    }

    // Reallocate memory if significant amount of space is freed
    size_t new_size = allocated_elements * sizeof(PHY_STATS_RECORD);
    if (new_size < total_allocated_memory / 2) {
        PHY_STATS_RECORD* new_list = realloc(phy_stats_record_list, new_size);
        if (!new_list) {
            fprintf(stderr, "Failed to reallocate memory\n");
            return;
        }
        phy_stats_record_list = new_list;
    }

    total_allocated_memory = new_size;
}

void cleanup() {
    free(phy_stats_record_list);
    phy_stats_record_list = NULL;
    allocated_elements = 0;
    total_allocated_memory = 0;
}
