typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void handle_user_request(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Simulate processing the PDU
    printf("Processing PDU with RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
           pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG, pdu->CRCFLAG);

    // Extract parameters from $_REQUEST
    char *id = getenv("id");
    char *name = getenv("name");
    char *email = getenv("email");
    char *password = getenv("password");
    char *sub_action = getenv("sub_action");

    if (!name || !email || !password || !sub_action) {
        printf("Invalid request parameters\n");
        return;
    }

    // Validate input data
    if (strlen(name) > 50 || strlen(email) > 100 || strlen(password) < 8) {
        printf("Invalid input data\n");
        return;
    }

    // Handle sub_action
    if (strcmp(sub_action, "create") == 0) {
        // Create user account logic here
        printf("Creating user: %s with email: %s\n", name, email);
    } else if (strcmp(sub_action, "update") == 0) {
        // Update user account logic here
        printf("Updating user with id: %s to name: %s and email: %s\n", id, name, email);
    } else if (strcmp(sub_action, "delete") == 0) {
        // Delete user account logic here
        printf("Deleting user with id: %s\n", id);
    } else {
        printf("Invalid sub_action\n");
        return;
    }

    // Store updated data to database
    printf("Storing data to database...\n");

    // Return JSON response
    struct json_object *response = json_object_new_object();
    json_object_object_add(response, "message", json_object_new_string("Operation successful"));

    const char *json_str = json_object_to_json_string_ext(response, JSON_C_TO_STRING_PRETTY);
    printf("JSON Response: %s\n", json_str);

    // Log critical events and errors
    printf("Logging event: %s\n", sub_action);
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 2, 3, rand() % 2};
    handle_user_request(&pdu);
    return 0;
}
```

