#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_DATA_SIZE 1024
#define BUFFER_SIZE 100

typedef struct {
    unsigned long timestamp;
    char data[MAX_DATA_SIZE];
    unsigned int checksum;
} FrameBuffer;

typedef struct {
    FrameBuffer frames[BUFFER_SIZE];
    int head, tail;
    pthread_mutex_t lock;
    pthread_cond_t not_full, not_empty;
} FrameQueue;

void init_queue(FrameQueue *queue) {
    queue->head = 0;
    queue->tail = 0;
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->not_full, NULL);
    pthread_cond_init(&queue->not_empty, NULL);
}

int enqueue(FrameQueue *queue, FrameBuffer frame) {
    pthread_mutex_lock(&queue->lock);
    while ((queue->tail + 1) % BUFFER_SIZE == queue->head) {
        pthread_cond_wait(&queue->not_full, &queue->lock);
    }
    memcpy(&queue->frames[queue->tail], &frame, sizeof(FrameBuffer));
    queue->tail = (queue->tail + 1) % BUFFER_SIZE;
    pthread_cond_signal(&queue->not_empty);
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

int dequeue(FrameQueue *queue, FrameBuffer *frame) {
    pthread_mutex_lock(&queue->lock);
    while (queue->head == queue->tail) {
        pthread_cond_wait(&queue->not_empty, &queue->lock);
    }
    memcpy(frame, &queue->frames[queue->head], sizeof(FrameBuffer));
    queue->head = (queue->head + 1) % BUFFER_SIZE;
    pthread_cond_signal(&queue->not_full);
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

int main() {
    FrameQueue queue;
    init_queue(&queue);

    // Example usage
    FrameBuffer frame;
    frame.timestamp = 1234567890;
    strcpy(frame.data, "Example data");
    frame.checksum = 0; // Calculate checksum here

    enqueue(&queue, frame);

    FrameBuffer dequeued_frame;
    dequeue(&queue, &dequeued_frame);

    return 0;
}
