        pthread_mutex_unlock(&pdu_pool.mutex);
        return NULL; // Maximum limit reached
    }

    if (!pdu_pool.pdu_array || pdu_pool.allocated_size == pdu_pool.used_count) {
        size_t new_size = (pdu_pool.allocated_size == 0) ? 1 : pdu_pool.allocated_size * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_pdu_array = realloc(pdu_pool.pdu_array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_pdu_array) {
            pthread_mutex_unlock(&pdu_pool.mutex);
            return NULL; // Memory allocation failure
        }

        pdu_pool.pdu_array = new_pdu_array;
        pdu_pool.allocated_size = new_size;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_pdu = &pdu_pool.pdu_array[pdu_pool.used_count++];

    pthread_mutex_unlock(&pdu_pool.mutex);

