typedef struct {
    uint32_t source_ip;
    uint32_t destination_ip;
    size_t payload_size;
} NetworkPacket;

typedef struct PacketListNode {
    NetworkPacket packet;
    struct PacketListNode* next;
} PacketListNode;

typedef struct {
    PacketListNode* head;
    PacketListNode** tail;
    size_t count;
    pthread_mutex_t lock;
} NetworkPacketList;

void init_packet_list(NetworkPacketList* list) {
    list->head = NULL;
    list->tail = &list->head;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

int add_packet_to_list(NetworkPacketList* list, NetworkPacket packet) {
    PacketListNode* new_node = malloc(sizeof(PacketListNode));
    if (!new_node) return -1; // Memory allocation failed

    new_node->packet = packet;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    *list->tail = new_node;
    list->tail = &new_node->next;
    list->count++;
    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

void free_packet_list(NetworkPacketList* list) {
    PacketListNode* current = list->head;
    while (current) {
        PacketListNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}
```

