    pool->pool = (NFAPI_CRC_INDICATION_PDU_T *)calloc(pool->max_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    sem_init(&pool->pool_semaphore, 0, pool->current_size);
    return pool;
