    sem_wait(&pool->pool_semaphore);
    if (pool->current_size < pool->max_size) {
        NFAPI_CRC_INDICATION_PDU_T *memory = &pool->pool[pool->current_size++];
        memory->crc_indication.crcflag = rand() % 2; // Randomly set CRCFLAG
        return memory;
    }
