#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode* next;
} ListNode;

typedef struct DynamicList {
    pthread_mutex_t mutex;
    int count;
    int max_size;
    ListNode* head;
} DynamicList;

DynamicList* create_dynamic_list(int initial_capacity) {
    DynamicList* list = malloc(sizeof(DynamicList));
    if (list == NULL) {
        return NULL;
    }
    list->count = 0;
    list->max_size = initial_capacity;
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_dynamic_list(DynamicList* list) {
    pthread_mutex_lock(&list->mutex);
    ListNode* current = list->head;
    while (current != NULL) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_to_list(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= list->max_size) {
        // Resize or return error
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    ListNode* new_node = malloc(sizeof(ListNode));
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return -2;
    }
    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int update_list(DynamicList* list, uint16_t rnti, NFAPI_CRC_INDICATION_PDU_T new_data) {
    pthread_mutex_lock(&list->mutex);
    ListNode* current = list->head;
    while (current != NULL) {
        if (current->data.rnti == rnti) {
            current->data = new_data;
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    return -1;
}

int remove_from_list(DynamicList* list, uint16_t rnti) {
    pthread_mutex_lock(&list->mutex);
    ListNode* current = list->head;
    ListNode* prev = NULL;
    while (current != NULL) {
        if (current->data.rnti == rnti) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            list->count--;
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    return -1;
}

int save_list_to_disk(DynamicList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        return -1;
    }
    pthread_mutex_lock(&list->mutex);
    ListNode* current = list->head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    fclose(file);
    return 0;
}

int load_list_from_disk(DynamicList* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        return -1;
    }
    pthread_mutex_lock(&list->mutex);
    destroy_dynamic_list(list); // Clear existing data
    NFAPI_CRC_INDICATION_PDU_T data;
    while (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) == 1) {
        add_to_list(list, data);
    }
    pthread_mutex_unlock(&list->mutex);
    fclose(file);
    return 0;
}
