#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_RETRIES 3

typedef struct {
    char ip_address[16];
    char subnet_mask[16];
    char gateway[16];
} NetworkConfig;

void handle_error(const char *message) {
    perror(message);
}

int configure_network_interface(NetworkConfig config) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int sock = socket(AF_INET, SOCK_DGRAM, 0);
        if (sock == -1) {
            handle_error("Failed to create socket");
            retries++;
            continue;
        }

        struct sockaddr_in server_addr;
        memset(&server_addr, 0, sizeof(server_addr));
        server_addr.sin_family = AF_INET;
        server_addr.sin_port = htons(8080);
        if (inet_pton(AF_INET, "192.168.1.1", &server_addr.sin_addr) <= 0) {
            handle_error("Invalid IP address");
            close(sock);
            retries++;
            continue;
        }

        if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
            handle_error("Failed to connect to configuration service");
            close(sock);
            retries++;
            continue;
        }

        // Send configuration data
        char buffer[1024];
        snprintf(buffer, sizeof(buffer), "IP=%s\nSubnet=%s\nGateway=%s", config.ip_address, config.subnet_mask, config.gateway);
        send(sock, buffer, strlen(buffer), 0);

        close(sock);
        return 0;
    }

    handle_error("Failed to configure network interface after multiple retries");
    return -1;
}

int main() {
    NetworkConfig config = {
        .ip_address = "192.168.1.100",
        .subnet_mask = "255.255.255.0",
        .gateway = "192.168.1.1"
    };

    if (configure_network_interface(config) == 0) {
        printf("Network interface configured successfully\n");
    }

    return 0;
}
