#define MIN_N 100
#define MAX_N 1000
#define MIN_RNTI 1
#define MAX_RNTI 65535
#define MIN_TIMESTAMP_WINDOW 60 // seconds

typedef struct {
    time_t timestamp;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_NFAPI_CRC_INDICATION_PDU_list(int N, time_t start_timestamp, time_t end_timestamp) {
    if (N < MIN_N || N > MAX_N || difftime(end_timestamp, start_timestamp) < MIN_TIMESTAMP_WINDOW) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    srand(time(NULL));

    int last_crcflag = -1; // Initialize to a value not in {0, 1}

    for (int i = 0; i < N; ++i) {
        list[i].timestamp = start_timestamp + rand() % ((end_timestamp - start_timestamp) / N);
        list[i].RNTI = rand() % (MAX_RNTI - MIN_RNTI + 1) + MIN_RNTI;
        if (last_crcflag == -1) {
            // Initialize the first CRCFLAG randomly
            list[i].CRCFLAG = rand() % 2;
        } else {
            do {
                list[i].CRCFLAG = rand() % 2;
            } while (list[i].CRCFLAG == last_crcflag);
        }
        last_crcflag = list[i].CRCFLAG;
    }

    return list;
}

void free_NFAPI_CRC_INDICATION_PDU_list(NFAPI_CRC_INDICATION_PDU_T* list, int N) {
    if (list) {
        free(list);
    }
}
