} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* nfapi_array[MAX_NFAPIS];
sem_t semaphore;

void initialize_memory(int N, int frequency) {
    sem_wait(&semaphore);
    for (int i = 0; i < N; i++) {
        nfapi_array[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (nfapi_array[i] == NULL) {
            printf("Memory allocation failed\n");
            exit(1);
        }
        // Initialize each structure with valid data
        nfapi_array[i]->RX_UE_INFORMATION_TAG = i;
        nfapi_array[i]->RNTI = i * 2;
        nfapi_array[i]->CRC_INDICATION_REL8_TAG = i * 3;
    }
    sem_post(&semaphore);
}

void* data_flow_thread(void* arg) {
    int thread_id = *(int*)arg;
    while (1) {
        // Simulate data flow
        sem_wait(&semaphore);
        for (int i = 0; i < MAX_NFAPIS; i++) {
            if (nfapi_array[i] != NULL) {
                printf("Thread %d processing data: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d\n",
                       thread_id, nfapi_array[i]->RX_UE_INFORMATION_TAG, nfapi_array[i]->RNTI, nfapi_array[i]->CRC_INDICATION_REL8_TAG);
            }
        }
        sem_post(&semaphore);
        // Simulate frequency
        sleep(frequency);
    }
    return NULL;
}

int main() {
    int N = 100; // Number of NFAPIS
    int frequency = 2; // Initialization frequency

    sem_init(&semaphore, 0, 1);

    initialize_memory(N, frequency);

    pthread_t threads[MAX_NFAPIS];
    int thread_ids[MAX_NFAPIS];

    for (int i = 0; i < MAX_NFAPIS; i++) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, data_flow_thread, &thread_ids[i]);
    }

    for (int i = 0; i < MAX_NFAPIS; i++) {
        pthread_join(threads[i], NULL);
    }

    sem_destroy(&semaphore);

    // Cleanup allocated resources
    for (int i = 0; i < N; i++) {
        free(nfapi_array[i]);
    }

    return 0;
}
