#include <pthread.h>

#define MAX_METRICS 10

typedef struct LTE_PHY_TEST_COMMAND {
    TEST_COMMAND_TAG tag;
    PERFORMANCE_METRIC metrics[MAX_METRICS];
    int metric_count;
} LTE_PHY_TEST_COMMAND;

typedef struct LTE_PHY_TEST_LIST {
    LTE_PHY_TEST_COMMAND **commands;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} LTE_PHY_TEST_LIST;

LTE_PHY_TEST_LIST* create_test_list() {
    LTE_PHY_TEST_LIST *list = (LTE_PHY_TEST_LIST*)malloc(sizeof(LTE_PHY_TEST_LIST));
    if (!list) return NULL;

    list->commands = (LTE_PHY_TEST_COMMAND**)malloc(10 * sizeof(LTE_PHY_TEST_COMMAND*));
    if (!list->commands) {
        free(list);
        return NULL;
    }

    list->count = 0;
    list->capacity = 10;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_test_list(LTE_PHY_TEST_LIST *list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->commands[i]);
    }
    free(list->commands);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_command(LTE_PHY_TEST_LIST *list, LTE_PHY_TEST_COMMAND *command) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        LTE_PHY_TEST_COMMAND **new_commands = (LTE_PHY_TEST_COMMAND**)realloc(list->commands, new_capacity * sizeof(LTE_PHY_TEST_COMMAND*));
        if (!new_commands) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }
        list->commands = new_commands;
        list->capacity = new_capacity;
    }

    list->commands[list->count] = command;
    ++list->count;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Additional functions for adding metrics, retrieving commands/metrics, serializing/deserializing, etc. would go here

