} ResultCode;

ResultCode manageNFAPICRCIndicationPDUs(int N) {
    if (N <= 0 || N > MAX_STRUCTURES) {
        return INVALID_INPUT;
    }

    NFAPI_CRC_INDICATION_PDU_T** pdus = (NFAPI_CRC_INDICATION_PDU_T**)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!pdus) {
