        successfulAllocations++;
    }

    // Log resource usage and allocation statistics
    printf("Successful allocations: %d, Failed allocations: %d\n", successfulAllocations, failedAllocations);

    // Free allocated memory
    for (int i = 0; i < N; i++) {
        if (pdus[i]) {
            free(pdus[i]);
        }
    }

    free(pdus);

    return SUCCESS;
}

int main() {
