            break;
        case INVALID_INPUT:
            printf("Invalid input parameters provided.\n");
            break;
        case MEMORY_ALLOCATION_FAILED:
            printf("Memory allocation failed.\n");
            break;
        case EXCEEDS_RESOURCE_LIMIT:
            printf("Exceeds system resource limit.\n");
            break;
