        ni->pdu_pool[i] = (NFAPI_L2_PDU*)malloc(sizeof(NFAPI_L2_PDU));
        if (!ni->pdu_pool[i]) {
            log_message(LOG_LEVEL_DEBUG, "Failed to allocate memory for PDU buffer");
            return -1;
        }
    }

    log_message(LOG_LEVEL_DEBUG, "Network interface initialized successfully");
    return 0;
}

void configure_network_interface(NetworkInterface* ni) {
    // Populate PDU buffers with different types of messages
    for (int i = 0; i < MAX_PDU_BUFFERS; i++) {
        if (i % 2 == 0) {
            ni->pdu_pool[i]->header.type = CONFIG_REQUEST;
        } else {
            ni->pdu_pool[i]->header.type = STATUS_REPORT;
        }
    }

    log_message(LOG_LEVEL_DEBUG, "Network interface configured successfully");
}

void cleanup_network_interface(NetworkInterface* ni) {
    for (int i = 0; i < MAX_PDU_BUFFERS; i++) {
