    // Additional fields as needed
} NASMessage;

typedef struct RRCConnection {
    enum { IDLE, CONNECTED } status;
    // Additional fields as needed
} RRCConnection;

typedef struct UEState {
    RRCConnection rrcStatus;
    PDUSession** pdusessions;
    int pdusessionCount;
    NASMessage** nasMessages;
    int nasMessageCount;
    pthread_mutex_t mutex;
} UEState;

UEState* createUEState() {
    UEState* state = (UEState*)malloc(sizeof(UEState));
    if (state) {
        state->rrcStatus.status = IDLE;
        state->pdusessions = NULL;
        state->pdusessionCount = 0;
        state->nasMessages = NULL;
        state->nasMessageCount = 0;
        pthread_mutex_init(&state->mutex, NULL);
    }
    return state;
}

void destroyUEState(UEState* state) {
    if (state) {
        for (int i = 0; i < state->pdusessionCount; ++i) {
            free(state->pdusessions[i]);
        }
        free(state->pdusessions);
        for (int i = 0; i < state->nasMessageCount; ++i) {
            free(state->nasMessages[i]);
        }
        free(state->nasMessages);
        pthread_mutex_destroy(&state->mutex);
        free(state);
    }
}

void updateRRCStatus(UEState* state, RRCConnection newStatus) {
    pthread_mutex_lock(&state->mutex);
    state->rrcStatus = newStatus;
    pthread_mutex_unlock(&state->mutex);
}

int addPDUSession(UEState* state, PDUSession* session) {
    pthread_mutex_lock(&state->mutex);
    state->pdusessions = (PDUSession**)realloc(state->pdusessions, (state->pdusessionCount + 1) * sizeof(PDUSession*));
    if (!state->pdusessions) {
        pthread_mutex_unlock(&state->mutex);
        return -1; // Memory allocation failed
    }
    state->pdusessions[state->pdusessionCount++] = session;
    pthread_mutex_unlock(&state->mutex);
    return 0;
}

int removePDUSession(UEState* state, int sessionId) {
    pthread_mutex_lock(&state->mutex);
    for (int i = 0; i < state->pdusessionCount; ++i) {
        if (state->pdusessions[i]->sessionId == sessionId) {
            free(state->pdusessions[i]);
            for (; i < state->pdusessionCount - 1; ++i) {
                state->pdusessions[i] = state->pdusessions[i + 1];
            }
            state->pdusessions = (PDUSession**)realloc(state->pdusessions, state->pdusessionCount * sizeof(PDUSession*));
            pthread_mutex_unlock(&state->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&state->mutex);
    return -1; // Session not found
}

int addNASMessage(UEState* state, NASMessage* message) {
    pthread_mutex_lock(&state->mutex);
    state->nasMessages = (NASMessage**)realloc(state->nasMessages, (state->nasMessageCount + 1) * sizeof(NASMessage*));
    if (!state->nasMessages) {
        pthread_mutex_unlock(&state->mutex);
        return -1; // Memory allocation failed
    }
    state->nasMessages[state->nasMessageCount++] = message;
    pthread_mutex_unlock(&state->mutex);
    return 0;
}

int removeNASMessage(UEState* state, int messageId) {
    pthread_mutex_lock(&state->mutex);
    for (int i = 0; i < state->nasMessageCount; ++i) {
        if (state->nasMessages[i]->messageId == messageId) {
            free(state->nasMessages[i]);
            for (; i < state->nasMessageCount - 1; ++i) {
                state->nasMessages[i] = state->nasMessages[i + 1];
            }
            state->nasMessages = (NASMessage**)realloc(state->nasMessages, state->nasMessageCount * sizeof(NASMessage*));
            pthread_mutex_unlock(&state->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&state->mutex);
    return -1; // Message not found
