    if (list == NULL) return NULL;

    list->pdus = (NFAPI_CRC_INDICATION_PDU_T*)calloc(max_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list->pdus == NULL) {
        free(list);
        return NULL;
