        free(list->pdus);
        pthread_mutex_destroy(&list->mutex);
        free(list);
    }
}

int add_pdu_to_list(CRC_LIST_T* list, int RX_UE_INFORMATION_TAG, int RNTI, int CRCFLAG) {
    pthread_mutex_lock(&list->mutex);

    if (list->current_size >= list->max_size) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // List is full
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = &list->pdus[list->current_size++];
    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    pdu->CRCFLAG = CRCFLAG;

    pthread_mutex_unlock(&list->mutex);
    return 0;
