    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* dynamic_list_init(size_t initial_capacity) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (list == NULL) {
        return NULL; // Handle memory allocation failure
    }
    list->items = (NFAPI_CRC_INDICATION_PDU_T**)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (list->items == NULL) {
        free(list);
        return NULL; // Handle memory allocation failure
    }
    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void dynamic_list_free(DynamicList* list) {
    for (size_t i = 0; i < list->size; ++i) {
        free(list->items[i]);
    }
    free(list->items);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

bool dynamic_list_add(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T* item) {
    pthread_mutex_lock(&list->lock);
    if (list->size == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T** new_items = (NFAPI_CRC_INDICATION_PDU_T**)realloc(list->items, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (new_items == NULL) {
            pthread_mutex_unlock(&list->lock);
            return false; // Handle memory allocation failure
        }
        list->items = new_items;
        list->capacity = new_capacity;
    }
    list->items[list->size++] = item;
    pthread_mutex_unlock(&list->lock);
    return true;
}

bool dynamic_list_remove(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T* item) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; ++i) {
        if (list->items[i] == item) {
            free(item);
            for (size_t j = i; j < list->size - 1; ++j) {
                list->items[j] = list->items[j + 1];
            }
            list->size--;
            pthread_mutex_unlock(&list->lock);
            return true;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return false;
}

void dynamic_list_traverse(DynamicList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; ++i) {
        callback(list->items[i]);
    }
    pthread_mutex_unlock(&list->lock);
