#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>

#define MAX_CYCLES 100
#define NUM_THREADS 4

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t size;
    size_t used;
    pthread_mutex_t mutex;
} PoolAllocator;

void init_pool(PoolAllocator *allocator, size_t size) {
    allocator->pool = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    allocator->size = size;
    allocator->used = 0;
    pthread_mutex_init(&allocator->mutex, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_from_pool(PoolAllocator *allocator) {
    pthread_mutex_lock(&allocator->mutex);
    if (allocator->used < allocator->size) {
        return &allocator->pool[allocator->used++];
    } else {
        pthread_mutex_unlock(&allocator->mutex);
        return NULL;
    }
}

void deallocate_to_pool(PoolAllocator *allocator, NFAPI_CRC_INDICATION_PDU_T* item) {
    pthread_mutex_lock(&allocator->mutex);
    // Assuming the pool is circular
    if (allocator->used > 0) {
        allocator->used--;
        // Copy the item back to the pool
        allocator->pool[allocator->used] = *item;
    }
    pthread_mutex_unlock(&allocator->mutex);
}

void* process_radio_data(void* arg) {
    PoolAllocator *allocator = (PoolAllocator*)arg;
    for (int i = 0; i < MAX_CYCLES; i++) {
        NFAPI_CRC_INDICATION_PDU_T *packet = allocate_from_pool(allocator);
        if (packet) {
            // Populate packet with data
            packet->RX_UE_INFORMATION_TAG = rand() % 100;
            packet->RNTI = rand() % 256;
            packet->CRC_INDICATION_REL8_TAG = rand() % 2;
            // Simulate processing
            usleep(100);
            deallocate_to_pool(allocator, packet);
        } else {
            fprintf(stderr, "Failed to allocate memory for packet.\n");
        }
    }
    return NULL;
}

int main() {
    PoolAllocator allocator;
    init_pool(&allocator, MAX_CYCLES * NUM_THREADS);

    pthread_t threads[NUM_THREADS];
    for (int i = 0; i < NUM_THREADS; i++) {
        if (pthread_create(&threads[i], NULL, process_radio_data, &allocator) != 0) {
            perror("Failed to create thread");
        }
    }

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    free(allocator.pool);
    pthread_mutex_destroy(&allocator.mutex);

    return 0;
}
