#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    uint32_t RNTI;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicList_T;

void initDynamicList(DynamicList_T *list, size_t initialCapacity) {
    list->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        fprintf(stderr, "Failed to allocate memory for dynamic list\n");
        exit(EXIT_FAILURE);
    }
    list->capacity = initialCapacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void resizeDynamicList(DynamicList_T *list, size_t newCapacity) {
    NFAPI_CRC_INDICATION_PDU_T *newData = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->data, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newData) {
        fprintf(stderr, "Failed to resize dynamic list\n");
        exit(EXIT_FAILURE);
    }
    list->data = newData;
    list->capacity = newCapacity;
}

void addElementToDynamicList(DynamicList_T *list, uint32_t RNTI, bool CRCFLAG) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity) {
        resizeDynamicList(list, list->capacity * 2);
    }

    list->data[list->size].RNTI = RNTI;
    list->data[list->size].CRCFLAG = CRCFLAG;
    list->size++;

    pthread_mutex_unlock(&list->lock);
}

bool isUniqueRNTI(DynamicList_T *list, uint32_t RNTI) {
    for (size_t i = 0; i < list->size; i++) {
        if (list->data[i].RNTI == RNTI) {
            return false;
        }
    }
    return true;
}

void generateRandomElements(DynamicList_T *list, size_t N) {
    srand(time(NULL));
    for (size_t i = 0; i < N; i++) {
        uint32_t RNTI;
        do {
            RNTI = rand() % UINT32_MAX;
        } while (!isUniqueRNTI(list, RNTI));

        bool CRCFLAG = (rand() & 1) == 0;

        addElementToDynamicList(list, RNTI, CRCFLAG);
    }
}

void freeDynamicList(DynamicList_T *list) {
    pthread_mutex_destroy(&list->lock);
    free(list->data);
}
