#include <stdlib.h>
#include <string.h>
#include <stdio.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct PduListNode {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct PduListNode *next;
} PduListNode;

typedef struct NfaApiPduListManager {
    PduListNode *head;
    PduListNode *tail;
    int size;
    int successfulAllocations;
    int failedAllocations;
} NfaApiPduListManager;

NfaApiPduListManager* fetchAndManageNfaApiPduList(int maxStructures) {
    NfaApiPduListManager *manager = (NfaApiPduListManager*)malloc(sizeof(NfaApiPduListManager));
    if (!manager) {
        fprintf(stderr, "Memory allocation failed for manager\n");
        return NULL;
    }
    memset(manager, 0, sizeof(NfaApiPduListManager));

    for (int i = 0; i < maxStructures; i++) {
        PduListNode *node = (PduListNode*)malloc(sizeof(PduListNode));
        if (!node) {
            fprintf(stderr, "Memory allocation failed for node %d\n", i);
            manager->failedAllocations++;
            continue;
        }
        memset(node, 0, sizeof(PduListNode));

        node->pdu.RX_UE_INFORMATION_TAG = rand();
        node->pdu.RNTI = rand() & 0xFFFF;
        node->pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2 == 0) ? 1 : 0;

        if (!manager->head) {
            manager->head = node;
            manager->tail = node;
        } else {
            manager->tail->next = node;
            manager->tail = node;
        }
        manager->size++;
        manager->successfulAllocations++;
    }

    return manager;
}

void freeNfaApiPduListManager(NfaApiPduListManager *manager) {
    PduListNode *current = manager->head;
    while (current) {
        PduListNode *next = current->next;
        free(current);
        current = next;
    }
    free(manager);
}
