#include <forward_list>
#include <string>
#include <chrono>
#include <thread>
#include <stdexcept>

std::forward_list<std::string> insertStringAfter(std::forward_list<std::string>& list, const std::string& target, const std::string& insert, std::optional<int> timeout_ms = std::nullopt) {
    auto start_time = std::chrono::high_resolution_clock::now();
    auto it = list.begin();
    while (it != list.end() && *it != target) {
        if (timeout_ms.has_value()) {
            auto now = std::chrono::high_resolution_clock::now();
            if (std::chrono::duration_cast<std::chrono::milliseconds>(now - start_time).count() > timeout_ms.value()) {
                throw std::runtime_error("Insertion timed out");
            }
        }
        ++it;
    }

    if (it != list.end()) {
        it = list.insert_after(it, insert);
    } else {
        list.push_front(insert);
    }

    return list;
}
