#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_PDUS 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
} UE_INFO;

typedef struct {
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    UE_INFO ue_info;
    CRC_INDICATION_REL8 crc_indication_rel8;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* pdu_pool[MAX_PDUS];
int pool_index = 0;
pthread_mutex_t lock;

void init_pdu_pool() {
    for (int i = 0; i < MAX_PDUS; i++) {
        pdu_pool[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdu_pool[i] == NULL) {
            fprintf(stderr, "Failed to allocate memory for PDU pool\n");
            exit(EXIT_FAILURE);
        }
    }
    pthread_mutex_init(&lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* get_pdu() {
    NFAPI_CRC_INDICATION_PDU_T* pdu;
    pthread_mutex_lock(&lock);
    if (pool_index == 0) {
        pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdu == NULL) {
            fprintf(stderr, "Failed to allocate memory for new PDU\n");
            exit(EXIT_FAILURE);
        }
    } else {
        pdu = pdu_pool[--pool_index];
    }
    pthread_mutex_unlock(&lock);
    return pdu;
}

void release_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&lock);
    if (pool_index < MAX_PDUS) {
        pdu_pool[pool_index++] = pdu;
    } else {
        free(pdu);
    }
    pthread_mutex_unlock(&lock);
}

NFAPI_CRC_INDICATION_PDU_T* populate_pdu() {
    NFAPI_CRC_INDICATION_PDU_T* pdu = get_pdu();
    // Simulate fetching UE information from an external source
    pdu->ue_info.RX_UE_INFORMATION_TAG = rand() % 1000;
    pdu->ue_info.RNTI = (uint16_t)(rand() % 1024);

    // Set a random CRCFLAG
    pdu->crc_indication_rel8.CRCFLAG = (rand() % 2) == 0 ? 0x01 : 0x00;

    return pdu;
}

void process_pdus(int num_pdus) {
    for (int i = 0; i < num_pdus; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = populate_pdu();
        // Simulate processing the PDU
        printf("Processed PDU with UE Tag: %u, RNTI: %u, CRCFLAG: %u\n", 
               pdu->ue_info.RX_UE_INFORMATION_TAG, 
               pdu->ue_info.RNTI, 
               pdu->crc_indication_rel8.CRCFLAG);
        release_pdu(pdu);
    }
}

int main() {
    srand(time(NULL));
    init_pdu_pool();

    int num_pdus = 500; // Example number of PDUs to process
    process_pdus(num_pdus);

    return 0;
}
