void* allocate_aligned_memory(size_t size, size_t alignment) {
    void *mem = malloc(size + alignment);
    if (!mem) return NULL;
    void *aligned_mem = (void *)(((size_t)(mem + alignment - 1)) & ~(alignment - 1));
    ((void **)aligned_mem)[-1] = mem;
    return aligned_mem;
}

void free_aligned_memory(void *ptr) {
    free(((void **)ptr)[-1]);
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_array(int N, int max_N) {
    if (N > max_N) {
        N = max_N;
    }

    size_t array_size = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    void *aligned_mem = allocate_aligned_memory(array_size, PAGE_SIZE);
    if (!aligned_mem) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T *)aligned_mem;
