#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RNTI 65535

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define structure members here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct ListNode *next;
} ListNode;

typedef struct LinkedList {
    ListNode *head;
    size_t size;
    pthread_mutex_t lock;
} LinkedList;

void* nfaapi_generate_list(size_t N) {
    if (N > 10000) {
        return NULL; // Handle error: Requested list size too large
    }

    LinkedList *list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) {
        return NULL; // Handle memory allocation failure
    }
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    srand(time(NULL)); // Seed random number generator

    for (size_t i = 0; i < N; ++i) {
        ListNode *new_node = (ListNode*)malloc(sizeof(ListNode));
        if (!new_node) {
            // Handle memory allocation failure
            nfaapi_free_list(list);
            return NULL;
        }

        new_node->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node->data) {
            free(new_node);
            // Handle memory allocation failure
            nfaapi_free_list(list);
            return NULL;
        }

        // Set RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG with random values
        new_node->data->RX_UE_INFORMATION_TAG = i; // Example assignment
        new_node->data->RNTI = rand() % (MAX_RNTI + 1); // Random RNTI
        new_node->data->CRC_INDICATION_REL8_TAG = rand() % 2; // Random CRCFLAG

        pthread_mutex_lock(&list->lock);
        new_node->next = list->head;
        list->head = new_node;
        ++list->size;
        pthread_mutex_unlock(&list->lock);
    }

    return list;
}

void nfaapi_free_list(LinkedList *list) {
    if (!list) {
        return;
    }

    ListNode *current = list->head;
    while (current) {
        ListNode *next = current->next;
        free(current->data);
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example usage
int main() {
    size_t N = 1000; // Example list size
    LinkedList *list = (LinkedList*)nfaapi_generate_list(N);

    if (list) {
        // Process the list
        nfaapi_free_list(list);
    }

    return 0;
}
