#define MAX_EVENTS 100

typedef enum {
    EVENT_UNKNOWN,
    EVENT_LATENCY_INCREASE,
    EVENT_PACKET_LOSS,
    EVENT_BANDWIDTH_LIMIT,
    EVENT_RECOVERY
} EventType;

typedef enum {
    NETWORK_HEALTHY,
    NETWORK_DEGRADED,
    NETWORK_DOWN
} NetworkState;

typedef struct {
    time_t Timestamp;
    EventType Type;
    NetworkState State;
} NetworkEvent;

NetworkEvent* simulateNetworkEvents(int *eventCount) {
    NetworkEvent* events = (NetworkEvent*)malloc(MAX_EVENTS * sizeof(NetworkEvent));
    if (events == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    time_t currentTime = time(NULL);

    NetworkState currentState = NETWORK_HEALTHY;
    for (int i = 0; i < MAX_EVENTS && currentTime <= time(NULL); ++i, currentTime++) {
        events[i].Timestamp = currentTime;

        if (currentState == NETWORK_HEALTHY) {
            int randomEvent = rand() % 10;
            if (randomEvent < 3) {
                currentState = NETWORK_DEGRADED;
                events[i].Type = EVENT_PACKET_LOSS;
            } else if (randomEvent < 6) {
                currentState = NETWORK_DEGRADED;
                events[i].Type = EVENT_LATENCY_INCREASE;
            } else if (randomEvent == 7) {
                currentState = NETWORK_DEGRADED;
                events[i].Type = EVENT_BANDWIDTH_LIMIT;
            }
        } else {
            int randomRecovery = rand() % 10;
            if (randomRecovery < 3) {
                currentState = NETWORK_HEALTHY;
                events[i].Type = EVENT_RECOVERY;
            }
        }

        events[i].State = currentState;
    }

    *eventCount = MAX_EVENTS > i ? i : MAX_EVENTS;
    return events;
}

int main() {
    int eventCount;
    NetworkEvent* events = simulateNetworkEvents(&eventCount);

    for (int i = 0; i < eventCount; ++i) {
        printf("Timestamp: %s, Type: %d, State: %d\n",
               ctime(&(events[i].Timestamp)), events[i].Type, events[i].State);
    }

    free(events);
    return 0;
}
