#include <stdlib.h>
#include <pthread.h>

typedef struct RRC_PDU_T {
    // Define fields for serialized PDU
} RRC_PDU_T;

typedef struct RX_UE_INFORMATION_TAG {
    // Define fields for UE information
} RX_UE_INFORMATION_TAG;

typedef struct NFAPI_RX_FRAME_T {
    RX_UE_INFORMATION_TAG ue_info;
    unsigned int RNTI;
    RRC_PDU_T *rrc_pdu;
} NFAPI_RX_FRAME_T;

typedef struct {
    NFAPI_RX_FRAME_T **frames;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} NFAPI_RX_QUEUE_T;

NFAPI_RX_QUEUE_T* nfapi_rx_queue_init(size_t initial_capacity) {
    NFAPI_RX_QUEUE_T *queue = (NFAPI_RX_QUEUE_T*)malloc(sizeof(NFAPI_RX_QUEUE_T));
    if (!queue) return NULL;

    queue->frames = (NFAPI_RX_FRAME_T**)malloc(initial_capacity * sizeof(NFAPI_RX_FRAME_T*));
    if (!queue->frames) {
        free(queue);
        return NULL;
    }

    queue->capacity = initial_capacity;
    queue->size = 0;
    pthread_mutex_init(&queue->mutex, NULL);

    return queue;
}

void nfapi_rx_queue_free(NFAPI_RX_QUEUE_T *queue) {
    for (size_t i = 0; i < queue->size; ++i) {
        free(queue->frames[i]->rrc_pdu);
        free(queue->frames[i]);
    }
    free(queue->frames);
    pthread_mutex_destroy(&queue->mutex);
    free(queue);
}

void nfapi_rx_queue_push(NFAPI_RX_QUEUE_T *queue, NFAPI_RX_FRAME_T *frame) {
    pthread_mutex_lock(&queue->mutex);

    if (queue->size >= queue->capacity) {
        size_t new_capacity = queue->capacity == 0 ? 1 : queue->capacity * 2;
        NFAPI_RX_FRAME_T **new_frames = (NFAPI_RX_FRAME_T**)realloc(queue->frames, new_capacity * sizeof(NFAPI_RX_FRAME_T*));
        if (!new_frames) {
            pthread_mutex_unlock(&queue->mutex);
            return; // Handle allocation failure gracefully
        }
        queue->frames = new_frames;
        queue->capacity = new_capacity;
    }

    queue->frames[queue->size++] = frame;

    pthread_mutex_unlock(&queue->mutex);
}

NFAPI_RX_FRAME_T* nfapi_rx_queue_pop(NFAPI_RX_QUEUE_T *queue) {
    pthread_mutex_lock(&queue->mutex);

    if (queue->size == 0) {
        pthread_mutex_unlock(&queue->mutex);
        return NULL;
    }

    NFAPI_RX_FRAME_T *frame = queue->frames[--queue->size];
    queue->frames[queue->size] = NULL; // Prevent dangling pointer

    pthread_mutex_unlock(&queue->mutex);

    return frame;
}

// Example usage:
void process_frames(NFAPI_RX_QUEUE_T *queue) {
    NFAPI_RX_FRAME_T *frame;
    while ((frame = nfapi_rx_queue_pop(queue)) != NULL) {
        // Process the frame
        free(frame->rrc_pdu);
        free(frame);
    }
}
