#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef enum { EVENT_TYPE_A, EVENT_TYPE_B } EventType;

typedef struct {
    EventType type;
    time_t timestamp;
    char *payload;
    size_t payload_size;
} NetworkEvent;

typedef struct EventNode {
    NetworkEvent event;
    struct EventNode *next;
} EventNode;

typedef struct {
    EventNode *head;
    pthread_mutex_t mutex;
} EventManager;

EventManager *event_manager_create() {
    EventManager *manager = (EventManager *)malloc(sizeof(EventManager));
    manager->head = NULL;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void event_manager_destroy(EventManager *manager) {
    pthread_mutex_lock(&manager->mutex);
    while (manager->head != NULL) {
        EventNode *node = manager->head;
        manager->head = node->next;
        free(node->event.payload);
        free(node);
    }
    pthread_mutex_unlock(&manager->mutex);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

void event_manager_insert(EventManager *manager, EventType type, time_t timestamp, char *payload, size_t payload_size) {
    pthread_mutex_lock(&manager->mutex);
    EventNode *new_node = (EventNode *)malloc(sizeof(EventNode));
    new_node->event.type = type;
    new_node->event.timestamp = timestamp;
    new_node->event.payload = (char *)malloc(payload_size + 1);
    strncpy(new_node->event.payload, payload, payload_size);
    new_node->event.payload[payload_size] = '\0';
    new_node->event.payload_size = payload_size;
    new_node->next = manager->head;
    manager->head = new_node;
    pthread_mutex_unlock(&manager->mutex);
}

NetworkEvent *event_manager_lookup(EventManager *manager, time_t timestamp) {
    NetworkEvent *result = NULL;
    pthread_mutex_lock(&manager->mutex);
    EventNode *current = manager->head;
    while (current != NULL) {
        if (current->event.timestamp == timestamp) {
            result = &current->event;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager->mutex);
    return result;
}
```

