// Define the event structure
typedef struct {
    int type;
    time_t timestamp;
    char *payload;
} NetworkEvent;

// Function to load a resource bundle from a file
int loadResourceBundle(const char *filePath, NetworkEvent **bundle) {
    FILE *file = fopen(filePath, "r");
    if (file == NULL) {
        perror("Failed to open file");
        return -1;
    }

    // Read the number of events in the bundle
    int itemCount;
    fscanf(file, "%d", &itemCount);
    *bundle = (NetworkEvent *)malloc(itemCount * sizeof(NetworkEvent));
    if (*bundle == NULL) {
        perror("Failed to allocate memory for resource bundle");
        fclose(file);
        return -1;
    }

    // Read each event from the file
    for (int i = 0; i < itemCount; i++) {
        fscanf(file, "%d %ld", &(*bundle)[i].type, &(*bundle)[i].timestamp);
        size_t payloadSize;
        fscanf(file, "%zu", &payloadSize);
        (*bundle)[i].payload = (char *)malloc(payloadSize + 1);
        if ((*bundle)[i].payload == NULL) {
            perror("Failed to allocate memory for payload");
            // Free previously allocated memory
            for (int j = 0; j < i; j++) {
                free((*bundle)[j].payload);
            }
            free(*bundle);
            fclose(file);
            return -1;
        }
        fread((*bundle)[i].payload, 1, payloadSize, file);
        (*bundle)[i].payload[payloadSize] = '\0';
    }

    fclose(file);
    return itemCount;
}

// Example usage
int main() {
    NetworkEvent *bundle;
    int itemCount = loadResourceBundle("events.txt", &bundle);
    if (itemCount > 0) {
        printf("Loaded %d events from the resource bundle.\n", itemCount);
        // Free allocated memory
        for (int i = 0; i < itemCount; i++) {
            free(bundle[i].payload);
        }
        free(bundle);
    } else {
        printf("Failed to load resource bundle.\n");
    }
    return 0;
}
