typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    time_t timestamp;
    int sequence_number;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct List {
    Node* head;
    size_t size;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) {
        return NULL;
    }
    list->head = NULL;
    list->size = 0;
    return list;
}

void free_list(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

int add_to_list(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        return -1; // Memory allocation failed
    }
    new_node->data = data;
    new_node->next = NULL;

    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    list->size++;
    return 0; // Success
}

void filter_list(List* list, int RNTI, int CRCFLAG) {
    Node* current = list->head;
    while (current != NULL) {
        if ((current->data.RNTI == RNTI || RNTI == -1) && 
            (current->data.CRC_INDICATION_REL8_TAG == CRCFLAG || CRCFLAG == -1)) {
            // Perform filtering logic here
        }
        current = current->next;
    }
}

// Example usage
int main() {
    List* my_list = create_list();
    if (!my_list) {
        return 1; // Memory allocation failed
    }

    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = 12345;
    pdu.RNTI = 1001;
    pdu.CRC_INDICATION_REL8_TAG = 1;
    time(&pdu.timestamp);
    pdu.sequence_number = 1;

    if (add_to_list(my_list, pdu) != 0) {
        free_list(my_list);
        return 1; // Memory allocation failed
    }

    filter_list(my_list, 1001, -1);

    free_list(my_list);
    return 0;
}
