#define MAX_PACKETS 1000

typedef struct MAC_HEADER {
    // Define MAC header fields here
} MAC_HEADER;

typedef struct MAC_PAYLOAD {
    // Define MAC payload fields here
} MAC_PAYLOAD;

typedef struct {
    MAC_HEADER header;
    MAC_PAYLOAD payload;
    uint32_t sequence_number;
    time_t timestamp;
} MAC_PDU;

typedef struct PacketList {
    MAC_PDU *packets[MAX_PACKETS];
    size_t count;
} PacketList;

void initialize_packet_list(PacketList *list) {
    list->count = 0;
}

int add_packet(PacketList *list, MAC_PDU *packet) {
    if (list->count >= MAX_PACKETS) {
        return -1; // List is full
    }
    list->packets[list->count++] = packet;
    return 0;
}

MAC_PDU* find_packet_by_sequence(PacketList *list, uint32_t sequence_number) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->packets[i]->sequence_number == sequence_number) {
            return list->packets[i];
        }
    }
    return NULL;
}

MAC_PDU* find_packet_by_timestamp(PacketList *list, time_t timestamp) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->packets[i]->timestamp == timestamp) {
            return list->packets[i];
        }
    }
    return NULL;
}

void free_packet_list(PacketList *list) {
    // Free each packet in the list
    for (size_t i = 0; i < list->count; ++i) {
        free(list->packets[i]);
    }
    list->count = 0;
}
