NFAPI_CRC_INDICATION_PDU_T* create_node(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, time_t timestamp, int sequence_number, float RSSI) {
    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->RNTI = RNTI;
    new_node->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_node->timestamp = timestamp;
    new_node->sequence_number = sequence_number;
    new_node->RSSI = RSSI;
    new_node->CRCFLAG = rand() % 10; // Randomly set CRCFLAG in the range 0-9
    new_node->next = NULL;
    return new_node;
}

void insert_node(NFAPI_CRC_INDICATION_PDU_T **head, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, time_t timestamp, int sequence_number, float RSSI) {
    NFAPI_CRC_INDICATION_PDU_T *new_node = create_node(RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG, timestamp, sequence_number, RSSI);
    if (*head == NULL) {
        *head = new_node;
    } else {
        new_node->next = *head;
        *head = new_node;
    }
}

void delete_node(NFAPI_CRC_INDICATION_PDU_T **head, int RX_UE_INFORMATION_TAG) {
    NFAPI_CRC_INDICATION_PDU_T *current = *head;
    NFAPI_CRC_INDICATION_PDU_T *prev = NULL;

    if (current != NULL && current->RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
        *head = current->next;
        free(current);
        return;
    }

    while (current != NULL && current->RX_UE_INFORMATION_TAG != RX_UE_INFORMATION_TAG) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        printf("Node not found\n");
        return;
    }

    prev->next = current->next;
    free(current);
}

void prune_list(NFAPI_CRC_INDICATION_PDU_T **head, time_t age_threshold) {
    NFAPI_CRC_INDICATION_PDU_T *current = *head;
    NFAPI_CRC_INDICATION_PDU_T *prev = NULL;

    while (current != NULL) {
        if (time(NULL) - current->timestamp > age_threshold) {
            if (prev == NULL) {
                *head = current->next;
            } else {
                prev->next = current->next;
            }
            NFAPI_CRC_INDICATION_PDU_T *temp = current;
            current = current->next;
            free(temp);
        } else {
            prev = current;
            current = current->next;
        }
    }
}

// Additional functions for filtering and sorting can be implemented here
