// Function to dynamically allocate and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
EVP_CIPHER_CTX* generate_cipher_list(NFAPI_CRC_INDICATION_PDU_T** pdu_list, int N) {
    // Initialize the EVP_CIPHER_CTX
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    // Allocate memory for the list of structures
    *pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*pdu_list) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Populate the list with unique data and random CRCFLAG
    for (int i = 0; i < N; ++i) {
        (*pdu_list)[i].rx_tag = i * 2 + 1;
        (*pdu_list)[i].rnti = i * 3 + 1;
        (*pdu_list)[i].crc_tag = i * 5 + 1;
        if (!RAND_bytes((unsigned char*)&(*pdu_list)[i].crcflag, sizeof((*pdu_list)[i].crcflag))) {
            free(*pdu_list);
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }
    }

    // Set the cipher mode based on the index
    switch (N % 4) {
        case 0:
            EVP_EncryptInit_ex(ctx, EVP_des_ecb(), NULL, NULL, NULL); break;
        case 1:
            EVP_EncryptInit_ex(ctx, EVP_des_ede(), NULL, NULL, NULL); break;
        case 2:
            EVP_EncryptInit_ex(ctx, EVP_des_ede3(), NULL, NULL, NULL); break;
        default:
            EVP_EncryptInit_ex(ctx, EVP_des_cfb(), NULL, NULL, NULL); break;
    }

    return ctx;
}
