NFAPI_CRC_INDICATION_PDU_T* manage_nfapi_list(NFAPI_CRC_INDICATION_PDU_T* current_list, size_t current_size, NFAPI_CRC_INDICATION_PDU_T new_entry) {
    if (current_size >= MAX_LIST_SIZE) {
        // Truncate the list by freeing the first entry and shifting the rest
        free(current_list);
        current_list = malloc((MAX_LIST_SIZE - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        for (size_t i = 0; i < MAX_LIST_SIZE - 1; ++i) {
            current_list[i] = current_list[i + 1];
        }
        --current_size;
    }

    // Insert the new entry at the end of the list
    current_list[current_size++] = new_entry;

    return current_list;
