#define MAX_INTERFACES 100

typedef struct {
    int id;
    char ip[45];
    char subnet_mask[45];
} NetworkInterface;

NetworkInterface interfaces[MAX_INTERFACES];
int interface_count = 0;
pthread_mutex_t interface_lock;

void initialize_interfaces() {
    pthread_mutex_init(&interface_lock, NULL);
}

int add_interface(int id, const char *ip, const char *subnet_mask) {
    pthread_mutex_lock(&interface_lock);
    if (interface_count >= MAX_INTERFACES) {
        fprintf(stderr, "Max interfaces reached\n");
        pthread_mutex_unlock(&interface_lock);
        return -1;
    }
    for (int i = 0; i < interface_count; i++) {
        if (!strcmp(interfaces[i].ip, ip) || !strcmp(interfaces[i].subnet_mask, subnet_mask)) {
            fprintf(stderr, "IP or subnet mask already in use\n");
            pthread_mutex_unlock(&interface_lock);
            return -1;
        }
    }
    interfaces[interface_count].id = id;
    strcpy(interfaces[interface_count].ip, ip);
    strcpy(interfaces[interface_count].subnet_mask, subnet_mask);
    interface_count++;
    pthread_mutex_unlock(&interface_lock);
    return 0;
}

int remove_interface(int id) {
    pthread_mutex_lock(&interface_lock);
    for (int i = 0; i < interface_count; i++) {
        if (interfaces[i].id == id) {
            for (int j = i; j < interface_count - 1; j++) {
                interfaces[j] = interfaces[j + 1];
            }
            interface_count--;
            pthread_mutex_unlock(&interface_lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&interface_lock);
    fprintf(stderr, "Interface not found\n");
    return -1;
}

void log_change(const char *action, int id, const char *ip, const char *subnet_mask) {
    printf("%s interface %d with IP %s and subnet mask %s\n", action, id, ip, subnet_mask);
}
