#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct DataPacket {
    size_t payloadSize;
    char* dataBuffer;
} DataPacket;

typedef struct NetworkEvent {
    int EventID;
    time_t timestamp;
    DataPacket** packets;
    size_t packetCount;
} NetworkEvent;

typedef struct EventCache {
    NetworkEvent* events;
    size_t eventCapacity;
    size_t eventCount;
} EventCache;

NetworkEvent* createNetworkEvent(int eventId, time_t timestamp) {
    NetworkEvent* event = (NetworkEvent*)malloc(sizeof(NetworkEvent));
    if (!event) {
        fprintf(stderr, "Memory allocation failed for NetworkEvent\n");
        return NULL;
    }
    event->EventID = eventId;
    event->timestamp = timestamp;
    event->packets = NULL;
    event->packetCount = 0;
    return event;
}

DataPacket* createDataPacket(size_t payloadSize) {
    DataPacket* packet = (DataPacket*)malloc(sizeof(DataPacket));
    if (!packet) {
        fprintf(stderr, "Memory allocation failed for DataPacket\n");
        return NULL;
    }
    packet->payloadSize = payloadSize;
    packet->dataBuffer = (char*)malloc(payloadSize * sizeof(char));
    if (!packet->dataBuffer) {
        free(packet);
        fprintf(stderr, "Memory allocation failed for data buffer in DataPacket\n");
        return NULL;
    }
    return packet;
}

void addDataPacketToEvent(NetworkEvent* event, DataPacket* packet) {
    event->packets = (DataPacket**)realloc(event->packets, (event->packetCount + 1) * sizeof(DataPacket*));
    if (!event->packets) {
        fprintf(stderr, "Memory reallocation failed for packets in NetworkEvent\n");
        return;
    }
    event->packets[event->packetCount++] = packet;
}

void initializeNetworkEvents(EventCache* cache, int eventId, time_t timestamp, size_t packetCount, size_t payloadSize) {
    if (cache->eventCount >= cache->eventCapacity) {
        cache->events = (NetworkEvent**)realloc(cache->events, (cache->eventCapacity + 10) * sizeof(NetworkEvent*));
        if (!cache->events) {
            fprintf(stderr, "Memory reallocation failed for events in EventCache\n");
            return;
        }
        cache->eventCapacity += 10;
    }
    NetworkEvent* event = createNetworkEvent(eventId, timestamp);
    if (event) {
        for (size_t i = 0; i < packetCount; ++i) {
            DataPacket* packet = createDataPacket(payloadSize);
            if (packet) {
                addDataPacketToEvent(event, packet);
            }
        }
        cache->events[cache->eventCount++] = event;
    }
}

void freeNetworkEvents(EventCache* cache) {
    for (size_t i = 0; i < cache->eventCount; ++i) {
        NetworkEvent* event = cache->events[i];
        if (event) {
            for (size_t j = 0; j < event->packetCount; ++j) {
                DataPacket* packet = event->packets[j];
                free(packet->dataBuffer);
                free(packet);
            }
            free(event->packets);
            free(event);
        }
    }
    free(cache->events);
}

