#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_ELEMENTS 10000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_list(int N, int min_rnti, int max_rnti) {
    if (N > MAX_ELEMENTS || min_rnti < 0 || max_rnti >= 65536) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    srand(time(NULL));

    int used_tags[MAX_ELEMENTS] = {0};
    int rnti_count = 0;

    for (int i = 0; i < N; ++i) {
        uint32_t tag = rand() % MAX_ELEMENTS;
        while (used_tags[tag]) {
            tag = rand() % MAX_ELEMENTS;
        }
        used_tags[tag] = 1;

        list[i].RX_UE_INFORMATION_TAG = tag;

        if (rnti_count < max_rnti - min_rnti + 1) {
            list[i].RNTI = min_rnti + rnti_count++;
        } else {
            list[i].RNTI = rand() % (max_rnti - min_rnti + 1) + min_rnti;
        }

        list[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
    }

    return list;
}

int main() {
    int N = 5000;
    int min_rnti = 100;
    int max_rnti = 999;

    NFAPI_CRC_INDICATION_PDU_T* list = allocate_and_populate_list(N, min_rnti, max_rnti);

    if (list != NULL) {
        for (int i = 0; i < N; ++i) {
            printf("Tag: %u, RNTI: %u, CRCFLAG: %d\n", list[i].RX_UE_INFORMATION_TAG, list[i].RNTI, list[i].CRCFLAG);
        }
        free(list);
    }

    return 0;
}
