typedef struct {
    NFAPI_CRC_INDICATION_PDU_T** pool;
    size_t poolSize;
    size_t usedCount;
    size_t budget;
    void (*allocateMemory)(size_t);
    void (*freeMemory)(void*);
} MemoryPoolManager;

MemoryPoolManager* createMemoryPool(size_t budget, size_t initialPoolSize) {
    MemoryPoolManager* manager = (MemoryPoolManager*)malloc(sizeof(MemoryPoolManager));
    if (!manager) return NULL;

    manager->budget = budget;
    manager->usedCount = 0;
    manager->poolSize = initialPoolSize;
    manager->pool = (NFAPI_CRC_INDICATION_PDU_T**)malloc(initialPoolSize * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!manager->pool) {
        free(manager);
        return NULL;
    }

    // Initialize the allocate and free memory functions
    manager->allocateMemory = malloc; // Replace with actual library function
    manager->freeMemory = free;      // Replace with actual library function

    for (size_t i = 0; i < initialPoolSize; ++i) {
        manager->pool[i] = (NFAPI_CRC_INDICATION_PDU_T*)manager->allocateMemory(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!manager->pool[i]) {
            // Handle allocation failure
            for (size_t j = 0; j < i; ++j) {
                manager->freeMemory(manager->pool[j]);
            }
            free(manager->pool);
            free(manager);
            return NULL;
        }
    }

    return manager;
}

void destroyMemoryPool(MemoryPoolManager* manager) {
    for (size_t i = 0; i < manager->usedCount; ++i) {
        manager->freeMemory(manager->pool[i]);
    }
    free(manager->pool);
    free(manager);
}

NFAPI_CRC_INDICATION_PDU_T* allocatePdu(MemoryPoolManager* manager) {
    if (manager->usedCount == manager->poolSize) {
        // Handle allocation failure
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = manager->pool[manager->usedCount++];
    return pdu;
}

void deallocatePdu(MemoryPoolManager* manager, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    for (size_t i = 0; i < manager->usedCount; ++i) {
        if (manager->pool[i] == pdu) {
            // Move the last element to fill the gap
            manager->pool[i] = manager->pool[--manager->usedCount];
            return;
        }
    }
}

void checkAndEvict(MemoryPoolManager* manager) {
    while (manager->usedCount > 0 && (manager->usedCount * sizeof(NFAPI_CRC_INDICATION_PDU_T)) > manager->budget) {
        deallocatePdu(manager, manager->pool[0]);
    }
}
