typedef struct NFAPI_CRC_INDICATION_PDU_NODE {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct NFAPI_CRC_INDICATION_PDU_NODE* next;
} NFAPI_CRC_INDICATION_PDU_NODE;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_NODE* head;
    NFAPI_CRC_INDICATION_PDU_NODE* tail;
    pthread_mutex_t lock;
} CRC_INDICATION_LIST;

CRC_INDICATION_LIST* create_crc_indication_list() {
    CRC_INDICATION_LIST* list = (CRC_INDICATION_LIST*)malloc(sizeof(CRC_INDICATION_LIST));
    if (!list) {
        log_error("Failed to allocate memory for CRC indication list.");
        return NULL;
    }
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_crc_indication_list(CRC_INDICATION_LIST* list) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_NODE* current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_NODE* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void add_to_crc_indication_list(CRC_INDICATION_LIST* list, NFAPI_CRC_INDICATION_PDU_T data) {
    NFAPI_CRC_INDICATION_PDU_NODE* new_node = (NFAPI_CRC_INDICATION_PDU_NODE*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_NODE));
    if (!new_node) {
        log_error("Failed to allocate memory for new CRC indication node.");
        return;
    }
    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    pthread_mutex_unlock(&list->lock);

    log_success("Successfully added CRC indication to the list.");
}

NFAPI_CRC_INDICATION_PDU_T* find_in_crc_indication_list(CRC_INDICATION_LIST* list, RX_UE_INFORMATION_TAG ue_tag) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_NODE* current = list->head;
    while (current) {
        if (current->data.ue_info_tag == ue_tag) {
            pthread_mutex_unlock(&list->lock);
            return &current->data;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void remove_from_crc_indication_list(CRC_INDICATION_LIST* list, RX_UE_INFORMATION_TAG ue_tag) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_NODE* current = list->head;
    NFAPI_CRC_INDICATION_PDU_NODE* prev = NULL;
    while (current) {
        if (current->data.ue_info_tag == ue_tag) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            if (current == list->tail) {
                list->tail = prev;
            }
            free(current);
            pthread_mutex_unlock(&list->lock);
            log_success("Successfully removed CRC indication from the list.");
            return;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    log_error("CRC indication not found in the list.");
}
