void encrypt_data(NFAPI_CRC_INDICATION_PDU_T* data, size_t size) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) return;

    unsigned char key[32];
    unsigned char iv[16];

    // Generate a random key and IV
    RAND_bytes(key, sizeof(key));
    RAND_bytes(iv, sizeof(iv));

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    // Encrypt the data
    int len;
    if (EVP_EncryptUpdate(ctx, NULL, &len, data, size) != 1 ||
        EVP_EncryptFinal_ex(ctx, NULL, &len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    EVP_CIPHER_CTX_free(ctx);
}

