#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "memory_manager_library.h" // Hypothetical external memory management library

typedef struct {
    int id;
    time_t timestamp;
    size_t payload_size;
    char* payload;
} NetworkMessage;

NetworkMessage** allocate_network_messages(size_t max_payload_size, size_t limit_in_bytes) {
    static NetworkMessage* messages = NULL;
    static size_t allocated_count = 0;
    static size_t total_memory_used = 0;

    // Check if allocation is needed
    if (allocated_count == 0) {
        messages = memory_manager_library_allocate(limit_in_bytes);
        if (messages == NULL) {
            printf("Failed to allocate initial memory.\n");
            return NULL;
        }
    }

    // Try to allocate a new message
    NetworkMessage* new_message = memory_manager_library_allocate(sizeof(NetworkMessage));
    if (new_message == NULL) {
        printf("Failed to allocate memory for a new message.\n");
        return NULL;
    }

    // Calculate the new total memory usage
    size_t new_memory_usage = total_memory_used + sizeof(NetworkMessage);
    while (new_memory_usage > limit_in_bytes) {
        NetworkMessage* oldest_message = messages[0];
        total_memory_used -= sizeof(NetworkMessage) + oldest_message->payload_size;
        memory_manager_library_deallocate(oldest_message->payload);
        memory_manager_library_deallocate(oldest_message);

        memmove(messages, messages + 1, (allocated_count - 1) * sizeof(NetworkMessage*));
        allocated_count--;
        new_memory_usage = total_memory_used + sizeof(NetworkMessage);
    }

    // Initialize the new message
    new_message->id = generated_unique_id();
    new_message->timestamp = time(NULL);
    new_message->payload_size = max_payload_size;
    new_message->payload = memory_manager_library_allocate(max_payload_size);
    if (new_message->payload == NULL) {
        printf("Failed to allocate payload for the message.\n");
        return NULL;
    }
    memset(new_message->payload, 0, max_payload_size);

    // Add the new message to the array
    messages[allocated_count++] = new_message;
    total_memory_used += sizeof(NetworkMessage);

    return messages;
}

void free_network_messages() {
    for (size_t i = 0; i < allocated_count; i++) {
        memory_manager_library_deallocate(messages[i]->payload);
        memory_manager_library_deallocate(messages[i]);
    }
    memory_manager_library_deallocate(messages);
    allocated_count = 0;
    total_memory_used = 0;
}
```

