#include <stdlib.h>
#include <pthread.h>

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T data;
    int in_use;
} NfaPduPoolEntry;

typedef struct {
    NfaPduPoolEntry* pool;
    size_t pool_size;
    size_t used_memory;
    size_t budget;
    pthread_mutex_t lock;
    // Additional fields for eviction policy and configuration
} NfaPduPool;

NfaPduPool* create_pool(size_t budget) {
    NfaPduPool* pool = (NfaPduPool*)malloc(sizeof(NfaPduPool));
    if (!pool) return NULL;

    pool->budget = budget;
    pool->used_memory = 0;
    pool->pool_size = budget / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    pool->pool = (NfaPduPoolEntry*)malloc(pool->pool_size * sizeof(NfaPduPoolEntry));
    if (!pool->pool) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);

    for (size_t i = 0; i < pool->pool_size; i++) {
        pool->pool[i].in_use = 0;
    }

    return pool;
}

void destroy_pool(NfaPduPool* pool) {
    if (!pool) return;

    pthread_mutex_lock(&pool->lock);
    free(pool->pool);
    pthread_mutex_unlock(&pool->lock);

    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu(NfaPduPool* pool) {
    if (!pool) return NULL;

    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->pool_size; i++) {
        if (!pool->pool[i].in_use) {
            pool->pool[i].in_use = 1;
            pthread_mutex_unlock(&pool->lock);
            return &pool->pool[i].data;
        }
    }

    pthread_mutex_unlock(&pool->lock);
    return NULL;
}

void deallocate_pdu(NfaPduPool* pool, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pool || !pdu) return;

    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->pool_size; i++) {
        if (&pool->pool[i].data == pdu) {
            pool->pool[i].in_use = 0;
            break;
        }
    }

    pthread_mutex_unlock(&pool->lock);
}
