            if (rc != SQLITE_OK) goto error;
            rc = sqlite3_bind_int(stmt, 2, rxTag.crcFlag);
            if (rc != SQLITE_OK) goto error;

            // Bind other fields for crcTag as needed

            rc = sqlite3_step(stmt);
            if (rc != SQLITE_DONE) goto error;
        }

        sqlite3_finalize(stmt);

        endTime = getCurrentTime();
        elapsedTime = endTime - startTime;
        printf("Processed %d entries in %lld ms\n", listSize, elapsedTime);

        return; // Success, exit the loop

error:
        sqlite3_finalize(stmt);
        rc = sqlite3_errcode(db);
        if (rc == SQLITE_BUSY || rc == SQLITE_LOCKED) {
            retryCount++;
            sleep(1 << retryCount); // Exponential backoff
        } else {
            fprintf(stderr, "Failed to execute SQL statement: %s\n", sqlite3_errmsg(db));
            sqlite3_close(db);
            exit(EXIT_FAILURE);
        }
    }

    fprintf(stderr, "Max retries reached. Failed to process entries.\n");
    sqlite3_close(db);
    exit(EXIT_FAILURE);
}

