FramePool* createNfadAndInitializeFrames(size_t initial_capacity, size_t frame_size, size_t realloc_threshold) {
    FramePool* pool = (FramePool*)malloc(sizeof(FramePool));
    if (!pool) {
        perror("Failed to allocate memory for FramePool");
        return NULL;
    }

    pool->frames = (Frame**)malloc(initial_capacity * sizeof(Frame*));
    if (!pool->frames) {
        free(pool);
        perror("Failed to allocate memory for frames");
        return NULL;
    }

    pool->capacity = initial_capacity;
    pool->size = 0;
    pool->realloc_threshold = realloc_threshold;

    // Initialize frames
    for (size_t i = 0; i < pool->capacity; ++i) {
        pool->frames[i] = (Frame*)malloc(frame_size);
        if (!pool->frames[i]) {
            perror("Failed to allocate memory for Frame");
            for (size_t j = 0; j < i; ++j) {
                free(pool->frames[j]);
            }
            free(pool->frames);
            free(pool);
            return NULL;
        }
    }

    // Log initialization parameters
    printf("FramePool initialized with capacity: %zu, frame size: %zu, realloc threshold: %zu\n", pool->capacity, frame_size, pool->realloc_threshold);

    return pool;
}

