#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/types.h>
#include <pthread.h>

#define MAX_RETRIES 5
#define INIT_BACKOFF_MS 100

typedef struct SensorDevice {
    int id;
    char type[50];
    struct sockaddr_in address;
} SensorDevice;

typedef struct ConnectionParams {
    int timeout;
    int max_bandwidth;
} ConnectionParams;

typedef struct DeviceConnection {
    int socket_fd;
    pthread_mutex_t lock;
} DeviceConnection;

DeviceConnection* connectToSensor(SensorDevice *device, ConnectionParams *params) {
    DeviceConnection *conn = (DeviceConnection*)malloc(sizeof(DeviceConnection));
    conn->socket_fd = -1;
    pthread_mutex_init(&conn->lock, NULL);

    int retry_count = 0;
    while(retry_count < MAX_RETRIES) {
        conn->socket_fd = socket(AF_INET, SOCK_STREAM, 0);
        if (conn->socket_fd == -1) {
            perror("Failed to create socket");
            usleep(INIT_BACKOFF_MS * (1 << retry_count));
            retry_count++;
            continue;
        }

        int optval = 1;
        if (setsockopt(conn->socket_fd, SOL_SOCKET, SO_REUSEADDR | SO_BROADCAST, &optval, sizeof(optval)) == -1) {
            perror("Failed to set socket options");
            close(conn->socket_fd);
            conn->socket_fd = -1;
            usleep(INIT_BACKOFF_MS * (1 << retry_count));
            retry_count++;
            continue;
        }

        if (connect(conn->socket_fd, (struct sockaddr*)&device->address, sizeof(device->address)) == -1) {
            perror("Failed to connect to sensor");
            close(conn->socket_fd);
            conn->socket_fd = -1;
            usleep(INIT_BACKOFF_MS * (1 << retry_count));
            retry_count++;
        } else {
            break; // Connection successful
        }
    }

    if (conn->socket_fd == -1) {
        free(conn);
        return NULL;
    }

    // Perform protocol negotiation here
    // ...

    return conn;
}

void* streamDataThread(void *arg) {
    DeviceConnection *conn = (DeviceConnection*)arg;

    pthread_mutex_lock(&conn->lock);
    if (conn->socket_fd == -1) {
        printf("No active connection to stream data.\n");
        pthread_mutex_unlock(&conn->lock);
        return NULL;
    }

    // Stream data logic here
    // ...

    pthread_mutex_unlock(&conn->lock);
    return NULL;
}

void initializeAndStreamDataFromSensorNetwork(SensorDevice *devices, int num_devices, ConnectionParams *params) {
    DeviceConnection **connections = (DeviceConnection**)malloc(num_devices * sizeof(DeviceConnection*));

    for(int i = 0; i < num_devices; i++) {
        connections[i] = connectToSensor(&devices[i], params);
        if (!connections[i]) {
            printf("Failed to connect to device %d\n", devices[i].id);
            continue;
        }

        // Start a thread to stream data for each connection
        pthread_t thread_id;
        if (pthread_create(&thread_id, NULL, streamDataThread, connections[i]) != 0) {
            perror("Failed to create thread");
            free(connections[i]);
            connections[i] = NULL;
        }
    }

    // Join threads and clean up
    for(int i = 0; i < num_devices; i++) {
        if (connections[i]) {
            pthread_join(connections[i]->thread_id, NULL);
            free(connections[i]);
        }
    }

    free(connections);
}
