#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
} ThreadSafeList;

void initThreadSafeList(ThreadSafeList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

void insertNode(ThreadSafeList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return; // Handle memory allocation failure
    newNode->data = data;
    newNode->next = NULL;

    pthread_mutex_lock(&list->mutex);
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->mutex);
}

void freeThreadSafeList(ThreadSafeList* list) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}

NFAPI_CRC_INDICATION_PDU_T generateRandomPDU(int minRNTIDiff) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = rand();
    pdu.RNTI = rand() % 4096; // Assuming a reasonable range for RNTI
    pdu.CRC_INDICATION_REL8_TAG = rand() % 256; // Random CRC value
    pdu.CRCFLAG = (rand() % minRNTIDiff) + minRNTIDiff; // Ensure non-consecutive RNTIs

    return pdu;
}

void generatePDUs(ThreadSafeList* list, int N, int minRNTIDiff) {
    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu = generateRandomPDU(minRNTIDiff);
        insertNode(list, pdu);
    }
}

// Example usage
int main() {
    ThreadSafeList list;
    initThreadSafeList(&list);

    int numPDUs = 1000;
    int minRNTIDiff = 50;

    generatePDUs(&list, numPDUs, minRNTIDiff);

    // Further processing...

    freeThreadSafeList(&list);
    return 0;
}
