#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <boost/asio.hpp>
#include <random>

struct NFAPI_CRC_INDICATION_PDU_T {
    std::string RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRCFLAG;
};

enum class State { IDLE, PROCESSING, ERROR };

class NFAPICRCManager {
private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> crcList;
    std::mutex listMutex;
    std::condition_variable cv;
    State state;

public:
    NFAPICRCManager() : state(State::IDLE) {}

    void addCRC(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        std::lock_guard<std::mutex> lock(listMutex);
        crcList.push_back(pdu);
        cv.notify_one();
    }

    void processCRCs(boost::asio::io_context& ioContext, const std::vector<std::string>& urls) {
        boost::asio::ip::tcp::resolver resolver(ioContext);

        for (const auto& url : urls) {
            std::thread([this, &resolver, url]() {
                try {
                    boost::asio::ip::tcp::resolver::results_type endpoints = resolver.resolve(url, "http");
                    boost::asio::ip::tcp::socket socket(ioContext);
                    boost::asio::connect(socket, endpoints);

                    // Simulate asynchronous GET request
                    auto start_time = std::chrono::steady_clock::now();
                    while (std::chrono::steady_clock::now() - start_time < std::chrono::seconds(1)) {
                        if (state != State::PROCESSING) {
                            break;
                        }
                        boost::asio::streambuf response;
                        boost::asio::read_until(socket, response, "\r\n\r\n");
                        // Process response
                    }
                } catch (std::exception& e) {
                    std::cerr << "Error: " << e.what() << std::endl;
                }
            }).detach();
        }

        cv.wait(lock, [this]() { return state == State::IDLE; });
    }

    void startProcessing() {
        std::unique_lock<std::mutex> lock(listMutex);
        state = State::PROCESSING;
    }

    void stopProcessing() {
        std::unique_lock<std::mutex> lock(listMutex);
        state = State::IDLE;
        cv.notify_all();
    }
};

int main() {
    boost::asio::io_context ioContext;

    NFAPICRCManager manager;
    manager.startProcessing();

    std::vector<NFAPI_CRC_INDICATION_PDU_T> pdus = {
        {"RX_UE_INFO_1", 100, true},
        {"RX_UE_INFO_2", 200, false}
    };

    for (const auto& pdu : pdus) {
        manager.addCRC(pdu);
    }

    std::vector<std::string> urls = {
        "http://example.com/api/data1",
        "http://example.com/api/data2"
    };

    manager.processCRCs(ioContext, urls);

    manager.stopProcessing();

    return 0;
}
