NFAPI_CRC_INDICATION_PDU_T** init_crc_list(int N) {
    if (N > MAX_LIST_SIZE) {
        return NULL; // Exceeds global maximum list size
    }

    NFAPI_CRC_INDICATION_PDU_T** list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (list == NULL) {
        return NULL; // Memory allocation failed
    }

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < N; i++) {
        list[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (list[i] == NULL) {
            // Free previously allocated memory on failure
            for (int j = 0; j < i; j++) {
                free(list[j]);
            }
            free(list);
            return NULL; // Memory allocation failed
        }

        list[i]->RX_UE_INFORMATION_TAG = rand();
        list[i]->RNTI = rand() % 1024;
        list[i]->CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG

        // Duplicate check logic
        for (int j = 0; j < i; j++) {
            if (list[i]->RX_UE_INFORMATION_TAG == list[j]->RX_UE_INFORMATION_TAG) {
                // Handle duplicate, e.g., skip this entry or use a unique identifier
                free(list[i]);
                for (int k = j; k < i; k++) {
                    list[k] = list[k + 1];
                }
                i--; // Adjust counter to compensate for removed entry
                break;
            }
        }
    }

    return list;
}

void free_crc_list(NFAPI_CRC_INDICATION_PDU_T** list, int N) {
    for (int i = 0; i < N; i++) {
        if (list[i] != NULL) {
            free(list[i]);
        }
    }
    free(list);
