#include <stdlib.h>
#include <pthread.h>

typedef struct {
    uint8_t *data;
    size_t length;
} MACSDU;

typedef struct {
    // Define your MAC_HEADER structure here
    uint16_t headerField;
} MAC_HEADER;

typedef struct {
    uint8_t *payload;
    size_t payloadSize;
    MACSDU **sdus;
    size_t sdusCount;
} MAC_PAYLOAD;

typedef struct {
    MAC_HEADER header;
    MAC_PAYLOAD payload;
} MAC_PDU;

typedef struct {
    MAC_PDU **array;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* dynamicArrayCreate(size_t initialCapacity) {
    DynamicArray *arr = (DynamicArray*)malloc(sizeof(DynamicArray));
    arr->array = (MAC_PDU**)malloc(initialCapacity * sizeof(MAC_PDU*));
    arr->count = 0;
    arr->capacity = initialCapacity;
    pthread_mutex_init(&arr->lock, NULL);
    return arr;
}

void dynamicArrayDestroy(DynamicArray *arr) {
    for (size_t i = 0; i < arr->count; ++i) {
        free(arr->array[i]->payload.payload);
        for (size_t j = 0; j < arr->array[i]->payload.sdusCount; ++j) {
            free(arr->array[i]->payload.sdus[j]);
        }
        free(arr->array[i]->payload.sdus);
        free(arr->array[i]);
    }
    free(arr->array);
    pthread_mutex_destroy(&arr->lock);
    free(arr);
}

void dynamicArrayAdd(DynamicArray *arr, MAC_PDU *pdu) {
    pthread_mutex_lock(&arr->lock);
    if (arr->count == arr->capacity) {
        arr->capacity *= 2;
        arr->array = realloc(arr->array, arr->capacity * sizeof(MAC_PDU*));
    }
    arr->array[arr->count++] = pdu;
    pthread_mutex_unlock(&arr->lock);
}

MAC_PDU* dynamicArrayGet(DynamicArray *arr, size_t index) {
    if (index >= arr->count) return NULL;
    pthread_mutex_lock(&arr->lock);
    MAC_PDU *pdu = arr->array[index];
    pthread_mutex_unlock(&arr->lock);
    return pdu;
}

void dynamicArrayRemove(DynamicArray *arr, size_t index) {
    if (index >= arr->count) return;
    pthread_mutex_lock(&arr->lock);
    free(arr->array[index]->payload.payload);
    for (size_t j = 0; j < arr->array[index]->payload.sdusCount; ++j) {
        free(arr->array[index]->payload.sdus[j]);
    }
    free(arr->array[index]->payload.sdus);
    free(arr->array[index]);
    for (size_t i = index; i < arr->count - 1; ++i) {
        arr->array[i] = arr->array[i + 1];
    }
    arr->count--;
    pthread_mutex_unlock(&arr->lock);
}
