#define MAX_ELEMENTS 1000
#define MAX_RNTI 4095

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

void log_event(const char *message) {
    // Placeholder for logging function
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_list(int N, int allocation_limit) {
    if (N > MAX_ELEMENTS || allocation_limit <= 0) {
        return NULL;
    }

    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T *head = NULL;
    NFAPI_CRC_INDICATION_PDU_T *current = NULL;

    for (int i = 0; i < N; ++i) {
        if (i > 0 && current->RNTI == rand() % MAX_RNTI) {
            --i; // Retry with a different RNTI
            continue;
        }

        NFAPI_CRC_INDICATION_PDU_T *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) {
            log_event("Memory allocation failed");
            free_list(head);
            return NULL;
        }

        new_node->RX_UE_INFORMATION_TAG = rand();
        new_node->RNTI = (current ? current->RNTI : 0) + 1; // Ensure no two consecutive elements share the same RNTI
        new_node->CRC_INDICATION_REL8_TAG = rand() % 2;
        new_node->next = NULL;

        if (!head) {
            head = new_node;
        } else {
            current->next = new_node;
        }

        current = new_node;
    }

    return head;
}

void free_list(NFAPI_CRC_INDICATION_PDU_T *head) {
    NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }
}

// Example usage
int main() {
    int N = 50;
    int allocation_limit = MAX_ELEMENTS / 2;

    NFAPI_CRC_INDICATION_PDU_T *head = create_crc_indication_list(N, allocation_limit);
    if (head) {
        // Process the list...
        free_list(head);
    }

    return 0;
}
