    pthread_mutex_init(&queue->lock, NULL);
}

void enqueue_message(NFAPI_MESSAGE_QUEUE *queue, NFAPI_MESSAGE_T message) {
    pthread_mutex_lock(&queue->lock);
    if (queue->count < MAX_MESSAGES) {
        queue->messages[queue->count++] = message;
    }
    pthread_mutex_unlock(&queue->lock);
}

NFAPI_MESSAGE_T dequeue_message(NFAPI_MESSAGE_QUEUE *queue) {
    NFAPI_MESSAGE_T message = {0};
    pthread_mutex_lock(&queue->lock);
    if (queue->count > 0) {
        message = queue->messages[--queue->count];
    }
    pthread_mutex_unlock(&queue->lock);
    return message;
}

