int is_unique_tag(NFAPI_CRC_INDICATION_PDU_T** array, int size, int tag) {
    for (int i = 0; i < size; i++) {
        if (array[i]->info.RX_UE_INFORMATION_TAG == tag) {
            return 0;
        }
    }
    return 1;
}

NFAPI_CRC_INDICATION_PDU_T** allocate_unique_tags(int N, int* actual_size, pthread_mutex_t* lock) {
    NFAPI_CRC_INDICATION_PDU_T** array = NULL;
    int size = N;

    while (size > 0) {
        pthread_mutex_lock(lock);
        array = realloc(array, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * size);
        if (!array) {
            pthread_mutex_unlock(lock);
            log_error("Memory allocation failed for unique tags.");
            return NULL;
        }

        int count = 0;
        for (int i = 0; i < size; i++) {
            array[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!array[i]) {
                log_error("Memory allocation failed for individual structure.");
                free(array);
                pthread_mutex_unlock(lock);
                return NULL;
            }

            do {
                array[i]->info.RX_UE_INFORMATION_TAG = rand() % 1000; // Simulate unique tag generation
                array[i]->RNTI = rand() % 256; // Simulate RNTI generation
                array[i]->CRCFLAG = rand() % 2; // Simulate CRCFLAG generation
            } while (!is_unique_tag(array, i + 1, array[i]->info.RX_UE_INFORMATION_TAG));

            count++;
        }

        if (count == N) {
            *actual_size = size;
            pthread_mutex_unlock(lock);
            return array;
        } else {
            free(array);
            size /= 2;
            log_warning("Duplicate tags found, reallocating memory.");
        }
    }

    pthread_mutex_unlock(lock);
    log_error("Failed to allocate unique tags within the given constraints.");
    return NULL;
}

int main() {
