    int actual_size = 0;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    NFAPI_CRC_INDICATION_PDU_T** array = allocate_unique_tags(N, &actual_size, &lock);
    if (array) {
        printf("Successfully allocated %d unique tags.\n", actual_size);
        // Free memory when done
        for (int i = 0; i < actual_size; i++) {
            free(array[i]);
        }
        free(array);
    } else {
        printf("Failed to allocate unique tags.\n");
    }

    return 0;
}
