typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} CRC_Queue;

CRC_Queue* create_crc_queue() {
    CRC_Queue *queue = (CRC_Queue *)malloc(sizeof(CRC_Queue));
    if (!queue) return NULL;

    queue->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_LIST_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!queue->data) {
        free(queue);
        return NULL;
    }

    queue->size = 0;
    queue->capacity = MAX_LIST_SIZE;
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->cond, NULL);

    return queue;
}

void destroy_crc_queue(CRC_Queue *queue) {
    if (queue) {
        free(queue->data);
        pthread_mutex_destroy(&queue->mutex);
        pthread_cond_destroy(&queue->cond);
        free(queue);
    }
}

int enqueue_crc_indication(CRC_Queue *queue, NFAPI_CRC_INDICATION_PDU_T *indication) {
    pthread_mutex_lock(&queue->mutex);

    while (queue->size == queue->capacity) {
        // Queue is full, wait for space
        pthread_cond_wait(&queue->cond, &queue->mutex);
    }

    if (queue->size >= MAX_LIST_SIZE) {
        pthread_mutex_unlock(&queue->mutex);
        return -1; // Error: List size exceeds maximum limit
    }

    queue->data[queue->size++] = *indication;
    pthread_cond_signal(&queue->cond);

    pthread_mutex_unlock(&queue->mutex);
    return 0;
}

int dequeue_crc_indication(CRC_Queue *queue, NFAPI_CRC_INDICATION_PDU_T *indication) {
    pthread_mutex_lock(&queue->mutex);

    while (queue->size == 0) {
        // Queue is empty, wait for data
        pthread_cond_wait(&queue->cond, &queue->mutex);
    }

    *indication = queue->data[--queue->size];
    pthread_cond_signal(&queue->cond);

    pthread_mutex_unlock(&queue->mutex);
    return 0;
}

int process_crc_indications(CRC_Queue *queue) {
    NFAPI_CRC_INDICATION_PDU_T indication;
    while (1) {
        if (dequeue_crc_indication(queue, &indication) == -1) break; // Error: List size exceeds maximum limit

        // Process the indication here
    }

    return 0;
}
