#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_UE 1024
#define NUM_BANDS 3

typedef struct {
    int ue_id;
    float signal_strength[NUM_BANDS];
    time_t timestamp;
} LTE_Measurement;

typedef struct {
    LTE_Measurement *measurements;
    int count;
    pthread_mutex_t lock;
} MeasurementManager;

MeasurementManager mm;

void init_measurement_manager() {
    mm.measurements = (LTE_Measurement *)malloc(MAX_UE * sizeof(LTE_Measurement));
    if (!mm.measurements) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    mm.count = 0;
    pthread_mutex_init(&mm.lock, NULL);
}

void add_measurement(int ue_id, float signal_strength[NUM_BANDS]) {
    pthread_mutex_lock(&mm.lock);
    if (mm.count < MAX_UE) {
        mm.measurements[mm.count].ue_id = ue_id;
        for (int i = 0; i < NUM_BANDS; i++) {
            mm.measurements[mm.count].signal_strength[i] = signal_strength[i];
        }
        mm.measurements[mm.count].timestamp = time(NULL);
        mm.count++;
    } else {
        fprintf(stderr, "Measurement manager is full\n");
    }
    pthread_mutex_unlock(&mm.lock);
}

void update_measurement(int ue_id, float signal_strength[NUM_BANDS]) {
    pthread_mutex_lock(&mm.lock);
    for (int i = 0; i < mm.count; i++) {
        if (mm.measurements[i].ue_id == ue_id) {
            for (int j = 0; j < NUM_BANDS; j++) {
                mm.measurements[i].signal_strength[j] = signal_strength[j];
            }
            mm.measurements[i].timestamp = time(NULL);
            break;
        }
    }
    pthread_mutex_unlock(&mm.lock);
}

float calculate_average_signal(int ue_id) {
    float sum = 0;
    int count = 0;
    pthread_mutex_lock(&mm.lock);
    for (int i = 0; i < mm.count; i++) {
        if (mm.measurements[i].ue_id == ue_id) {
            for (int j = 0; j < NUM_BANDS; j++) {
                sum += mm.measurements[i].signal_strength[j];
            }
            count++;
        }
    }
    pthread_mutex_unlock(&mm.lock);
    return count > 0 ? sum / (count * NUM_BANDS) : 0;
}

void purge_outdated_measurements(time_t cutoff_time) {
    pthread_mutex_lock(&mm.lock);
    for (int i = mm.count - 1; i >= 0; i--) {
        if (difftime(mm.measurements[i].timestamp, cutoff_time) > 0) {
            memmove(&mm.measurements[i], &mm.measurements[i + 1], (mm.count - i - 1) * sizeof(LTE_Measurement));
            mm.count--;
        }
    }
    pthread_mutex_unlock(&mm.lock);
}

void *measurement_thread(void *arg) {
    // Simulate adding and updating measurements
    float signal_strength[NUM_BANDS] = {20.5, 25.3, 18.9};
    add_measurement(1, signal_strength);
    update_measurement(1, (float[]){22.0, 24.5, 19.0});
    return NULL;
}

int main() {
    init_measurement_manager();
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, measurement_thread, NULL);
    pthread_join(thread_id, NULL);

    printf("Average signal strength for UE 1: %.2f\n", calculate_average_signal(1));

    // Purge outdated measurements (e.g., older than 1 hour)
    purge_outdated_measurements(time(NULL) - 3600);

    free(mm.measurements);
    pthread_mutex_destroy(&mm.lock);
    return 0;
}
