typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} DynamicList;

void initDynamicList(DynamicList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void addElement(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        // Handle allocation failure
        return;
    }
    newNode->data = data;
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
}

void removeElementByIndex(DynamicList* list, int index) {
    if (index < 0) {
        // Handle invalid index
        return;
    }

    Node* current = list->head;
    Node* previous = NULL;

    pthread_mutex_lock(&list->lock);

    while (current != NULL && index > 0) {
        previous = current;
        current = current->next;
        index--;
    }

    if (current == NULL) {
        // Handle invalid index
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (previous == NULL) {
        list->head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
    pthread_mutex_unlock(&list->lock);
}

void updateElement(DynamicList* list, int index, NFAPI_CRC_INDICATION_PDU_T newData) {
    if (index < 0) {
        // Handle invalid index
        return;
    }

    Node* current = list->head;

    pthread_mutex_lock(&list->lock);

    while (current != NULL && index > 0) {
        current = current->next;
        index--;
    }

    if (current == NULL) {
        // Handle invalid index
        pthread_mutex_unlock(&list->lock);
        return;
    }

    current->data = newData;

    pthread_mutex_unlock(&list->lock);
}

// Function to update elements from external data source
void updateFromExternalSource(DynamicList* list) {
    // Simulate periodic updates
    NFAPI_CRC_INDICATION_PDU_T newData = { /* new values */ };
    updateElement(list, 0, newData); // Update the first element for example
}

