#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_STRUCTS 10000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
    size_t count;
} DynamicCollection;

DynamicCollection* initCollection() {
    DynamicCollection* collection = (DynamicCollection*)malloc(sizeof(DynamicCollection));
    if (!collection) return NULL;

    collection->head = NULL;
    pthread_mutex_init(&collection->mutex, NULL);
    collection->count = 0;
    return collection;
}

int addStructure(DynamicCollection* collection, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, unsigned char CRCFLAG) {
    if (collection->count >= MAX_STRUCTS) return -1; // Max limit reached

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return -2; // Allocation failed

    newNode->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newNode->data.RNTI = RNTI;
    newNode->data.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    newNode->data.CRCFLAG = CRCFLAG;
    newNode->next = NULL;

    pthread_mutex_lock(&collection->mutex);
    if (!collection->head) {
        collection->head = newNode;
    } else {
        Node* current = collection->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
    collection->count++;
    pthread_mutex_unlock(&collection->mutex);

    return 0; // Success
}

size_t getCollectionSize(DynamicCollection* collection) {
    size_t size;
    pthread_mutex_lock(&collection->mutex);
    size = collection->count;
    pthread_mutex_unlock(&collection->mutex);
    return size;
}

void freeCollection(DynamicCollection* collection) {
    pthread_mutex_lock(&collection->mutex);
    Node* current = collection->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    collection->head = NULL;
    collection->count = 0;
    pthread_mutex_unlock(&collection->mutex);

    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}
