    NFAPI_CRC_INDICATION_PDU_T *list[MAX_LIST_SIZE];
    size_t count;
    pthread_mutex_t mutex;
} NFAPI_List_T;

StatusCode init_list(NFAPI_List_T *list) {
    list->count = 0;
    if (pthread_mutex_init(&list->mutex, NULL) != 0) {
        return STATUS_ERROR_OUT_OF_MEMORY;
    }
    return STATUS_SUCCESS;
}

StatusCode add_element(NFAPI_List_T *list, NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= MAX_LIST_SIZE) {
        pthread_mutex_unlock(&list->mutex);
        return STATUS_ERROR_OUT_OF_MEMORY;
    }
    list->list[list->count++] = element;
    pthread_mutex_unlock(&list->mutex);
    return STATUS_SUCCESS;
}

StatusCode remove_element(NFAPI_List_T *list, size_t index) {
    pthread_mutex_lock(&list->mutex);
    if (index >= list->count) {
        pthread_mutex_unlock(&list->mutex);
        return STATUS_ERROR_INVALID_INDEX;
    }
    for (size_t i = index; i < list->count - 1; ++i) {
        list->list[i] = list->list[i + 1];
    }
    --list->count;
    pthread_mutex_unlock(&list->mutex);
    return STATUS_SUCCESS;
}

StatusCode update_element(NFAPI_List_T *list, size_t index, NFAPI_CRC_INDICATION_PDU_T *newElement) {
    pthread_mutex_lock(&list->mutex);
    if (index >= list->count) {
        pthread_mutex_unlock(&list->mutex);
        return STATUS_ERROR_INVALID_INDEX;
    }
    list->list[index] = newElement;
    pthread_mutex_unlock(&list->mutex);
    return STATUS_SUCCESS;
}

void free_list(NFAPI_List_T *list) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; ++i) {
        free(list->list[i]);
    }
    list->count = 0;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}

