#include <pthread.h>

typedef struct TCP_CONNECTION_RECORD_T {
    char client_ip[16];
    char server_ip[16];
    int connection_id;
    int tcp_error_code;
} TCP_CONNECTION_RECORD_T;

typedef struct CONNECTION_LIST_T {
    TCP_CONNECTION_RECORD_T* connections;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} CONNECTION_LIST_T;

void init_connection_list(CONNECTION_LIST_T* list, size_t initial_capacity) {
    list->connections = malloc(initial_capacity * sizeof(TCP_CONNECTION_RECORD_T));
    if (list->connections == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
}

void add_connection(CONNECTION_LIST_T* list, TCP_CONNECTION_RECORD_T connection) {
    pthread_mutex_lock(&list->lock);
    if (list->size == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        TCP_CONNECTION_RECORD_T* new_connections = realloc(list->connections, new_capacity * sizeof(TCP_CONNECTION_RECORD_T));
        if (new_connections == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&list->lock);
            return;
        }
        list->connections = new_connections;
        list->capacity = new_capacity;
    }
    list->connections[list->size++] = connection;
    pthread_mutex_unlock(&list->lock);
}

void close_connection(CONNECTION_LIST_T* list, int connection_id) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; ++i) {
        if (list->connections[i].connection_id == connection_id) {
            list->connections[i] = list->connections[--list->size];
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void update_tcp_error_code(CONNECTION_LIST_T* list, int connection_id, int new_error_code) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; ++i) {
        if (list->connections[i].connection_id == connection_id) {
            list->connections[i].tcp_error_code = new_error_code;
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void destroy_connection_list(CONNECTION_LIST_T* list) {
    pthread_mutex_lock(&list->lock);
    free(list->connections);
    pthread_mutex_destroy(&list->lock);
}
