#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>

#define BLOCK_SIZE 1024

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct FixedSizeBlock {
    NFAPI_CRC_INDICATION_PDU_T data[BLOCK_SIZE];
    struct FixedSizeBlock *next;
} FixedSizeBlock;

typedef struct DynamicArrayManager {
    pthread_mutex_t mutex;
    FixedSizeBlock *head;
    int count;
} DynamicArrayManager;

DynamicArrayManager* create_dam() {
    DynamicArrayManager *dam = malloc(sizeof(DynamicArrayManager));
    pthread_mutex_init(&dam->mutex, NULL);
    dam->head = NULL;
    dam->count = 0;
    return dam;
}

void destroy_dam(DynamicArrayManager *dam) {
    FixedSizeBlock *current = dam->head;
    while (current != NULL) {
        FixedSizeBlock *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&dam->mutex);
    free(dam);
}

void add_element(DynamicArrayManager *dam, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&dam->mutex);
    if (dam->count % BLOCK_SIZE == 0) {
        FixedSizeBlock *new_block = malloc(sizeof(FixedSizeBlock));
        new_block->next = dam->head;
        dam->head = new_block;
    }
    FixedSizeBlock *current_block = dam->head;
    current_block->data[dam->count % BLOCK_SIZE] = element;
    dam->count++;
    pthread_mutex_unlock(&dam->mutex);
}

NFAPI_CRC_INDICATION_PDU_T get_element(DynamicArrayManager *dam, int index) {
    pthread_mutex_lock(&dam->mutex);
    if (index < 0 || index >= dam->count) {
        NFAPI_CRC_INDICATION_PDU_T invalid = {0};
        pthread_mutex_unlock(&dam->mutex);
        return invalid;
    }
    FixedSizeBlock *current_block = dam->head;
    int block_index = index / BLOCK_SIZE;
    while (block_index--) {
        current_block = current_block->next;
    }
    NFAPI_CRC_INDICATION_PDU_T element = current_block->data[index % BLOCK_SIZE];
    pthread_mutex_unlock(&dam->mutex);
    return element;
}

int get_count(DynamicArrayManager *dam) {
    pthread_mutex_lock(&dam->mutex);
    int count = dam->count;
    pthread_mutex_unlock(&dam->mutex);
    return count;
}
