typedef struct NFAPI_CRC_INDICATION_PDU_T {
    struct NFAPI_CRC_INDICATION_PDU_T *next;
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_list(int N, int sort_by_rnti) {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T *head = NULL;
    NFAPI_CRC_INDICATION_PDU_T *tail = NULL;

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) {
            printf("Memory allocation failed\n");
            return NULL;
        }
        new_node->RX_UE_INFORMATION_TAG = i + 1;
        new_node->RNTI = rand() % 256; // Assuming RNTI is an integer
        new_node->CRCFLAG = (rand() % 2) ? 0 : 1; // Randomly set CRCFLAG
        new_node->next = NULL;

        if (!head) {
            head = tail = new_node;
        } else {
            tail->next = new_node;
            tail = new_node;
        }
    }

    if (sort_by_rnti) {
        NFAPI_CRC_INDICATION_PDU_T *current, *index, *temp;

        for (current = head; current != NULL; current = current->next) {
            index = current->next;
            while (index != NULL) {
                if (current->RNTI > index->RNTI) {
                    temp->RX_UE_INFORMATION_TAG = current->RX_UE_INFORMATION_TAG;
                    current->RX_UE_INFORMATION_TAG = index->RX_UE_INFORMATION_TAG;
                    index->RX_UE_INFORMATION_TAG = temp->RX_UE_INFORMATION_TAG;

                    temp->RNTI = current->RNTI;
                    current->RNTI = index->RNTI;
                    index->RNTI = temp->RNTI;

                    temp->CRCFLAG = current->CRCFLAG;
                    current->CRCFLAG = index->CRCFLAG;
                    index->CRCFLAG = temp->CRCFLAG;
                }
                index = index->next;
            }
        }
    }

    return head;
}

void validate_list(NFAPI_CRC_INDICATION_PDU_T *head) {
    NFAPI_CRC_INDICATION_PDU_T *current = head;
    int previous_rnti = -1;

    while (current != NULL) {
        if (!current) {
            printf("Invalid pointer found\n");
            return;
        }
        if (previous_rnti == current->RNTI) {
            printf("Duplicate RNTI found: %d\n", current->RNTI);
            return;
        }
        previous_rnti = current->RNTI;
        current = current->next;
    }

    printf("List validation successful\n");
}

void free_list(NFAPI_CRC_INDICATION_PDU_T *head) {
    NFAPI_CRC_INDICATION_PDU_T *current, *temp;

    current = head;
    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }
}
