PHY_RX_INDICATION_MANAGER_T *phy_rx_indication_manager_init(size_t max_entries, const char *log_path) {
    PHY_RX_INDICATION_MANAGER_T *manager = (PHY_RX_INDICATION_MANAGER_T *)malloc(sizeof(PHY_RX_INDICATION_MANAGER_T));
    if (!manager) {
        perror("Failed to allocate memory for manager");
        return NULL;
    }
    manager->count = 0;

    int ret = pthread_mutex_init(&manager->mutex, NULL);
    if (ret != 0) {
        perror("Failed to initialize mutex");
        free(manager);
        return NULL;
    }

    manager->log_file = fopen(log_path, "a");
    if (!manager->log_file) {
        manager->log_file = stderr;
    } else {
        setbuf(manager->log_file, NULL); // Line buffering for real-time logging
    }

    return manager;
}

void phy_rx_indication_manager_destroy(PHY_RX_INDICATION_MANAGER_T *manager) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->entries[i]);
    }
    manager->count = 0;
    pthread_mutex_unlock(&manager->mutex);

    if (manager->log_file != stderr) {
        fclose(manager->log_file);
    }

    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

void phy_rx_indication_manager_add(PHY_RX_INDICATION_MANAGER_T *manager, PHY_RX_INDICATION_PDU_T *entry) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->count < MAX_ENTRIES) {
        manager->entries[manager->count++] = entry;
    } else {
        fprintf(manager->log_file, "Manager at capacity, cannot add new entry\n");
    }
    pthread_mutex_unlock(&manager->mutex);
}

PHY_RX_INDICATION_PDU_T *phy_rx_indication_manager_get(PHY_RX_INDICATION_MANAGER_T *manager, size_t index) {
    pthread_mutex_lock(&manager->mutex);
    if (index < manager->count) {
        PHY_RX_INDICATION_PDU_T *entry = manager->entries[index];
        pthread_mutex_unlock(&manager->mutex);
        return entry;
    } else {
        fprintf(manager->log_file, "Index out of bounds\n");
        pthread_mutex_unlock(&manager->mutex);
        return NULL;
    }
}

void phy_rx_indication_manager_log(PHY_RX_INDICATION_MANAGER_T *manager, const char *message) {
    pthread_mutex_lock(&manager->mutex);
    vfprintf(manager->log_file, message, va_list);
    pthread_mutex_unlock(&manager->mutex);
}
