public class WorldManager : MonoBehaviour
{
    private const int MaxWorlds = 20;
    private Dictionary<int, World> worlds = new Dictionary<int, World>();
    private int currentWorldIndex = -1;
    private Queue<World> worldQueue = new Queue<World>();

    public void LoadWorldsFromConfig(string configPath)
    {
        XDocument config = XDocument.Load(configPath);
        var worldConfigs = config.Element("Worlds").Elements("World");

        foreach (var worldConfig in worldConfigs.Take(MaxWorlds))
        {
            int id = (int)worldConfig.Attribute("Id");
            float tileSize = (float)worldConfig.Element("TileSize");
            Vector2 dimensions = new Vector2((float)worldConfig.Element("Width"), (float)worldConfig.Element("Height"));
            float cameraSpeed = (float)worldConfig.Element("CameraSpeed");

            World world = new World(id, tileSize, dimensions, cameraSpeed);
            worlds[id] = world;
        }

        foreach (var world in worlds.Values)
        {
            worldQueue.Enqueue(world);
        }
    }

    public void LoadNextWorld()
    {
        if (worldQueue.Count > 0)
        {
            World nextWorld = worldQueue.Dequeue();
            nextWorld.Load();
            currentWorldIndex = nextWorld.Id;
        }
        else
        {
            Debug.LogWarning("No more worlds to load.");
        }
    }

    public void LoadWorld(int id)
    {
        if (worlds.ContainsKey(id))
        {
            World requestedWorld = worlds[id];
            requestedWorld.Load();
            currentWorldIndex = requestedWorld.Id;
        }
        else
        {
            Debug.LogWarning($"World with ID {id} not found.");
        }
    }

    public void SaveWorldState()
    {
        if (currentWorldIndex >= 0)
        {
            World currentWorld = worlds[currentWorldIndex];
            currentWorld.SaveState();
        }
    }

    public void LoadWorldState()
    {
        if (currentWorldIndex >= 0)
        {
            World currentWorld = worlds[currentWorldIndex];
            currentWorld.LoadState();
        }
    }

    private class World
    {
        public int Id { get; private set; }
        public float TileSize { get; private set; }
        public Vector2 Dimensions { get; private set; }
        public float CameraSpeed { get; private set; }
        private GameObject worldObject;

        public World(int id, float tileSize, Vector2 dimensions, float cameraSpeed)
        {
            Id = id;
            TileSize = tileSize;
            Dimensions = dimensions;
            CameraSpeed = cameraSpeed;
        }

        public void Load()
        {
            if (worldObject != null)
                Destroy(worldObject);

            worldObject = new GameObject($"World_{Id}");
            worldObject.transform.position = Vector3.zero;

            // Load the world data from an external service
            StartCoroutine(LoadWorldDataAsync());
        }

        private IEnumerator LoadWorldDataAsync()
