ArrayManager* create_array_manager() {
    ArrayManager* manager = (ArrayManager*)malloc(sizeof(ArrayManager));
    if (!manager) return NULL;
    manager->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(REALLOC_BLOCK_SIZE, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        free(manager);
        return NULL;
    }
    manager->capacity = REALLOC_BLOCK_SIZE;
    manager->size = 0;
    return manager;
}

int insert_element(ArrayManager* manager, NFAPI_CRC_INDICATION_PDU_T element) {
    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity + REALLOC_BLOCK_SIZE;
        NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            return -1; // Memory allocation failed
        }
        manager->array = new_array;
        manager->capacity = new_capacity;
    }
    manager->array[manager->size++] = element;
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_element(ArrayManager* manager, size_t index) {
    if (index >= manager->size) return NULL; // Index out of bounds
    return &manager->array[index];
}

void free_array_manager(ArrayManager* manager) {
    free(manager->array);
    free(manager);
}
