#include <netdb.h>

#define MAX_IP_LEN 16

typedef struct {
    int rx_ue_information_tag;
    int rnti;
    int crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

int resolveDNS(const char *hostname, char *ip_address) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        char *ipver;

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
            ipver = "IPv4";
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
            ipver = "IPv6";
        }

        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ip_address, INET6_ADDRSTRLEN);
    }

    freeaddrinfo(res); // all done with this structure
    return 0;
}

int populateRxIndicationsAndResolveDNS(int nfaapi_pdu_list[], const char *hostname) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_array = malloc(nfaapi_pdu_list[0] * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu_array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    for (int i = 0; i < nfaapi_pdu_list[0]; i++) {
        pdu_array[i].rx_ue_information_tag = rand() % 1000 + 1; // Example range
        pdu_array[i].rnti = rand() % 256 + 1;
        pdu_array[i].crc_indication_rel8_tag = rand() % 2;

        char ip_address[MAX_IP_LEN];
        if (resolveDNS(hostname, ip_address) != 0) {
            free(pdu_array);
            return -2; // DNS resolution failed
        }
    }

    // Simulate processing of PDUs
    for (int i = 0; i < nfaapi_pdu_list[0]; i++) {
        printf("Processed PDU %d: RX_UE_INFO=%d, RNTI=%d, CRC_INDICATOR=%d\n",
               i, pdu_array[i].rx_ue_information_tag,
               pdu_array[i].rnti, pdu_array[i].crc_indication_rel8_tag);
    }

    free(pdu_array);
    return 0;
}
