#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    // Define PHY_VARS_NGAP_T structure members here
} PHY_VARS_NGAP_T;

typedef struct {
    // Define LOGGING_CONTEXT_T structure members here
    void (*reset_to_defaults)(LOGGING_CONTEXT_T*);
} LOGGING_CONTEXT_T;

typedef struct NFAPI_MESSAGE_T NFAPI_MESSAGE_T;
struct NFAPI_MESSAGE_T {
    int unique_id;
    PHY_VARS_NGAP_T config;
    LOGGING_CONTEXT_T log_ctx;
    NFAPI_MESSAGE_T* next;
};

typedef struct {
    NFAPI_MESSAGE_T** messages;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} MessageList;

void init_message_list(MessageList* list) {
    list->messages = NULL;
    list->capacity = 0;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_message_list(MessageList* list) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; ++i) {
        free(list->messages[i]);
    }
    free(list->messages);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int add_message(MessageList* list, PHY_VARS_NGAP_T config, LOGGING_CONTEXT_T log_ctx) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) {
        size_t new_capacity = (list->capacity == 0) ? 16 : list->capacity * 2;
        NFAPI_MESSAGE_T** new_messages = realloc(list->messages, new_capacity * sizeof(NFAPI_MESSAGE_T*));
        if (!new_messages) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }
        list->messages = new_messages;
        list->capacity = new_capacity;
    }

    NFAPI_MESSAGE_T* message = malloc(sizeof(NFAPI_MESSAGE_T));
    if (!message) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failed
    }

    message->unique_id = list->size + 1;
    message->config = config;
    log_ctx.reset_to_defaults(&message->log_ctx);
    message->next = NULL;

    list->messages[list->size++] = message;
    pthread_mutex_unlock(&list->lock);
    return message->unique_id;
}

void remove_message(MessageList* list, int unique_id) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; ++i) {
        if (list->messages[i]->unique_id == unique_id) {
            free(list->messages[i]);
            for (size_t j = i; j < list->size - 1; ++j) {
                list->messages[j] = list->messages[j + 1];
            }
            --list->size;
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void reset_log_context(MessageList* list, int unique_id) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; ++i) {
        if (list->messages[i]->unique_id == unique_id) {
            list->messages[i]->log_ctx.reset_to_defaults(&list->messages[i]->log_ctx);
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void iterate_messages(MessageList* list, void (*callback)(NFAPI_MESSAGE_T*)) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; ++i) {
        callback(list->messages[i]);
    }
    pthread_mutex_unlock(&list->lock);
}
