    if (!list->data) {
        free(list);
        return NULL;
    }

    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void destroy_dynamic_crc_list(DynamicCRCList_T* list) {
    if (list) {
        free(list->data);
        pthread_mutex_destroy(&list->mutex);
        free(list);
    }
