#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ARRAY_SIZE 1024

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t current_size;
    size_t max_size;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *da = (DynamicArray*)malloc(sizeof(DynamicArray));
    da->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_ARRAY_SIZE, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    da->current_size = 0;
    da->max_size = MAX_ARRAY_SIZE;
    pthread_mutex_init(&da->mutex, NULL);
    return da;
}

void destroy_dynamic_array(DynamicArray *da) {
    free(da->array);
    free(da);
}

int add_to_array(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&da->mutex);
    if (da->current_size >= da->max_size) {
        size_t new_max_size = da->max_size * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(da->array, new_max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&da->mutex);
            return -1; // Memory allocation failed
        }
        da->array = new_array;
        da->max_size = new_max_size;
    }

    for (size_t i = 0; i < da->current_size; ++i) {
        if (da->array[i].RNTI == pdu.RNTI) {
            pthread_mutex_unlock(&da->mutex);
            return -2; // Duplicate RNTI
        }
    }

    da->array[da->current_size++] = pdu;
    pthread_mutex_unlock(&da->mutex);
    return 0; // Success
}

int main() {
    DynamicArray *da = create_dynamic_array();

    NFAPI_CRC_INDICATION_PDU_T pdu1 = {1, 12345, 1};
    NFAPI_CRC_INDICATION_PDU_T pdu2 = {2, 67890, 0};

    add_to_array(da, pdu1);
    add_to_array(da, pdu2);

    destroy_dynamic_array(da);
    return 0;
}
```

This code snippet provides a basic implementation of a dynamically resizing array for `NFAPI_CRC_INDICATION_PDU_T` structures with thread safety. It includes functions to create and destroy the dynamic array, as well as add new elements while ensuring uniqueness of RNTI values. The use of mutexes ensures that concurrent access is handled safely.']

