char* calculate_CRC_INDICATION_REL8_TAG(int rnti, int rx_ue_info_tag) {
    static char crc_flag[2];
    snprintf(crc_flag, sizeof(crc_flag), "%d%d", (rnti % 10), (rx_ue_info_tag % 10));
    return crc_flag;
}

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_array(int *error_code) {
    if (error_code == NULL) {
        printf("Error: Error code pointer is NULL\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array == NULL) {
        printf("Error: Memory allocation failed\n");
        *error_code = -1;
        return NULL;
