        if (rnti < RNTI_VALID_RANGE_MIN || rnti > RNTI_VALID_RANGE_MAX) {
            printf("Error: Invalid RNTI value\n");
            *error_code = -2;
            free(array);
            return NULL;
        }

        array[i].RX_UE_INFORMATION_TAG = fetch_RX_UE_INFORMATION_TAG(rnti);
        array[i].RNTI = rnti;
        strcpy(array[i].CRC_INDICATION_REL8_TAG, calculate_CRC_INDICATION_REL8_TAG(rnti, array[i].RX_UE_INFORMATION_TAG));
    }

    *error_code = 0; // Success
    return array;
}

void free_array(NFAPI_CRC_INDICATION_PDU_T *array) {
    if (array != NULL) {
        free(array);
    }
}

int main() {
    int error_code;
    NFAPI_CRC_INDICATION_PDU_T *array = create_and_populate_array(&error_code);
    if (array == NULL) {
        printf("Failed to create and populate array with error code: %d\n", error_code);
        return 1;
    }

    // Process the array as needed
    free_array(array);
    return 0;
}
