NFAPICRCArrayElement mem_pool[MAX_NFAPIS];
int pool_index = 0;
pthread_mutex_t mem_lock;

void* allocate_memory(size_t size) {
    pthread_mutex_lock(&mem_lock);
    if (pool_index < MAX_NFAPIS) {
        void* ptr = &mem_pool[pool_index++];
        pthread_mutex_unlock(&mem_lock);
        return ptr;
    } else {
        pthread_mutex_unlock(&mem_lock);
        // Log memory allocation failure
        return NULL;
    }
}

void initialize_memory_pool() {
    for (int i = 0; i < MAX_NFAPIS; i++) {
        NFAPICRCArrayElement* element = &mem_pool[i];
        NFAPI_CRC_INDICATION_PDU_T* nfapi_cqi_pdu = &element->nfapi_cqi_pdu;

        // Initialize RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
