    pthread_mutex_lock(&mem_lock);
    for (int i = 0; i < N; i++) {
        NFAPICRCArrayElement* element = allocate_memory(sizeof(NFAPICRCArrayElement));
        if (element != NULL) {
            memcpy(array + i, &element->nfapi_cqi_pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        } else {
            // Handle memory allocation failure
            pthread_mutex_unlock(&mem_lock);
            return;
        }
    }
    pthread_mutex_unlock(&mem_lock);
}

void free_memory(void* ptr) {
    pthread_mutex_lock(&mem_lock);
    if (ptr >= mem_pool && ptr < mem_pool + MAX_NFAPIS) {
        pool_index = ((NFAPICRCArrayElement*)ptr - mem_pool);
    } else {
        // Handle invalid pointer
    }
    pthread_mutex_unlock(&mem_lock);
}
