#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_MEASUREMENTS 100

typedef enum {
    LTE_PHY_CHANNEL_TYPE_A,
    LTE_PHY_CHANNEL_TYPE_B,
    LTE_PHY_CHANNEL_TYPE_C
} LTE_PHY_CHANNEL_TYPE;

typedef struct LTE_PHY_CHANNEL_MEASUREMENTS_T {
    LTE_PHY_CHANNEL_TYPE type;
    int center_frequency;
    int channel_bandwidth;
    struct LTE_PHY_CHANNEL_MEASUREMENTS_T* next;
} LTE_PHY_CHANNEL_MEASUREMENTS_T;

LTE_PHY_CHANNEL_MEASUREMENTS_T* measurements_head = NULL;

int add_measurement(int center_frequency, int channel_bandwidth) {
    if (measurements_head == NULL) {
        measurements_head = malloc(sizeof(LTE_PHY_CHANNEL_MEASUREMENTS_T));
        if (measurements_head == NULL) {
            return -1; // Memory allocation failed
        }
        memset(measurements_head, 0, sizeof(LTE_PHY_CHANNEL_MEASUREMENTS_T));
    } else {
        LTE_PHY_CHANNEL_MEASUREMENTS_T* current = measurements_head;
        while (current->next != NULL && current->center_frequency != center_frequency) {
            current = current->next;
        }
        if (current->center_frequency == center_frequency) {
            // Center frequency already exists, reallocate memory
            LTE_PHY_CHANNEL_MEASUREMENTS_T* new_measurement = malloc(sizeof(LTE_PHY_CHANNEL_MEASUREMENTS_T));
            if (new_measurement == NULL) {
                return -1; // Memory allocation failed
            }
            memset(new_measurement, 0, sizeof(LTE_PHY_CHANNEL_MEASUREMENTS_T));
            new_measurement->center_frequency = center_frequency;
            new_measurement->channel_bandwidth = channel_bandwidth;
            new_measurement->next = measurements_head;
            measurements_head = new_measurement;
        } else {
            current->next = malloc(sizeof(LTE_PHY_CHANNEL_MEASUREMENTS_T));
            if (current->next == NULL) {
                return -1; // Memory allocation failed
            }
            memset(current->next, 0, sizeof(LTE_PHY_CHANNEL_MEASUREMENTS_T));
            current->next->center_frequency = center_frequency;
            current->next->channel_bandwidth = channel_bandwidth;
        }
    }
    return 0;
}

void free_measurements() {
    LTE_PHY_CHANNEL_MEASUREMENTS_T* current = measurements_head;
    while (current != NULL) {
        LTE_PHY_CHANNEL_MEASUREMENTS_T* next = current->next;
        free(current);
        current = next;
    }
    measurements_head = NULL;
}

int update_channel_bandwidth(int center_frequency, int new_bandwidth) {
    LTE_PHY_CHANNEL_MEASUREMENTS_T* current = measurements_head;
    while (current != NULL) {
        if (current->center_frequency == center_frequency) {
            current->channel_bandwidth = new_bandwidth;
            return 0;
        }
        current = current->next;
    }
    return -1; // Center frequency not found
}

void print_measurements() {
    LTE_PHY_CHANNEL_MEASUREMENTS_T* current = measurements_head;
    while (current != NULL) {
        printf("Center Frequency: %d, Channel Bandwidth: %d\n", current->center_frequency, current->channel_bandwidth);
        current = current->next;
    }
}

int main() {
    add_measurement(1000, 20);
    add_measurement(2000, 30);
    print_measurements();
    update_channel_bandwidth(1000, 25);
    print_measurements();
    free_measurements();
    return 0;
}
```

