#include <stdlib.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10
#define MAX_PACKET_SIZE 100

typedef struct {
    uint64_t rx_ue_info_tag;
    int logical_cell_id;
    char mac_packet[MAX_PACKET_SIZE];
} MAC_RX_CONTEXT_T;

typedef struct {
    MAC_RX_CONTEXT_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray_T;

DynamicArray_T* create_dynamic_array() {
    DynamicArray_T *arr = (DynamicArray_T*)malloc(sizeof(DynamicArray_T));
    arr->array = (MAC_RX_CONTEXT_T*)malloc(INITIAL_CAPACITY * sizeof(MAC_RX_CONTEXT_T));
    arr->size = 0;
    arr->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&arr->lock, NULL);
    return arr;
}

void resize_array(DynamicArray_T *arr) {
    size_t new_capacity = arr->capacity * 2;
    MAC_RX_CONTEXT_T *new_array = (MAC_RX_CONTEXT_T*)realloc(arr->array, new_capacity * sizeof(MAC_RX_CONTEXT_T));
    if (new_array != NULL) {
        arr->array = new_array;
        arr->capacity = new_capacity;
    }
}

void add_to_array(DynamicArray_T *arr, MAC_RX_CONTEXT_T context) {
    pthread_mutex_lock(&arr->lock);
    if (arr->size == arr->capacity) {
        resize_array(arr);
    }
    arr->array[arr->size] = context;
    arr->size++;
    pthread_mutex_unlock(&arr->lock);
}

int is_unique_cell_id(DynamicArray_T *arr, int cell_id) {
    pthread_mutex_lock(&arr->lock);
    for (size_t i = 0; i < arr->size; i++) {
        if (arr->array[i].logical_cell_id == cell_id) {
            pthread_mutex_unlock(&arr->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&arr->lock);
    return 1;
}

void destroy_dynamic_array(DynamicArray_T *arr) {
    pthread_mutex_destroy(&arr->lock);
    free(arr->array);
    free(arr);
}
```

