    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicList;

DynamicList* dynamic_list_init() {
    DynamicList *list = malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->elements = malloc(MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) {
        free(list);
        return NULL;
    }

    list->count = 0;
    list->capacity = MAX_ELEMENTS;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void dynamic_list_free(DynamicList *list) {
    if (list->elements) free(list->elements);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int dynamic_list_add(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->mutex);

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        void *new_elements = realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_elements) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Memory allocation failed
        }

        list->elements = new_elements;
        list->capacity = new_capacity;
    }

    list->elements[list->count++] = element;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int dynamic_list_get(DynamicList *list, size_t index, NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&list->mutex);

    if (index >= list->count) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Index out of bounds
    }

    *element = list->elements[index];

    pthread_mutex_unlock(&list->mutex);
    return 0;
}
