#define NFAPI_CRC_INDICATION_PDU_T struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocate_memory(size_t N) {
    return (NFAPI_CRC_INDICATION_PDU_T*)calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void deallocate_memory(NFAPI_CRC_INDICATION_PDU_T* array, size_t N) {
    free(array);
}

void populate_array(NFAPI_CRC_INDICATION_PDU_T* array, size_t N, int* RNTI_values, int num_RNTIs) {
    for (size_t i = 0; i < N; ++i) {
        if (i < num_RNTIs) {
            array[i].RX_UE_INFORMATION_TAG = i;
            array[i].RNTI = RNTI_values[i];
            array[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
        } else {
            array[i].RX_UE_INFORMATION_TAG = -1;
            array[i].RNTI = -1;
            array[i].CRCFLAG = false;
        }
    }
}

void* update_crc_flag(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T** array_ptr = (NFAPI_CRC_INDICATION_PDU_T**)arg;
    NFAPI_CRC_INDICATION_PDU_T* array = *array_ptr;

    for (size_t i = 0; i < N; ++i) {
        if (array[i].RX_UE_INFORMATION_TAG != -1) {
            array[i].CRCFLAG = rand() % 2; // Update CRCFLAG randomly
        }
    }

    return NULL;
}

void publish_crc_flags(NFAPI_CRC_INDICATION_PDU_T* array, size_t N, RdKafka::Producer* producer, const std::string& topic) {
    for (size_t i = 0; i < N; ++i) {
        if (array[i].RX_UE_INFORMATION_TAG != -1) {
            std::string message = "RX_UE_INFORMATION_TAG: " + std::to_string(array[i].RX_UE_INFORMATION_TAG) +
                                 ", RNTI: " + std::to_string(array[i].RNTI) +
                                 ", CRCFLAG: " + (array[i].CRCFLAG ? "true" : "false");
            RdKafka::ErrorCode resp = producer->produce(topic, RdKafka::Topic::PARTITION_UA,
                                                       RdKafka::Producer::RK_MSG_COPY,
                                                       const_cast<char*>(message.c_str()), message.size(),
                                                       NULL, 0);
            if (resp != RdKafka::ERR_NO_ERROR) {
                fprintf(stderr, "Failed to produce message: %s\n", RdKafka::err2str(resp).c_str());
            }
        }
    }

    producer->flush(10 * 1000); // Wait up to 10 seconds for messages to be delivered
}

void log_message(const char* message) {
    printf("%s\n", message);
}
