NFAPI_CRC_INDICATION_PDU_T* entries[MAX_ENTRIES];
int next_index = 0;
time_t last_cleanup_time = 0;

int process_entries(int max_entries) {
    if (max_entries <= 0 || max_entries > MAX_ENTRIES) {
        log_operation("Invalid input parameter", 0);
        return -1;
    }

    pthread_mutex_lock(&mutex);

    int actual_entries = 0;
    for (int i = 0; i < max_entries && next_index < MAX_ENTRIES; ++i, ++next_index) {
        entries[next_index] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (entries[next_index] == NULL) {
