        ++actual_entries;
    }

    pthread_mutex_unlock(&mutex);

    // Periodic cleanup
    time_t current_time = time(NULL);
    if (current_time - last_cleanup_time > 60) { // Clean up every minute
        for (int i = next_index; i < MAX_ENTRIES; ++i) {
            free(entries[i]);
