void *populate_list_thread(void *arg) {
    int seed = *(int *)arg;
    srand(seed);

    while (1) {
        pthread_mutex_lock(&list_mutex);
        if (list_size >= MAX_ELEMENTS) {
            pthread_mutex_unlock(&list_mutex);
            break;
        }
        NFAPI_CRC_INDICATION_PDU_T *new_item = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        new_item->ue_info.RNTI = rand();
        new_item->crc_ind.CRCFLAG = (rand() % 2) ? 1 : 0;

        // Check for duplicates and add to list
        int is_duplicate = 0;
        for (int i = 0; i < list_size; i++) {
            if (list[i]->ue_info.RNTI == new_item->ue_info.RNTI) {
                is_duplicate = 1;
                break;
            }
        }
        if (!is_duplicate) {
            list[list_size++] = new_item;
            log_operation_status("Added new element to the list");
        } else {
            free(new_item);
            log_operation_status("Duplicate RNTI found, skipping");
        }
        pthread_mutex_unlock(&list_mutex);

        // Simulate work load
        sleep(1);
    }

    return NULL;
}

void populate_list(int N, int seed) {
    initialize_log_file("operation.log");

    pthread_t threads[N];
    for (int i = 0; i < N; i++) {
        pthread_create(&threads[i], NULL, populate_list_thread, &seed);
    }

    for (int i = 0; i < N; i++) {
        pthread_join(threads[i], NULL);
    }

    log_operation_status("List population completed");
}

void verify_list() {
    pthread_mutex_lock(&list_mutex);
    for (int i = 0; i < list_size; i++) {
        if (list[i]->ue_info.RNTI <= 0 || list[i]->crc_ind.CRCFLAG != 0 && list[i]->crc_ind.CRCFLAG != 1) {
            log_operation_status("Verification failed");
            pthread_mutex_unlock(&list_mutex);
            return;
        }
    }
    log_operation_status("Verification passed");
    pthread_mutex_unlock(&list_mutex);
}

int main() {
    int N = 5; // Number of threads
    int seed = time(NULL); // Use current time as seed for reproducibility

    populate_list(N, seed);
    verify_list();
    free_list();

    return 0;
}
