#include <stdlib.h>
#include <pthread.h>

typedef struct RadioBearerInfo {
    // Define fields for radio bearer information
} RadioBearerInfo;

typedef struct UEIdentity {
    // Define fields for user equipment identity
} UEIdentity;

typedef enum TransmissionStatus {
    STATUS_IDLE,
    STATUS_ACTIVE,
    STATUS_ERROR
} TransmissionStatus;

typedef struct UEContext {
    RadioBearerInfo rb_info;
    UEIdentity ue_id;
    TransmissionStatus status;
    struct UEContext* next;
} UEContext;

typedef struct LinkedList {
    UEContext* head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* initialize_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void insert_context(LinkedList* list, UEContext* new_context) {
    pthread_mutex_lock(&list->lock);
    new_context->next = list->head;
    list->head = new_context;
    pthread_mutex_unlock(&list->lock);
}

UEContext* find_context(LinkedList* list, UEIdentity* identity) {
    pthread_mutex_lock(&list->lock);
    UEContext* current = list->head;
    while (current != NULL) {
        if (memcmp(&current->ue_id, identity, sizeof(UEIdentity)) == 0) {
            pthread_mutex_unlock(&list->lock);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void delete_context(LinkedList* list, UEIdentity* identity) {
    pthread_mutex_lock(&list->lock);
    UEContext* current = list->head;
    UEContext* prev = NULL;
    while (current != NULL) {
        if (memcmp(&current->ue_id, identity, sizeof(UEIdentity)) == 0) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            pthread_mutex_unlock(&list->lock);
            return;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void update_context_status(LinkedList* list, UEIdentity* identity, TransmissionStatus new_status) {
    pthread_mutex_lock(&list->lock);
    UEContext* current = find_context(list, identity);
    if (current != NULL) {
        current->status = new_status;
    }
    pthread_mutex_unlock(&list->lock);
}

void free_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    UEContext* current = list->head;
    while (current != NULL) {
        UEContext* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
