    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_record(int rx_tag, int rnti, int crc_indication) {
    NFAPI_CRC_INDICATION_PDU_T *record = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (record == NULL) {
        log_message("Memory allocation failed for record");
        return NULL;
    }
