    record->RNTI = rnti;
    record->CRC_INDICATION_REL8_TAG = crc_indication;
    record->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    return record;
}

int check_uniqueness(int rnti) {
    for (int i = 0; i < record_count; i++) {
        if (nfapi_crc_list[i]->RNTI == rnti) {
            return 0; // Duplicate RNTI found
        }
    }
    return 1;
}

void populate_nfa_list(int N, int seed) {
    srand(seed);
    for (int i = 0; i < N && record_count < MAX_N; i++) {
        pthread_mutex_lock(&list_mutex);
        int rx_tag = rand();
        int rnti = rand();
        while (!check_uniqueness(rnti)) {
            rnti = rand(); // Ensure RNTI uniqueness
        }
        int crc_indication = rand() % 2;
        NFAPI_CRC_INDICATION_PDU_T *record = create_record(rx_tag, rnti, crc_indication);
        if (record != NULL) {
            nfapi_crc_list[record_count++] = record;
        }
        pthread_mutex_unlock(&list_mutex);
    }
}

void free_nfa_list() {
    for (int i = 0; i < record_count; i++) {
        free(nfapi_crc_list[i]);
    }
    free(offsets);
    free(keys);
    free(records);
