#define MAX_RECORDS 100000
#define DEFAULT_CURRENCY "USD"

typedef struct {
    int id;
    char name[100];
    double amount;
} CUSTOMER_TRANSACTION_RECORD;

CUSTOMER_TRANSACTION_RECORD records[MAX_RECORDS];
int record_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int add_record(int transaction_id, const char* customer_name, double transaction_amount) {
    pthread_mutex_lock(&lock);
    if (record_count >= MAX_RECORDS) {
        pthread_mutex_unlock(&lock);
        return -1; // Collection full
    }
    records[record_count].id = transaction_id;
    strncpy(records[record_count].name, customer_name, sizeof(records[record_count].name));
    records[record_count].amount = transaction_amount;
    record_count++;
    pthread_mutex_unlock(&lock);
    return 0;
}

int check_duplicate(const char* customer_name) {
    for (int i = 0; i < record_count; i++) {
        if (strcmp(records[i].name, customer_name) == 0) {
            return 1; // Duplicate found
        }
    }
    return 0;
}

void log_operation(const char* operation_status) {
    printf("Operation: %s\n", operation_status);
}

int verify_records() {
    for (int i = 0; i < record_count; i++) {
        if (records[i].id <= 0 || records[i].name[0] == '\0' || records[i].amount <= 0) {
            return -1; // Invalid record
        }
    }
    return 0;
}

void* dynamic_memory_allocation(size_t N) {
    CUSTOMER_TRANSACTION_RECORD* batch = (CUSTOMER_TRANSACTION_RECORD*)malloc(N * sizeof(CUSTOMER_TRANSACTION_RECORD));
    if (batch == NULL) {
        log_operation("Memory allocation failed");
        return NULL;
    }
    // Initialize batch
    for (size_t i = 0; i < N; i++) {
        batch[i].id = -1;
        strcpy(batch[i].name, "");
        batch[i].amount = 0.0;
    }
    log_operation("Memory allocation successful");
    return batch;
}

int main() {
    if (add_record(1, "John Doe", 150.0) == 0) {
        printf("Record added successfully\n");
    } else {
        printf("Failed to add record: Collection full\n");
    }

    if (check_duplicate("John Doe")) {
        printf("Duplicate customer name found\n");
    } else {
        printf("No duplicates found\n");
    }

    log_operation("Operation completed");

    if (verify_records() == 0) {
        printf("All records are valid\n");
    } else {
        printf("Invalid records found\n");
    }

    CUSTOMER_TRANSACTION_RECORD* batch = dynamic_memory_allocation(5);
    if (batch != NULL) {
        free(batch);
    }

    return 0;
}
