typedef struct {
    int RX_TX_STREAM_ID;
    int SUBFRAMENO;
    int ANTENNA_PORT;
    float RX_SNR;
} PHY_RX_STATS_T;

typedef struct {
    PHY_RX_STATS_T* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* dynamic_array_init() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->data = (PHY_RX_STATS_T*)calloc(50000, sizeof(PHY_RX_STATS_T));
    if (!array->data) {
        free(array);
        return NULL;
    }

    array->capacity = 50000;
    array->size = 0;

    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void dynamic_array_free(DynamicArray* array) {
    if (array) {
        pthread_mutex_lock(&array->lock);
        free(array->data);
        pthread_mutex_unlock(&array->lock);
        pthread_mutex_destroy(&array->lock);
        free(array);
    }
}

int dynamic_array_add(DynamicArray* array, PHY_RX_STATS_T item) {
    pthread_mutex_lock(&array->lock);

    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        PHY_RX_STATS_T* new_data = (PHY_RX_STATS_T*)realloc(array->data, new_capacity * sizeof(PHY_RX_STATS_T));
        if (!new_data) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failure
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }

    array->data[array->size++] = item;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

void dynamic_array_validate_snr(DynamicArray* array, float threshold) {
    if (!array || !array->data) return;

    pthread_mutex_lock(&array->lock);

    size_t total_frames = array->size;
    float total_snr = 0.0f;

    for (size_t i = 0; i < total_frames; ++i) {
        total_snr += array->data[i].RX_SNR;
    }

    float average_snr = total_snr / total_frames;

    for (size_t i = 0; i < total_frames; ++i) {
        if (fabs(array->data[i].RX_SNR - average_snr) > threshold) {
            // Log warning: SNR deviation exceeds threshold
        }
    }

    pthread_mutex_unlock(&array->lock);
}

// Additional functions for concurrent access, error handling, and system integration can be added here.
