} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t list_mutex;

void init_list() {
    pthread_mutex_init(&list_mutex, NULL);
}

int validate_tag(uint32_t tag) {
    // Simulate external validation
    return (tag % 2 == 0); // Example condition
}

void* allocate_and_populate_list(int N) {
    Node* current = NULL;
    for (int i = 0; i < N; i++) {
        if (pthread_mutex_lock(&list_mutex) != 0) {
            perror("Mutex lock failed");
            continue;
        }
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (new_node == NULL) {
            pthread_mutex_unlock(&list_mutex);
            break;
        }
        new_node->data.RX_UE_INFORMATION_TAG = rand() % 1000; // Simulate tag generation
        while (!validate_tag(new_node->data.RX_UE_INFORMATION_TAG)) {
            new_node->data.RX_UE_INFORMATION_TAG = rand() % 1000;
        }
        new_node->data.RNTI = rand() % 256; // Simulate RNTI generation
        new_node->data.CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0; // Random CRCFLAG

        if (head == NULL) {
            head = new_node;
            current = new_node;
        } else {
            current->next = new_node;
            current = new_node;
        }

        pthread_mutex_unlock(&list_mutex);

        if (pthread_mutex_lock(&list_mutex) != 0) {
            perror("Mutex lock failed");
            continue;
        }
        if (head != NULL && list_size() >= MAX_LIST_SIZE) {
            Node* temp = head;
            while (temp->next != current) {
                temp = temp->next;
            }
            temp->next = NULL;
            free(current);
            current = temp;
        }

        pthread_mutex_unlock(&list_mutex);

        usleep(1000); // Simulate delay
    }
    return head;
}

int list_size() {
    int size = 0;
    Node* temp = head;
    while (temp != NULL) {
        size++;
        temp = temp->next;
    }
    return size;
}

void reset_list() {
    pthread_mutex_lock(&list_mutex);
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    head = NULL;
    pthread_mutex_unlock(&list_mutex);
}
