typedef struct LTE_RRC_CU_Config_DownlinkPagingMessage_t {
    lte_rlc_t *rlc;
    lte_mac_t *mac;
    int emergency_paging_flag;
} LTE_RRC_CU_Config_DownlinkPagingMessage_t;

typedef struct DynamicArray {
    LTE_RRC_CU_Config_DownlinkPagingMessage_t **data;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->data = NULL;
    array->size = 0;
    array->capacity = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    for(size_t i = 0; i < array->size; ++i) {
        free(array->data[i]);
    }
    free(array->data);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int add_message_to_array(DynamicArray *array, LTE_RRC_CU_Config_DownlinkPagingMessage_t *message) {
    pthread_mutex_lock(&array->mutex);
    if (array->size == array->capacity) {
        size_t new_capacity = (array->capacity == 0) ? 1 : array->capacity * 2;
        LTE_RRC_CU_Config_DownlinkPagingMessage_t **new_data = realloc(array->data, new_capacity * sizeof(LTE_RRC_CU_Config_DownlinkPagingMessage_t *));
        if (!new_data) {
            pthread_mutex_unlock(&array->mutex);
            return -1; // Memory allocation failed
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }
    array->data[array->size++] = message;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

LTE_RRC_CU_Config_DownlinkPagingMessage_t* get_message_from_array(DynamicArray *array, size_t index) {
    if (index >= array->size) {
        return NULL; // Index out of bounds
    }
    pthread_mutex_lock(&array->mutex);
    LTE_RRC_CU_Config_DownlinkPagingMessage_t *message = array->data[index];
    pthread_mutex_unlock(&array->mutex);
    return message;
}

int remove_message_from_array(DynamicArray *array, size_t index) {
    if (index >= array->size) {
        return -1; // Index out of bounds
    }
    pthread_mutex_lock(&array->mutex);
    free(array->data[index]);
    for(size_t i = index; i < array->size - 1; ++i) {
        array->data[i] = array->data[i + 1];
    }
    --array->size;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int periodic_statistics_retrieval(DynamicArray *array, StatisticsFunction stats_func) {
    pthread_mutex_lock(&array->mutex);
    for(size_t i = 0; i < array->size; ++i) {
        LTE_RRC_CU_Config_DownlinkPagingMessage_t *message = array->data[i];
        // Call the statistics function with the message
        stats_func(message);
    }
    pthread_mutex_unlock(&array->mutex);
    return 0;
}
