#include <stdint.h>

#define MAX_PACKETS 50000

typedef struct {
    uint8_t source_mac[6];
    uint8_t destination_mac[6];
    uint32_t timestamp;
} MAC_FRAME;

typedef struct L2_PACKET_DATA {
    MAC_FRAME frame;
    uint64_t identifier;
    struct L2_PACKET_DATA *next;
} L2_PACKET_DATA;

typedef struct {
    L2_PACKET_DATA *head;
    L2_PACKET_DATA *tail;
    int count;
} PacketList;

uint64_t hash_mac_frame(const MAC_FRAME *frame, uint32_t timestamp) {
    // Simple hash function for demonstration purposes
    return ((uint64_t)frame->source_mac[0] << 48) |
           ((uint64_t)frame->source_mac[1] << 40) |
           ((uint64_t)frame->source_mac[2] << 32) |
           ((uint64_t)frame->source_mac[3] << 24) |
           ((uint64_t)frame->source_mac[4] << 16) |
           ((uint64_t)frame->source_mac[5] << 8) |
           timestamp;
}

int validate_mac_frame(const MAC_FRAME *frame) {
    // Basic validation check
    return frame->source_mac[0] != 0 && frame->destination_mac[0] != 0;
}

void init_packet_list(PacketList *list) {
    list->head = list->tail = NULL;
    list->count = 0;
}

int add_packet_to_list(PacketList *list, const MAC_FRAME *frame, uint32_t timestamp) {
    L2_PACKET_DATA *new_data = (L2_PACKET_DATA *)malloc(sizeof(L2_PACKET_DATA));
    if (!new_data) return -1;

    memcpy(&new_data->frame, frame, sizeof(MAC_FRAME));
    new_data->identifier = hash_mac_frame(frame, timestamp);
    new_data->next = NULL;

    if (list->count == 0) {
        list->head = list->tail = new_data;
    } else {
        list->tail->next = new_data;
        list->tail = new_data;
    }
    list->count++;
    return 0;
}

void free_packet_list(PacketList *list) {
    L2_PACKET_DATA *current = list->head;
    while (current) {
        L2_PACKET_DATA *next = current->next;
        free(current);
        current = next;
    }
    init_packet_list(list);
}

// Add other functions as needed for serialization, deserialization, and callbacks
