    if (list->size >= MAX_NFAPI_LIST_SIZE) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }
    for (int i = 0; i < list->size; i++) {
        if (list->list[i]->rnti == rnti || 
            (i > 0 && list->list[i - 1]->rx_ue_info == rx_ue_info)) {
            pthread_mutex_unlock(&list->lock);
            return false;
        }
    }
    NFAPI_CRC_INDICATION_PDU_T *new_item = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_item == NULL) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }
    new_item->rx_ue_info = rx_ue_info;
    new_item->rnti = rnti;
    new_item->crc_ind = crc_ind;
    list->list[list->size++] = new_item;
    pthread_mutex_unlock(&list->lock);
    return true;
}

void free_nfa_pi_list(NFAPI_List *list) {
    for (int i = 0; i < list->size; i++) {
        free(list->list[i]);
    }
    pthread_mutex_destroy(&list->lock);
}
