        fprintf(stderr, "Failed to lock mutex\n");
        return -1;
    }

    count = allocation_stats.successful_allocations;

    pthread_mutex_unlock(&allocation_stats.mutex);
    return count;
}

size_t get_failed_attempts() {
    size_t count;
    if (pthread_mutex_lock(&allocation_stats.mutex) != 0) {
        fprintf(stderr, "Failed to lock mutex\n");
        return -1;
    }

    count = allocation_stats.failed_attempts;

    pthread_mutex_unlock(&allocation_stats.mutex);
