    TRANSPORT_CHANNEL_INFO tcInfo;
    DATA_INDICATION_TAG tag;
    uint8_t payload[MAX_DATA_SIZE];
} NFC_API_DATA_PDU_T;

pthread_mutex_t dataMutex = PTHREAD_MUTEX_INITIALIZER;
NFC_API_DATA_PDU_T* dataArray = NULL;
int currentSize = 0;
int maxSize = 0;

void initializeDataHandler(int maxElements) {
    pthread_mutex_lock(&dataMutex);
    if (dataArray != NULL) {
        free(dataArray);
    }
    dataArray = (NFC_API_DATA_PDU_T*)malloc(maxElements * sizeof(NFC_API_DATA_PDU_T));
    if (dataArray == NULL) {
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&dataMutex);
        exit(1);
    }
    maxSize = maxElements;
    currentSize = 0;
    pthread_mutex_unlock(&dataMutex);
}

void extendAndOptimizeNFC_API_DataHandler(int newSize) {
    pthread_mutex_lock(&dataMutex);
    if (newSize > maxSize) {
        NFC_API_DATA_PDU_T* newDataArray = (NFC_API_DATA_PDU_T*)realloc(dataArray, newSize * sizeof(NFC_API_DATA_PDU_T));
        if (newDataArray == NULL) {
            printf("Memory reallocation failed\n");
            pthread_mutex_unlock(&dataMutex);
            return;
        }
        dataArray = newDataArray;
        maxSize = newSize;
    }
    for (int i = currentSize; i < newSize; i++) {
        // Initialize each new element with random data
        srand(time(NULL));
        for (int j = 0; j < sizeof(dataArray[i].payload); j++) {
            dataArray[i].payload[j] = rand() % 256;
        }
    }
    currentSize = newSize;
    pthread_mutex_unlock(&dataMutex);
}

void* threadFunction(void* arg) {
    int threadId = *(int*)arg;
    extendAndOptimizeNFC_API_DataHandler(threadId * 10 + 5);
    return NULL;
}

int main() {
    int maxElements = 100;
    initializeDataHandler(maxElements);

    pthread_t threads[5];
    int threadIds[5] = {1, 2, 3, 4, 5};

    for (int i = 0; i < 5; i++) {
        pthread_create(&threads[i], NULL, threadFunction, &threadIds[i]);
    }

    for (int i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }

    if (dataArray != NULL) {
        free(dataArray);
    }

    return 0;
}
