use std::sync::{Arc, Mutex};
use std::time::Duration;
use reqwest::ClientBuilder;

#[derive(Clone)]
struct HttpClientPool {
    clients: Arc<Mutex<Vec<ClientBuilder>>>,
    config: PoolConfig,
}

#[derive(Copy, Clone)]
struct PoolConfig {
    max_clients: usize,
    timeout: Duration,
    retry_policy: RetryPolicy,
}

enum RetryPolicy {
    FixedAttempts(u32),
    ExponentialBackoff(Duration),
}

impl HttpClientPool {
    fn new(config: PoolConfig) -> Self {
        HttpClientPool {
            clients: Arc::new(Mutex::new(Vec::with_capacity(config.max_clients))),
            config,
        }
    }

    async fn get_client(&self) -> ClientBuilder {
        let mut clients = self.clients.lock().unwrap();
        if let Some(client) = clients.pop() {
            client
        } else {
            // Create a new client and apply configuration
            let mut builder = ClientBuilder::new();
            builder.timeout(self.config.timeout);
            match self.config.retry_policy {
                RetryPolicy::FixedAttempts(attempts) => builder.retry(RetryPolicy::fixed_attempts(attempts)),
                RetryPolicy::ExponentialBackoff(backoff) => builder.retry(RetryPolicy::exponential_backoff(backoff)),
            }
            builder.build().unwrap()
        }
    }

    async fn return_client(&self, client: ClientBuilder) {
        let mut clients = self.clients.lock().unwrap();
        if clients.len() < self.config.max_clients {
            clients.push(client);
        }
    }

    fn scale_to_load(&self, load: f64, latency: Duration) {
        // Logic to dynamically adjust the number of clients based on load and latency
        let current_clients = self.clients.lock().unwrap().len();
        if load > 0.8 || latency > Duration::from_millis(500) {
            // Scale up
            for _ in 0..self.config.max_clients - current_clients {
                let mut builder = ClientBuilder::new();
                builder.timeout(self.config.timeout);
                match self.config.retry_policy {
                    RetryPolicy::FixedAttempts(attempts) => builder.retry(RetryPolicy::fixed_attempts(attempts)),
                    RetryPolicy::ExponentialBackoff(backoff) => builder.retry(RetryPolicy::exponential_backoff(backoff)),
                }
                let client = builder.build().unwrap();
                self.clients.lock().unwrap().push(client);
            }
        } else if load < 0.3 && latency < Duration::from_millis(250) {
            // Scale down
            while self.clients.lock().unwrap().len() > self.config.max_clients / 2 {
                if let Some(_) = self.clients.lock().unwrap().pop() {}
            }
        }
    }
}
