#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    size_t payload_length;
    unsigned int identifier;
} DataPacket;

typedef struct Node {
    DataPacket packet;
    struct Node* next;
} PacketNode;

typedef struct {
    PacketNode* head;
    size_t count;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->head = NULL;
    array->count = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    if (!array) return;

    PacketNode* current = array->head;
    while (current) {
        PacketNode* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&array->mutex);
    free(array);
}

void add_packet(DynamicArray* array, DataPacket packet) {
    if (!array || !packet.identifier) return;

    PacketNode* new_node = (PacketNode*)malloc(sizeof(PacketNode));
    if (!new_node) return;

    new_node->packet = packet;
    new_node->next = NULL;

    pthread_mutex_lock(&array->mutex);
    if (!array->head) {
        array->head = new_node;
    } else {
        PacketNode* current = array->head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    }
    array->count++;
    pthread_mutex_unlock(&array->mutex);
}

void remove_packet_by_id(DynamicArray* array, unsigned int identifier) {
    if (!array || !identifier) return;

    pthread_mutex_lock(&array->mutex);
    PacketNode* current = array->head;
    PacketNode* prev = NULL;

    while (current) {
        if (current->packet.identifier == identifier) {
            if (prev) {
                prev->next = current->next;
            } else {
                array->head = current->next;
            }
            free(current);
            array->count--;
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&array->mutex);
}

void update_packet_timestamps(DynamicArray* array) {
    if (!array) return;

    time_t now = time(NULL);

    pthread_mutex_lock(&array->mutex);
    PacketNode* current = array->head;

    while (current) {
        current->packet.timestamp = now - difftime(now, current->packet.timestamp);
        current = current->next;
    }
    pthread_mutex_unlock(&array->mutex);
}

int main() {
    DynamicArray* array = create_dynamic_array();

    DataPacket packet1 = {0, 1024, 1};
    DataPacket packet2 = {0, 512, 2};

    add_packet(array, packet1);
    add_packet(array, packet2);

    update_packet_timestamps(array);

    remove_packet_by_id(array, 1);

    destroy_dynamic_array(array);

    return 0;
}
