        cache->cache = new_cache;
        cache->capacity = new_capacity;
    }
    cache->cache[cache->count++] = packet;
}

void evict_lru(Cache* cache) {
    if (cache->count == 0) return;
    size_t min_access_time = time(NULL);
    int lru_index = -1;
    for (size_t i = 0; i < cache->count; ++i) {
        DataPacket* packet = cache->cache[i];
        // Assuming we have a mechanism to track access times
        if (packet->timestamp < min_access_time) {
            min_access_time = packet->timestamp;
            lru_index = i;
