void addDataPacket(DataPacket** packets, size_t* count, DataPacket newPacket) {
    *packets = realloc(*packets, (*count + 1) * sizeof(DataPacket));
    if (*packets == NULL) {
        // Handle memory allocation failure
        perror("Failed to allocate memory for new packet");
        exit(EXIT_FAILURE);
    }
    (*packets)[*count] = newPacket;
    (*count)++;
}

// Function to remove a packet by identifier from the dynamic array
void removeDataPacketById(DataPacket** packets, size_t* count, int id) {
    for (size_t i = 0; i < *count; i++) {
        if ((*packets)[i].uniqueIdentifier == id) {
            // Shift elements to fill the gap
            memmove(&(*packets)[i], &(*packets)[i + 1], (*count - i - 1) * sizeof(DataPacket));
            (*count)--;
            break;
        }
    }
}

// Function to update packet timestamps based on elapsed time
void updateTimestamps(DataPacket** packets, size_t count) {
    time_t now = time(NULL);
    for (size_t i = 0; i < count; i++) {
        (*packets)[i].timestamp = now;
    }
}
