    pthread_mutex_lock(&array->lock);
    if (index < 0 || index >= array->size) {
        pthread_mutex_unlock(&array->lock);
        return; // Error: Index out of bounds
    }
    array->array[index].RX_UE_INFORMATION = rx_info;
    array->array[index].CRC_INDICATION_REL8 = crc_ind;
    pthread_mutex_unlock(&array->lock);
}

NFAPI_CRC_INDICATION_PDU_T get_element(NFAPI_DYNAMIC_ARRAY *array, int index) {
