        NFAPI_CRC_INDICATION_PDU_T empty = {0};
        return empty; // Error: Index out of bounds
    }
    NFAPI_CRC_INDICATION_PDU_T element = array->array[index];
    pthread_mutex_unlock(&array->lock);
    return element;
}
