NFAPI_RX_FRAME_ARRAY_T* nfapi_rx_frame_array_create(size_t initial_capacity) {
    NFAPI_RX_FRAME_ARRAY_T *array = (NFAPI_RX_FRAME_ARRAY_T*)malloc(sizeof(NFAPI_RX_FRAME_ARRAY_T));
    if (!array) return NULL;

    array->frames = (RX_FRAME_PDU_T**)malloc(initial_capacity * sizeof(RX_FRAME_PDU_T*));
    if (!array->frames) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void nfapi_rx_frame_array_destroy(NFAPI_RX_FRAME_ARRAY_T *array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->frames[i]->PDCP_PDUs);
        free(array->frames[i]);
    }
    free(array->frames);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int nfapi_rx_frame_array_add(NFAPI_RX_FRAME_ARRAY_T *array, RX_FRAME_PDU_T *frame) {
    pthread_mutex_lock(&array->lock);

    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        RX_FRAME_PDU_T **new_frames = (RX_FRAME_PDU_T**)realloc(array->frames, new_capacity * sizeof(RX_FRAME_PDU_T*));
        if (!new_frames) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failed
        }
        array->frames = new_frames;
        array->capacity = new_capacity;
    }

    array->frames[array->size++] = frame;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

int nfapi_rx_frame_array_remove(NFAPI_RX_FRAME_ARRAY_T *array, uint64_t RX_FRAME_TAG) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->size; ++i) {
        if (array->frames[i]->RX_FRAME_TAG == RX_FRAME_TAG) {
            free(array->frames[i]->PDCP_PDUs);
            free(array->frames[i]);
            while (i + 1 < array->size) {
                array->frames[i] = array->frames[i + 1];
                ++i;
            }
            --array->size;
            pthread_mutex_unlock(&array->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&array->lock);
    return -1; // Frame not found
}

RX_FRAME_PDU_T* nfapi_rx_frame_array_get(NFAPI_RX_FRAME_ARRAY_T *array, uint64_t RX_FRAME_TAG) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->size; ++i) {
        if (array->frames[i]->RX_FRAME_TAG == RX_FRAME_TAG) {
            pthread_mutex_unlock(&array->lock);
            return array->frames[i];
        }
    }

    pthread_mutex_unlock(&array->lock);
    return NULL; // Frame not found
}
