#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int id;
    time_t timestamp;
    pthread_mutex_t lock;
    struct PACKET_T* packets;
} TCP_CONNECTION;

typedef struct PACKET_T {
    int data_size;
    unsigned char* data;
    struct PACKET_T* next;
} PACKET_T;

TCP_CONNECTION** connection_pool;
int pool_size;
pthread_mutex_t pool_lock;

void initialize_connection_pool(int size) {
    pool_size = size;
    connection_pool = (TCP_CONNECTION**)malloc(pool_size * sizeof(TCP_CONNECTION*));
    pthread_mutex_init(&pool_lock, NULL);
}

TCP_CONNECTION* create_tcp_connection(int id) {
    TCP_CONNECTION* conn = (TCP_CONNECTION*)malloc(sizeof(TCP_CONNECTION));
    conn->id = id;
    conn->timestamp = time(NULL);
    pthread_mutex_init(&conn->lock, NULL);
    conn->packets = NULL;
    return conn;
}

void add_connection_to_pool(TCP_CONNECTION* conn) {
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < pool_size; i++) {
        if (connection_pool[i] == NULL) {
            connection_pool[i] = conn;
            break;
        }
    }
    pthread_mutex_unlock(&pool_lock);
}

void remove_connection_from_pool(TCP_CONNECTION* conn) {
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < pool_size; i++) {
        if (connection_pool[i] == conn) {
            connection_pool[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&pool_lock);
}

TCP_CONNECTION* get_connection_by_id(int id) {
    TCP_CONNECTION* result = NULL;
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < pool_size; i++) {
        if (connection_pool[i] != NULL && connection_pool[i]->id == id) {
            result = connection_pool[i];
            break;
        }
    }
    pthread_mutex_unlock(&pool_lock);
    return result;
}

void add_packet_to_connection(TCP_CONNECTION* conn, PACKET_T* packet) {
    pthread_mutex_lock(&conn->lock);
    if (conn->packets == NULL) {
        conn->packets = packet;
    } else {
        PACKET_T* current = conn->packets;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = packet;
    }
    pthread_mutex_unlock(&conn->lock);
}

void free_connection(TCP_CONNECTION* conn) {
    if (conn == NULL) return;

    pthread_mutex_lock(&conn->lock);
    PACKET_T* packet = conn->packets;
    while (packet != NULL) {
        PACKET_T* next_packet = packet->next;
        free(packet->data);
        free(packet);
        packet = next_packet;
    }
    conn->packets = NULL;
    pthread_mutex_unlock(&conn->lock);

    free(conn);
}

void destroy_connection_pool() {
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < pool_size; i++) {
        if (connection_pool[i] != NULL) {
            free_connection(connection_pool[i]);
            connection_pool[i] = NULL;
        }
    }
    pthread_mutex_unlock(&pool_lock);

    free(connection_pool);
    pthread_mutex_destroy(&pool_lock);
}
