typedef struct {
    int UE_ID;
    // Other configurable parameters such as PUCCH configuration
} NFAPI_RRC_UE_CONTEXT;

typedef struct {
    NFAPI_RRC_UE_CONTEXT *contexts;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} UE_CONTEXT_MANAGER;

void init_ue_context_manager(UE_CONTEXT_MANAGER *manager, size_t initial_capacity) {
    manager->capacity = initial_capacity;
    manager->size = 0;
    manager->contexts = (NFAPI_RRC_UE_CONTEXT *)malloc(initial_capacity * sizeof(NFAPI_RRC_UE_CONTEXT));
    pthread_mutex_init(&manager->mutex, NULL);
}

void destroy_ue_context_manager(UE_CONTEXT_MANAGER *manager) {
    pthread_mutex_lock(&manager->mutex);
    free(manager->contexts);
    manager->contexts = NULL;
    manager->capacity = 0;
    manager->size = 0;
    pthread_mutex_unlock(&manager->mutex);
    pthread_mutex_destroy(&manager->mutex);
}

void expand_ue_context_manager(UE_CONTEXT_MANAGER *manager) {
    pthread_mutex_lock(&manager->mutex);
    size_t new_capacity = manager->capacity ? manager->capacity * 2 : 16;
    NFAPI_RRC_UE_CONTEXT *new_contexts = (NFAPI_RRC_UE_CONTEXT *)realloc(manager->contexts, new_capacity * sizeof(NFAPI_RRC_UE_CONTEXT));
    if (new_contexts) {
        manager->contexts = new_contexts;
        manager->capacity = new_capacity;
    }
    pthread_mutex_unlock(&manager->mutex);
}

void add_ue_context(UE_CONTEXT_MANAGER *manager, NFAPI_RRC_UE_CONTEXT context) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->size >= manager->capacity) {
        expand_ue_context_manager(manager);
    }
    manager->contexts[manager->size++] = context;
    pthread_mutex_unlock(&manager->mutex);
}

void delete_ue_context(UE_CONTEXT_MANAGER *manager, int UE_ID) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->contexts[i].UE_ID == UE_ID) {
            for (size_t j = i; j < manager->size - 1; ++j) {
                manager->contexts[j] = manager->contexts[j + 1];
            }
            --manager->size;
            break;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
}

NFAPI_RRC_UE_CONTEXT *get_ue_context(UE_CONTEXT_MANAGER *manager, int UE_ID) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->contexts[i].UE_ID == UE_ID) {
            pthread_mutex_unlock(&manager->mutex);
            return &manager->contexts[i];
        }
    }
    pthread_mutex_unlock(&manager->mutex);
    return NULL;
}
