        new_message.rrc_ue_identity_response.content = RRC_RESPONSE_TEMPLATE;

        (*messages)[*current_size] = new_message;
        (*current_size)++;

        // Check for growth threshold and resize if necessary
        if ((*current_size % GROWTH_THRESHOLD == 0) && (*current_size < MAX_MESSAGES)) {
            LTE_DL_CCCH_MSG_TYPE_1_T *new_messages = (LTE_DL_CCCH_MSG_TYPE_1_T *)realloc(*messages, (*current_size + GROWTH_THRESHOLD) * sizeof(LTE_DL_CCCH_MSG_TYPE_1_T));
            if (new_messages == NULL) {
                return -2; // Memory reallocation failure
            }
            *messages = new_messages;
        }
    }

    return *current_size; // Number of successfully initialized structures
}
