}

void insert_crc_item(CRC_Indication_List* list, NFAPI_CRC_INDICATION_PDU_T* item) {
    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = item;
    } else {
        list->tail->next = item;
    }
    list->tail = item;
    item->next = NULL;
    list->count++;
    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T* get_crc_item(CRC_Indication_List* list, size_t index) {
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    for (size_t i = 0; i < index && current != NULL; i++) {
        current = current->next;
    }
    return current;
}

void validate_crc_list(CRC_Indication_List* list) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    size_t count = 0;
    while (current != NULL) {
        // Perform validation checks here
        current = current->next;
        count++;
    }
    if (count != list->count) {
        // Handle validation failure
    }
    pthread_mutex_unlock(&list->lock);
}

void export_crc_list(CRC_Indication_List* list, const char* filename) {
    pthread_mutex_lock(&list->lock);
    FILE* file = fopen(filename, "ab");
    if (file != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* current = list->head;
        while (current != NULL) {
            // Write each item to the file
            fwrite(current, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
            current = current->next;
        }
        fclose(file);
    }
    pthread_mutex_unlock(&list->lock);
}
