class NFAPI_CRC_INDICATION_PDU_T {
  constructor(rxUeInfoTag, rnti, crcIndicationRel8Tag) {
    this.rxUeInformationTag = rxUeInfoTag;
    this.rnti = rnti;
    this.crcIndicationRel8Tag = crcIndicationRel8Tag;
  }
}

function getRandomValue() {
  return Math.random();
}

async function populateNfaPduList(N, initialValue, reducerCallback) {
  const pduList = [];

  for (let i = 0; i < N; i++) {
    const rxUeInfoTag = getRandomValue();
    const rnti = getRandomValue();
    const crcIndicationRel8Tag = Math.round(getRandomValue());
    const pdu = new NFAPI_CRC_INDICATION_PDU_T(rxUeInfoTag, rnti, crcIndicationRel8Tag);
    pduList.push(pdu);
  }

  try {
    const result = await pduList.reduce(async (acc, currentValue) => {
      return reducerCallback(await acc, currentValue);
    }, initialValue);

    return result;
  } catch (error) {
    console.error("Error during reduction process:", error);
    throw error;
  }
}

// Example usage:
