const initialValue = 0;
const reducerCallback = async (acc, currentValue) => {
  return acc + currentValue.rxUeInformationTag; // Example operation
};

populateNfaPduList(N, initialValue, reducerCallback)
  .then(result => console.log("Reduction result:", result))
  .catch(error => console.error("Error in population or reduction:", error));
