#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* head;
    pthread_mutex_t mutex;
    int timeout_period;
} NFAPI_CRC_LIST_T;

NFAPI_CRC_LIST_T* create_crc_list(int timeout_period) {
    NFAPI_CRC_LIST_T* list = (NFAPI_CRC_LIST_T*)malloc(sizeof(NFAPI_CRC_LIST_T));
    if (!list) {
        perror("Failed to allocate memory for CRC list");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    list->timeout_period = timeout_period;
    return list;
}

void destroy_crc_list(NFAPI_CRC_LIST_T* list) {
    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_to_crc_list(NFAPI_CRC_LIST_T* list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        perror("Failed to allocate memory for CRC node");
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    new_node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->RNTI = RNTI;
    new_node->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void clear_crc_list(NFAPI_CRC_LIST_T* list) {
    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->mutex);
}

// Function to periodically clear the list after a specified timeout period
void* periodic_clear(void* arg) {
    NFAPI_CRC_LIST_T* list = (NFAPI_CRC_LIST_T*)arg;
    while (1) {
        sleep(list->timeout_period);
        clear_crc_list(list);
    }
    return NULL;
}

int main() {
    NFAPI_CRC_LIST_T* crc_list = create_crc_list(60); // Clear every 60 seconds
    if (!crc_list) {
        return -1;
    }

    pthread_t clear_thread;
    if (pthread_create(&clear_thread, NULL, periodic_clear, crc_list) != 0) {
        perror("Failed to create thread for periodic clearing");
        destroy_crc_list(crc_list);
        return -1;
    }

    // Example usage
    add_to_crc_list(crc_list, 123, 456, 789);

    pthread_join(clear_thread, NULL);
    destroy_crc_list(crc_list);
    return 0;
}
```

