typedef struct NetworkEventLogEntry {
    time_t timestamp;
    char event_type[50];
    char description[256];
} NetworkEventLogEntry;

typedef struct LogNode {
    NetworkEventLogEntry entry;
    struct LogNode* next;
} LogNode;

typedef struct {
    LogNode* head;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int flush_interval;
} NetworkEventLog;

NetworkEventLog* init_log(int flush_interval) {
    NetworkEventLog* log = (NetworkEventLog*)malloc(sizeof(NetworkEventLog));
    if (!log) {
        fprintf(stderr, "Memory allocation failed for log structure\n");
        return NULL;
    }
    log->head = NULL;
    pthread_mutex_init(&log->lock, NULL);
    pthread_cond_init(&log->cond, NULL);
    log->flush_interval = flush_interval;
    return log;
}

void add_entry(NetworkEventLog* log, const NetworkEventLogEntry* entry) {
    pthread_mutex_lock(&log->lock);
    LogNode* new_node = (LogNode*)malloc(sizeof(LogNode));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed for log node\n");
        pthread_mutex_unlock(&log->lock);
        return;
    }
    memcpy(&new_node->entry, entry, sizeof(NetworkEventLogEntry));
    new_node->next = NULL;

    if (log->head == NULL) {
        log->head = new_node;
    } else {
        LogNode* current = log->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    pthread_cond_signal(&log->cond);
    pthread_mutex_unlock(&log->lock);
}

void flush_log(NetworkEventLog* log) {
    pthread_mutex_lock(&log->lock);
    LogNode* current = log->head;
    while (current != NULL) {
        // Simulate external logging service call
        printf("Logging: %s - %s\n", current->entry.event_type, current->entry.description);
        LogNode* temp = current;
        current = current->next;
        free(temp);
    }
    log->head = NULL;
    pthread_mutex_unlock(&log->lock);
}

void* log_flush_thread(void* arg) {
    NetworkEventLog* log = (NetworkEventLog*)arg;
    while (1) {
        pthread_mutex_lock(&log->lock);
        if (log->head == NULL) {
            pthread_cond_wait(&log->cond, &log->lock);
        }
        pthread_mutex_unlock(&log->lock);

        flush_log(log);

        sleep(log->flush_interval);
    }
    return NULL;
}

int main() {
    NetworkEventLog* log = init_log(5); // Flush every 5 seconds
    if (!log) {
        return -1;
    }

    pthread_t thread;
    pthread_create(&thread, NULL, log_flush_thread, (void*)log);

    NetworkEventLogEntry entry;
    time_t now = time(NULL);
    strcpy(entry.event_type, "ERROR");
    strcpy(entry.description, "Network connection failed");

    add_entry(log, &entry);

    pthread_join(thread, NULL);
    free(log);
    return 0;
}
