} LTE_List;

LTE_List *lte_list_init() {
    LTE_List *list = (LTE_List *)malloc(sizeof(LTE_List));
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void lte_list_add_event(LTE_List *list, LTE_Event *event) {
    pthread_mutex_lock(&list->mutex);
    if (list->count < MAX_EVENTS) {
        list->events[list->count++] = event;
    }
    pthread_mutex_unlock(&list->mutex);
}

LTE_Event* lte_list_get_event_by_cell_id(LTE_List *list, int cell_id) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; i++) {
        if (list->events[i]->cell_id == cell_id) {
            pthread_mutex_unlock(&list->mutex);
            return list->events[i];
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

void lte_list_update_event(LTE_List *list, int cell_id, LTE_Event *new_event) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; i++) {
        if (list->events[i]->cell_id == cell_id) {
            memcpy(list->events[i], new_event, sizeof(LTE_Event));
            break;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

void lte_list_free(LTE_List *list) {
    pthread_mutex_destroy(&list->mutex);
    free(list);
}
