typedef struct {
    uint32_t S_TMSI;
    uint16_t EPS_BEARER_ID;
    uint16_t PDCP_SN;
} PDCP_entity_t;

typedef struct {
    PDCP_entity_t *entities;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PDCP_list_t;

int PDCP_list_init(PDCP_list_t *list, size_t initial_capacity);
void PDCP_list_destroy(PDCP_list_t *list);
int PDCP_list_add(PDCP_list_t *list, uint32_t S_TMSI, uint16_t EPS_BEARER_ID);
int PDCP_list_remove_by_S_TMSI(PDCP_list_t *list, uint32_t S_TMSI);

// Implementation of PDCP_list_init
int PDCP_list_init(PDCP_list_t *list, size_t initial_capacity) {
    list->entities = malloc(initial_capacity * sizeof(PDCP_entity_t));
    if (!list->entities) return -1; // Insufficient memory
    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
    return 0;
}

// Implementation of PDCP_list_destroy
void PDCP_list_destroy(PDCP_list_t *list) {
    free(list->entities);
    pthread_mutex_destroy(&list->lock);
}

// Implementation of PDCP_list_add
int PDCP_list_add(PDCP_list_t *list, uint32_t S_TMSI, uint16_t EPS_BEARER_ID) {
    pthread_mutex_lock(&list->lock);
    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 4;
        PDCP_entity_t *new_entities = realloc(list->entities, new_capacity * sizeof(PDCP_entity_t));
        if (!new_entities) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Insufficient memory
        }
        list->entities = new_entities;
        list->capacity = new_capacity;
    }

    for (size_t i = 0; i < list->count; ++i) {
        if (list->entities[i].S_TMSI == S_TMSI) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Duplicate S-TMSI
        }
    }

    PDCP_entity_t new_entity = {S_TMSI, EPS_BEARER_ID, 0};
    list->entities[list->count++] = new_entity;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Implementation of PDCP_list_remove_by_S_TMSI
int PDCP_list_remove_by_S_TMSI(PDCP_list_t *list, uint32_t S_TMSI) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->entities[i].S_TMSI == S_TMSI) {
            memmove(&list->entities[i], &list->entities[i + 1], (list->count - i - 1) * sizeof(PDCP_entity_t));
            --list->count;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // S-TMSI not found
}
