LinkedList* createLinkedList() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (list) {
        list->head = NULL;
        list->size = 0;
        list->capacity = MAX_ENTRIES;
    }
    return list;
}

void resizeList(LinkedList* list) {
