int insertEntry(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list->size >= list->capacity) {
        resizeList(list);
    }
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return -1; // Memory allocation failure
    newNode->data = data;
    newNode->next = list->head;
    list->head = newNode;
    list->size++;
