        crcFlag = rand() % 2; // Ensure different from previous
    }
    data->CRC_INDICATION_REL8_TAG = crcFlag;
}

void insertNewEntry(LinkedList* list, int RX_UE_INFORMATION_TAG, int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T newData;
    newData.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newData.RNTI = RNTI;
    setRandomCrcFlag(&newData);
    insertEntry(list, newData);
}

void freeList(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}
