#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
} List;

List* list_create() {
    List* list = (List*)malloc(sizeof(List));
    if (list == NULL) {
        return NULL; // Handle memory allocation failure
    }
    list->head = NULL;
    list->count = 0;
    return list;
}

void list_add(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        return; // Handle memory allocation failure
    }
    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
}

bool list_remove(List* list, uint16_t RNTI) {
    Node* current = list->head;
    Node* previous = NULL;

    while (current != NULL && current->data.RNTI != RNTI) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        return false; // Element not found
    }

    if (previous == NULL) {
        list->head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
    list->count--;
    return true;
}

void list_clear(List* list) {
    Node* current = list->head;
    Node* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    list->count = 0;
}

bool list_is_valid(List* list) {
    Node* current = list->head;
    bool seen_rntis[65536] = {false}; // Assuming RNTI is a 16-bit unsigned integer

    while (current != NULL) {
        if (seen_rntis[current->data.RNTI]) {
            return false; // Duplicate RNTI found
        }
        seen_rntis[current->data.RNTI] = true;
        current = current->next;
    }

    return true;
}

void list_destroy(List* list) {
    list_clear(list);
    free(list);
}
