    uint64_t timestamp;
} RECEIVED_FRAME_INFO;

typedef struct MAC_FRAME_RECEIVE_T {
    RECEIVED_FRAME_INFO frame_info;
} MAC_FRAME_RECEIVE_T;

#define MAX_FRAMES 1024

typedef struct DynamicArray {
    MAC_FRAME_RECEIVE_T** frames;
    size_t count;
    size_t capacity;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->frames = (MAC_FRAME_RECEIVE_T**)malloc(MAX_FRAMES * sizeof(MAC_FRAME_RECEIVE_T*));
    array->count = 0;
    array->capacity = MAX_FRAMES;
    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    for (size_t i = 0; i < array->count; ++i) {
        free(array->frames[i]);
    }
    free(array->frames);
    free(array);
}

int add_frame(DynamicArray* array, MAC_FRAME_RECEIVE_T* frame) {
    if (array->count >= array->capacity) {
        return -1; // Array is full
    }
    size_t insert_index = array->count;
    while (insert_index > 0 && array->frames[insert_index - 1]->frame_info.timestamp >= frame->frame_info.timestamp) {
        insert_index--;
    }
    memmove(&array->frames[insert_index + 1], &array->frames[insert_index], (array->count - insert_index) * sizeof(MAC_FRAME_RECEIVE_T*));
    array->frames[insert_index] = frame;
    array->count++;
    return 0;
}

int delete_frame(DynamicArray* array, uint64_t timestamp) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->frames[i]->frame_info.timestamp == timestamp) {
            memmove(&array->frames[i], &array->frames[i + 1], (array->count - i - 1) * sizeof(MAC_FRAME_RECEIVE_T*));
            array->count--;
            return 0;
        }
    }
    return -1; // Frame not found
}

MAC_FRAME_RECEIVE_T* get_latest_frame(DynamicArray* array) {
    if (array->count == 0) {
        return NULL;
    }
    return array->frames[array->count - 1];
}

int validate_frames(DynamicArray* array) {
    for (size_t i = 1; i < array->count; ++i) {
        if (array->frames[i]->frame_info.timestamp <= array->frames[i - 1]->frame_info.timestamp) {
            return 0; // Invalid timestamp order
        }
    }
    for (size_t i = 0; i < array->count; ++i) {
        if (array->frames[i]->frame_info.PHY_CONTEXT == NULL) {
            return 0; // PHY_CONTEXT is null
        }
    }
    return 1;
}
