#include <pthread.h>

typedef struct CUSTOMER_TRANSACTION_RECORD_T {
    int TRANSACTION_ID;
    int CUSTOMER_ID;
    double TRANSACTION_AMOUNT;
} CUSTOMER_TRANSACTION_RECORD_T;

#define MAX_ENTRIES 1024

typedef struct HASH_TABLE_NODE_T {
    CUSTOMER_TRANSACTION_RECORD_T data;
    struct HASH_TABLE_NODE_T* next;
} HASH_TABLE_NODE_T;

typedef struct HASH_TABLE_T {
    HASH_TABLE_NODE_T** buckets;
    int size;
    int count;
    pthread_mutex_t lock;
} HASH_TABLE_T;

HASH_TABLE_T* hash_table_init(int size) {
    HASH_TABLE_T* table = (HASH_TABLE_T*)malloc(sizeof(HASH_TABLE_T));
    table->buckets = (HASH_TABLE_NODE_T**)calloc(size, sizeof(HASH_TABLE_NODE_T*));
    table->size = size;
    table->count = 0;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void hash_table_destroy(HASH_TABLE_T* table) {
    for (int i = 0; i < table->size; i++) {
        HASH_TABLE_NODE_T* node = table->buckets[i];
        while (node != NULL) {
            HASH_TABLE_NODE_T* next = node->next;
            free(node);
            node = next;
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

int hash_function(int key, int size) {
    return abs(key) % size;
}

void hash_table_insert(HASH_TABLE_T* table, CUSTOMER_TRANSACTION_RECORD_T record) {
    pthread_mutex_lock(&table->lock);
    int index = hash_function(record.CUSTOMER_ID, table->size);
    HASH_TABLE_NODE_T* node = (HASH_TABLE_NODE_T*)malloc(sizeof(HASH_TABLE_NODE_T));
    node->data = record;
    node->next = table->buckets[index];
    table->buckets[index] = node;
    table->count++;
    if (table->count >= table->size * 0.75) {
        hash_table_resize(table);
    }
    pthread_mutex_unlock(&table->lock);
}

void hash_table_resize(HASH_TABLE_T* table) {
    int old_size = table->size;
    HASH_TABLE_NODE_T** old_buckets = table->buckets;

    table->size *= 2;
    table->buckets = (HASH_TABLE_NODE_T**)calloc(table->size, sizeof(HASH_TABLE_NODE_T*));
    table->count = 0;

    for (int i = 0; i < old_size; i++) {
        HASH_TABLE_NODE_T* node = old_buckets[i];
        while (node != NULL) {
            hash_table_insert(table, node->data);
            HASH_TABLE_NODE_T* next = node->next;
            free(node);
            node = next;
        }
    }

    free(old_buckets);
}

CUSTOMER_TRANSACTION_RECORD_T* hash_table_lookup(HASH_TABLE_T* table, int customer_id) {
    pthread_mutex_lock(&table->lock);
    int index = hash_function(customer_id, table->size);
    HASH_TABLE_NODE_T* node = table->buckets[index];
    while (node != NULL) {
        if (node->data.CUSTOMER_ID == customer_id) {
            CUSTOMER_TRANSACTION_RECORD_T* result = malloc(sizeof(CUSTOMER_TRANSACTION_RECORD_T));
            *result = node->data;
            pthread_mutex_unlock(&table->lock);
            return result;
        }
        node = node->next;
    }
    pthread_mutex_unlock(&table->lock);
    return NULL;
}

void hash_table_delete(HASH_TABLE_T* table, int customer_id) {
    pthread_mutex_lock(&table->lock);
    int index = hash_function(customer_id, table->size);
    HASH_TABLE_NODE_T** prev_ptr = &table->buckets[index];
    HASH_TABLE_NODE_T* node = *prev_ptr;
    while (node != NULL) {
        if (node->data.CUSTOMER_ID == customer_id) {
            *prev_ptr = node->next;
            free(node);
            table->count--;
            pthread_mutex_unlock(&table->lock);
            return;
        }
        prev_ptr = &node->next;
        node = *prev_ptr;
    }
    pthread_mutex_unlock(&table->lock);
}

int main() {
    HASH_TABLE_T* table = hash_table_init(MAX_ENTRIES);

    // Insert, lookup, and delete operations go here

    hash_table_destroy(table);
    return 0;
}
