typedef struct {
    uint32_t rx_ue_information_tag;
    uint16_t rnti;
    uint8_t crc_indication_rel8_tag;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPool {
    void* memory;
    size_t size;
    size_t block_size;
    size_t free_count;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t total_size, size_t block_size) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->memory = malloc(total_size);
    if (!pool->memory) {
        free(pool);
        return NULL;
    }

    pool->size = total_size;
    pool->block_size = block_size;
    pool->free_count = total_size / block_size;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void* memory_pool_alloc(MemoryPool* pool) {
    void* ptr;
    pthread_mutex_lock(&pool->lock);
    if (pool->free_count == 0) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // No more memory available
    }

    ptr = pool->memory + (pool->size - pool->block_size * pool->free_count);
    pool->free_count--;
    pthread_mutex_unlock(&pool->lock);

    return ptr;
}

void memory_pool_free(MemoryPool* pool, void* ptr) {
    pthread_mutex_lock(&pool->lock);
    size_t offset = ((char*)ptr - (char*)pool->memory);
    if (offset % pool->block_size != 0 || offset / pool->block_size >= pool->free_count) {
        pthread_mutex_unlock(&pool->lock);
        return; // Invalid pointer
    }

    pool->free_count++;
    pthread_mutex_unlock(&pool->lock);
}

void init_nicp_packet_headers(NICP_PACKET_HEADER* headers, int count, MemoryPool* memory_pool) {
    for (int i = 0; i < count; i++) {
        memset(&headers[i], 0, sizeof(NICP_PACKET_HEADER));

        // Initialize MAC address, VLAN tag, and IP packet length
        // (Assuming initialization logic here)

        // Populate NFAPI_CRC_INDICATION_PDU_T structures with random CRC flags
        for (int j = 0; j < 10; j++) { // Example number of PDUs per header
            NFAPI_CRC_INDICATION_PDU_T* pdu = memory_pool_alloc(memory_pool);
            if (!pdu) {
                // Handle memory allocation failure, e.g., log error and continue
                continue;
            }

            pdu->rx_ue_information_tag = i * 10 + j; // Example tag
            pdu->rnti = (i * 10 + j) % 4096; // Example RNTI
            pdu->crc_indication_rel8_tag = 0x12; // Example value
            pdu->crcflag = rand() % 2; // Random CRC flag
        }
    }
}

void free_nicp_packet_headers(NICP_PACKET_HEADER* headers, int count, MemoryPool* memory_pool) {
