int allocate_and_populate_array(int num_ues, NFAPI_CRC_INDICATION_PDU_T **array) {
    if (num_ues > SYSTEM_LIMIT) {
        log_error("Number of UEs exceeds system limit");
        return -1;
    }

    *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_ues * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*array == NULL) {
        log_error("Memory allocation failed");
        return -1;
    }

    srand(time(NULL));
    int last_crc_flag = -1;

    for (int i = 0; i < num_ues; i++) {
        (*array)[i].RX_UE_INFORMATION_TAG = i + 1;
        (*array)[i].RNTI = get_unique_rnti();
        if ((*array)[i].RNTI == -1) {
            log_error("Failed to obtain unique RNTI");
            free(*array);
            return -1;
        }

        do {
            (*array)[i].CRC_INDICATION_REL8_TAG = rand() % 2;
        } while (last_crc_flag == (*array)[i].CRC_INDICATION_REL8_TAG);

        last_crc_flag = (*array)[i].CRC_INDICATION_REL8_TAG;
    }

    return 0;
}

int get_unique_rnti() {
    static int rntis[SYSTEM_LIMIT] = {0};
    static int count = 0;

    if (count >= SYSTEM_LIMIT) {
        return -1;
    }

    int rnti;
    do {
        rnti = rand() % SYSTEM_LIMIT + 1;
    } while (rntis[rnti] != 0);

    rntis[rnti] = 1;
    count++;
    return rnti;
}

