NFAPI_CRC_INDICATION_PDU** createDynamicList(int N, int minThreshold) {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU** list = (NFAPI_CRC_INDICATION_PDU**)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU*));
    if (!list) return NULL;

    int prevRNTI = rand() % 100; // Initial RNTI, adjust as needed
    for (int i = 0; i < N; ++i) {
        list[i] = (NFAPI_CRC_INDICATION_PDU*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
        if (!list[i]) {
            // Clean up allocated memory before returning NULL
            for (int j = 0; j < i; ++j) free(list[j]);
            free(list);
            return NULL;
        }

        list[i]->RX_UE_INFORMATION_TAG = rand() % 100; // Adjust as needed
        int newRNTI;
        do {
            newRNTI = rand() % 100; // Adjust as needed
        } while (abs(newRNTI - prevRNTI) < minThreshold);
        list[i]->RNTI = newRNTI;
        prevRNTI = newRNTI;

        list[i]->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    }
    return list;
}

void freeDynamicList(NFAPI_CRC_INDICATION_PDU** list, int N) {
    for (int i = 0; i < N; ++i) {
        free(list[i]);
    }
    free(list);
}
