LTE_ENB_CONTEXT* enb_context_create() {
    LTE_ENB_CONTEXT* enb = (LTE_ENB_CONTEXT*)malloc(sizeof(LTE_ENB_CONTEXT));
    if (!enb) {
        return NULL; // Memory allocation failed
    }
    memset(enb, 0, sizeof(LTE_ENB_CONTEXT));
    return enb;
}

int ue_context_add(LTE_ENB_CONTEXT* enb, UE_CONTEXT* new_ue) {
    if (enb->num_ues >= MAX_UE_CONTEXTS) {
        return -1; // Maximum number of UEs reached
    }
    if (new_ue->ENB_ID >= ENB_ID_MAX || new_ue->CELL_ID >= CELL_ID_MAX || !new_ue->MME_ID) {
        return -2; // Invalid UE parameters
    }
    enb->ue_contexts[enb->num_ues++] = *new_ue;
    return 0; // Success
}

int update_sib1(LTE_ENB_CONTEXT* enb, unsigned int mme_id, const char* new_sib1) {
    for (int i = 0; i < enb->num_ues; i++) {
        if (enb->ue_contexts[i].MME_ID == mme_id) {
            strncpy(enb->ue_contexts[i].SIB1, new_sib1, sizeof(enb->ue_contexts[i].SIB1));
            return 0; // Success
        }
    }
    return -1; // MME_ID not found
}

int main() {
    LTE_ENB_CONTEXT* enb = enb_context_create();
    if (!enb) {
        // Handle memory allocation failure
        return -1;
    }

    UE_CONTEXT new_ue = {1, RRC_CONNECTED, "SIB1 Data"};
    int result = ue_context_add(enb, &new_ue);
    if (result == -1) {
        free(enb);
        return -2; // Maximum number of UEs reached
    }
    if (result == -2) {
        free(enb);
        return -3; // Invalid UE parameters
    }

    result = update_sib1(enb, 1, "Updated SIB1 Data");
    if (result == -1) {
        free(enb);
        return -4; // MME_ID not found
    }

    free(enb);
    return enb->num_ues;
}
