#include <stdlib.h>
#include <pthread.h>

#define MAX_UE_INFO_TAG 1000
#define MAX_RNTI 65535
#define MAX_CRC_INDICATION_REL8_TAG 2

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t front;
    size_t rear;
    pthread_mutex_t mutex;
    pthread_cond_t not_empty;
    pthread_cond_t not_full;
} ThreadSafeQueue;

ThreadSafeQueue* create_queue(size_t capacity) {
    ThreadSafeQueue* queue = (ThreadSafeQueue*)malloc(sizeof(ThreadSafeQueue));
    if (!queue) return NULL;

    queue->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!queue->data) {
        free(queue);
        return NULL;
    }

    queue->capacity = capacity;
    queue->front = 0;
    queue->rear = -1;
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->not_empty, NULL);
    pthread_cond_init(&queue->not_full, NULL);

    return queue;
}

void destroy_queue(ThreadSafeQueue* queue) {
    free(queue->data);
    pthread_mutex_destroy(&queue->mutex);
    pthread_cond_destroy(&queue->not_empty);
    pthread_cond_destroy(&queue->not_full);
    free(queue);
}

int enqueue(ThreadSafeQueue* queue, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&queue->mutex);

    while ((queue->rear + 1) % queue->capacity == queue->front) {
        pthread_cond_wait(&queue->not_full, &queue->mutex);
    }

    queue->rear = (queue->rear + 1) % queue->capacity;
    queue->data[queue->rear] = item;

    pthread_cond_signal(&queue->not_empty);
    pthread_mutex_unlock(&queue->mutex);

    return 0;
}

int dequeue(ThreadSafeQueue* queue, NFAPI_CRC_INDICATION_PDU_T* item) {
    pthread_mutex_lock(&queue->mutex);

    while (queue->front == queue->rear) {
        pthread_cond_wait(&queue->not_empty, &queue->mutex);
    }

    *item = queue->data[queue->front];
    queue->front = (queue->front + 1) % queue->capacity;

    pthread_cond_signal(&queue->not_full);
    pthread_mutex_unlock(&queue->mutex);

    return 0;
}

void* create_and_enqueue_crc_indications(void* arg) {
    ThreadSafeQueue* queue = (ThreadSafeQueue*)arg;
    size_t N = 1000; // Example value for N
    size_t created_count = 0;
    size_t failed_count = 0;

    for (size_t i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % MAX_UE_INFO_TAG;
        pdu.RNTI = rand() % MAX_RNTI;
        pdu.CRC_INDICATION_REL8_TAG = rand() % MAX_CRC_INDICATION_REL8_TAG;

        if (enqueue(queue, pdu) == 0) {
            ++created_count;
        } else {
            ++failed_count;
        }
    }

    printf("Created: %zu, Failed: %zu\n", created_count, failed_count);
    return NULL;
}

int main() {
    ThreadSafeQueue* queue = create_queue(1024);
    if (!queue) {
        fprintf(stderr, "Failed to create queue\n");
        return 1;
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, create_and_enqueue_crc_indications, queue) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        destroy_queue(queue);
        return 1;
    }

    // Simulate other tasks or wait for the thread to finish
    pthread_join(thread, NULL);

    destroy_queue(queue);
    return 0;
}
