    struct PduNode* next;
} PduNode;

PduNode* head = NULL;
pthread_mutex_t listMutex = PTHREAD_MUTEX_INITIALIZER;

void addPdu(int id) {
    pthread_mutex_lock(&listMutex);
    PduNode* newNode = (PduNode*)malloc(sizeof(PduNode));
    if (newNode != NULL) {
        newNode->pdu.id = id;
        newNode->next = head;
        head = newNode;
    }
    pthread_mutex_unlock(&listMutex);
}

void closePdu(int id) {
    pthread_mutex_lock(&listMutex);
    PduNode* current = head;
    PduNode* previous = NULL;

    while (current != NULL && current->pdu.id != id) {
        previous = current;
        current = current->next;
    }

    if (current != NULL) {
        if (previous == NULL) {
            head = current->next;
        } else {
            previous->next = current->next;
        }
        free(current);
    }
    pthread_mutex_unlock(&listMutex);
}

void updateCrcFlag(int id, int newCrcFlag) {
    pthread_mutex_lock(&listMutex);
    PduNode* current = head;

    while (current != NULL && current->pdu.id != id) {
        current = current->next;
    }

    if (current != NULL) {
        // Assuming there's a function to update the CRC flag
        // updateCrcFlag(&current->pdu.crc_indication, newCrcFlag);
    }
    pthread_mutex_unlock(&listMutex);
}

