        free(temp);
    }
    free(list);
}

int add_mac_pdu(List* list, MAC_PDU pdu) {
    if (list == NULL || list->tail == NULL) return -1;

    if (list->tail->data.BSID + MIN_BSID_DIFF > pdu.BSID) {
        printf("BSID difference is less than the minimum threshold.\n");
        return -1;
    }

    ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
    if (new_node == NULL) return -1;

    new_node->data = pdu;
    new_node->next = NULL;
    list->tail->next = new_node;
    list->tail = new_node;

    return 0;
}

int main() {
    List* mac_pdu_list = create_list();

    MAC_PDU pdu1 = {1, 100, 200};
    MAC_PDU pdu2 = {2, 120, 300};

    if (add_mac_pdu(mac_pdu_list, pdu1) == 0) {
        printf("PDU added successfully.\n");
    }

    if (add_mac_pdu(mac_pdu_list, pdu2) == 0) {
        printf("PDU added successfully.\n");
    } else {
        printf("Failed to add PDU due to BSID difference constraint.\n");
    }

    destroy_list(mac_pdu_list);
    return 0;
}
