#include <pthread.h>
#include <stdlib.h>
#include <time.h>

#define NFAPI_CRC_INDICATION_PDU_T_SIZE 1024
#define MAX_UE_INFOS 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *pool[NFAPI_CRC_INDICATION_PDU_T_SIZE];
int pool_index = 0;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

void generate_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T **pdu) {
    pthread_mutex_lock(&pool_lock);
    if (pool_index < NFAPI_CRC_INDICATION_PDU_T_SIZE) {
        *pdu = &pool[pool_index++];
        (*pdu)->RX_UE_INFORMATION_TAG = rand() % MAX_UE_INFOS;
        (*pdu)->RNTI = rand() % 1024;
        (*pdu)->CRCFLAG = rand() % 2;
    } else {
        *pdu = NULL;
    }
    pthread_mutex_unlock(&pool_lock);
}

void* update_crc_indication_pdu(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    while (1) {
        generate_crc_indication_pdu(&pdu);
        if (pdu != NULL) {
            // Process the pdu, e.g., store in database or forward to network
        }
        usleep(1000);  // Simulate processing time
    }
    return NULL;
}

void* report_statistics(void* arg) {
    int rnti_counts[MAX_UE_INFOS] = {0};
    int total_crcflag = 0;
    int count = 0;

    while (1) {
        for (int i = 0; i < pool_index; i++) {
            NFAPI_CRC_INDICATION_PDU_T *pdu = &pool[i];
            rnti_counts[pdu->RNTI]++;
            total_crcflag += pdu->CRCFLAG;
            count++;
        }

        // Calculate averages and print or log the report
        printf("Average CRCFLAG: %f\n", (double)total_crcflag / count);

        for (int i = 0; i < MAX_UE_INFOS; i++) {
            if (rnti_counts[i] > 0) {
                printf("RNTI %d frequency: %d\n", i, rnti_counts[i]);
            }
        }

        memset(rnti_counts, 0, sizeof(rnti_counts));
        total_crcflag = 0;
        count = 0;

        usleep(10000);  // Update report every 10 seconds
    }
    return NULL;
}

int main() {
    pthread_t threads[2];
    srand(time(NULL));

    if (pthread_create(&threads[0], NULL, update_crc_indication_pdu, NULL) != 0) {
        perror("Failed to create thread for updating PDUs");
        exit(EXIT_FAILURE);
    }

    if (pthread_create(&threads[1], NULL, report_statistics, NULL) != 0) {
        perror("Failed to create thread for reporting statistics");
        exit(EXIT_FAILURE);
    }

    pthread_join(threads[0], NULL);
    pthread_join(threads[1], NULL);

    return 0;
}
