PduNode* pdu_list_head = NULL;
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

void add_pdu(int id, RX_UE_INFORMATION_TAG rx_tag, RNTI rnti, CRC_INDICATION_REL8_TAG crc_flag) {
    pthread_mutex_lock(&list_lock);
    PduNode* new_node = (PduNode*)malloc(sizeof(PduNode));
    if (!new_node) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&list_lock);
        return;
    }
    new_node->pdu.id = id;
    new_node->pdu.rx_tag = rx_tag;
    new_node->pdu.rnti = rnti;
    new_node->pdu.crc_flag = crc_flag;
    new_node->next = pdu_list_head;
    pdu_list_head = new_node;
    pthread_mutex_unlock(&list_lock);
}

void close_pdu(int id) {
    pthread_mutex_lock(&list_lock);
    PduNode* current = pdu_list_head;
    PduNode* previous = NULL;
    while (current != NULL) {
        if (current->pdu.id == id) {
            if (previous == NULL) {
                pdu_list_head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            pthread_mutex_unlock(&list_lock);
            return;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list_lock);
}

