    NFAPI_CRC_INDICATION_PDU_T *new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdu) return NULL;

    new_pdu->RX_UE_INFORMATION_TAG = rand();
    new_pdu->RNTI = rand();
    new_pdu->CRC_INDICATION_REL8_TAG = rand();
    new_pdu->CRCFLAG = rand();

    pdu_list[pdu_count++] = new_pdu;
    return new_pdu;
}

int close_pdu(int id) {
    if (id < 0 || id >= pdu_count) return -1;

    free(pdu_list[id]);
    pdu_list[id] = NULL;

    for (int i = id; i < pdu_count - 1; ++i) {
        pdu_list[i] = pdu_list[i + 1];
    }
    --pdu_count;

    return 0;
}

