namespace RandomSystem {

class MersenneTwisterGenerator {
public:
    static MersenneTwisterGenerator& getInstance(unsigned seed) {
        static MersenneTwisterGenerator instance(seed);
        return instance;
    }

    uint32_t generateUint32() {
        std::lock_guard<std::mutex> lock(mutex_);
        return generator_.operator()();
    }

    uint64_t generateUint64() {
        std::lock_guard<std::mutex> lock(mutex_);
        return generator_64_.operator()();
    }

    double generateDouble() {
        std::lock_guard<std::mutex> lock(mutex_);
        return static_cast<double>(generator_()) / UINT32_MAX;
    }

private:
    MersenneTwisterGenerator(unsigned seed)
        : generator_(seed), generator_64_(seed) {}

    ~MersenneTwisterGenerator() = default;

    std::mt19937 generator_;
    std::mt19937_64 generator_64_;
    std::mutex mutex_;
};

}  // namespace RandomSystem
