    memcpy(context->buffer, newBuffer, newSize);
    context->lastUpdate = time(NULL);

    // Log the buffer change using an external logging system
    logBufferChange(channelID, context->buffer, newSize);

    pthread_mutex_unlock(&mutex);
}

