#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_EVENTS 1024
#define LOG_EVENT(msg) printf("Event: %s\n", msg)

typedef struct {
    time_t timestamp;
    char ip[16];
    int port;
} NetworkEvent;

NetworkEvent *events[MAX_EVENTS];
int event_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void add_event(const NetworkEvent *new_event) {
    pthread_mutex_lock(&mutex);
    if (event_count < MAX_EVENTS) {
        events[event_count++] = malloc(sizeof(NetworkEvent));
        memcpy(events[event_count - 1], new_event, sizeof(NetworkEvent));
        LOG_EVENT("New event added");
    } else {
        LOG_EVENT("Event array full, cannot add more events");
    }
    pthread_mutex_unlock(&mutex);
}

void remove_events_by_ip(const char *ip) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < event_count; ) {
        if (strcmp(events[i]->ip, ip) == 0) {
            free(events[i]);
            memmove(&events[i], &events[i + 1], sizeof(NetworkEvent *) * (event_count - i - 1));
            event_count--;
        } else {
            i++;
        }
    }
    LOG_EVENT("Events removed by IP");
    pthread_mutex_unlock(&mutex);
}

NetworkEvent* find_most_recent_event_by_port(int port) {
    NetworkEvent *result = NULL;
    time_t max_timestamp = 0;
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < event_count; i++) {
        if (events[i]->port == port && events[i]->timestamp > max_timestamp) {
            result = events[i];
            max_timestamp = events[i]->timestamp;
        }
    }
    LOG_EVENT("Most recent event by port found");
    pthread_mutex_unlock(&mutex);
    return result;
}

void cleanup_outdated_events(time_t cutoff_time) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < event_count; ) {
        if (events[i]->timestamp < cutoff_time) {
            free(events[i]);
            memmove(&events[i], &events[i + 1], sizeof(NetworkEvent *) * (event_count - i - 1));
            event_count--;
        } else {
            i++;
        }
    }
    LOG_EVENT("Outdated events cleaned up");
    pthread_mutex_unlock(&mutex);
}
