#include <pthread.h>
#include <stdlib.h>
#include <time.h>

#define MAX_LIST_SIZE 1000
#define CRC_THRESHOLD 5

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info_tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements[MAX_LIST_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
    pthread_cond_t condition;
} CRCList;

void init_crc_list(CRCList* list) {
    list->head = 0;
    list->tail = -1;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->condition, NULL);
}

void enqueue_crc(CRCList* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list->mutex);
    while (list->count == MAX_LIST_SIZE) {
        pthread_cond_wait(&list->condition, &list->mutex);
    }
    list->tail = (list->tail + 1) % MAX_LIST_SIZE;
    list->elements[list->tail] = pdu;
    if (list->count == 0) {
        pthread_cond_signal(&list->condition);
    }
    list->count++;
    pthread_mutex_unlock(&list->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* dequeue_crc(CRCList* list) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = NULL;
    pthread_mutex_lock(&list->mutex);
    while (list->count == 0) {
        pthread_cond_wait(&list->condition, &list->mutex);
    }
    pdu = list->elements[list->head];
    list->head = (list->head + 1) % MAX_LIST_SIZE;
    list->count--;
    if (list->count == MAX_LIST_SIZE - 1) {
        pthread_cond_signal(&list->condition);
    }
    pthread_mutex_unlock(&list->mutex);
    return pdu;
}

void* crc_monitor_thread(void* arg) {
    CRCList* list = (CRCList*)arg;
    int rnti_crc_count[65536] = {0};
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = dequeue_crc(list);
        if (pdu->crc_indication_rel8.crcflag == CRC_CHECK_SUCCESS) {
            rnti_crc_count[pdu->rnti]++;
            if (rnti_crc_count[pdu->rnti] > CRC_THRESHOLD) {
                log_event("CRC threshold exceeded for RNTI %d", pdu->rnti);
            }
        }
    }
    return NULL;
}

void log_event(const char* format, ...) {
    va_list args;
    va_start(args, format);
    // Log the event to a file or external system
    va_end(args);
}
