typedef struct NetworkContext {
    int network_id;
    char *connection_status_buffer;
    size_t buffer_size;
    size_t active_sessions;
} NetworkContext;

typedef struct NetworkManager {
    NetworkContext **contexts;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    // Add configuration parameters here
} NetworkManager;

NetworkManager* create_network_manager(size_t initial_capacity) {
    NetworkManager *manager = (NetworkManager*) malloc(sizeof(NetworkManager));
    manager->contexts = (NetworkContext**) malloc(initial_capacity * sizeof(NetworkContext*));
    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);
    // Initialize configuration parameters
    return manager;
}

void destroy_network_manager(NetworkManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->contexts[i]->connection_status_buffer);
        free(manager->contexts[i]);
    }
    free(manager->contexts);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void add_network_context(NetworkManager *manager, NetworkContext *context) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        manager->contexts = (NetworkContext**) realloc(manager->contexts, new_capacity * sizeof(NetworkContext*));
        manager->capacity = new_capacity;
    }
    manager->contexts[manager->count++] = context;
    pthread_mutex_unlock(&manager->lock);
}

void update_network_context(NetworkManager *manager, int network_id, char *new_status) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->contexts[i]->network_id == network_id) {
            size_t new_size = strlen(new_status) + 1;
            manager->contexts[i]->connection_status_buffer = realloc(manager->contexts[i]->connection_status_buffer, new_size);
            strcpy(manager->contexts[i]->connection_status_buffer, new_status);
            manager->contexts[i]->active_sessions++;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

// Add other functions for managing concurrent access and resource optimization here
