        do {
            pdcp_sn = rand();
        } while (isSNDuplicate(array, i, pdcp_sn));
        array[i].PDCP_SN = pdcp_sn;
        array[i].PDCP_STATUS = 0; // Example status
        array[i].SDU_SIZE = rand() % 1500; // Random SDU size between 0 and 1499
    }

    if (log_level > 0) {
        logArrayInitialization(array, MAX_ELEMENTS);
    }

    *error_code = 0;
    return array;
}

int isSNDuplicate(LTE_PDCP_SAP_DATA_PDU_T* array, int index, uint32_t sn) {
    for (int i = 0; i < index; i++) {
        if (array[i].PDCP_SN == sn) {
            return 1;
        }
    }
    return 0;
}

void logArrayInitialization(LTE_PDCP_SAP_DATA_PDU_T* array, int count) {
    printf("Initialized array with %d elements.\n", count);
    for (int i = 0; i < count; i++) {
        printf("Element %d: PDCP_SN=%u, PDCP_STATUS=%hhu, SDU_SIZE=%hu\n",
               i, array[i].PDCP_SN, array[i].PDCP_STATUS, array[i].SDU_SIZE);
    }
}

// Example usage
int main() {
    int error_code;
    LTE_PDCP_SAP_DATA_PDU_T* array = initializeArray(&error_code, 1);
    if (error_code != 0) {
        printf("Failed to initialize array. Error code: %d\n", error_code);
    } else {
        // Use the array as needed
        free(array);
    }
    return 0;
}
