typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to create and populate a linked list
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_list(int max_elements, int default_crcflag) {
    // Initialize the random seed
    srand(time(NULL));

    // Allocate memory for the head of the linked list
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T** current = &head;

    // Loop to populate the linked list with unique RNTI values and random CRC flags
    int rnti = rand() % 100; // Initial RNTI value
    for (int i = 0; i < max_elements; ++i) {
        // Allocate memory for a new node
        NFAPI_CRC_INDICATION_PDU_T* new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed\n");
            return NULL;
        }

        // Set the values for the new node
        new_node->RX_UE_INFORMATION_TAG = i + 1;
        new_node->RNTI = rnti; // Use the same RNTI for simplicity in this example
        new_node->CRC_INDICATION_REL8_TAG = rand() % 2 ? default_crcflag : !default_crcflag;

        // Append the new node to the list
        *current = new_node;
        current = &new_node->next;
    }

    // Null-terminate the list
    *current = NULL;

    return head;
}

// Function to free the linked list memory
void free_crc_indication_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    int max_elements = 10; // Example value for MAX_ELEMENTS
    int default_crcflag = 1; // Example value for default CRCFLAG

    NFAPI_CRC_INDICATION_PDU_T* head = create_crc_indication_list(max_elements, default_crcflag);
    if (head) {
        free_crc_indication_list(head);
    }

    return 0;
}
