pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* createRandomCRCList(int N, int minCRC, int maxCRC) {
    if (N > MAX_LIST_SIZE) {
        return NULL;
    }

    pthread_mutex_lock(&list_lock);

    NFAPI_CRC_INDICATION_PDU_T *head = NULL;
    NFAPI_CRC_INDICATION_PDU_T **tail = &head;

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T *newNode = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newNode) {
            pthread_mutex_unlock(&list_lock);
            while (head) {
                NFAPI_CRC_INDICATION_PDU_T *temp = head;
                head = head->next;
                free(temp);
            }
            return NULL;
        }

        newNode->RX_UE_INFORMATION_TAG = i; // Example initialization
        newNode->RNTI = rand() % 4096; // Random RNTI within a typical range
        newNode->CRC_INDICATION_REL8_TAG = rand() % (maxCRC - minCRC + 1) + minCRC;
        newNode->next = NULL;

        *tail = newNode;
        tail = &newNode->next;
    }

    pthread_mutex_unlock(&list_lock);
    return head;
}
