#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int timestamp;
    char ip[16];
    int port;
} NetworkEvent;

typedef struct {
    NetworkEvent* events;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} EventManager;

EventManager* create_event_manager(size_t initial_capacity) {
    EventManager* manager = (EventManager*)malloc(sizeof(EventManager));
    if (!manager) return NULL;

    manager->events = (NetworkEvent*)calloc(initial_capacity, sizeof(NetworkEvent));
    if (!manager->events) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->mutex, NULL);

    return manager;
}

void destroy_event_manager(EventManager* manager) {
    pthread_mutex_lock(&manager->mutex);
    free(manager->events);
    pthread_mutex_unlock(&manager->mutex);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

void add_event(EventManager* manager, int timestamp, const char* ip, int port) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->size == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NetworkEvent* new_events = (NetworkEvent*)realloc(manager->events, new_capacity * sizeof(NetworkEvent));
        if (!new_events) {
            pthread_mutex_unlock(&manager->mutex);
            return;
        }
        manager->events = new_events;
        manager->capacity = new_capacity;
    }

    strcpy(manager->events[manager->size].ip, ip);
    manager->events[manager->size].port = port;
    manager->events[manager->size].timestamp = timestamp;
    manager->size++;
    pthread_mutex_unlock(&manager->mutex);
}

void remove_event_by_ip(EventManager* manager, const char* ip) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->size; ++i) {
        if (strcmp(manager->events[i].ip, ip) == 0) {
            for (size_t j = i + 1; j < manager->size; ++j) {
                manager->events[j - 1] = manager->events[j];
            }
            manager->size--;
            break;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
}

NetworkEvent* find_most_recent_event_by_port(EventManager* manager, int port) {
    pthread_mutex_lock(&manager->mutex);
    NetworkEvent* most_recent = NULL;
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->events[i].port == port && (!most_recent || manager->events[i].timestamp > most_recent->timestamp)) {
            most_recent = &manager->events[i];
        }
    }
    pthread_mutex_unlock(&manager->mutex);
    return most_recent;
}

void update_event_timestamp(EventManager* manager, const char* ip, int new_timestamp) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->size; ++i) {
        if (strcmp(manager->events[i].ip, ip) == 0) {
            manager->events[i].timestamp = new_timestamp;
            break;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
}
