pthread_mutex_t allocation_lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T *array[MAX_ELEMENTS] = { NULL };
int array_size = 0;

void initialize_element(NFAPI_CRC_INDICATION_PDU_T **element) {
    *element = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*element) {
        perror("Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T");
        exit(EXIT_FAILURE);
    }
}

void validate_element(NFAPI_CRC_INDICATION_PDU_T *element, int RX_UE_INFORMATION_TAG, int RNTI) {
    if (RNTI < 0 || RNTI > 65535) {
        fprintf(stderr, "Invalid RNTI value: %d\n", RNTI);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < array_size; i++) {
        if (array[i]->RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            fprintf(stderr, "Duplicate RX_UE_INFORMATION_TAG: %d\n", RX_UE_INFORMATION_TAG);
            exit(EXIT_FAILURE);
        }
    }
}

void initialize_array(int N) {
    pthread_mutex_lock(&allocation_lock);
    if (array_size + N > MAX_ELEMENTS) {
        fprintf(stderr, "Not enough space to allocate %d elements\n", N);
        pthread_mutex_unlock(&allocation_lock);
        return;
    }

    for (int i = 0; i < N; i++) {
        initialize_element(&array[array_size]);
        array[array_size]->RX_UE_INFORMATION_TAG = rand();
        array[array_size]->RNTI = rand() % 65536;
        array[array_size]->CRC_INDICATION_REL8_TAG = rand();
        array[array_size]->CRCFLAG = (rand() % 2 == 0) ? 1 : 0;

        validate_element(array[array_size], array[array_size]->RX_UE_INFORMATION_TAG, array[array_size]->RNTI);
        array_size++;
    }

    pthread_mutex_unlock(&allocation_lock);
}

void cleanup_array() {
    for (int i = 0; i < array_size; i++) {
        free(array[i]);
        array[i] = NULL;
    }
    array_size = 0;
}
