typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    atomic_bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct Linked_List {
    Node* head;
    Node* tail;
    pthread_mutex_t mutex;
    atomic_int list_size;
} Linked_List;

// Function to initialize the linked list
void init_linked_list(Linked_List* list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    atomic_store(&list->list_size, 0);
}

// Function to insert a new element at the end of the list
void insert_element(Linked_List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = data;
    new_node->next = NULL;

    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }

    atomic_fetch_add(&list->list_size, 1);

    // Remove the oldest element if the list exceeds max size
    if (atomic_load(&list->list_size) > MAX_LIST_SIZE) {
        Node* temp = list->head;
        list->head = list->head->next;
        free(temp);
        atomic_fetch_sub(&list->list_size, 1);
    }

    pthread_mutex_unlock(&list->mutex);
}

