int insertPDU(FrameManager* manager, int frame_index, NFAPI_RX_PDU_T pdu) {
    if (frame_index < 0 || frame_index >= manager->max_frames) return -1; // Invalid frame index
    if (manager->frames[frame_index].pdu_count >= MAX_PDUS_PER_FRAME) return -2; // Frame is full

    int sequence_number = pdu.sequence_number;
    for (int i = 0; i < manager->frames[frame_index].pdu_count; i++) {
        if (manager->frames[frame_index].pdus[i].sequence_number == sequence_number) return -3; // Duplicate PDU
    }

    manager->frames[frame_index].pdus[manager->frames[frame_index].pdu_count++] = pdu;
    manager->frames[frame_index].checksum += sequence_number;

    return 0; // Success
}

NFAPI_RX_PDU_T* retrievePDU(FrameManager* manager, int frame_index, int sequence_number) {
    if (frame_index < 0 || frame_index >= manager->max_frames) return NULL; // Invalid frame index

    for (int i = 0; i < manager->frames[frame_index].pdu_count; i++) {
        if (manager->frames[frame_index].pdus[i].sequence_number == sequence_number) {
            return &manager->frames[frame_index].pdus[i];
        }
    }

    return NULL; // PDU not found
}

int initFrameManager(FrameManager* manager, int max_frames) {
    manager->max_frames = max_frames;
    manager->frame_count = 0;
    manager->frames = (NFAPI_RX_FRAME_T*)malloc(max_frames * sizeof(NFAPI_RX_FRAME_T));
    if (!manager->frames) return -1; // Memory allocation failed

    return 0; // Success
}

void destroyFrameManager(FrameManager* manager) {
    free(manager->frames);
}
