#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define N_MAX 1000

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} NFAPI_LIST_T;

void nfaapi_list_init(NFAPI_LIST_T *list, size_t initial_capacity) {
    list->pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->cond, NULL);
}

void nfaapi_list_destroy(NFAPI_LIST_T *list) {
    free(list->pdu_list);
    pthread_mutex_destroy(&list->mutex);
    pthread_cond_destroy(&list->cond);
}

int nfaapi_list_add(NFAPI_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *new_pdu) {
    pthread_mutex_lock(&list->mutex);
    while (list->size >= list->capacity && list->size > 0) {
        pthread_cond_wait(&list->cond, &list->mutex);
    }
    if (list->size < list->capacity) {
        list->pdu_list[list->size++] = *new_pdu;
        pthread_cond_signal(&list->cond);
        pthread_mutex_unlock(&list->mutex);
        return 0;
    }
    pthread_mutex_unlock(&list->mutex);
    return -1; // List is full
}

int nfaapi_list_remove(NFAPI_LIST_T *list) {
    pthread_mutex_lock(&list->mutex);
    while (list->size == 0) {
        pthread_cond_wait(&list->cond, &list->mutex);
    }
    list->size--;
    pthread_cond_signal(&list->cond);
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Example usage
int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <N_MAX>\n", argv[0]);
        return 1;
    }

    NFAPI_LIST_T list;
    nfaapi_list_init(&list, atoi(argv[1]));

    // Example adding a PDU
    NFAPI_CRC_INDICATION_PDU_T pdu;
    // Initialize pdu...
    if (nfaapi_list_add(&list, &pdu) != 0) {
        fprintf(stderr, "Failed to add PDU\n");
        return 1;
    }

    nfaapi_list_destroy(&list);
    return 0;
}
