#define MAX_INSTANCES 10000
#define MEMORY_LIMIT 5 * 1024 * 1024 // 5 MB

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void init_random_seed() {
    srand(time(0));
}

int is_rnti_duplicate(int rnti) {
    Node* current = head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            return 1;
        }
        current = current->next;
    }
    return 0;
}

int generate_unique_rnti() {
    int rnti;
    do {
        rnti = rand() % MAX_INSTANCES + 1; // Assuming RNTI range from 1 to MAX_INSTANCES
    } while (is_rnti_duplicate(rnti));
    return rnti;
}

int calculate_crc_flag() {
    return rand() % 2; // Randomly set CRCFLAG to 0 or 1
}

void* init_nfaapi_pdu(void* arg) {
    pthread_mutex_lock(&lock);
    if ((malloc_usable_size(head) + sizeof(Node)) > MEMORY_LIMIT) {
        printf("Memory limit exceeded.\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        printf("Memory allocation failed.\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    int rnti = generate_unique_rnti();
    int rx_ue_tag = rand() % MAX_INSTANCES + 1; // Assuming RX_UE_INFORMATION_TAG range from 1 to MAX_INSTANCES
    int crc_flag = calculate_crc_flag();

    newNode->data.RX_UE_INFORMATION_TAG = rx_ue_tag;
    newNode->data.RNTI = rnti;
    newNode->data.CRC_INDICATION_REL8_TAG = (crc_flag << 7) | (rand() % 127 + 1); // Setting CRCFLAG and a random value

    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
    return NULL;
}

void free_list() {
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    init_random_seed();

    // Example usage
    pthread_t threads[MAX_INSTANCES];
    for (int i = 0; i < MAX_INSTANCES; i++) {
        if (pthread_create(&threads[i], NULL, init_nfaapi_pdu, NULL) != 0) {
            printf("Thread creation failed.\n");
            return 1;
        }
    }

    for (int i = 0; i < MAX_INSTANCES; i++) {
        pthread_join(threads[i], NULL);
    }

    free_list();
    return 0;
}
