#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} CRC_QUEUE_T;

CRC_QUEUE_T* create_queue() {
    CRC_QUEUE_T* queue = (CRC_QUEUE_T*)malloc(sizeof(CRC_QUEUE_T));
    if (queue == NULL) return NULL;
    queue->count = 0;
    queue->capacity = 10;
    queue->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(queue->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (queue->data == NULL) {
        free(queue);
        return NULL;
    }
    pthread_mutex_init(&queue->mutex, NULL);
    return queue;
}

void destroy_queue(CRC_QUEUE_T* queue) {
    free(queue->data);
    pthread_mutex_destroy(&queue->mutex);
    free(queue);
}

int add_to_queue(CRC_QUEUE_T* queue, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&queue->mutex);
    if (queue->count == queue->capacity) {
        size_t new_capacity = queue->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(queue->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_data == NULL) {
            pthread_mutex_unlock(&queue->mutex);
            return -1;
        }
        queue->data = new_data;
        queue->capacity = new_capacity;
    }
    queue->data[queue->count++] = pdu;
    pthread_mutex_unlock(&queue->mutex);
    return 0;
}

int remove_from_queue(CRC_QUEUE_T* queue, int RNTI) {
    pthread_mutex_lock(&queue->mutex);
    for (size_t i = 0; i < queue->count; ++i) {
        if (queue->data[i].RNTI == RNTI) {
            for (size_t j = i; j < queue->count - 1; ++j) {
                queue->data[j] = queue->data[j + 1];
            }
            --queue->count;
            pthread_mutex_unlock(&queue->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&queue->mutex);
    return -1;
}

NFAPI_CRC_INDICATION_PDU_T* get_from_queue(CRC_QUEUE_T* queue, int RNTI) {
    pthread_mutex_lock(&queue->mutex);
    for (size_t i = 0; i < queue->count; ++i) {
        if (queue->data[i].RNTI == RNTI) {
            NFAPI_CRC_INDICATION_PDU_T* pdu = &queue->data[i];
            pthread_mutex_unlock(&queue->mutex);
            return pdu;
        }
    }
    pthread_mutex_unlock(&queue->mutex);
    return NULL;
}
```

