#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    pthread_mutex_t mutex;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU;

typedef struct {
    NFAPI_CRC_INDICATION_PDU** table;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} CRC_Indication_List;

void init_crc_ind_list(CRC_Indication_List* list, size_t capacity) {
    list->table = (NFAPI_CRC_INDICATION_PDU**)malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU*));
    for(size_t i = 0; i < capacity; ++i)
        list->table[i] = NULL;
    list->size = 0;
    list->capacity = capacity;
    pthread_mutex_init(&list->lock, NULL);
}

void insert_crc_ind(CRC_Indication_List* list, NFAPI_CRC_INDICATION_PDU* new_pdu) {
    pthread_mutex_lock(&list->lock);
    size_t index = hash(new_pdu->RNTI, list->capacity);
    while(list->table[index] != NULL)
        index = (index + 1) % list->capacity; // Linear probing for collision resolution
    list->table[index] = new_pdu;
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU* search_crc_ind(CRC_Indication_List* list, uint16_t RNTI) {
    pthread_mutex_lock(&list->lock);
    size_t index = hash(RNTI, list->capacity);
    while(list->table[index] != NULL && list->table[index]->RNTI != RNTI)
        index = (index + 1) % list->capacity;
    pthread_mutex_unlock(&list->lock);
    return list->table[index];
}

void free_crc_ind_list(CRC_Indication_List* list) {
    for(size_t i = 0; i < list->capacity; ++i) {
        NFAPI_CRC_INDICATION_PDU* pdu = list->table[i];
        while(pdu != NULL) {
            NFAPI_CRC_INDICATION_PDU* next = pdu->next;
            pthread_mutex_destroy(&pdu->mutex);
            free(pdu);
            pdu = next;
        }
    }
    free(list->table);
    pthread_mutex_destroy(&list->lock);
}
