    }
    cache->eventCount = 0;
    cache->maxEvents = maxEvents;
    return cache;
}

void addToEventCache(EventCache *cache, NetworkEvent event) {
    if (cache->eventCount >= cache->maxEvents) {
        fprintf(stderr, "EventCache is full\n");
        return;
    }
    cache->events[cache->eventCount++] = event;
}

