#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ENTRIES 1024

typedef struct LTE_UERadioState {
    int ue_id;
    int rf_tx_state;
    float tx_power_dbm;
    float sinr_db;
    float frequency_mhz;
} LTE_UERadioState;

typedef struct DynamicArray {
    LTE_UERadioState *entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->entries = (LTE_UERadioState*)malloc(MAX_ENTRIES * sizeof(LTE_UERadioState));
    array->count = 0;
    array->capacity = MAX_ENTRIES;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    free(array->entries);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int insert_entry(DynamicArray *array, LTE_UERadioState entry) {
    pthread_mutex_lock(&array->mutex);
    if (array->count >= array->capacity) {
        // Resize the array
        array->capacity *= 2;
        array->entries = (LTE_UERadioState*)realloc(array->entries, array->capacity * sizeof(LTE_UERadioState));
    }
    array->entries[array->count++] = entry;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int delete_entry(DynamicArray *array, int ue_id) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->count; ++i) {
        if (array->entries[i].ue_id == ue_id) {
            for (size_t j = i; j < array->count - 1; ++j) {
                array->entries[j] = array->entries[j + 1];
            }
            array->count--;
            pthread_mutex_unlock(&array->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&array->mutex);
    return -1;
}

void update_entries(DynamicArray *array, float (*get_tx_power)(int), float (*get_sinr)(int)) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->count; ++i) {
        LTE_UERadioState *entry = &array->entries[i];
        entry->tx_power_dbm = get_tx_power(entry->ue_id);
        entry->sinr_db = get_sinr(entry->ue_id);
    }
    pthread_mutex_unlock(&array->mutex);
}

void* periodic_update(void *arg) {
    DynamicArray *array = (DynamicArray*)arg;
    float (*get_tx_power)(int) = (float (*)(int))pthread_getspecific(get_tx_power_key);
    float (*get_sinr)(int) = (float (*)(int))pthread_getspecific(get_sinr_key);

    struct timespec interval = { .tv_sec = 1, .tv_nsec = 0 }; // Update every second
    while (1) {
        update_entries(array, get_tx_power, get_sinr);
        nanosleep(&interval, NULL);
    }
    return NULL;
}

// Example usage:
// DynamicArray *array = create_dynamic_array();
// insert_entry(array, ...);
// delete_entry(array, ...);

// pthread_t thread_id;
// pthread_create(&thread_id, NULL, periodic_update, array);
