typedef struct NFAPI_LIST_ENTRY {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct NFAPI_LIST_ENTRY *next;
} NFAPI_LIST_ENTRY;

typedef struct {
    pthread_mutex_t lock;
    NFAPI_LIST_ENTRY *head;
} NFAPI_LIST;

void nfapi_list_init(NFAPI_LIST *list) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
}

int nfapi_list_add(NFAPI_LIST *list, const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->lock);
    NFAPI_LIST_ENTRY *new_entry = (NFAPI_LIST_ENTRY *)malloc(sizeof(NFAPI_LIST_ENTRY));
    if (!new_entry) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }
    new_entry->pdu = *pdu;
    new_entry->next = list->head;
    list->head = new_entry;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void nfapi_list_free(NFAPI_LIST *list) {
    pthread_mutex_lock(&list->lock);
    NFAPI_LIST_ENTRY *current = list->head;
    while (current) {
        NFAPI_LIST_ENTRY *next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int nfapi_list_size(NFAPI_LIST *list) {
    pthread_mutex_lock(&list->lock);
    int size = 0;
    NFAPI_LIST_ENTRY *current = list->head;
    while (current) {
        size++;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return size;
}

