LTE_UserDatabase* create_user_database() {
    LTE_UserDatabase* db = (LTE_UserDatabase*)malloc(sizeof(LTE_UserDatabase));
    db->capacity = MAX_UE_ID;
    db->size = 0;
    db->array = (LTE_UERadioState*)calloc(db->capacity, sizeof(LTE_UERadioState));
    pthread_mutex_init(&db->lock, NULL);
    return db;
}

void destroy_user_database(LTE_UserDatabase* db) {
    free(db->array);
    pthread_mutex_destroy(&db->lock);
    free(db);
}

int insert_user(LTE_UserDatabase* db, int ue_id, LTE_UERadioState state) {
    pthread_mutex_lock(&db->lock);
    if (db->size == db->capacity) {
        pthread_mutex_unlock(&db->lock);
        return -1;
    }
    db->array[db->size++] = state;
    pthread_mutex_unlock(&db->lock);
    return 0;
}

int delete_user(LTE_UserDatabase* db, int ue_id) {
    pthread_mutex_lock(&db->lock);
    for (size_t i = 0; i < db->size; ++i) {
        if (db->array[i].ue_id == ue_id) {
            memmove(&db->array[i], &db->array[i + 1], sizeof(LTE_UERadioState) * (db->size - i - 1));
            --db->size;
            pthread_mutex_unlock(&db->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&db->lock);
    return -1;
}

void update_user_states(LTE_UserDatabase* db, float (*get_tx_power)(void), float (*get_sinr)(void)) {
    pthread_mutex_lock(&db->lock);
    for (size_t i = 0; i < db->size; ++i) {
        db->array[i].tx_power_dbm = get_tx_power();
        db->array[i].sinr_db = get_sinr();
    }
    pthread_mutex_unlock(&db->lock);
}

void serialize_database(LTE_UserDatabase* db, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file != NULL) {
        fwrite(&db->size, sizeof(size_t), 1, file);
        fwrite(db->array, sizeof(LTE_UERadioState), db->size, file);
        fclose(file);
    }
}

void deserialize_database(LTE_UserDatabase* db, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file != NULL) {
        size_t size;
        fread(&size, sizeof(size_t), 1, file);
        pthread_mutex_lock(&db->lock);
        if (size > db->capacity) {
            free(db->array);
            db->capacity = size;
            db->array = (LTE_UERadioState*)calloc(db->capacity, sizeof(LTE_UERadioState));
        }
        fread(db->array, sizeof(LTE_UERadioState), size, file);
        db->size = size;
        pthread_mutex_unlock(&db->lock);
        fclose(file);
    }
}

void compact_database(LTE_UserDatabase* db) {
    pthread_mutex_lock(&db->lock);
    memmove(db->array, db->array, sizeof(LTE_UERadioState) * db->size);
    memset(&db->array[db->size], 0, sizeof(LTE_UERadioState) * (db->capacity - db->size));
    pthread_mutex_unlock(&db->lock);
}

