#define MAX_ELEMENTS 1024

static LTE_UERadioState *ue_array[MAX_ELEMENTS];
static pthread_mutex_t ue_array_mutex = PTHREAD_MUTEX_INITIALIZER;
static int ue_count = 0;

int insert_UE(LTE_UERadioState state) {
    pthread_mutex_lock(&ue_array_mutex);
    if (ue_count >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&ue_array_mutex);
        return -1; // Array full
    }
    for (int i = 0; i < ue_count; ++i) {
        if (ue_array[i]->ue_id == state.ue_id) {
            pthread_mutex_unlock(&ue_array_mutex);
            return -2; // Duplicate ue_id
        }
    }
    ue_array[ue_count++] = malloc(sizeof(LTE_UERadioState));
    *ue_array[ue_count - 1] = state;
    pthread_mutex_unlock(&ue_array_mutex);
    return 0; // Success
}

int delete_UE(int ue_id) {
    pthread_mutex_lock(&ue_array_mutex);
    for (int i = 0; i < ue_count; ++i) {
        if (ue_array[i]->ue_id == ue_id) {
            free(ue_array[i]);
            for (; i < ue_count - 1; ++i) {
                ue_array[i] = ue_array[i + 1];
            }
            --ue_count;
            pthread_mutex_unlock(&ue_array_mutex);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&ue_array_mutex);
    return -1; // UE not found
}

// Function to fetch updated tx_power_dbm and sinr_db values from an external data source

void serialize_to_disk() {
    pthread_mutex_lock(&ue_array_mutex);
    // Code to serialize ue_array to disk
    pthread_mutex_unlock(&ue_array_mutex);
}

void deserialize_from_disk() {
    pthread_mutex_lock(&ue_array_mutex);
    // Code to deserialize ue_array from disk
    pthread_mutex_unlock(&ue_array_mutex);
}

int main() {
    LTE_UERadioState state = {1, 0, -50, 10, 2.6};
    insert_UE(state);
    delete_UE(1);
    return 0;
}
```

