#define BUFFER_SIZE_LIMIT 1024 * 1024 // 1MB buffer size limit

typedef struct {
    int DL_FRAME_INFO;
    int CELL_ID;
    int PHY_RX_DATA;
} PHY_RX_PDU_T;

typedef struct Node {
    PHY_RX_PDU_T data;
    struct Node* next;
} Node;

int allocate_and_populate_pdu_array(int num_structures, Node** head) {
    if (num_structures <= 0 || head == NULL) return -1; // Invalid input

    *head = NULL;
    int allocated_size = 0;
    int qfi_threshold = num_structures / 3; // 30% threshold for RX_QFI > 15
    int rx_qfi_counter = 0;

    for (int i = 0; i < num_structures; ++i) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (new_node == NULL) {
            // Handle memory allocation failure gracefully
            printf("Memory allocation failed.\n");
            while (*head != NULL) {
                Node* temp = *head;
                *head = (*head)->next;
                free(temp);
            }
            return -1; // Return error code
        }

        new_node->data.DL_FRAME_INFO = i + 1; // Example valid value
        new_node->data.CELL_ID = i; // Assign unique CELL_ID

        if (rx_qfi_counter < qfi_threshold) {
            new_node->data.PHY_RX_DATA = rand() % 32; // Random RX_QFI value up to 31
            if (new_node->data.PHY_RX_DATA > 15) ++rx_qfi_counter;
        } else {
            new_node->data.PHY_RX_DATA = rand() % 16; // Ensure no more than 30% have RX_QFI > 15
        }

        new_node->next = *head;
        *head = new_node;

        allocated_size += sizeof(Node);
        if (allocated_size > BUFFER_SIZE_LIMIT) {
            printf("Buffer size limit exceeded.\n");
            while (*head != NULL) {
                Node* temp = *head;
                *head = (*head)->next;
                free(temp);
            }
            return -2; // Return error code for buffer size limit
        }
    }

    return 0; // Success
}

int main() {
    Node* head = NULL;
    int num_structures = 100;

    if (allocate_and_populate_pdu_array(num_structures, &head) == 0) {
        printf("Memory allocation and population successful.\n");
        // Free allocated memory
        while (head != NULL) {
            Node* temp = head;
            head = head->next;
            free(temp);
        }
    } else {
        printf("Memory allocation or population failed.\n");
    }

    return 0;
}
