NFAPI_CRC_INDICATION_PDU_T* create_crc_indications(int N) {
    if (N <= 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation

    uint8_t last_crcflag = 0; // Initialize with a dummy value
    for (int i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand();
        array[i].RNTI = rand() % 65536;
        do {
            array[i].CRCFLAG = rand() % 2;
        } while (array[i].CRCFLAG == last_crcflag);
        last_crcflag = array[i].CRCFLAG;
    }

    return array;
}

int verify_crc_indications(NFAPI_CRC_INDICATION_PDU_T* array, int N) {
    if (!array || N <= 0) return -1;

    uint8_t last_crcflag = 0;
    for (int i = 0; i < N; i++) {
        if (last_crcflag == array[i].CRCFLAG) {
            printf("Verification failed: Consecutive elements have the same CRCFLAG\n");
            return -1;
        }
        last_crcflag = array[i].CRCFLAG;
    }

    printf("Verification passed: All CRCFLAGS are unique\n");
    return 0;
}

