int allocate_and_populate_crc_indication_pdu(int N, u_char *buffer, size_t buffer_size) {
    if (N > 10000) {
        return -1; // Error: Maximum of 10,000 structures allowed
    }

    NFAPI_CRC_INDICATION_PDU_T **pdu_list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (!pdu_list) {
        return -2; // Error: Memory allocation failed
    }

    int unique_rnti[N];
    srand(time(NULL));
    for (int i = 0; i < N; ++i) {
        do {
            unique_rnti[i] = rand() % 10000 + 1;
        } while (i > 0 && find(unique_rnti, i, unique_rnti[i]) != -1);
    }

    int attempts = 0;
    while (attempts < 3) {
        for (int i = 0; i < N; ++i) {
            size_t struct_size = sizeof(NFAPI_CRC_INDICATION_PDU_T) + sizeof(u_char);
            if (buffer + buffer_size - (char *)pdu_list[i] < struct_size) {
                free(pdu_list);
                return -3; // Error: Buffer overflow
            }

            pdu_list[i] = (NFAPI_CRC_INDICATION_PDU_T *)(buffer + buffer_size - struct_size);
            buffer_size -= struct_size;

            pdu_list[i]->RX_UE_INFORMATION_TAG = rand() % 1000;
            pdu_list[i]->RNTI = unique_rnti[i];
            pdu_list[i]->CRCFLAG = (rand() % 2 == 0) ? true : false;
        }

        if (buffer_size >= sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
            break;
        }
        buffer_size += 4096; // Attempt to reallocate memory
        attempts++;
    }

    free(pdu_list);
    return 0; // Success
}

int find(int arr[], int n, int x) {
    for (int i = 0; i < n; ++i) {
        if (arr[i] == x) {
            return i;
        }
    }
    return -1;
}
