struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
};

class DynamicValueGenerator {
public:
    DynamicValueGenerator(int minRNTI, int maxRNTI, float minCRCFLAG, float maxCRCFLAG)
        : rntiDistribution(minRNTI, maxRNTI), crcFlagDistribution(minCRCFLAG, maxCRCFLAG) {}

    int GenerateRandomInteger() {
        return std::uniform_int_distribution<>(minRNTI, maxRNTI)(engine);
    }

    float GenerateRandomFloat() {
        return std::uniform_real_distribution<>(minCRCFLAG, maxCRCFLAG)(engine);
    }

    std::string ToString() const {
        return "DynamicValueGenerator(minRNTI=" + std::to_string(minRNTI) + ", maxRNTI=" + std::to_string(maxRNTI) +
               ", minCRCFLAG=" + std::to_string(minCRCFLAG) + ", maxCRCFLAG=" + std::to_string(maxCRCFLAG) + ")";
    }

private:
    int minRNTI, maxRNTI;
    float minCRCFLAG, maxCRCFLAG;
    std::mt19937 engine{std::random_device{}()};
    std::uniform_int_distribution<int> rntiDistribution;
    std::uniform_real_distribution<float> crcFlagDistribution;
};

NFAPI_CRC_INDICATION_PDU_T* generateNfareRandomIndications(int N) {
    if (N <= 0) return nullptr;

    DynamicValueGenerator generator(1, 1024, 0.0f, 1.0f);
    NFAPI_CRC_INDICATION_PDU_T* indications = new NFAPI_CRC_INDICATION_PDU_T[N];

    for (int i = 0; i < N; ++i) {
        indications[i].RX_UE_INFORMATION_TAG = generator.GenerateRandomInteger();
        indications[i].RNTI = generator.GenerateRandomInteger();
        indications[i].CRCFLAG = static_cast<int>(generator.GenerateRandomFloat());
    }

    return indications;
}

int main() {
    const int N = 5;
    NFAPI_CRC_INDICATION_PDU_T* indications = generateNfareRandomIndications(N);

    if (indications) {
        for (int i = 0; i < N; ++i) {
            std::cout << "RX_UE_INFORMATION_TAG: " << indications[i].RX_UE_INFORMATION_TAG
                      << ", RNTI: " << indications[i].RNTI
                      << ", CRCFLAG: " << indications[i].CRCFLAG << std::endl;
        }
        delete[] indications;
    } else {
        std::cout << "Failed to generate NFAPI_CRC_INDICATION_PDU_T structures." << std::endl;
    }

    return 0;
}
