        config->elements = (RRC_CONFIGURATION_ELEMENT_T*)malloc(sizeof(RRC_CONFIGURATION_ELEMENT_T));
        if (!config->elements) return -1;
        config->num_elements = 1;
    } else {
        RRC_CONFIGURATION_ELEMENT_T* new_elements = (RRC_CONFIGURATION_ELEMENT_T*)realloc(config->elements, config->num_elements * sizeof(RRC_CONFIGURATION_ELEMENT_T));
        if (!new_elements) return -1;
        config->elements = new_elements;
        config->num_elements++;
    }

    config->elements[config->num_elements - 1].BWP = BWP;
    config->elements[config->num_elements - 1].TPC = TPC;

    return 0;
}

int remove_configuration_element(NFAPI_RRC_CONNECTION_RECONFIGURATION_REQUEST_T* config, int index) {
    if (index < 0 || index >= config->num_elements) return -1;

    for (size_t i = index; i < config->num_elements - 1; i++) {
        config->elements[i] = config->elements[i + 1];
    }

    config->num_elements--;

