typedef struct NFAPI_CRC_INDICATION_PDU_S {
    uint32_t UE_ID;
    CRC_FLAG_T CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_S *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T *head;
} NFAPI_CRC_LIST_T;

NFAPI_CRC_LIST_T* create_crc_list() {
    NFAPI_CRC_LIST_T* list = (NFAPI_CRC_LIST_T*)malloc(sizeof(NFAPI_CRC_LIST_T));
    if (!list) return NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    return list;
}

void destroy_crc_list(NFAPI_CRC_LIST_T* list) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void add_crc_to_list(NFAPI_CRC_LIST_T* list, uint32_t UE_ID) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    new_node->UE_ID = UE_ID;
    new_node->CRCFLAG = (CRC_FLAG_T)((rand() % 3) + 1); // Randomly set CRCFLAG
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

void* iterate_crc_list(void* arg) {
    NFAPI_CRC_LIST_T* list = (NFAPI_CRC_LIST_T*)arg;
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        // Process current node
        printf("UE_ID: %u, CRCFLAG: %d\n", current->UE_ID, current->CRCFLAG);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

int main() {
    srand(time(NULL));
    NFAPI_CRC_LIST_T* list = create_crc_list();
    if (!list) {
        printf("Failed to create CRC list\n");
        return -1;
    }

    add_crc_to_list(list, 1001);
    add_crc_to_list(list, 1002);

    pthread_t thread1, thread2;
    pthread_create(&thread1, NULL, iterate_crc_list, (void*)list);
    pthread_create(&thread2, NULL, iterate_crc_list, (void*)list);

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    destroy_crc_list(list);
    return 0;
}
