#define MAX_USERS 100
#define LOG_LEVEL_DEBUG 0
#define LOG_LEVEL_INFO 1

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void log_message(int level, const char *message) {
    if (level == LOG_LEVEL_DEBUG) {
        printf("DEBUG: %s\n", message);
    } else if (level == LOG_LEVEL_INFO) {
        printf("INFO: %s\n", message);
    }
}

int is_valid_rnti(int rnti, int network_mode) {
    // Implement RNTI validation logic based on network mode
    return (network_mode == 4G && rnti >= 1 && rnti <= 256) ||
           (network_mode == 5G && rnti >= 0x4000 && rnti <= 0x3FFFF);
}

void *create_nfaapi_crc_pdu(int network_mode, int max_users, int debug_enabled) {
    srand(time(NULL));
    int users = rand() % max_users + 1;
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(users * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < users; i++) {
        pdus[i].RX_UE_INFORMATION_TAG = i;
        do {
            pdus[i].RNTI = rand() % 260; // Example RNTI range for 4G
        } while (!is_valid_rnti(pdus[i].RNTI, network_mode));
        pdus[i].CRC_INDICATION_REL8_TAG = rand() % 2;

        if (debug_enabled) {
            log_message(LOG_LEVEL_DEBUG, "Created PDU for RNTI: %d", pdus[i].RNTI);
        }
    }

    return pdus;
