typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_size) {
    DynamicArray *da = malloc(sizeof(DynamicArray));
    if (da == NULL) return NULL;
    da->array = realloc(NULL, initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (da->array == NULL) {
        free(da);
        return NULL;
    }
    da->size = initial_size;
    pthread_mutex_init(&da->mutex, NULL);
    return da;
}

void destroy_dynamic_array(DynamicArray *da) {
    pthread_mutex_lock(&da->mutex);
    free(da->array);
    pthread_mutex_unlock(&da->mutex);
    pthread_mutex_destroy(&da->mutex);
    free(da);
}

int insert_into_array(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&da->mutex);
    if (da->size == 0) {
        da->array = realloc(NULL, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (da->array == NULL) {
            pthread_mutex_unlock(&da->mutex);
            return -1;
        }
        da->size = 1;
    } else {
        da->array = realloc(da->array, (da->size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (da->array == NULL) {
            pthread_mutex_unlock(&da->mutex);
            return -1;
        }
        da->size++;
    }
    da->array[da->size - 1] = pdu;
    pthread_mutex_unlock(&da->mutex);
    return 0;
}

int get_from_array(DynamicArray *da, size_t index, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (index >= da->size) return -1;
    pthread_mutex_lock(&da->mutex);
    *pdu = da->array[index];
    pthread_mutex_unlock(&da->mutex);
    return 0;
}

