void addPacketEntry(PacketHeader **packetArray, int *size, PacketHeader *newPacket) {
    if (*size % 10 == 0) { // Reallocate when the array is full
        *size += 5; // Increase by 5 for better amortized performance
        packetArray = (PacketHeader **)realloc(packetArray, *size * sizeof(PacketHeader *));
        if (packetArray == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(1);
        }
    }
    packetArray[*size / 5] = newPacket;
}

void iterateAndCheckPackets(PacketHeader **packetArray, int size) {
