        ueContexts[i].qos.latencyBudget = 200 - (rand() % 100); // Random latency budget
        ueContexts[i].traffic.bandwidth = 10 * i; // Bandwidth grows linearly with user ID
        ueContexts[i].traffic.delay = rand() % 5 + 1; // Random delay from 1 to 5

        // Validate against network policies and optimize configuration
        if (ueContexts[i].qos.priority < 3) {
            ueContexts[i].qos.priority = 3; // Minimum priority set to 3
        }
        if (ueContexts[i].traffic.bandwidth > 1000) {
            ueContexts[i].traffic.bandwidth = 1000; // Maximum bandwidth capped at 1000
        }
    }

    return ueContexts;
}
