int allocate_crc_array(CRC_ARRAY** array, size_t N) {
    *array = (CRC_ARRAY*)aligned_alloc(64, sizeof(CRC_ARRAY));
    if (*array == NULL) return -1; // Memory allocation failed

    (*array)->count = N;
    (*array)->pdus = (NFAPI_CRC_INDICATION_PDU_T*)aligned_alloc(64, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
