        return -1; // Memory allocation failed
    }

    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    pthread_mutex_init(&(*array)->mutex, &attr);

    for (size_t i = 0; i < N; ++i) {
        (*array)->pdus[i].RX_UE_INFORMATION_TAG = rand();
        (*array)->pdus[i].RNTI = rand() % 65536;
        (*array)->pdus[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        (*array)->pdus[i].CRCFLAG = rand() % 2;
