typedef struct TLS_CONNECTION {
    SSL_CTX *ctx;
    SSL *ssl;
    int fd;
    int retries_left;
} TLS_CONNECTION;

int init_nfaip_rx_pdu(NFAPI_RX_PDU_T *pdu, int ue_id, size_t buffer_size) {
    pdu->UE_ID = ue_id;
    pdu->buffer = (unsigned char *)malloc(buffer_size);
    if (!pdu->buffer) return -1;
    pdu->buffer_size = buffer_size;
    pdu->signal_strength = 0;
    pdu->timestamp = 0;
    return 0;
}

void cleanup_nfaip_rx_pdu(NFAPI_RX_PDU_T *pdu) {
    free(pdu->buffer);
    pdu->buffer = NULL;
    pdu->buffer_size = 0;
}

TLS_CONNECTION* init_tls_connection(const char *hostname, const char *port) {
    TLS_CONNECTION *conn = (TLS_CONNECTION *)malloc(sizeof(TLS_CONNECTION));
    if (!conn) return NULL;

    OpenSSL_add_all_algorithms();
    SSL_load_error_strings();
    conn->ctx = SSL_CTX_new(TLS_client_method());
    if (!conn->ctx) {
        ERR_print_errors_fp(stderr);
        free(conn);
        return NULL;
    }

    conn->ssl = SSL_new(conn->ctx);
    if (!conn->ssl) {
        ERR_print_errors_fp(stderr);
        SSL_CTX_free(conn->ctx);
        free(conn);
        return NULL;
    }

    conn->retries_left = 3;
    conn->fd = -1;

    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    if (getaddrinfo(hostname, port, &hints, &res) != 0) {
        SSL_free(conn->ssl);
        SSL_CTX_free(conn->ctx);
        free(conn);
        return NULL;
    }

    conn->fd = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    if (conn->fd < 0) {
        freeaddrinfo(res);
        SSL_free(conn->ssl);
        SSL_CTX_free(conn->ctx);
        free(conn);
        return NULL;
    }

    if (connect(conn->fd, res->ai_addr, res->ai_addrlen) != 0) {
        close(conn->fd);
        freeaddrinfo(res);
        SSL_free(conn->ssl);
        SSL_CTX_free(conn->ctx);
        free(conn);
        return NULL;
    }

    freeaddrinfo(res);
    SSL_set_fd(conn->ssl, conn->fd);

    if (SSL_connect(conn->ssl) <= 0) {
        ERR_print_errors_fp(stderr);
        close(conn->fd);
        SSL_free(conn->ssl);
        SSL_CTX_free(conn->ctx);
        free(conn);
        return NULL;
    }

    return conn;
}

void cleanup_tls_connection(TLS_CONNECTION *conn) {
    if (SSL_is_init_finished(conn->ssl)) {
        SSL_shutdown(conn->ssl);
    }
    close(conn->fd);
    SSL_free(conn->ssl);
    SSL_CTX_free(conn->ctx);
    free(conn);
}
