typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* create_node(int rx_tag, int rnti, int crc_flag) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        printf("Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    new_node->data.RX_UE_INFORMATION_TAG = rx_tag;
    new_node->data.RNTI = rnti;
    new_node->data.CRC_INDICATION_REL8_TAG = crc_flag;
    new_node->next = NULL;
    return new_node;
}

Node* create_linked_list(int max_elements) {
    Node* head = NULL;
    int current_rnti = rand() % 100; // Initial RNTI value
    for (int i = 0; i < max_elements; i++) {
        int new_rnti;
        do {
            new_rnti = rand() % 100;
        } while (new_rnti == current_rnti);
        Node* new_node = create_node(i, new_rnti, DEFAULT_CRCFLAG);
        if (head == NULL) {
            head = new_node;
        } else {
            Node* temp = head;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = new_node;
        }
        current_rnti = new_rnti;
    }
    return head;
}

void free_linked_list(Node* head) {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    srand(time(0));
    int max_elements = MAX_ELEMENTS;
    Node* list = create_linked_list(max_elements);
    printf("Linked List Created with %d elements\n", max_elements);
    free_linked_list(list);
    return 0;
}
