#include <stdlib.h>
#include <stdio.h>
#include <time.h>

#define MAX_RNTI 1024

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

int validateRNTI(int rnti, int* validRNTIs) {
    for (int i = 0; i < MAX_RNTI; ++i) {
        if (validRNTIs[i] == rnti) return 1;
    }
    return 0;
}

Node* createLinkedList(int N, int maxListSize, int* validRNTIs, int crcFlagConsistency) {
    srand(time(NULL)); // Seed for random number generation
    Node* head = NULL;
    Node** current = &head;

    for (int i = 0; i < N && *current != NULL && (*current)->next == NULL && (i + 1 <= maxListSize); ++i) {
        if ((*current)->data.RX_UE_INFORMATION_TAG == -1) {
            *current = malloc(sizeof(Node));
            if (*current == NULL) {
                freeLinkedList(head);
                return NULL;
            }
        }

        (*current)->data.RX_UE_INFORMATION_TAG = i + 1;
        (*current)->data.CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG

        int validRNTI = 0;
        while (!validRNTI) {
            (*current)->data.RNTI = rand() % MAX_RNTI + 1;
            if (validateRNTI((*current)->data.RNTI, validRNTIs)) validRNTI = 1;
        }

        // Ensure CRC flag consistency
        if (crcFlagConsistency && i > 0) {
            int prevCrcFlag = (*current)->next->prev->data.CRC_INDICATION_REL8_TAG;
            if ((*current)->data.CRC_INDICATION_REL8_TAG != prevCrcFlag) {
                freeLinkedList(head);
                return NULL;
            }
        }

        (*current)->next = (*current)->data.RX_UE_INFORMATION_TAG == N ? NULL : malloc(sizeof(Node));
        current = &(*current)->next;
    }

    if (*current != NULL && (*current)->next != NULL) {
        freeLinkedList(head);
        return NULL;
    }

    return head;
}

void freeLinkedList(Node* head) {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}
```

