    time_t TIME_TO_LIVE;
    struct HTTP_REQUEST_PDU_T *next;
} HTTP_REQUEST_PDU_T;

typedef struct {
    HTTP_REQUEST_PDU_T *head;
    size_t size;
    size_t cache_size_limit;
    pthread_mutex_t lock;
} HTTP_CACHE_T;

HTTP_CACHE_T http_cache = {NULL, 0, 100, PTHREAD_MUTEX_INITIALIZER};

int fetch_config_param(const char *param_name, void *value, size_t value_size) {
    // Simulate fetching config parameters from an external service
    return 0; // Return 0 on success, non-zero on failure
}

void *cache_request(HTTP_REQUEST_PDU_T *request) {
    pthread_mutex_lock(&http_cache.lock);
    if (fetch_config_param("CACHE_SIZE_LIMIT", &http_cache.cache_size_limit, sizeof(http_cache.cache_size_limit)) != 0) {
        fprintf(stderr, "Failed to fetch cache size limit\n");
        pthread_mutex_unlock(&http_cache.lock);
        return NULL;
    }

    while (http_cache.size >= http_cache.cache_size_limit && http_cache.head != NULL) {
        HTTP_REQUEST_PDU_T *to_evict = http_cache.head;
        http_cache.head = http_cache.head->next;
        http_cache.size--;
        free(to_evict->METHOD);
        free(to_evict->URL);
        free(to_evict->HEADER_DATA);
        free(to_evict);
    }

    if (http_cache.head == NULL || strcmp(http_cache.head->URL, request->URL) != 0) {
        HTTP_REQUEST_PDU_T *new_request = malloc(sizeof(HTTP_REQUEST_PDU_T));
        new_request->REQUEST_ID = request->REQUEST_ID;
        new_request->METHOD = strdup(request->METHOD);
        new_request->URL = strdup(request->URL);
        new_request->HEADER_DATA = strdup(request->HEADER_DATA);
        new_request->TIME_TO_LIVE = time(NULL) + fetch_config_param("TIME_TO_LIVE", NULL, 0); // Simulate fetching TIME_TO_LIVE
        new_request->next = http_cache.head;
        http_cache.head = new_request;
        http_cache.size++;
    }
    pthread_mutex_unlock(&http_cache.lock);
    return (void *)http_cache.head;
}

int main() {
    HTTP_REQUEST_PDU_T request1 = {1, "GET", "/api/v1/data", "Authorization: Bearer token"};
    HTTP_REQUEST_PDU_T request2 = {2, "POST", "/api/v1/data", "Content-Type: application/json"};

    void *cached_request1 = cache_request(&request1);
    if (cached_request1 == NULL) {
        fprintf(stderr, "Failed to cache request\n");
        return 1;
    }

    void *cached_request2 = cache_request(&request2);
    if (cached_request2 == NULL) {
        fprintf(stderr, "Failed to cache request\n");
        return 1;
    }

    // Simulate processing the cached requests
    printf("Cached Request 1: ID=%d, URL=%s\n", ((HTTP_REQUEST_PDU_T *)cached_request1)->REQUEST_ID, ((HTTP_REQUEST_PDU_T *)cached_request1)->URL);
    printf("Cached Request 2: ID=%d, URL=%s\n", ((HTTP_REQUEST_PDU_T *)cached_request2)->REQUEST_ID, ((HTTP_REQUEST_PDU_T *)cached_request2)->URL);

    // Clean up
    HTTP_REQUEST_PDU_T *current = http_cache.head;
    while (current != NULL) {
        HTTP_REQUEST_PDU_T *next = current->next;
        free(current->METHOD);
        free(current->URL);
        free(current->HEADER_DATA);
        free(current);
        current = next;
    }

    return 0;
}
