#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    // Assuming CRC_INDICATION_REL8_TAG has a field named 'CRCFLAG'
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* list;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} DynamicList;

DynamicList* create_dynamic_list(size_t initial_capacity) {
    DynamicList* dl = (DynamicList*)malloc(sizeof(DynamicList));
    if (!dl) return NULL;

    dl->list = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!dl->list) {
        free(dl);
        return NULL;
    }

    dl->capacity = initial_capacity;
    dl->count = 0;
    pthread_mutex_init(&dl->mutex, NULL);

    return dl;
}

void destroy_dynamic_list(DynamicList* dl) {
    pthread_mutex_lock(&dl->mutex);
    if (dl->list) {
        free(dl->list);
        dl->list = NULL;
    }
    pthread_mutex_unlock(&dl->mutex);
    pthread_mutex_destroy(&dl->mutex);
    free(dl);
}

int add_to_list(DynamicList* dl, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&dl->mutex);
    if (dl->count >= dl->capacity) {
        size_t new_capacity = dl->capacity ? dl->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T* new_list = realloc(dl->list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            pthread_mutex_unlock(&dl->mutex);
            return -1; // Memory allocation failed
        }
        dl->list = new_list;
        dl->capacity = new_capacity;
    }
    dl->list[dl->count++] = item;
    pthread_mutex_unlock(&dl->mutex);
    return 0;
}

int update_crc_flag(DynamicList* dl, size_t index, int new_crcflag) {
    pthread_mutex_lock(&dl->mutex);
    if (index >= dl->count) {
        pthread_mutex_unlock(&dl->mutex);
        return -1; // Index out of bounds
    }
    dl->list[index].CRCFLAG = new_crcflag;
    pthread_mutex_unlock(&dl->mutex);
    return 0;
}
