#define NICP_HEADER_SIZE 14
#define MAX_PAYLOAD_LENGTH 1024

typedef struct {
    unsigned char source_mac[6];
    unsigned char destination_mac[6];
    unsigned char payload[MAX_PAYLOAD_LENGTH];
    unsigned short checksum;
} NICPMessage;

void generate_random_mac(unsigned char *mac) {
    for (int i = 0; i < 6; i++) {
        mac[i] = rand() % 256;
    }
}

unsigned short calculate_checksum(NICPMessage *msg) {
    unsigned int sum = 0;
    unsigned char *ptr = (unsigned char *)msg;
    for (int i = 0; i < NICP_HEADER_SIZE + msg->payload[0]; i++) {
        sum += ptr[i];
    }
    return ~sum & 0xFFFF;
}

NICPMessage* initialize_nicp_messages(int num_messages, int payload_length) {
    srand(time(NULL));
    NICPMessage *messages = (NICPMessage *)malloc(num_messages * sizeof(NICPMessage));
    if (!messages) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    for (int i = 0; i < num_messages; i++) {
        generate_random_mac(messages[i].source_mac);
        generate_random_mac(messages[i].destination_mac);
        messages[i].payload[0] = payload_length;
        for (int j = 1; j <= payload_length; j++) {
            messages[i].payload[j] = rand() % 256;
        }
        messages[i].checksum = calculate_checksum(&messages[i]);
    }
    return messages;
}

void free_nicp_messages(NICPMessage *messages, int num_messages) {
    free(messages);
}

int main() {
    int num_messages = 1000000;
    int payload_length = 512;
    NICPMessage *nicp_messages = initialize_nicp_messages(num_messages, payload_length);
    if (nicp_messages) {
        // Process the messages
        free_nicp_messages(nicp_messages, num_messages);
    }
    return 0;
}
