typedef struct memory_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct memory_node* next;
} MemoryNode;

MemoryNode* memory_pool = NULL;
int pool_size = 0;

NFAPI_CRC_INDICATION_PDU_T* allocate_structure() {
    if (memory_pool == NULL || pool_size == 0) {
        // Allocate new block of memory
        memory_pool = (MemoryNode*)malloc(MAX_STRUCTURES * sizeof(MemoryNode));
        if (memory_pool == NULL) {
            // Handle memory allocation failure
            return NULL;
        }
        for (int i = 0; i < MAX_STRUCTURES; i++) {
            memory_pool[i].next = &memory_pool[i + 1];
        }
        memory_pool[MAX_STRUCTURES - 1].next = NULL;
        pool_size = MAX_STRUCTURES;
    }

    MemoryNode* node = memory_pool;
    memory_pool = memory_pool->next;
    pool_size--;

    // Initialize structure
    NFAPI_CRC_INDICATION_PDU_T* new_struct = &node->data;
    new_struct->RX_UE_INFORMATION_TAG = rand(); // Simulate dynamic RX_UE_INFORMATION_TAG from external source
    new_struct->RNTI = (uint16_t)rand(); // Simulate dynamic RNTI from external source
    new_struct->CRCFLAG = (bool)(rand() % 2); // Randomly set CRCFLAG

    return new_struct;
}

void deallocate_structure(NFAPI_CRC_INDICATION_PDU_T* structure) {
    MemoryNode* node = (MemoryNode*)structure - offsetof(MemoryNode, data);
    node->next = memory_pool;
    memory_pool = node;
    pool_size++;
}
