    size_t capacity;
    pthread_mutex_t mutex;
} DynamicList_T;

DynamicList_T* create_dynamic_list() {
    DynamicList_T* list = (DynamicList_T*)malloc(sizeof(DynamicList_T));
    if (!list) return NULL;
    list->list = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_dynamic_list(DynamicList_T* list) {
    pthread_mutex_lock(&list->mutex);
    free(list->list);
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

bool is_valid_rnti(uint16_t RNTI) {
    return RNTI <= MAX_RNTI;
}

void resize_list(DynamicList_T* list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* new_list = realloc(list->list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_list) {
        pthread_mutex_lock(&list->mutex);
        free(list->list);
        list->list = new_list;
        list->capacity = new_capacity;
        pthread_mutex_unlock(&list->mutex);
    }
}

bool add_rnti(DynamicList_T* list, uint16_t RNTI) {
    if (!is_valid_rnti(RNTI)) return false;

    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->count; i++) {
        if (list->list[i].RNTI == RNTI) {
            pthread_mutex_unlock(&list->mutex);
            return false;
        }
    }

    if (list->count >= list->capacity) {
        size_t new_capacity = (list->capacity == 0) ? 1 : list->capacity * 2;
        resize_list(list, new_capacity);
    }

    list->list[list->count].RNTI = RNTI;
    list->count++;

    pthread_mutex_unlock(&list->mutex);
    return true;
}
