    if (frame->symbols) {
        free(frame->symbols);
    }
    free(frame);
}

// Function to insert a new DL_FRAME_T into the list, ensuring uniqueness of SUBFRAME_ID and respecting max size
int insert_dl_frame(DL_FRAME_T** frameList, int* count, int maxSize, DL_FRAME_T newFrame) {
    if (*count >= maxSize) {
        fprintf(stderr, "Max size limit reached\n");
        return -1;
    }
    for (int i = 0; i < *count; i++) {
        if (frameList[i]->subframeInfo.subframeId == newFrame.subframeInfo.subframeId) {
            fprintf(stderr, "Duplicate SUBFRAME_ID found\n");
            return -1;
        }
    }
    frameList[*count] = allocate_dl_frame();
    *frameList[*count] = newFrame;
    (*count)++;
    return 0;
}

// Function to free the memory allocated for a list of DL_FRAME_T structures
void free_dl_frame_list(DL_FRAME_T** frameList, int count) {
    for (int i = 0; i < count; i++) {
        deallocate_dl_frame(frameList[i]);
    }
    free(frameList);
