        if (!new_elements) {
            perror("Failed to allocate more memory for list elements");
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }
        list->elements = new_elements;
        list->capacity = new_capacity;
    }
    list->elements[list->size++] = pdu;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int remove_mac_pdu(List* list, MAC_PDU* pdu) {
