        if (list->elements[i] == pdu) {
            for (size_t j = i; j < list->size - 1; ++j) {
                list->elements[j] = list->elements[j + 1];
            }
            --list->size;
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return -1;
