#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_CONNECTIONS 100
#define MAX_ACTIVE_INSTANCES 5

typedef struct {
    int connection_id;
    char peer_address[256];
    int state; // Assume 0 for closed, 1 for open
} TCP_CONNECTION_RECORD_T;

typedef struct {
    TCP_CONNECTION_RECORD_T connections[MAX_CONNECTIONS];
    sem_t active_instances_semaphore;
    pthread_mutex_t pool_mutex;
    int next_available_id;
} TCP_POOL_T;

TCP_POOL_T tcp_pool;

void initialize_tcp_pool(int max_connections) {
    if (max_connections > MAX_CONNECTIONS) {
        printf("Error: Maximum connections exceeded.\n");
        exit(EXIT_FAILURE);
    }
    sem_init(&tcp_pool.active_instances_semaphore, 0, MAX_ACTIVE_INSTANCES);
    pthread_mutex_init(&tcp_pool.pool_mutex, NULL);
    tcp_pool.next_available_id = 0;
}

int allocate_connection_record(const char* peer_address) {
    if (sem_wait(&tcp_pool.active_instances_semaphore) == -1) {
        perror("Error: Failed to acquire semaphore.");
        return -1;
    }
    pthread_mutex_lock(&tcp_pool.pool_mutex);
    int connection_id = tcp_pool.next_available_id;
    if (connection_id >= MAX_CONNECTIONS) {
        sem_post(&tcp_pool.active_instances_semaphore);
        pthread_mutex_unlock(&tcp_pool.pool_mutex);
        printf("Error: Connection pool is full.\n");
        return -1;
    }
    TCP_CONNECTION_RECORD_T* record = &tcp_pool.connections[connection_id];
    record->connection_id = connection_id;
    strcpy(record->peer_address, peer_address);
    record->state = 1; // Open
    tcp_pool.next_available_id = (connection_id + 1) % MAX_CONNECTIONS;
    pthread_mutex_unlock(&tcp_pool.pool_mutex);
    printf("Connection allocated with ID: %d\n", connection_id);
    return connection_id;
}

void free_connection_record(int connection_id) {
    pthread_mutex_lock(&tcp_pool.pool_mutex);
    TCP_CONNECTION_RECORD_T* record = &tcp_pool.connections[connection_id];
    if (record->state == 1) {
        record->state = 0; // Close
        tcp_pool.next_available_id = (connection_id + 1) % MAX_CONNECTIONS;
        printf("Connection freed with ID: %d\n", connection_id);
    }
    pthread_mutex_unlock(&tcp_pool.pool_mutex);
    sem_post(&tcp_pool.active_instances_semaphore);
}

void log_active_connections() {
    int count = 0;
    pthread_mutex_lock(&tcp_pool.pool_mutex);
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (tcp_pool.connections[i].state == 1) {
            count++;
        }
    }
    pthread_mutex_unlock(&tcp_pool.pool_mutex);
    printf("Total active connections: %d\n", count);
}

void* tcp_manager_thread(void* arg) {
    while (1) {
        // Simulate connection establishment and closure
        allocate_connection_record("192.168.0.1");
        free_connection_record(0);
        log_active_connections();
        sleep(5); // Simulate time passing
    }
    return NULL;
}

int main() {
    initialize_tcp_pool(MAX_CONNECTIONS);

    pthread_t threads[MAX_ACTIVE_INSTANCES];
    for (int i = 0; i < MAX_ACTIVE_INSTANCES; i++) {
        if (pthread_create(&threads[i], NULL, tcp_manager_thread, NULL) != 0) {
            perror("Error: Failed to create thread.");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < MAX_ACTIVE_INSTANCES; i++) {
        pthread_join(threads[i], NULL);
    }

    sem_destroy(&tcp_pool.active_instances_semaphore);
    pthread_mutex_destroy(&tcp_pool.pool_mutex);

    return 0;
}
