Instance instances[M];

void initialize_instances(int num_instances, int max_structures) {
    for (int i = 0; i < num_instances; i++) {
        instances[i].priority = i % 10; // Example priority assignment
        instances[i].pool_size = max_structures;
        instances[i].active_count = 0;
        pthread_mutex_init(&instances[i].mutex, NULL);
    }
}

NFAPI_CRC_INDICATION_PDU_T* get_structure(int instance_id) {
    if (instance_id < 0 || instance_id >= M) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *new_struct = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_struct) return NULL; // Handle memory allocation failure

    pthread_mutex_lock(&instances[instance_id].mutex);
    while (instances[instance_id].active_count >= instances[instance_id].pool_size) {
        pthread_cond_wait(&instances[instance_id].cond, &instances[instance_id].mutex);
    }
    instances[instance_id].pool[instances[instance_id].active_count++] = *new_struct;
    pthread_mutex_unlock(&instances[instance_id].mutex);

    return new_struct;
}

void release_structure(int instance_id, NFAPI_CRC_INDICATION_PDU_T *struct_ptr) {
    if (instance_id < 0 || instance_id >= M || !struct_ptr) return;

    pthread_mutex_lock(&instances[instance_id].mutex);
    for (int i = 0; i < instances[instance_id].active_count; i++) {
        if (&instances[instance_id].pool[i] == struct_ptr) {
            instances[instance_id].pool[i] = instances[instance_id].pool[--instances[instance_id].active_count];
            pthread_cond_signal(&instances[instance_id].cond);
            break;
        }
    }
    pthread_mutex_unlock(&instances[instance_id].mutex);
}

