#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_CONNECTIONS 1024

typedef struct {
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ConnectionPool {
    NFAPI_CRC_INDICATION_PDU_T pool[MAX_CONNECTIONS];
    pthread_mutex_t lock;
    int size;
} ConnectionPool;

void initialize_pool(ConnectionPool *pool) {
    pthread_mutex_init(&pool->lock, NULL);
    pool->size = 0;
}

int add_connection(ConnectionPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->size >= MAX_CONNECTIONS) {
        pthread_mutex_unlock(&pool->lock);
        return -1; // Pool is full
    }
    NFAPI_CRC_INDICATION_PDU_T new_conn;
    new_conn.RNTI = rand() % 4096; // Random RNTI between 0 and 4095
    new_conn.CRCFLAG = rand() % 2;  // Random CRCFLAG (0 or 1)
    pool->pool[pool->size++] = new_conn;
    pthread_mutex_unlock(&pool->lock);
    return 0;
}

void remove_connection(ConnectionPool *pool, int index) {
    pthread_mutex_lock(&pool->lock);
    if (index < 0 || index >= pool->size) {
        pthread_mutex_unlock(&pool->lock);
        return; // Invalid index
    }
    for (; index < pool->size - 1; index++) {
        pool->pool[index] = pool->pool[index + 1];
    }
    pool->size--;
    pthread_mutex_unlock(&pool->lock);
}

void log_active_connections(ConnectionPool *pool) {
    pthread_mutex_lock(&pool->lock);
    printf("Active connections: %d\n", pool->size);
    pthread_mutex_unlock(&pool->lock);
}

int main() {
    ConnectionPool pool;
    initialize_pool(&pool);

    srand(time(NULL));

    // Simulate adding and removing connections
    for (int i = 0; i < MAX_CONNECTIONS * 2; i++) {
        if (add_connection(&pool) == -1) {
            printf("Failed to add connection\n");
        } else {
            log_active_connections(&pool);
        }
        // Randomly remove a connection with a certain probability
        if (rand() % 5 == 0 && pool.size > 0) {
            int index_to_remove = rand() % pool.size;
            remove_connection(&pool, index_to_remove);
            log_active_connections(&pool);
        }
    }

    return 0;
}
