    RRCState state;
    struct UEStatusUpdate *next;
} UEStatusUpdate;

typedef struct {
    UEStatusUpdate *head;
    pthread_mutex_t lock;
} UEStatusList;

void initUEStatusList(UEStatusList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void addOrUpdateUEStatus(UEStatusList *list, int ueId, long timestamp, RRCState state) {
    pthread_mutex_lock(&list->lock);

    UEStatusUpdate **current = &list->head;
    while (*current != NULL) {
        if ((*current)->ueId == ueId) {
            (*current)->timestamp = timestamp;
            (*current)->state = state;
            pthread_mutex_unlock(&list->lock);
            return;
        }
        current = &(*current)->next;
    }

    UEStatusUpdate *newEntry = (UEStatusUpdate *)malloc(sizeof(UEStatusUpdate));
    newEntry->ueId = ueId;
    newEntry->timestamp = timestamp;
    newEntry->state = state;
    newEntry->next = NULL;

    *current = newEntry;
    pthread_mutex_unlock(&list->lock);
}

RRCState getLatestUEStatus(UEStatusList *list, int ueId) {
    pthread_mutex_lock(&list->lock);

    UEStatusUpdate *current = list->head;
    RRCState latestState = RELEASED; // Default state if not found
    while (current != NULL) {
        if (current->ueId == ueId) {
            latestState = current->state;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return latestState;
}

void freeUEStatusList(UEStatusList *list) {
    pthread_mutex_lock(&list->lock);

    UEStatusUpdate *current = list->head;
    while (current != NULL) {
        UEStatusUpdate *next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
