#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MIN_RNTI 1
#define MAX_RNTI 65534

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t count;
    pthread_mutex_t mutex;
} PduList;

void initialize_pdu_list(PduList *list, size_t capacity) {
    list->pdus = malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->pdus) {
        perror("Failed to allocate memory for PDUs");
        list->count = 0;
        return;
    }
    list->count = capacity;
    pthread_mutex_init(&list->mutex, NULL);
}

void destroy_pdu_list(PduList *list) {
    free(list->pdus);
    pthread_mutex_destroy(&list->mutex);
}

int add_pdu_to_list(PduList *list, RX_UE_INFORMATION_TAG ue_info, RNTI rnti) {
    if (rnti < MIN_RNTI || rnti > MAX_RNTI) {
        fprintf(stderr, "Invalid RNTI value: %u\n", rnti);
        return -1;
    }

    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; ++i) {
        if (!list->pdus[i].ue_info.is_valid && !list->pdus[i].crc_indication.is_valid) {
            list->pdus[i].ue_info = ue_info;
            list->pdus[i].rnti = rnti;
            list->pdus[i].crc_indication.crcflag = rand() % 2; // Random CRC flag
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
    }

    pthread_mutex_unlock(&list->mutex);
    fprintf(stderr, "No available slot to add PDU\n");
    return -1;
}

void process_pdu_list(PduList *list) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->pdus[i].ue_info.is_valid && !list->pdus[i].crc_indication.is_valid) {
            // Process PDU
            printf("Processing PDU with RNTI: %u\n", list->pdus[i].rnti);
            // Reset for next use
            memset(&list->pdus[i], 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        }
    }
    pthread_mutex_unlock(&list->mutex);
}
