    pthread_mutex_lock(&queue->lock);
    if (queue->size == 0) {
        log_error("Attempted to enqueue into an empty queue");
        pthread_mutex_unlock(&queue->lock);
        return;
    }
    queue->reports[queue->size - 1] = report;
    queue->size--;
    pthread_mutex_unlock(&queue->lock);
    thread_safe_queue_enqueue(measurement_processing_queue, report);
}

