#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_MESSAGES 100000

typedef struct {
    int sender_id;
    int type;
    size_t payload_size;
    void* payload;
} Message;

typedef struct {
    Message messages[MAX_MESSAGES];
    int head;
    int tail;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} MessageQueue;

void init_queue(MessageQueue* queue) {
    queue->head = 0;
    queue->tail = 0;
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->not_full, NULL);
    pthread_cond_init(&queue->not_empty, NULL);
}

int enqueue(MessageQueue* queue, Message msg) {
    pthread_mutex_lock(&queue->lock);
    while ((queue->tail + 1) % MAX_MESSAGES == queue->head) {
        pthread_cond_wait(&queue->not_full, &queue->lock);
    }
    queue->messages[queue->tail] = msg;
    queue->tail = (queue->tail + 1) % MAX_MESSAGES;
    pthread_cond_signal(&queue->not_empty);
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

int dequeue(MessageQueue* queue, Message* msg) {
    pthread_mutex_lock(&queue->lock);
    while (queue->head == queue->tail) {
        pthread_cond_wait(&queue->not_empty, &queue->lock);
    }
    *msg = queue->messages[queue->head];
    queue->head = (queue->head + 1) % MAX_MESSAGES;
    pthread_cond_signal(&queue->not_full);
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

void* message_dispatcher(void* arg) {
    MessageQueue* queue = (MessageQueue*)arg;
    while (1) {
        Message msg;
        dequeue(queue, &msg);
        // Process the message
        printf("Received message from sender %d, type %d, payload size %zu\n", msg.sender_id, msg.type, msg.payload_size);
        // Free the message payload if dynamically allocated
        free(msg.payload);
    }
    return NULL;
}

int main() {
    MessageQueue queue;
    init_queue(&queue);

    pthread_t dispatcher_thread;
    pthread_create(&dispatcher_thread, NULL, message_dispatcher, &queue);

    // Example of enqueuing messages from multiple sources
    for (int i = 0; i < 1000; i++) {
        Message msg;
        msg.sender_id = i % 100;
        msg.type = i % 5;
        msg.payload_size = rand() % 1024 + 1;
        msg.payload = malloc(msg.payload_size);
        enqueue(&queue, msg);
    }

    pthread_join(dispatcher_thread, NULL);

    return 0;
}
