    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* insert(NFAPI_CRC_INDICATION_PDU_T** head, int RX_UE_INFORMATION_TAG, int RNTI, int CRCFLAG) {
    if (RNTI < 0 || RNTI > 65535) {
        printf("Error: Invalid RNTI value\n");
        return *head;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_node == NULL) {
        printf("Error: Memory allocation failed\n");
        return *head;
    }

    new_node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->RNTI = RNTI;
    new_node->CRCFLAG = CRCFLAG;
    new_node->next = *head;

    while (*head != NULL) {
        if ((*head)->RNTI == RNTI) {
            printf("Error: Duplicate RNTI value\n");
            free(new_node);
            return *head;
        }
        head = &(*head)->next;
    }

    *head = new_node;
    return new_node;
}

void delete(NFAPI_CRC_INDICATION_PDU_T** head, int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T* current = *head;
    NFAPI_CRC_INDICATION_PDU_T* prev = NULL;

    while (current != NULL && current->RNTI != RNTI) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        printf("Error: RNTI not found\n");
        return;
    }

    if (prev == NULL) {
        *head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
}

void traverse(NFAPI_CRC_INDICATION_PDU_T* head) {
    while (head != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n", 
               head->RX_UE_INFORMATION_TAG, head->RNTI, head->CRCFLAG);
        head = head->next;
    }
}

void free_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* temp = current;
        current = current->next;
        free(temp);
    }
}
