LTE_PHY_Statistics *lte_phy_stats[MAX_UE_ID] = {NULL};
pthread_mutex_t stats_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t stats_updated = PTHREAD_COND_INITIALIZER;

void init_lte_phy_stats() {
    for (int i = 0; i < MAX_UE_ID; i++) {
        lte_phy_stats[i] = NULL;
    }
}

LTE_PHY_Statistics* get_lte_phy_stat(int UE_ID) {
    pthread_mutex_lock(&stats_lock);
    if (lte_phy_stats[UE_ID] == NULL) {
        lte_phy_stats[UE_ID] = (LTE_PHY_Statistics*)malloc(sizeof(LTE_PHY_Statistics));
        memset(lte_phy_stats[UE_ID], 0, sizeof(LTE_PHY_Statistics));
    }
    pthread_mutex_unlock(&stats_lock);
    return lte_phy_stats[UE_ID];
}

void update_lte_phy_stat(int UE_ID, double EVM[], double RSSI[], double SNR[]) {
    LTE_PHY_Statistics *stat = get_lte_phy_stat(UE_ID);
    pthread_mutex_lock(&stats_lock);
    memcpy(stat->EVM, EVM, sizeof(double) * MAX_MEASUREMENT_INTERVALS);
    memcpy(stat->RSSI, RSSI, sizeof(double) * MAX_MEASUREMENT_INTERVALS);
    memcpy(stat->SNR, SNR, sizeof(double) * MAX_MEASUREMENT_INTERVALS);
    pthread_cond_signal(&stats_updated);
    pthread_mutex_unlock(&stats_lock);
}

void aggregate_lte_phy_stats() {
    pthread_mutex_lock(&stats_lock);
    // Perform aggregation logic here
    pthread_mutex_unlock(&stats_lock);
}

