['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} CRC_List;

CRC_List* create_crc_list(size_t initial_capacity) {
    CRC_List *list = malloc(sizeof(CRC_List));
    if (!list) {
        perror("Failed to allocate memory for CRC List");
        return NULL;
    }

    list->array = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->array) {
        free(list);
        perror("Failed to allocate memory for CRC Array");
        return NULL;
    }

    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void destroy_crc_list(CRC_List *list) {
    if (!list) {
        return;
    }
    free(list->array);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_to_crc_list(CRC_List *list, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&list->mutex);

    if (list->size == list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        void *new_array = realloc(list->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&list->mutex);
            perror("Failed to reallocate memory for CRC Array");
            return -1;
        }
        list->array = new_array;
        list->capacity = new_capacity;
    }

    list->array[list->size++] = item;
    pthread_mutex_unlock(&list->mutex);

    return 0;
}

void populate_crc_list(CRC_List *list, size_t N) {
    srand(time(NULL));

    for (size_t i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T item = {i, rand() % 1024};
        if (add_to_crc_list(list, item)) {
            fprintf(stderr, "Failed to add item to CRC list\n");
        }
    }
}

int main() {
    size_t N = 1000;
    CRC_List *list = create_crc_list(N);
    if (!list) {
        return EXIT_FAILURE;
    }

    populate_crc_list(list, N);

    // Simulate processing
    for (size_t i = 0; i < list->size; ++i) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d\n", list->array[i].RX_UE_INFORMATION_TAG, list->array[i].RNTI);
    }

    destroy_crc_list(list);
    return EXIT_SUCCESS;
}
```

