    Packet* pool;
    size_t size;
    size_t used;
} MemoryPool;

// Define structure to manage packet list with concurrency support
typedef struct {
    Packet** packets;
    size_t count;
    pthread_mutex_t lock;
    MemoryPool pool;
} PacketList;

// Function to initialize a new packet list
void init_packet_list(PacketList* list, size_t initial_size) {
    list->packets = (Packet**)malloc(initial_size * sizeof(Packet*));
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    init_memory_pool(&list->pool, initial_size);
}

// Function to create a new packet and add it to the list
int create_packet(PacketList* list, unsigned int header, const char* payload, size_t payload_size) {
    Packet* packet = (Packet*)memory_pool_alloc(&list->pool);
    if (!packet) return -1; // Memory allocation failed

    packet->header = header;
    memcpy(packet->payload, payload, payload_size);
    packet->payload_size = payload_size;
    packet->transmission_status = 0;

    pthread_mutex_lock(&list->lock);
    list->packets[list->count++] = packet;
    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

