void prioritize_packets(PacketList* list, int priority_level) {
    // Implement prioritization logic here
}

// Function to free resources used by the packet list
void destroy_packet_list(PacketList* list) {
    for (size_t i = 0; i < list->count; ++i) {
        memory_pool_free(&list->pool, list->packets[i]);
    }
    pthread_mutex_destroy(&list->lock);
    free(list->packets);
}

// Example usage
