typedef struct NFAPI_CRC_INDICATION_PDU_T {
    char RX_UE_INFORMATION_TAG[20];
    int RNTI;
    struct {
        unsigned char CRCFLAG;
        unsigned char hash[MD5_DIGEST_LENGTH];
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    Node* tail;
} LinkedList;

void initializeNfadPduList(LinkedList* list, int count) {
    for (int i = 0; i < count; i++) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }

        // Initialize data
        snprintf(newNode->data.RX_UE_INFORMATION_TAG, sizeof(newNode->data.RX_UE_INFORMATION_TAG), "Tag%d", i);
        newNode->data.RNTI = i % 10; // Simulate RNTI values

        // Compute MD5 hash
        unsigned char hash[MD5_DIGEST_LENGTH];
        MD5((unsigned char*)newNode->data.RX_UE_INFORMATION_TAG, strlen(newNode->data.RX_UE_INFORMATION_TAG), hash);
        memcpy(newNode->data.CRC_INDICATION_REL8_TAG.hash, hash, sizeof(hash));

        // Set random CRCFLAG
        newNode->data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        // Insert node into list
        if (!list->head) {
            list->head = list->tail = newNode;
        } else {
            list->tail->next = newNode;
            list->tail = newNode;
        }
    }
}

unsigned char* computeMD5Hash(const char* input, size_t length) {
    unsigned char hash[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)input, length, hash);

    unsigned char* result = (unsigned char*)malloc(MD5_DIGEST_LENGTH);
    if (!result) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    memcpy(result, hash, MD5_DIGEST_LENGTH);
    return result;
}

// Example usage
int main() {
    LinkedList list = {NULL, NULL};
    initializeNfadPduList(&list, 10);

    // Clean up
    Node* current = list.head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    return 0;
}
```

