#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

#define MAX_CAPACITY 1000

typedef struct {
    uint64_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} CRC_LIST_T;

int init_crc_list(CRC_LIST_T *list, size_t initial_capacity) {
    if (initial_capacity > MAX_CAPACITY) return -1; // Exceeds maximum capacity
    list->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) return -2; // Memory allocation failed
    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->mutex, NULL);
    return 0;
}

int add_crc_indication(CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->mutex);
    if (list->size == list->capacity) {
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, 2 * list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&list->mutex);
            return -3; // Memory reallocation failed
        }
        list->data = new_data;
        list->capacity *= 2;
    }
    list->data[list->size++] = pdu;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void destroy_crc_list(CRC_LIST_T *list) {
    pthread_mutex_lock(&list->mutex);
    free(list->data);
    pthread_mutex_destroy(&list->mutex);
}
```

