NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_array(int N, float crc_threshold) {
    static pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;
    static NFAPI_CRC_INDICATION_PDU_T* memory_pool = NULL;
    static size_t pool_size = 0;

    if (N > pool_size) {
