        if (N > pool_size) {
            free(memory_pool);
            memory_pool = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pool_size = N;
        }
        pthread_mutex_unlock(&pool_lock);
    }

    NFAPI_CRC_INDICATION_PDU_T* array = memory_pool;

    for (int i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Example tag generation
        array[i].RNTI = rand() % 256; // Example RNTI generation

        pthread_mutex_lock(&pool_lock);
        srand(time(NULL)); // Seed for random number generation
        if ((float)rand() / RAND_MAX < crc_threshold) {
            array[i].CRCFLAG = 1;
        } else {
            array[i].CRCFLAG = 0;
        }
        pthread_mutex_unlock(&pool_lock);
    }

    return array;
}
