#define MAX_PACKETS 10000
#define DEFAULT_WINDOW_SIZE 60 // seconds
#define DEFAULT_CONGESTION_RETRIEVAL_INTERVAL 30 // seconds

typedef struct {
    int id;
    char src_ip[16];
    size_t size;
    time_t timestamp;
} Packet;

typedef struct {
    Packet packets[MAX_PACKETS];
    int count;
    int window_size;
    double congestion_level;
    time_t last_congestion_retrieval_time;
} PacketProcessor;

void init_processor(PacketProcessor *processor, int window_size) {
    processor->count = 0;
    processor->window_size = window_size;
    processor->congestion_level = 0.5; // Default congestion level
    processor->last_congestion_retrieval_time = time(NULL);
}

int process_packet(PacketProcessor *processor, Packet packet) {
    if (time(NULL) - packet.timestamp > processor->window_size) {
        return -1; // Packet is out of window
    }

    // Add packet to sliding window
    processor->packets[processor->count++] = packet;

    // Update congestion level from external source
    time_t current_time = time(NULL);
    if (current_time - processor->last_congestion_retrieval_time > DEFAULT_CONGESTION_RETRIEVAL_INTERVAL) {
        // Simulate fetching real-time congestion level from external data source
        processor->congestion_level = fetch_congestion_level();
        processor->last_congestion_retrieval_time = current_time;
    }

    // Calculate packet priority score
    double priority_score = packet.size / 1024.0 * (1 - processor->congestion_level);

    // Return highest priority score and corresponding packet details
    return priority_score;
}

double fetch_congestion_level() {
    // Simulate fetching congestion level from external data source
    return 0.6; // Example congestion level
}

int main() {
    PacketProcessor processor;
    init_processor(&processor, DEFAULT_WINDOW_SIZE);

    Packet packet1 = {1, "192.168.1.1", 1500, time(NULL)};
    Packet packet2 = {2, "192.168.1.2", 2048, time(NULL)};

    int priority_score1 = process_packet(&processor, packet1);
    int priority_score2 = process_packet(&processor, packet2);

    printf("Packet 1 Priority Score: %d\n", priority_score1);
    printf("Packet 2 Priority Score: %d\n", priority_score2);

    return 0;
}
