    if (index < 0 || index >= active_connections) {
        pthread_mutex_unlock(&pool_mutex);
        fprintf(stderr, "Error: Invalid connection index\n");
        return -1;
    }
    free(connection_pool[index]);
    for (int i = index; i < active_connections - 1; i++) {
        connection_pool[i] = connection_pool[i + 1];
    }
    active_connections--;
    printf("Connection closed. Active connections: %d\n", active_connections);
    pthread_mutex_unlock(&pool_mutex);
    return 0;
}

