void initialize_crc_pool(int P) {
    if (P > MAX_CONNECTIONS) return;
    pthread_mutex_init(&pool_mutex, NULL);
    for (int i = 0; i < P; i++) {
        crc_pool[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
