void destroy_crc_pool() {
    pthread_mutex_lock(&pool_mutex);
    for (int i = 0; i < pool_size; i++) {
        free(crc_pool[i]);
    }
    pthread_mutex_unlock(&pool_mutex);
    pthread_mutex_destroy(&pool_mutex);
