    pthread_mutex_init(&crcList->lock, NULL);
    crcList->count = 0;
    return 0;
}

void destroyCRCList(CRCList *crcList) {
    pthread_mutex_lock(&crcList->lock);
    for (size_t i = 0; i < crcList->count; ++i) {
        free(crcList->list[i]);
    }
    crcList->count = 0;
    pthread_mutex_unlock(&crcList->lock);
    pthread_mutex_destroy(&crcList->lock);
}

int addCRCIndication(CRCList *crcList, unsigned short RNTI, int bitmask) {
    pthread_mutex_lock(&crcList->lock);
    if (crcList->count >= MAX_LIST_SIZE) {
        printf("List size limit reached.\n");
        pthread_mutex_unlock(&crcList->lock);
        return -1;
    }

    for (size_t i = 0; i < crcList->count; ++i) {
        if (crcList->list[i]->RNTI == RNTI) {
            printf("Duplicate RNTI detected.\n");
            pthread_mutex_unlock(&crcList->lock);
            return -1;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T *newPdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newPdu) {
        printf("Memory allocation failed.\n");
        pthread_mutex_unlock(&crcList->lock);
        return -1;
    }

    newPdu->RNTI = RNTI;
    newPdu->CRCFLAG = (rand() & bitmask) % 2; // Randomly set CRCFLAG based on bitmask
    crcList->list[crcList->count++] = newPdu;

    pthread_mutex_unlock(&crcList->lock);
    return 0;
}

void logCRCList(CRCList *crcList) {
    printf("Current list size: %zu\n", crcList->count);
    for (size_t i = 0; i < crcList->count; ++i) {
        printf("RNTI: %hu, CRCFLAG: %d\n", crcList->list[i]->RNTI, crcList->list[i]->CRCFLAG);
    }
}

int main() {
    srand(time(NULL)); // Seed for random number generation
    CRCList crcList;
    initializeCRCList(&crcList);

    int bitmask = 0b110; // Example bitmask

    for (int i = 0; i < 5; ++i) { // Add 5 elements to the list for demonstration
        if (addCRCIndication(&crcList, i * 2 + 1, bitmask) == -1) {
            printf("Failed to add element %d\n", i);
            break;
        }
    }

    logCRCList(&crcList);

    destroyCRCList(&crcList);
    return 0;
}
```

