#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
} DynamicList;

DynamicList* create_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    return list;
}

void destroy_list(DynamicList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void add_to_list(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    pthread_mutex_unlock(&list->lock);
}

void prune_list(DynamicList* list, size_t max_size) {
    pthread_mutex_lock(&list->lock);
    if (list->count > max_size) {
        Node* current = list->head;
        Node* prev = NULL;
        while (current != NULL && list->count > max_size) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            current = prev->next;
            list->count--;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void* producer_thread(void* arg) {
    DynamicList* list = (DynamicList*)arg;
    srand(time(NULL));
    for (size_t i = 0; i < 1000; ++i) {
        NFAPI_CRC_INDICATION_PDU_T data;
        // Populate data with valid values
        add_to_list(list, data);
    }
    return NULL;
}

int main() {
    DynamicList* list = create_list();
    pthread_t producer;

    if (pthread_create(&producer, NULL, producer_thread, list) != 0) {
        perror("Failed to create thread");
        destroy_list(list);
        return 1;
    }

    pthread_join(producer, NULL);

    // Periodically prune the list
    for (size_t i = 0; i < 5; ++i) {
        prune_list(list, 100); // Prune to a maximum size of 100
        sleep(60); // Sleep for 60 seconds before pruning again
    }

    destroy_list(list);
    return 0;
}
