#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_RRC_UE_CONTEXT_T {
    int CELL_ID;
    int RNTI;
    // Other fields...
} NFAPI_RRC_UE_CONTEXT_T;

typedef struct HashNode {
    NFAPI_RRC_UE_CONTEXT_T data;
    struct HashNode* next;
} HashNode;

typedef struct HashTable {
    HashNode** buckets;
    size_t size;
    size_t count;
    float loadFactorThreshold;
    pthread_mutex_t mutex;
} HashTable;

HashTable* createHashTable(size_t initialSize, float loadFactorThreshold) {
    HashTable* table = malloc(sizeof(HashTable));
    table->buckets = calloc(initialSize, sizeof(HashNode*));
    table->size = initialSize;
    table->count = 0;
    table->loadFactorThreshold = loadFactorThreshold;
    pthread_mutex_init(&table->mutex, NULL);
    return table;
}

void destroyHashTable(HashTable* table) {
    for (size_t i = 0; i < table->size; ++i) {
        HashNode* node = table->buckets[i];
        while (node) {
            HashNode* next = node->next;
            free(node);
            node = next;
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->mutex);
    free(table);
}

size_t hashFunction(HashTable* table, int key) {
    return abs(key) % table->size;
}

int insert(HashTable* table, NFAPI_RRC_UE_CONTEXT_T data) {
    pthread_mutex_lock(&table->mutex);
    size_t index = hashFunction(table, data.CELL_ID);
    HashNode* newNode = malloc(sizeof(HashNode));
    if (!newNode) {
        pthread_mutex_unlock(&table->mutex);
        return -1;
    }
    newNode->data = data;
    newNode->next = table->buckets[index];
    table->buckets[index] = newNode;
    ++table->count;

    if (table->count / (float)table->size > table->loadFactorThreshold) {
        // Resize the hash table
        size_t newSize = table->size * 2;
        HashNode** newBuckets = calloc(newSize, sizeof(HashNode*));
        for (size_t i = 0; i < table->size; ++i) {
            HashNode* node = table->buckets[i];
            while (node) {
                HashNode* next = node->next;
                size_t newIndex = hashFunction(table, node->data.CELL_ID);
                node->next = newBuckets[newIndex];
                newBuckets[newIndex] = node;
                node = next;
            }
        }
        free(table->buckets);
        table->buckets = newBuckets;
        table->size = newSize;
    }

    pthread_mutex_unlock(&table->mutex);
    return 0;
}

