typedef struct LTE_PHY_CHANNEL_STATE {
    int RB_ID;
    int SFN;
    int TIME_SLOT;
    char CHANNEL_TYPE[32];
} LTE_PHY_CHANNEL_STATE;

typedef struct ChannelList {
    LTE_PHY_CHANNEL_STATE *list[MAX_LIST_SIZE];
    int count;
    pthread_mutex_t lock;
} ChannelList;

void init_channel_list(ChannelList *cl) {
    cl->count = 0;
    pthread_mutex_init(&cl->lock, NULL);
}

int add_channel_state(ChannelList *cl, LTE_PHY_CHANNEL_STATE *state, int start_sfn, int time_offset, const char *channel_type_map[]) {
    pthread_mutex_lock(&cl->lock);
    if (cl->count >= MAX_LIST_SIZE) {
        pthread_mutex_unlock(&cl->lock);
        return -1;
    }

    for (int i = 0; i < cl->count; i++) {
        if (cl->list[i]->RB_ID == state->RB_ID) {
            pthread_mutex_unlock(&cl->lock);
            return -2;
        }
    }

    state->SFN = start_sfn + time_offset / 10; // Assuming time offset is in milliseconds
    state->TIME_SLOT = time_offset % 10;      // Assuming time slot range is 0-9
    strncpy(state->CHANNEL_TYPE, channel_type_map[state->RB_ID], sizeof(state->CHANNEL_TYPE) - 1);
    state->CHANNEL_TYPE[sizeof(state->CHANNEL_TYPE) - 1] = '\0';

    cl->list[cl->count++] = state;
    pthread_mutex_unlock(&cl->lock);
    return cl->count;
}

void free_channel_list(ChannelList *cl) {
    for (int i = 0; i < cl->count; i++) {
        free(cl->list[i]);
    }
    pthread_mutex_destroy(&cl->lock);
}
