#include <stdlib.h>
#include <string.h>
#include <time.h>

#define NFAPI_CRC_INDICATION_PDU_T_SIZE sizeof(NFAPI_CRC_INDICATION_PDU_T)
#define MAX_RNTI 65535

typedef struct {
    int RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPoolEntry {
    void* data;
    struct MemoryPoolEntry* next;
} MemoryPoolEntry;

typedef struct {
    MemoryPoolEntry** pool;
    size_t size;
    size_t capacity;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_capacity, size_t element_size) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->pool = (MemoryPoolEntry**)calloc(initial_capacity, sizeof(MemoryPoolEntry*));
    if (!pool->pool) {
        free(pool);
        return NULL;
    }

    pool->size = 0;
    pool->capacity = initial_capacity;

    for (size_t i = 0; i < initial_capacity; ++i) {
        pool->pool[i] = (MemoryPoolEntry*)malloc(sizeof(MemoryPoolEntry));
        if (!pool->pool[i]) {
            // Free previously allocated entries
            for (size_t j = 0; j < i; ++j) {
                free(pool->pool[j]);
            }
            free(pool->pool);
            free(pool);
            return NULL;
        }
        pool->pool[i]->data = malloc(element_size);
        if (!pool->pool[i]->data) {
            // Free previously allocated entries and data
            for (size_t j = 0; j <= i; ++j) {
                free(((MemoryPoolEntry*)pool->pool[j])->data);
                free(pool->pool[j]);
            }
            free(pool->pool);
            free(pool);
            return NULL;
        }
        pool->pool[i]->next = NULL;
    }

    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    for (size_t i = 0; i < pool->capacity; ++i) {
        free(((MemoryPoolEntry*)pool->pool[i])->data);
        free(pool->pool[i]);
    }
    free(pool->pool);
    free(pool);
}

void* allocate_from_pool(MemoryPool* pool) {
    if (pool->size >= pool->capacity) return NULL;

    MemoryPoolEntry* entry = pool->pool[pool->size++];
    return entry->data;
}

void deallocate_to_pool(MemoryPool* pool, void* ptr) {
    for (size_t i = 0; i < pool->size; ++i) {
        if (((MemoryPoolEntry*)pool->pool[i])->data == ptr) {
            ((MemoryPoolEntry*)pool->pool[i])->next = NULL;
            --pool->size;
            break;
        }
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_pdu_pool(size_t N, MemoryPool** pool) {
    *pool = create_memory_pool(N, NFAPI_CRC_INDICATION_PDU_T_SIZE);
    if (!(*pool)) return NULL;

    for (size_t i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)allocate_from_pool(*pool);
        if (!pdu) {
            // Free previously allocated PDU structures
            while ((*pool)->size > i) {
                deallocate_to_pool(*pool, ((MemoryPoolEntry*)(*pool)->pool[--(*pool)->size])->data);
            }
            destroy_memory_pool(*pool);
            return NULL;
        }

        pdu->RX_UE_INFORMATION_TAG = rand();
        if (pdu->RX_UE_INFORMATION_TAG == 0) {
            // Reallocate with a non-zero tag
            deallocate_to_pool(*pool, pdu);
            --i;
            continue;
        }

        pdu->RNTI = rand() % (MAX_RNTI + 1);
        pdu->CRCFLAG = rand() % 256;

        if (i == N - 1) {
            (*pool)->pool[(*pool)->size - 1]->next = NULL; // Ensure last entry is not linked
        }
    }

    return (NFAPI_CRC_INDICATION_PDU_T*)((*pool)->pool);
}

void free_crc_pdu_pool(NFAPI_CRC_INDICATION_PDU_T* pdu_array, MemoryPool* pool) {
    for (size_t i = 0; i < pool->size; ++i) {
        deallocate_to_pool(pool, ((MemoryPoolEntry*)(pool->pool[i]))->data);
    }
    destroy_memory_pool(pool);
}

void sort_by_rnti(NFAPI_CRC_INDICATION_PDU_T* pdu_array, size_t N) {
    qsort(pdu_array, N, sizeof(NFAPI_CRC_INDICATION_PDU_T), 
          [](const void* a, const void* b) {
              return ((NFAPI_CRC_INDICATION_PDU_T*)a)->RNTI - ((NFAPI_CRC_INDICATION_PDU_T*)b)->RNTI;
          });
}

// Example usage
int main() {
    srand(time(NULL));
    MemoryPool* pool = NULL;
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = create_crc_pdu_pool(10, &pool);
    if (pdu_array) {
        sort_by_rnti(pdu_array, 10);
        // Use the pdu_array
        free_crc_pdu_pool(pdu_array, pool);
    }
    return 0;
}
