using System;
using System.Collections.Concurrent;
using System.Threading;

public class RandomNumberGenerator
{
    private readonly ConcurrentDictionary<(int, int, bool, bool), Random> _randomCache = new();
    private readonly object _lockObject = new();

    public int Min { get; set; }
    public int Max { get; set; }
    public bool IsInclusiveMin { get; set; }
    public bool IsInclusiveMax { get; set; }

    public RandomNumberGenerator(int min, int max, bool inclusiveMin = true, bool inclusiveMax = true)
    {
        Min = min;
        Max = max;
        IsInclusiveMin = inclusiveMin;
        IsInclusiveMax = inclusiveMax;
    }

    public int GenerateRandomInt(int seed = 0)
    {
        var key = (Min, Max, IsInclusiveMin, IsInclusiveMax);
        Random random;

        if (!_randomCache.TryGetValue(key, out random))
        {
            lock (_lockObject)
            {
                if (!_randomCache.TryGetValue(key, out random))
                {
                    random = new Random(seed + GetHash(key));
                    _randomCache[key] = random;
                }
            }
        }

        int range = Max - Min + (IsInclusiveMax ? 1 : 0) - (IsInclusiveMin ? 0 : 1);
        return Min + random.Next(0, range);
    }

    public double GenerateRandomFloat(int seed = 0)
    {
        var key = (Min, Max, IsInclusiveMin, IsInclusiveMax);
        Random random;

        if (!_randomCache.TryGetValue(key, out random))
        {
            lock (_lockObject)
            {
                if (!_randomCache.TryGetValue(key, out random))
                {
                    random = new Random(seed + GetHash(key));
                    _randomCache[key] = random;
                }
            }
        }

        double range = Max - Min + (IsInclusiveMax ? 1 : 0) - (IsInclusiveMin ? 0 : 1);
        return Min + range * random.NextDouble();
    }

    public override string ToString()
    {
        return $"Range: [{Min}, {Max}], Inclusive Min: {IsInclusiveMin}, Inclusive Max: {IsInclusiveMax}";
    }

    private int GetHash((int min, int max, bool inclusiveMin, bool inclusiveMax) key)
    {
        unchecked
        {
            int hash = 17;
            hash = hash * 23 + key.min.GetHashCode();
            hash = hash * 23 + key.max.GetHashCode();
            hash = hash * 23 + key.inclusiveMin.GetHashCode();
            hash = hash * 23 + key.inclusiveMax.GetHashCode();
            return hash;
        }
    }
}
