#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ITERATIONS 10000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct AllocationNode {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct AllocationNode *next;
} AllocationNode;

typedef struct MemoryManager {
    AllocationNode *head;
    pthread_mutex_t lock;
} MemoryManager;

void initializeMemoryManager(MemoryManager *manager) {
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
}

void freeAllocation(AllocationNode *node) {
    free(node->data);
    free(node);
}

void addToManager(MemoryManager *manager, NFAPI_CRC_INDICATION_PDU_T *data) {
    AllocationNode *newNode = (AllocationNode *)malloc(sizeof(AllocationNode));
    newNode->data = data;
    newNode->next = NULL;

    pthread_mutex_lock(&manager->lock);
    if (manager->head == NULL) {
        manager->head = newNode;
    } else {
        AllocationNode *current = manager->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
    pthread_mutex_unlock(&manager->lock);
}

void removeFromManager(MemoryManager *manager, AllocationNode *node) {
    pthread_mutex_lock(&manager->lock);
    if (manager->head == node) {
        manager->head = node->next;
    } else {
        AllocationNode *current = manager->head;
        while (current->next != node) {
            current = current->next;
        }
        current->next = node->next;
    }
    pthread_mutex_unlock(&manager->lock);
    freeAllocation(node);
}

void logMemoryUsage(MemoryManager *manager) {
    AllocationNode *current = manager->head;
    int count = 0;

    while (current != NULL) {
        count++;
        current = current->next;
    }

    printf("Allocated structures: %d\n", count);
}

int allocateAndInitializeData(MemoryManager *manager, unsigned int N) {
    if (N > MAX_ITERATIONS) {
        return -1; // Error: Exceeds maximum allowed iterations
    }

    NFAPI_CRC_INDICATION_PDU_T *data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (data == NULL) {
        return -2; // Memory allocation failed
    }

    for (unsigned int i = 0; i < N; i++) {
        data[i].RX_UE_INFORMATION_TAG = (i % 1000) + 1; // Ensure non-zero value
        data[i].RNTI = (i % 65535) + 1; // Valid RNTI range
        data[i].CRCFLAG = (rand() % 2); // Randomly set CRCFLAG
    }

    addToManager(manager, data);
    return 0; // Success
}

void cleanupMemory(MemoryManager *manager) {
    AllocationNode *current = manager->head;
    while (current != NULL) {
        AllocationNode *next = current->next;
        freeAllocation(current);
        current = next;
    }
    pthread_mutex_destroy(&manager->lock);
}
