#define MAX_PACKETS 1024

typedef struct {
    uint8_t header[16];
    size_t payload_length;
    time_t timestamp;
} NetworkPacket;

NetworkPacket* initialize_packets(size_t *packet_count, size_t max_memory) {
    size_t packet_size = sizeof(NetworkPacket);
    size_t total_size = packet_size * MAX_PACKETS;

    if (total_size > max_memory) {
        *packet_count = max_memory / packet_size;
        total_size = *packet_count * packet_size;
    } else {
        *packet_count = MAX_PACKETS;
    }

    NetworkPacket* packets = malloc(total_size);
    if (!packets) {
        return NULL; // Memory allocation failed
    }

    time_t current_time = time(NULL);

    for (size_t i = 0; i < *packet_count; ++i) {
        memcpy(packets[i].header, "NetworkPacket", 16); // Example header initialization
        packets[i].payload_length = rand() % 1024 + 1;
        packets[i].timestamp = current_time + i; // Avoiding duplicate timestamps for simplicity

        if (i > 0 && packets[i].timestamp == packets[i - 1].timestamp) {
            packets[i].timestamp += 1; // Adjust timestamp to avoid duplicates
        }
    }

    return packets;
}

void free_packets(NetworkPacket* packets, size_t packet_count) {
    free(packets);
}
