#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

#define MAX_ENTRIES 1000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t mutex;
} LinkedList;

LinkedList* createLinkedList() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (list) {
        list->head = NULL;
        pthread_mutex_init(&list->mutex, NULL);
    }
    return list;
}

bool insertEntry(LinkedList* list, int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&list->mutex);
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&list->mutex);
        return false; // Memory allocation failure
    }

    newNode->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newNode->data.RNTI = RNTI;

    do {
        newNode->data.CRCFLAG = rand() % 2;
        if (list->head) {
            Node* current = list->head;
            while (current->next && current->next->data.CRCFLAG == newNode->data.CRCFLAG) {
                newNode->data.CRCFLAG = rand() % 2;
            }
        } else {
            break; // List is empty, CRCFLAG can be anything
        }
    } while (true);

    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->mutex);
    return true;
}

bool areRNTIsUnique(LinkedList* list) {
    bool* rntiMap = (bool*)calloc(MAX_ENTRIES, sizeof(bool));
    if (!rntiMap) return false; // Memory allocation failure

    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current) {
        int rnti = current->data.RNTI;
        if (rnti >= 0 && rnti < MAX_ENTRIES) {
            if (rntiMap[rnti]) {
                pthread_mutex_unlock(&list->mutex);
                free(rntiMap);
                return false; // Duplicate RNTI found
            }
            rntiMap[rnti] = true;
        } else {
            pthread_mutex_unlock(&list->mutex);
            free(rntiMap);
            return false; // Invalid RNTI value
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    free(rntiMap);
    return true;
}

LinkedList* populateList(int numEntries) {
    if (numEntries > MAX_ENTRIES) return NULL;

    LinkedList* list = createLinkedList();
    if (!list) return NULL; // Memory allocation failure

    for (int i = 0; i < numEntries; ++i) {
        int RX_UE_INFORMATION_TAG = rand() % 100;
        int RNTI = rand() % MAX_ENTRIES;
        if (!insertEntry(list, RX_UE_INFORMATION_TAG, RNTI)) {
            freeLinkedList(list);
            return NULL; // Insertion failed
        }
    }

    if (!areRNTIsUnique(list)) {
        freeLinkedList(list);
        return NULL; // Duplicate RNTIs found
    }

    return list;
}

void freeLinkedList(LinkedList* list) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}
