typedef struct MAC_PDU_T {
    TX_PDU_HEADER *pdu_header;
    SAPI sapi;
    BSR_REL16_TAG bsr_tag;
    struct MAC_PDU_T *next;
} MAC_PDU_T;

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

bool is_sapi_unique(MAC_PDU_T **head, SAPI sapi) {
    MAC_PDU_T *current = *head;
    while (current != NULL) {
        if (current->sapi == sapi) {
            return false;
        }
        current = current->next;
    }
    return true;
}

MAC_PDU_T* populate_mac_pdu_list(int max_entries, TX_PDU_HEADER *(*get_pdu_header)(), SAPI (*get_sapi)()) {
    MAC_PDU_T *head = NULL, **tail = &head;
    int count = 0;

    while (count < max_entries) {
        if (pthread_mutex_lock(&list_mutex) != 0) {
            perror("Mutex lock failed");
            exit(EXIT_FAILURE);
        }

        if (*tail == NULL) {
            *tail = malloc(sizeof(MAC_PDU_T));
            if (*tail == NULL) {
                fprintf(stderr, "Memory allocation failed\n");
                pthread_mutex_unlock(&list_mutex);
                continue;
            }
            (*tail)->next = NULL;
        } else {
            (*tail)->next = malloc(sizeof(MAC_PDU_T));
            if ((*tail)->next == NULL) {
                fprintf(stderr, "Memory allocation failed\n");
                free(*tail);
                *tail = NULL;
                pthread_mutex_unlock(&list_mutex);
                continue;
            }
            (*tail)->next->next = NULL;
            *tail = (*tail)->next;
        }

        if (pthread_mutex_unlock(&list_mutex) != 0) {
            perror("Mutex unlock failed");
            exit(EXIT_FAILURE);
        }

        (*tail)->pdu_header = get_pdu_header();
        (*tail)->sapi = get_sapi();

        BSR_REL16_TAG bsr_tag;
        bsr_tag.BSR_COUNT = rand() % 10 + 1; // Example range
        bsr_tag.BSR_UNIT_SIZE = rand() % 1024 + 1; // Example range

        (*tail)->bsr_tag = bsr_tag;

        if (!is_sapi_unique(&head, (*tail)->sapi)) {
            fprintf(stderr, "SAPI not unique\n");
            free(*tail);
            *tail = NULL;
            continue;
        }

        count++;
    }

    return head;
}

// Example usage
TX_PDU_HEADER* get_pdu_header() {
    // Implement this function to return a valid TX_PDU_HEADER
    static TX_PDU_HEADER header;
    return &header;
}

SAPI get_sapi() {
    // Implement this function to return a unique SAPI
    static int sapi_counter = 0;
    return sapi_counter++;
}
