void serialize_list(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    pthread_mutex_lock(&mutex);
    fwrite(list, sizeof(NFAPI_CRC_INDICATION_PDU_T), count, file);
    pthread_mutex_unlock(&mutex);

    fclose(file);
}

void deserialize_list(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }

    pthread_mutex_lock(&mutex);
    count = fread(list, sizeof(NFAPI_CRC_INDICATION_PDU_T), MAX_ENTRIES, file);
    pthread_mutex_unlock(&mutex);

    fclose(file);
}

void check_integrity() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < count; i++) {
        for (int j = i + 1; j < count; j++) {
            if (list[i]->RNTI == list[j]->RNTI) {
