} MemoryManager;

MAC_PDU* create_mac_pdu(MemoryManager* manager, size_t payload_size) {
    pthread_mutex_lock(&manager->lock);
    if (manager->used_memory + sizeof(MAC_PDU) + payload_size * sizeof(MACSDU) > manager->pool_size) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&manager->lock);
        return NULL;
    }

    MAC_PDU* pdu = (MAC_PDU*)manager->memory_pool + manager->used_memory / sizeof(MAC_PDU);
    manager->used_memory += sizeof(MAC_PDU);

    pdu->header = (MAC_HEADER){}; // Initialize header
    pdu->payload = (MAC_PAYLOAD){}; // Initialize payload

    pdu->sdus = (MACSDU*)((char*)manager->memory_pool + manager->used_memory);
    manager->used_memory += payload_size * sizeof(MACSDU);

    pdu->num_sdus = payload_size;
    pthread_mutex_unlock(&manager->lock);

    return pdu;
}

void destroy_mac_pdu(MemoryManager* manager, MAC_PDU* pdu) {
    pthread_mutex_lock(&manager->lock);
    // Mark the memory as free (for simplicity, not actually freeing it here)
    manager->used_memory -= sizeof(MAC_PDU) + pdu->num_sdus * sizeof(MACSDU);
    pthread_mutex_unlock(&manager->lock);
}

