    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock == -1) {
        perror("Failed to create socket");
        free(indications);
        return NULL;
    }

    // Resolve DNS asynchronously using getaddrinfo
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_INET; // Use IPv4
    hints.ai_socktype = SOCK_DGRAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        close(sock);
        free(indications);
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        if (connect(sock, p->ai_addr, p->ai_addrlen) == 0) {
            break; // Connection successful
        }
    }

    freeaddrinfo(res);

    if (!p) {
        fprintf(stderr, "Failed to connect to %s\n", hostname);
        close(sock);
        free(indications);
        return NULL;
    }

    close(sock);

    for (int i = 0; i < n; ++i) {
        // Populate RX_UE_INFORMATION_TAG and RNTI
        indications[i].ueInfoTag = generateRandomRxUeInformationTag();
        indications[i].rnti = generateRandomRNTI();

        // Randomly set CRCFLAG
        indications[i].crcFlag = (CRC_INDICATION_REL8_TAG)(rand() % 2);
    }

    return indications;
}
