typedef struct {
    int UE_ID;
    float* RX_SYMBOLS;
    size_t num_symbols;
    size_t capacity;
    pthread_mutex_t lock;
} PHY_RX_CONTEXT;

void initialize_phy_rx_context(PHY_RX_CONTEXT* ctx, int ue_id) {
    ctx->UE_ID = ue_id;
    ctx->RX_SYMBOLS = NULL;
    ctx->num_symbols = 0;
    ctx->capacity = 16; // Initial capacity
    pthread_mutex_init(&ctx->lock, NULL);
}

void free_phy_rx_context(PHY_RX_CONTEXT* ctx) {
    pthread_mutex_lock(&ctx->lock);
    if (ctx->RX_SYMBOLS) {
        free(ctx->RX_SYMBOLS);
        ctx->RX_SYMBOLS = NULL;
    }
    pthread_mutex_unlock(&ctx->lock);
    pthread_mutex_destroy(&ctx->lock);
}

void resize_rx_symbols(PHY_RX_CONTEXT* ctx, size_t new_capacity) {
    pthread_mutex_lock(&ctx->lock);
    float* new_symbols = realloc(ctx->RX_SYMBOLS, new_capacity * sizeof(float));
    if (new_symbols) {
        ctx->RX_SYMBOLS = new_symbols;
        ctx->capacity = new_capacity;
    }
    pthread_mutex_unlock(&ctx->lock);
}

void add_rx_symbol(PHY_RX_CONTEXT* ctx, float symbol) {
    pthread_mutex_lock(&ctx->lock);
    if (ctx->num_symbols >= ctx->capacity) {
        resize_rx_symbols(ctx, ctx->capacity * 2);
    }
    ctx->RX_SYMBOLS[ctx->num_symbols++] = symbol;
    pthread_mutex_unlock(&ctx->lock);
}

int add_phy_rx_context_to_collection(PHY_RX_CONTEXT* collection[], int collection_size, PHY_RX_CONTEXT new_ctx) {
    for (int i = 0; i < collection_size; i++) {
        if (collection[i] && collection[i]->UE_ID == new_ctx.UE_ID) {
            return -1; // Duplicate UE_ID
        }
    }

    PHY_RX_CONTEXT* new_collection = realloc(collection, (collection_size + 1) * sizeof(PHY_RX_CONTEXT));
    if (new_collection) {
        collection = new_collection;
        collection[collection_size++] = &new_ctx;
        initialize_phy_rx_context(&new_ctx, new_ctx.UE_ID);
        return 0; // Success
    }

    return -2; // Memory allocation failed
}

// Example usage
int main() {
    PHY_RX_CONTEXT ctx1;
    initialize_phy_rx_context(&ctx1, 1);

    add_rx_symbol(&ctx1, 1.23f);
    add_rx_symbol(&ctx1, 4.56f);

    printf("UE_ID: %d, Symbols: %f, %f\n", ctx1.UE_ID, ctx1.RX_SYMBOLS[0], ctx1.RX_SYMBOLS[1]);

    free_phy_rx_context(&ctx1);
    return 0;
}
```

