typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct List {
    Node* head;
    size_t count;
    size_t growth_factor;
    pthread_mutex_t mutex;
} List;

List* create_list(size_t initial_capacity, size_t growth_factor) {
    if (initial_capacity == 0 || growth_factor == 0) return NULL;

    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;

    list->head = NULL;
    list->count = 0;
    list->growth_factor = growth_factor > 1 ? growth_factor : 2; // Ensure at least a 50% increase
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void destroy_list(List* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_item(List* list, NFAPI_CRC_INDICATION_PDU_T item) {
    if (!list) return -1;

    pthread_mutex_lock(&list->mutex);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return -2; // Allocation failure
    }

    new_node->data = item;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->mutex);

    return 0;
}

void reset_list(List* list) {
    if (!list) return;

    pthread_mutex_lock(&list->mutex);

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    list->count = 0;

    pthread_mutex_unlock(&list->mutex);
}

int validate_list(List* list) {
    if (!list || !list->head) return -1;

    Node* current = list->head;
    while (current) {
        // Perform validation checks on current->data
        current = current->next;
    }

    return 0; // Validation passed
}

// Example usage:
int main() {
    List* my_list = create_list(100, 2);
    if (!my_list) {
        // Handle error
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T item;
    // Populate item with data

    if (add_item(my_list, item) != 0) {
        // Handle error
        destroy_list(my_list);
        return -2;
    }

    if (validate_list(my_list) != 0) {
        // Handle validation failure
    }

    reset_list(my_list);
    destroy_list(my_list);

    return 0;
}
