    log->entries = NULL;
    log->count = 0;
    log->capacity = 0;
}

void freeEventLog(EventLog *log) {
    free(log->entries);
    log->entries = NULL;
    log->count = 0;
    log->capacity = 0;
}

int addEventLogEntry(EventLog *log, time_t timestamp, int event_id, const char *description) {
    if (log->count >= log->capacity) {
        size_t new_capacity = log->capacity == 0 ? 1 : log->capacity * 2;
        EventLogEntry *new_entries = realloc(log->entries, new_capacity * sizeof(EventLogEntry));
        if (!new_entries) return -1; // Memory allocation failed
        log->entries = new_entries;
        log->capacity = new_capacity;
    }
    log->entries[log->count].timestamp = timestamp;
    log->entries[log->count].event_id = event_id;
    strncpy(log->entries[log->count].description, description, sizeof(log->entries[log->count].description) - 1);
    log->count++;
    return 0; // Success
}

EventLogEntry *getEventLogEntry(EventLog *log, int event_id) {
    for (size_t i = 0; i < log->count; i++) {
        if (log->entries[i].event_id == event_id) {
            return &log->entries[i];
        }
    }
    return NULL; // Entry not found
}

void clearEventLog(EventLog *log) {
    free(log->entries);
    log->entries = NULL;
    log->count = 0;
    log->capacity = 0;
}
