#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ENTRIES 10000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define fields of the structure
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Entry {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct Entry *next;
} Entry;

typedef struct Queue {
    Entry *front;
    Entry *rear;
    pthread_mutex_t lock;
    int size;
    int max_size;
    float growth_factor;
} Queue;

Queue* create_queue(float growth_factor) {
    Queue *queue = (Queue*)malloc(sizeof(Queue));
    if (!queue) return NULL;
    queue->front = queue->rear = NULL;
    pthread_mutex_init(&queue->lock, NULL);
    queue->size = 0;
    queue->max_size = MAX_ENTRIES;
    queue->growth_factor = growth_factor;
    return queue;
}

void enqueue(Queue *queue, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&queue->lock);
    if (queue->size == queue->max_size) {
        Entry *new_entries = realloc(queue->front, queue->max_size * queue->growth_factor * sizeof(Entry));
        if (!new_entries) {
            // Handle allocation failure
            printf("Memory allocation failed\n");
            pthread_mutex_unlock(&queue->lock);
            return;
        }
        queue->front = new_entries;
        queue->max_size *= (int)queue->growth_factor;
    }
    Entry *entry = (Entry*)malloc(sizeof(Entry));
    if (!entry) {
        // Handle allocation failure
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&queue->lock);
        return;
    }
    entry->pdu = pdu;
    entry->next = NULL;
    if (queue->rear) queue->rear->next = entry;
    else queue->front = entry;
    queue->rear = entry;
    queue->size++;
    pthread_mutex_unlock(&queue->lock);
}

NFAPI_CRC_INDICATION_PDU_T dequeue(Queue *queue) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pthread_mutex_lock(&queue->lock);
    if (queue->front == NULL) {
        // Handle empty queue
        printf("Queue is empty\n");
        pdu = (NFAPI_CRC_INDICATION_PDU_T){0}; // Initialize to default value
    } else {
        Entry *entry = queue->front;
        pdu = entry->pdu;
        if (queue->front == queue->rear) {
            queue->front = queue->rear = NULL;
        } else {
            queue->front = entry->next;
        }
        free(entry);
        queue->size--;
    }
    pthread_mutex_unlock(&queue->lock);
    return pdu;
}

void reset_queue(Queue *queue) {
    pthread_mutex_lock(&queue->lock);
    Entry *entry = queue->front;
    while (entry != NULL) {
        Entry *next_entry = entry->next;
        free(entry);
        entry = next_entry;
    }
    queue->front = queue->rear = NULL;
    queue->size = 0;
    pthread_mutex_unlock(&queue->lock);
}

void destroy_queue(Queue *queue) {
    reset_queue(queue);
    pthread_mutex_destroy(&queue->lock);
    free(queue);
}

