        int SNR_VALUE;
    } stats;
} PHY_RX_BUFFER_PDU_T;

typedef struct Node {
    PHY_RX_BUFFER_PDU_T data;
    struct Node* next;
} Node;

typedef struct List {
    Node* head;
} List;

void initList(List* list) {
    list->head = NULL;
}

Node* createNode(PHY_RX_BUFFER_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        return NULL; // Handle memory allocation failure
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

int addNode(List* list, PHY_RX_BUFFER_PDU_T data) {
    Node* newNode = createNode(data);
    if (newNode == NULL) {
        return -1; // Handle memory allocation failure
    }
    newNode->next = list->head;
    list->head = newNode;
    return 0; // Success
}

void freeList(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
}

void iterateList(List* list, void (*callback)(PHY_RX_BUFFER_PDU_T*)) {
    Node* current = list->head;
    while (current != NULL) {
        callback(&current->data);
        current = current->next;
    }
}

int main() {
    List myList;
    initList(&myList);

    srand(time(NULL));
    for (int i = 0; i < 10; ++i) {
