#define MAX_FRAME_LENGTH 1024

typedef struct {
    unsigned char data[MAX_FRAME_LENGTH];
    int length;
} TX_FRAME_PDU;

typedef struct {
    TX_FRAME_PDU frame;
    // Add other frame metadata fields here
    int checksum_valid;
} NFAPI_MESSAGE_T;

unsigned short calculateChecksum(const unsigned char *data, int length) {
    unsigned int sum = 0;
    for (int i = 0; i < length; i++) {
        sum += data[i];
    }
    return (unsigned short)(~sum);
}

NFAPI_MESSAGE_T* initializeFrames(int numFrames, const TX_FRAME_PDU *frames) {
    NFAPI_MESSAGE_T *messages = malloc(numFrames * sizeof(NFAPI_MESSAGE_T));
    if (!messages) {
        perror("Failed to allocate memory for frames");
        return NULL;
    }

    for (int i = 0; i < numFrames; i++) {
        messages[i].frame = frames[i];
        messages[i].checksum_valid = 1; // Assuming all frames are valid initially
        messages[i].checksum = calculateChecksum(messages[i].frame.data, messages[i].frame.length);
    }

    return messages;
}

void freeFrames(NFAPI_MESSAGE_T *messages, int numFrames) {
    if (messages) {
        free(messages);
    }
}

int main() {
    // Example usage
    TX_FRAME_PDU frames[] = {
        { .data = {0x1, 0x2, 0x3}, .length = 3 },
        { .data = {0x4, 0x5, 0x6, 0x7}, .length = 4 }
    };
    int numFrames = sizeof(frames) / sizeof(frames[0]);

    NFAPI_MESSAGE_T *messages = initializeFrames(numFrames, frames);
    if (messages) {
        for (int i = 0; i < numFrames; i++) {
            printf("Frame %d: Length=%d, Checksum Valid=%d\n", i, messages[i].frame.length, messages[i].checksum_valid);
        }
        freeFrames(messages, numFrames);
    }

    return 0;
}
