        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    arr->size = 0;
    arr->capacity = MAX_SIZE;
}

void growManagedArray(ManagedArray *arr) {
    size_t newCapacity = arr->capacity + GROWTH_THRESHOLD;
    FlexibleStructure *newArray = (FlexibleStructure *)realloc(arr->array, newCapacity * sizeof(FlexibleStructure));
    if (!newArray) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    arr->array = newArray;
    arr->capacity = newCapacity;
}

void addCrcIndicationPdu(ManagedArray *arr) {
    if (arr->size >= arr->capacity) {
        growManagedArray(arr);
    }
    arr->array[arr->size].crcIndicationPdu.tag = 1;
    arr->array[arr->size].crcIndicationPdu.rnti = rand() % 65536;
    do {
        arr->array[arr->size].crcIndicationPdu.rnti = rand() % 65536;
    } while (arr->size > 0 && arr->array[arr->size - 1].crcIndicationPdu.rnti == arr->array[arr->size].crcIndicationPdu.rnti);
    arr->array[arr->size].crcIndicationPdu.crcFlag = rand() % 2;
    arr->size++;
}

void addLteDlCcchMsgType1(ManagedArray *arr) {
    if (arr->size >= arr->capacity) {
        growManagedArray(arr);
    }
    arr->array[arr->size].lteDlCcchMsgType1.nasMessage[0] = 'H';
    arr->array[arr->size].lteDlCcchMsgType1.nasMessage[1] = 'e';
    arr->array[arr->size].lteDlCcchMsgType1.nasMessage[2] = 'l';
    arr->array[arr->size].lteDlCcchMsgType1.nasMessage[3] = 'l';
    arr->array[arr->size].lteDlCcchMsgType1.nasMessage[4] = 'o';
    arr->array[arr->size].lteDlCcchMsgType1.nasMessage[5] = '\0';
    arr->array[arr->size].lteDlCcchMsgType1.rrcUeIdentityRequest = rand() % 1000;
    arr->array[arr->size].lteDlCcchMsgType1.rrcUeIdentityResponse = rand() % 1000;
    arr->size++;
}

void printManagedArray(ManagedArray *arr) {
    for (size_t i = 0; i < arr->size; i++) {
        if (arr->array[i].crcIndicationPdu.tag == 1) {
            printf("CRC Indication PDU: RNTI=%d, CRC Flag=%d\n", arr->array[i].crcIndicationPdu.rnti, arr->array[i].crcIndicationPdu.crcFlag);
        } else {
            printf("LTE DL CCCH Msg Type 1: NAS Message='%s', RRC UE Identity Request=%d, RRC UE Identity Response=%d\n",
                   arr->array[i].lteDlCcchMsgType1.nasMessage,
                   arr->array[i].lteDlCcchMsgType1.rrcUeIdentityRequest,
                   arr->array[i].lteDlCcchMsgType1.rrcUeIdentityResponse);
        }
    }
}

int main() {
    srand(time(NULL));
    ManagedArray arr;
    initializeManagedArray(&arr);

    for (size_t i = 0; i < 200; i++) {
