// Define packet types
typedef struct {
    int PacketID;
    char SourceIP[16];
    char DestinationIP[16];
    size_t PacketSize;
    int SequenceNumber;
    int AcknowledgeBit;
    char DataPayload[256];
} IPacketType_A;

typedef struct {
    int PacketID;
    char SourceIP[16];
    char DestinationIP[16];
    size_t PacketSize;
    int SequenceNumber;
    int AcknowledgeBit;
    char DataPayload[256];
    // Additional fields for B
} IPacketType_B;

// Define packet union
typedef struct {
    int type;  // 0 for A, 1 for B
    union {
        IPacketType_A a;
        IPacketType_B b;
    } data;
} DataPacket;

// Function to create a new DataPacket
DataPacket* createPacket(int type, void* packetData) {
    DataPacket* packet = (DataPacket*)malloc(sizeof(DataPacket));
    if (packet == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    packet->type = type;
    memcpy(&packet->data, packetData, sizeof(packet->data));
    return packet;
}

// Function to free a DataPacket
void freePacket(DataPacket* packet) {
    free(packet);
}

// Thread-safe function to add a packet to the array
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void addPacketToArray(DataPacket** packets, int* size, int* capacity, DataPacket* newPacket) {
    pthread_mutex_lock(&mutex);
    if (*size >= *capacity) {
        *capacity *= 2;
        DataPacket** temp = realloc(*packets, *capacity * sizeof(DataPacket*));
        if (temp == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        *packets = temp;
    }
    (*packets)[*size] = newPacket;
    (*size)++;
    pthread_mutex_unlock(&mutex);
}

// Function to initialize a packet with parameters from external templates
void initializePacket(DataPacket* packet, int type, void* templateData) {
    if (type == 0) {
        // Initialize IPacketType_A using templateData
        memcpy(&packet->data.a, templateData, sizeof(IPacketType_A));
    } else {
        // Initialize IPacketType_B using templateData
        memcpy(&packet->data.b, templateData, sizeof(IPacketType_B));
    }
}

// Function to handle external data source access with proper error handling
void* fetchPacketFromSource(void* param) {
    // Simulate fetching a packet from an external source
    void* packet = malloc(sizeof(DataPacket));
    if (packet == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    // Populate packet with data from the source
    initializePacket(packet, 0, param);  // Example type A initialization
    return packet;
}

int main() {
    DataPacket** packets = NULL;
    int size = 0;
    int capacity = 1;

    pthread_t thread;
    void* result;

    // Fetch a packet from the external source
    if (pthread_create(&thread, NULL, fetchPacketFromSource, NULL) != 0) {
        fprintf(stderr, "Thread creation failed\n");
        return EXIT_FAILURE;
    }

    if (pthread_join(thread, &result) != 0) {
        fprintf(stderr, "Thread join failed\n");
        return EXIT_FAILURE;
    }

    DataPacket* newPacket = (DataPacket*)result;

    // Add the packet to the array
    addPacketToArray(&packets, &size, &capacity, newPacket);

    // Free all allocated memory when done
    for (int i = 0; i < size; i++) {
        freePacket(packets[i]);
    }
    free(packets);

    return EXIT_SUCCESS;
}
