#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_UE_MEASUREMENTS 1000
#define RETENTION_POLICY_SECONDS 60

typedef struct {
    int UE_ID;
    int PCI;
    int RSRP;
} NFAPI_LTE_UE_MEASUREMENTS_T;

typedef struct {
    NFAPI_LTE_UE_MEASUREMENTS_T measurements[MAX_UE_MEASUREMENTS];
    int size;
    pthread_mutex_t mutex;
} MeasurementManager;

MeasurementManager measurement_manager = {0};

void init_measurement_manager() {
    pthread_mutex_init(&measurement_manager.mutex, NULL);
}

int add_or_update_measurement(int UE_ID, int PCI, int RSRP) {
    pthread_mutex_lock(&measurement_manager.mutex);
    for (int i = 0; i < measurement_manager.size; i++) {
        if (measurement_manager.measurements[i].UE_ID == UE_ID) {
            measurement_manager.measurements[i].PCI = PCI;
            measurement_manager.measurements[i].RSRP = RSRP;
            pthread_mutex_unlock(&measurement_manager.mutex);
            return 1;
        }
    }
    if (measurement_manager.size < MAX_UE_MEASUREMENTS) {
        measurement_manager.measurements[measurement_manager.size].UE_ID = UE_ID;
        measurement_manager.measurements[measurement_manager.size].PCI = PCI;
        measurement_manager.measurements[measurement_manager.size].RSRP = RSRP;
        measurement_manager.size++;
        pthread_mutex_unlock(&measurement_manager.mutex);
        return 1;
    }
    pthread_mutex_unlock(&measurement_manager.mutex);
    return -1; // Maximum number of measurements reached
}

NFAPI_LTE_UE_MEASUREMENTS_T* get_latest_measurement(int UE_ID) {
    pthread_mutex_lock(&measurement_manager.mutex);
    for (int i = measurement_manager.size - 1; i >= 0; i--) {
        if (measurement_manager.measurements[i].UE_ID == UE_ID) {
            NFAPI_LTE_UE_MEASUREMENTS_T* result = malloc(sizeof(NFAPI_LTE_UE_MEASUREMENTS_T));
            *result = measurement_manager.measurements[i];
            pthread_mutex_unlock(&measurement_manager.mutex);
            return result;
        }
    }
    pthread_mutex_unlock(&measurement_manager.mutex);
    return NULL; // Measurement not found
}

void* cleanup_measurements(void* arg) {
    while (1) {
        sleep(RETENTION_POLICY_SECONDS);
        pthread_mutex_lock(&measurement_manager.mutex);
        int current_time = time(NULL);
        for (int i = measurement_manager.size - 1; i >= 0; i--) {
            if (current_time - measurement_manager.measurements[i].UE_ID > RETENTION_POLICY_SECONDS) {
                measurement_manager.size--;
            } else {
                break;
            }
        }
        pthread_mutex_unlock(&measurement_manager.mutex);
    }
    return NULL;
}

void start_cleanup_thread() {
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, cleanup_measurements, NULL);
    pthread_detach(thread_id);
}
```

