#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ENTRIES 1000

typedef struct {
    int sid;
    time_t timestamp;
    char status[20];
} Message;

typedef struct {
    Message* messages;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} MessageArray;

void init_message_array(MessageArray* array) {
    array->messages = (Message*)malloc(MAX_ENTRIES * sizeof(Message));
    if (array->messages == NULL) {
        // Handle memory allocation failure
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    array->count = 0;
    array->capacity = MAX_ENTRIES;
    pthread_mutex_init(&array->lock, NULL);
}

void append_message(MessageArray* array, Message msg) {
    pthread_mutex_lock(&array->lock);
    if (array->count >= array->capacity) {
        // Handle maximum entries limit
        fprintf(stderr, "Maximum entries limit reached\n");
        pthread_mutex_unlock(&array->lock);
        return;
    }
    array->messages[array->count++] = msg;
    pthread_mutex_unlock(&array->lock);
}

void cleanup_old_messages(MessageArray* array, time_t cutoff) {
    pthread_mutex_lock(&array->lock);
    size_t i = 0, j = 0;
    while (j < array->count) {
        if (array->messages[j].timestamp >= cutoff) {
            array->messages[i++] = array->messages[j];
        }
        j++;
    }
    array->count = i;
    pthread_mutex_unlock(&array->lock);
}

void destroy_message_array(MessageArray* array) {
    free(array->messages);
    pthread_mutex_destroy(&array->lock);
}
