typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct List {
    Node* head;
    size_t count;
    size_t capacity;
} List;

List* list_init(size_t initial_capacity) {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;

    list->head = NULL;
    list->count = 0;
    list->capacity = initial_capacity;

    return list;
}

int list_add_entry(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list->count >= list->capacity) {
        Node* new_head = (Node*)realloc(list->head, (list->capacity * 2) * sizeof(Node));
        if (!new_head) return -1;
        list->head = new_head;
        list->capacity *= 2;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;

    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;

    list->count++;
    return 0;
}

size_t list_get_count(List* list) {
    return list->count;
}

void list_free(List* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}
