#define MAX_STRUCTURES 1024
#define MAX_MEMORY_PER_STRUCT 512

typedef struct {
    uint64_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t count;
    size_t capacity;
} DynamicArray;

uint64_t hash_function(uint32_t RNTI, int sequence_index) {
    // Implement a robust and scalable hash function
    return ((uint64_t)RNTI << 32) | sequence_index;
}

void init_structure(NFAPI_CRC_INDICATION_PDU_T *struct_ptr, uint32_t RNTI, int sequence_index) {
    struct_ptr->RX_UE_INFORMATION_TAG = hash_function(RNTI, sequence_index);
    struct_ptr->RNTI = RNTI;
}

uint8_t roll_xor(uint8_t *crc_flags, size_t count) {
    // Implement efficient rolling XOR operation
    uint8_t xor_result = 0;
    for (size_t i = 0; i < count; ++i) {
        xor_result ^= crc_flags[i];
    }
    return xor_result;
}

void insert_structure(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T new_struct) {
    if (array->count >= array->capacity) {
        // Handle memory reallocation
        size_t new_capacity = array->capacity ? array->capacity * 2 : 16;
        if (new_capacity > MAX_STRUCTURES) {
            return; // Reached maximum allowed structures
        }
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            return; // Memory allocation failed
        }
        array->array = new_array;
        array->capacity = new_capacity;
    }

    array->array[array->count++] = new_struct;
}

void delete_structure(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T to_delete) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->array[i].RX_UE_INFORMATION_TAG == to_delete.RX_UE_INFORMATION_TAG &&
            array->array[i].RNTI == to_delete.RNTI) {
            // Shift elements to fill the gap
            for (size_t j = i; j < array->count - 1; ++j) {
                array->array[j] = array->array[j + 1];
            }
            --array->count;
            break;
        }
    }
}

void manage_dynamic_array(DynamicArray *array, uint32_t RNTI, int sequence_index) {
    NFAPI_CRC_INDICATION_PDU_T new_struct;
    init_structure(&new_struct, RNTI, sequence_index);

    if (array->count > 0) {
        // Update CRCFLAG using rolling XOR
        uint8_t new_crcflag = roll_xor((uint8_t *)&array->array[0], array->count);
        new_struct.CRC_INDICATION_REL8_TAG = new_crcflag;
    }

    insert_structure(array, new_struct);
}

// Example usage
int main() {
    DynamicArray dynamic_array = {NULL, 0, 0};
    manage_dynamic_array(&dynamic_array, 12345, 0); // Add a structure with RNTI 12345 and sequence index 0
    delete_structure(&dynamic_array, (NFAPI_CRC_INDICATION_PDU_T){12345, 0}); // Remove the added structure

    free(dynamic_array.array);
    return 0;
}
