} RLC_PDU_T;

typedef struct LTE_DL_FRAME_MESSAGE {
    MAC_PDU_T mac_pdu;
    RLC_PDU_T rlc_pdu;
} LTE_DL_FRAME_MESSAGE;

typedef struct DynamicArray {
    LTE_DL_FRAME_MESSAGE* data;
    size_t capacity;
    size_t size;
    sem_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;
    array->data = (LTE_DL_FRAME_MESSAGE*)calloc(initial_capacity, sizeof(LTE_DL_FRAME_MESSAGE));
    if (!array->data) {
        free(array);
        return NULL;
    }
    array->capacity = initial_capacity;
    array->size = 0;
    sem_init(&array->mutex, 0, 1);
    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    if (array) {
        sem_wait(&array->mutex);
        free(array->data);
        sem_post(&array->mutex);
        sem_destroy(&array->mutex);
        free(array);
    }
}

int add_to_array(DynamicArray* array, LTE_DL_FRAME_MESSAGE message) {
    sem_wait(&array->mutex);
    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        LTE_DL_FRAME_MESSAGE* new_data = (LTE_DL_FRAME_MESSAGE*)realloc(array->data, new_capacity * sizeof(LTE_DL_FRAME_MESSAGE));
        if (!new_data) {
            sem_post(&array->mutex);
            return -1; // Memory allocation failed
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }
    array->data[array->size++] = message;
    sem_post(&array->mutex);
    return 0;
}

int get_from_array(DynamicArray* array, size_t index, LTE_DL_FRAME_MESSAGE* output) {
    if (index >= array->size) return -1; // Index out of bounds
    sem_wait(&array->mutex);
    *output = array->data[index];
    sem_post(&array->mutex);
    return 0;
}

void update_rlc_pdu(DynamicArray* array, size_t index, RLC_PDU_T new_rlc_pdu) {
    if (index >= array->size) return; // Index out of bounds
    sem_wait(&array->mutex);
    array->data[index].rlc_pdu = new_rlc_pdu;
    sem_post(&array->mutex);
}

void* external_data_source_thread(void* arg) {
    DynamicArray* array = (DynamicArray*)arg;
    while (1) {
        // Simulate periodic updates
        LTE_DL_FRAME_MESSAGE message = { /* Initialize with new data */ };
        for (size_t i = 0; i < array->size; ++i) {
            update_rlc_pdu(array, i, message.rlc_pdu);
        }
        sleep(1); // Simulate delay
    }
    return NULL;
}
