#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* createList() {
    LinkedList *list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void insertElement(LinkedList *list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, int CRCFLAG) {
    NFAPI_CRC_INDICATION_PDU_T *newNode = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newNode) return;

    newNode->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newNode->RNTI = RNTI;
    newNode->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    newNode->CRCFLAG = CRCFLAG;
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (!list->head || list->head->RNTI > RNTI) {
        newNode->next = list->head;
        list->head = newNode;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *current = list->head;
        while (current->next && current->next->RNTI < RNTI) {
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }
    pthread_mutex_unlock(&list->lock);
}

int getSize(LinkedList *list) {
    int size = 0;
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        size++;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return size;
}

void removeElement(LinkedList *list, int RNTI) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    NFAPI_CRC_INDICATION_PDU_T *previous = NULL;

    while (current && current->RNTI != RNTI) {
        previous = current;
        current = current->next;
    }

    if (current) {
        if (previous) {
            previous->next = current->next;
        } else {
            list->head = current->next;
        }
        free(current);
    }
    pthread_mutex_unlock(&list->lock);
}

void iterateList(LinkedList *list, void (*action)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        action(current);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void destroyList(LinkedList *list) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    NFAPI_CRC_INDICATION_PDU_T *temp;

    while (current) {
        temp = current;
        current = current->next;
        free(temp);
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
