    return SUCCESS;
}

ErrorCode serializePDUs(NFAPI_CRC_INDICATION_PDU_T* pdus, int size, const char* filename) {
    FILE* file = fopen(filename, "wb");

    if (file == NULL) return ERROR_FILE_IO;

    if (fwrite(pdus, NFAPI_CRC_INDICATION_PDU_T_SIZE, size, file) != size) {
        fclose(file);
        return ERROR_FILE_IO;
    }

    fclose(file);
    return SUCCESS;
}

ErrorCode deserializePDUs(NFAPI_CRC_INDICATION_PDU_T** pdus, int* size, const char* filename) {
    FILE* file = fopen(filename, "rb");

    if (file == NULL) return ERROR_FILE_IO;

    fseek(file, 0, SEEK_END);
    *size = ftell(file) / NFAPI_CRC_INDICATION_PDU_T_SIZE;
    fseek(file, 0, SEEK_SET);

    *pdus = malloc(*size * NFAPI_CRC_INDICATION_PDU_T_SIZE);

    if (*pdus == NULL) {
        fclose(file);
        return ERROR_OUT_OF_MEMORY;
    }

    if (fread(*pdus, NFAPI_CRC_INDICATION_PDU_T_SIZE, *size, file) != *size) {
        free(*pdus);
        fclose(file);
        return ERROR_FILE_IO;
    }

    fclose(file);
    return SUCCESS;
}

