typedef struct pool_block {
    struct pool_block *next;
    NFAPI_CRC_INDICATION_PDU_T data[MAX_NFAPI_PDUS];
} pool_block;

pool_block *pool_head = NULL;
int pool_size = 0;

void init_pool(int block_size, int max_blocks) {
    for (int i = 0; i < max_blocks; i++) {
        pool_block *new_block = malloc(sizeof(pool_block));
        new_block->next = pool_head;
        pool_head = new_block;
        pool_size += block_size;
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu() {
    if (pool_size <= 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *pdu = &pool_head->data[--pool_size];
    pdu->RNTI = rand() % 1024; // Random RNTI for demonstration
    pdu->rx_ue_info_tag = (NFAPI_RX_UE_INFORMATION_TAG)rand(); // Random RX_UE_INFORMATION_TAG

    return pdu;
}

void free_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    int index = ((char*)pdu - (char*)pool_head->data) / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (index < 0 || index >= MAX_NFAPI_PDUS) return;

    pdu->RNTI = 0; // Reset RNTI for reuse
    pool_size++;
}

void serialize_and_transmit(NFAPI_CRC_INDICATION_PDU_T *pdus, int count) {
    // Network interface API integration and serialization logic here
}

