    int count = 0;

    while (count < MAX_NFAPI_PDUS && allocate_pdu() != NULL) {
        pdus[count++] = allocate_pdu();
    }

    // Validate and process the array
    for (int i = 1; i < count; i++) {
        if (pdus[i]->RNTI == pdus[i-1]->RNTI) {
            printf("Error: Consecutive PDUs have the same RNTI\n");
            return -1;
        }
