#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <time.h>

#define N 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} NFapiCrcIndicationPdu;

typedef struct {
    NFapiCrcIndicationPdu *pool;
    size_t size;
    size_t count;
    pthread_mutex_t mutex;
} CrcIndicationPool;

void initialize_pool(CrcIndicationPool *pool, size_t size) {
    pool->size = size;
    pool->count = 0;
    pool->pool = (NFapiCrcIndicationPdu *)malloc(size * sizeof(NFapiCrcIndicationPdu));
    if (!pool->pool) {
        perror("Failed to allocate memory for CRC indication pool");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&pool->mutex, NULL);
}

void destroy_pool(CrcIndicationPool *pool) {
    free(pool->pool);
    pthread_mutex_destroy(&pool->mutex);
}

NFapiCrcIndicationPdu *allocate_from_pool(CrcIndicationPool *pool) {
    NFapiCrcIndicationPdu *pdu;
    pthread_mutex_lock(&pool->mutex);
    if (pool->count < pool->size) {
        pdu = &pool->pool[pool->count++];
    } else {
        pdu = NULL;
    }
    pthread_mutex_unlock(&pool->mutex);
    return pdu;
}

void populate_pdu(NFapiCrcIndicationPdu *pdu, int ue_info_tag, int rnti) {
    pdu->RX_UE_INFORMATION_TAG = ue_info_tag;
    pdu->RNTI = rnti;
    // Assume CRCFLAG is a bitfield in the structure
    pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
}

int main() {
    srand(time(NULL));
    CrcIndicationPool pool;
    initialize_pool(&pool, N);

    for (size_t i = 0; i < N; ++i) {
        NFapiCrcIndicationPdu *pdu = allocate_from_pool(&pool);
        if (pdu) {
            populate_pdu(pdu, rand() % 100, rand() % 256); // Randomly set tags
            printf("Allocated PDU with RX_UE_INFORMATION_TAG: %d and RNTI: %d\n", pdu->RX_UE_INFORMATION_TAG, pdu->RNTI);
        } else {
            fprintf(stderr, "Failed to allocate PDU from pool\n");
            break;
        }
    }

    destroy_pool(&pool);
    return 0;
}
