typedef struct PDU {
    int pdu_id;
    void *data;
    struct PDU *next;
} PDU;

typedef struct Session {
    int session_id;
    int ue_id;
    PDU *pdu_list;
    pthread_mutex_t lock;
} Session;

Session *sessions = NULL;
pthread_mutex_t sessions_lock = PTHREAD_MUTEX_INITIALIZER;

void validate_data(int session_id, int ue_id, void *user_data, const char *action) {
    // Custom validation logic here
}

int find_session_index(int session_id) {
    pthread_mutex_lock(&sessions_lock);
    for (Session *s = sessions; s != NULL; s = s->next) {
        if (s->session_id == session_id) {
            pthread_mutex_unlock(&sessions_lock);
            return 1;
        }
    }
    pthread_mutex_unlock(&sessions_lock);
    return 0;
}

int create_session(int session_id, int ue_id, void *user_data) {
    Session *new_session = (Session *)malloc(sizeof(Session));
    if (new_session == NULL) {
        return -1; // Memory allocation failed
    }
    new_session->session_id = session_id;
    new_session->ue_id = ue_id;
    new_session->pdu_list = NULL;
    pthread_mutex_init(&new_session->lock, NULL);
    pthread_mutex_lock(&sessions_lock);
    if (find_session_index(session_id)) {
        free(new_session);
        pthread_mutex_unlock(&sessions_lock);
        return -1; // Session already exists
    }
    new_session->next = sessions;
    sessions = new_session;
    pthread_mutex_unlock(&sessions_lock);
    return 0;
}

int update_session(int session_id, int ue_id, void *user_data) {
    pthread_mutex_lock(&sessions_lock);
    if (!find_session_index(session_id)) {
        pthread_mutex_unlock(&sessions_lock);
        return -1; // Session not found
    }
    for (Session *s = sessions; s != NULL; s = s->next) {
        if (s->session_id == session_id) {
            s->ue_id = ue_id;
            // Update other fields as needed
            pthread_mutex_unlock(&sessions_lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&sessions_lock);
    return -1; // Should not reach here
}

void terminate_session(int session_id) {
    pthread_mutex_lock(&sessions_lock);
    if (!find_session_index(session_id)) {
        pthread_mutex_unlock(&sessions_lock);
        return; // Session not found
    }
    for (Session *s = sessions, *prev = NULL; s != NULL; prev = s, s = s->next) {
        if (s->session_id == session_id) {
            if (prev == NULL) {
                sessions = s->next;
            } else {
                prev->next = s->next;
            }
            pthread_mutex_destroy(&s->lock);
            free(s);
            pthread_mutex_unlock(&sessions_lock);
            return;
        }
    }
    pthread_mutex_unlock(&sessions_lock);
}

int manage_session(int session_id, int ue_id, void *user_data, const char *action) {
    validate_data(session_id, ue_id, user_data, action);
    if (strcmp(action, "terminate") == 0) {
        terminate_session(session_id);
        return 0;
    } else if (session_id != -1) {
        if (find_session_index(session_id)) {
            update_session(session_id, ue_id, user_data);
        } else {
            create_session(session_id, ue_id, user_data);
        }
        return 0;
    }
    return -1; // Invalid action or session ID
}
