void* validateData(void* arg) {
    Node* current = head;
    while (current != NULL) {
        if (current->data.CRC_INDICATION_REL8_TAG == 0 || current->data.CRC_INDICATION_REL8_TAG > 1) {
            fprintf(stderr, "Validation error: Invalid CRCFLAG value\n");
        }
        current = current->next;
    }
    return NULL;
}

