typedef struct ListNode {
    LTE_UERadioResourceConfigDedicated_T* config;
    struct ListNode* next;
} ListNode;

typedef struct {
    ListNode* head;
    size_t count;
} LTE_List;

LTE_List* createList() {
    LTE_List* list = (LTE_List*)malloc(sizeof(LTE_List));
    if (list == NULL) {
        return NULL; // Handle memory allocation failure
    }
    list->head = NULL;
    list->count = 0;
    return list;
}

void destroyList(LTE_List* list) {
    ListNode* current = list->head;
    while (current != NULL) {
        ListNode* next = current->next;
        free(current->config->RadioBearerContainer);
        free(current->config);
        free(current);
        current = next;
    }
    free(list);
}

LTE_UERadioResourceConfigDedicated_T* createConfig(uint16_t C_RNTI, void* RadioBearerContainer) {
    LTE_UERadioResourceConfigDedicated_T* config = (LTE_UERadioResourceConfigDedicated_T*)malloc(sizeof(LTE_UERadioResourceConfigDedicated_T));
    if (config == NULL) {
        return NULL; // Handle memory allocation failure
    }
    config->C_RNTI = C_RNTI;
    config->RadioBearerContainer = RadioBearerContainer;
    return config;
}

void addConfigTo(ListNode** head, LTE_UERadioResourceConfigDedicated_T* config) {
    ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
    if (newNode == NULL) {
        // Handle memory allocation failure
        free(config->RadioBearerContainer);
        free(config);
        return;
    }
    newNode->config = config;
    newNode->next = *head;
    *head = newNode;
}

void removeConfigFrom(ListNode** head, uint16_t C_RNTI) {
    ListNode* current = *head;
    ListNode* prev = NULL;

    while (current != NULL) {
        if (current->config->C_RNTI == C_RNTI) {
            if (prev == NULL) {
                *head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current->config->RadioBearerContainer);
            free(current->config);
            free(current);
            return;
        }
        prev = current;
        current = current->next;
    }
}

void printList(LTE_List* list) {
    ListNode* current = list->head;
    while (current != NULL) {
        printf("C-RNTI: %d\n", current->config->C_RNTI);
        // Print additional fields as needed
        current = current->next;
