#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_CRC_INDICATIONS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T *indicators;
    size_t count;
} CRCData;

CRCData *crc_data = NULL;

void init_crc_data() {
    crc_data = (CRCData *)malloc(sizeof(CRCData));
    if (!crc_data) {
        perror("Failed to allocate memory for CRC data");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&crc_data->lock, NULL);
    crc_data->indicators = (NFAPI_CRC_INDICATION_PDU_T *)calloc(MAX_CRC_INDICATIONS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_data->indicators) {
        perror("Failed to allocate memory for CRC indicators");
        free(crc_data);
        exit(EXIT_FAILURE);
    }
    crc_data->count = 0;
}

void populate_crc_indicators() {
    srand(time(NULL));
    pthread_mutex_lock(&crc_data->lock);
    for (size_t i = 0; i < MAX_CRC_INDICATIONS; ++i) {
        crc_data->indicators[i].RX_UE_INFORMATION_TAG = rand();
        crc_data->indicators[i].RNTI = rand();
        crc_data->indicators[i].CRCFLAG = rand() % 2;
    }
    pthread_mutex_unlock(&crc_data->lock);
}

void validate_crc_indicators() {
    pthread_mutex_lock(&crc_data->lock);
    for (size_t i = 0; i < MAX_CRC_INDICATIONS; ++i) {
        if (!(crc_data->indicators[i].CRCFLAG == 0 || crc_data->indicators[i].CRCFLAG == 1)) {
            fprintf(stderr, "Validation failed: CRCFLAG out of range at index %zu\n", i);
            // Handle validation failure
        }
    }
    pthread_mutex_unlock(&crc_data->lock);
}

void persist_crc_data() {
    char *crc_dir_path = getenv("CRC_DIR_PATH");
    if (!crc_dir_path) {
        time_t now = time(NULL);
        char dir_name[20];
        strftime(dir_name, sizeof(dir_name), "crc_data_%Y%m%d%H%M%S", localtime(&now));
        if (mkdir(dir_name, 0755) != 0) {
            perror("Failed to create CRC data directory");
            return;
        }
        crc_dir_path = dir_name;
    }

    char file_name[100];
    snprintf(file_name, sizeof(file_name), "%s/crc_data.bin", crc_dir_path);

    FILE *file = fopen(file_name, "wb");
    if (!file) {
        perror("Failed to open CRC data file for writing");
        return;
    }

    pthread_mutex_lock(&crc_data->lock);
    size_t bytes_written = fwrite(crc_data->indicators, sizeof(NFAPI_CRC_INDICATION_PDU_T), crc_data->count, file);
    pthread_mutex_unlock(&crc_data->lock);

    if (bytes_written != crc_data->count) {
        perror("Failed to write all CRC data");
    }

    fclose(file);
}

void free_crc_data() {
    pthread_mutex_destroy(&crc_data->lock);
    free(crc_data->indicators);
    free(crc_data);
}

int main() {
    init_crc_data();
    populate_crc_indicators();
    validate_crc_indicators();
    persist_crc_data();
    free_crc_data();

    return 0;
}
```

