#define INITIAL_CAPACITY 10

typedef struct MeasurementResult {
    int frequencyBand;
    int signalStrength;
    int qualityMetrics;
} MeasurementResult;

typedef struct MeasurementReport {
    MeasurementResult* results;
    size_t count;
    size_t capacity;
} MeasurementReport;

typedef struct UEContext {
    int ueId;
    int cellId;
    MeasurementReport* report;
} UEContext;

UEContext** initializeAndPopulateUEContexts(int numUEs, int* newMeasurements, size_t measurementCount) {
    UEContext** ueContexts = (UEContext**)malloc(numUEs * sizeof(UEContext*));
    for (int i = 0; i < numUEs; ++i) {
        ueContexts[i] = (UEContext*)malloc(sizeof(UEContext));
        ueContexts[i]->ueId = i;
        ueContexts[i]->cellId = i % 100; // Example cell ID calculation
        ueContexts[i]->report = (MeasurementReport*)malloc(sizeof(MeasurementReport));
        initializeMeasurementReport(ueContexts[i]->report);
    }
    for (int j = 0; j < measurementCount; ++j) {
        int ueId = newMeasurements[j] / 100;
        int frequencyBand = newMeasurements[j] % 100;
        if (ueId >= numUEs) continue;
        addMeasurementToReport(ueContexts[ueId]->report, frequencyBand);
    }
    return ueContexts;
}

void initializeMeasurementReport(MeasurementReport* report) {
    report->results = NULL;
    report->count = 0;
    report->capacity = 0;
}

void addMeasurementToReport(MeasurementReport* report, int frequencyBand) {
    if (report->count == report->capacity) {
        report->capacity = report->capacity == 0 ? INITIAL_CAPACITY : report->capacity * 2;
        report->results = realloc(report->results, report->capacity * sizeof(MeasurementResult));
    }
    MeasurementResult result = {frequencyBand, /* signalStrength from external source */, /* qualityMetrics from external source */};
    report->results[report->count++] = result;
}

void freeUEContexts(UEContext** ueContexts, int numUEs) {
    for (int i = 0; i < numUEs; ++i) {
        if (ueContexts[i]->report->results) {
            free(ueContexts[i]->report->results);
        }
        free(ueContexts[i]->report);
        free(ueContexts[i]);
    }
    free(ueContexts);
}
