} TrafficMetric;

typedef struct {
    int userId;
    double sessionDuration;
    TrafficMetric* metrics;
    int metricCount;
} UserSession;

typedef struct {
    UserSession** sessions;
    int size;
    int capacity;
} SessionCollection;

// Function declarations
void initSessionCollection(SessionCollection* collection);
void addSession(SessionCollection* collection, UserSession* session);
UserSession* findSessionsByDuration(SessionCollection* collection, double minDuration, double maxDuration);
void updateTrafficMetrics(UserSession* session);
void freeSessionCollection(SessionCollection* collection);

int main() {
    // Example usage
    SessionCollection collection;
    initSessionCollection(&collection);

    UserSession session1 = {1, 3600, NULL, 0};
    TrafficMetric metric1 = {"TCP", 5.0, 0.02};
    session1.metrics = (TrafficMetric*)malloc(sizeof(TrafficMetric));
    session1.metrics[0] = metric1;
    session1.metricCount = 1;

    addSession(&collection, &session1);

    UserSession* sessions = findSessionsByDuration(&collection, 1800, 7200);
    for (int i = 0; sessions[i] != NULL; i++) {
        printf("User ID: %d, Duration: %.2f\n", sessions[i]->userId, sessions[i]->sessionDuration);
    }

    freeSessionCollection(&collection);

    return 0;
}

// Function definitions
void initSessionCollection(SessionCollection* collection) {
    collection->sessions = (UserSession**)malloc(sizeof(UserSession*) * 4); // Initial capacity
    if (!collection->sessions) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    collection->size = 0;
    collection->capacity = 4;
}

void addSession(SessionCollection* collection, UserSession* session) {
    if (collection->size == collection->capacity) {
        collection->capacity *= 2;
        collection->sessions = (UserSession**)realloc(collection->sessions, sizeof(UserSession*) * collection->capacity);
        if (!collection->sessions) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(1);
        }
    }
    collection->sessions[collection->size++] = session;
}

UserSession* findSessionsByDuration(SessionCollection* collection, double minDuration, double maxDuration) {
    static UserSession** result = NULL;
    static int resultSize = 0;
    static int resultCapacity = 4;

    if (!result) {
        result = (UserSession**)malloc(sizeof(UserSession*) * resultCapacity);
        if (!result) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
    }

    for (int i = 0; i < collection->size; i++) {
        UserSession* session = collection->sessions[i];
        if (session->sessionDuration >= minDuration && session->sessionDuration <= maxDuration) {
            if (resultSize == resultCapacity) {
                resultCapacity *= 2;
                result = (UserSession**)realloc(result, sizeof(UserSession*) * resultCapacity);
                if (!result) {
                    fprintf(stderr, "Memory reallocation failed\n");
                    exit(1);
                }
            }
            result[resultSize++] = session;
        } else {
            // Set the next element to NULL to mark the end of valid results
            if (i >= resultSize) {
                result[i] = NULL;
            }
        }
    }

    return result;
}

void updateTrafficMetrics(UserSession* session) {
    // Implement logic to fetch real-time traffic metrics from system interfaces
    // For demonstration, we'll assume static data for simplicity
    TrafficMetric newMetric = {"UDP", 3.0, 0.01};
    if (session->metricCount == session->capacity) {
        session->capacity *= 2;
        session->metrics = (TrafficMetric*)realloc(session->metrics, sizeof(TrafficMetric) * session->capacity);
        if (!session->metrics) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(1);
        }
    }
    session->metrics[session->metricCount++] = newMetric;
}

void freeSessionCollection(SessionCollection* collection) {
    for (int i = 0; i < collection->size; i++) {
        UserSession* session = collection->sessions[i];
        if (session->metrics) {
            free(session->metrics);
        }
        free(session);
    }
    free(collection->sessions);
}
