#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list;
    int allocated_size;
    int used_count;
    pthread_mutex_t lock;
} CRC_LIST_T;

int allocate_crc_list(CRC_LIST_T **list, int N) {
    *list = (CRC_LIST_T *)malloc(sizeof(CRC_LIST_T));
    if (*list == NULL) {
        perror("Failed to allocate memory for CRC list");
        return -1;
    }
    (*list)->pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if ((*list)->pdu_list == NULL) {
        perror("Failed to allocate memory for PDU list");
        free(*list);
        return -1;
    }
    (*list)->allocated_size = N;
    (*list)->used_count = 0;
    pthread_mutex_init(&((*list)->lock), NULL);
    return 0;
}

void deallocate_crc_list(CRC_LIST_T *list) {
    if (list != NULL) {
        free(list->pdu_list);
        free(list);
    }
}

int log_operation(const char *operation, const CRC_LIST_T *list) {
    FILE *log_file = fopen("crc_operations.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file for writing");
        return -1;
    }
    time_t current_time = time(NULL);
    fprintf(log_file, "%s: %s\n", ctime(&current_time), operation);
    fclose(log_file);
    return 0;
}

int add_crc_indication(CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&(list->lock));
    if (list->used_count < list->allocated_size) {
        list->pdu_list[list->used_count++] = pdu;
        log_operation("Added CRC indication", list);
        pthread_mutex_unlock(&(list->lock));
        return 0;
    } else {
        pthread_mutex_unlock(&(list->lock));
        perror("CRC list is full");
        return -1;
    }
}

int query_crc_indication(const CRC_LIST_T *list, int RNTI, NFAPI_CRC_INDICATION_PDU_T **result) {
    pthread_mutex_lock(&(list->lock));
    for (int i = 0; i < list->used_count; i++) {
        if (list->pdu_list[i].RNTI == RNTI) {
            *result = &(list->pdu_list[i]);
            pthread_mutex_unlock(&(list->lock));
            return 0;
        }
    }
    pthread_mutex_unlock(&(list->lock));
    *result = NULL;
    return -1;
}
