#define MAX_RNTI 65535

typedef struct {
    int rnti;
    int crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_nfaapi_pdu(int n, const char* log_format) {
    if (n <= 0 || n > MAX_RNTI) {
        fprintf(stderr, "Invalid number of entries: %d\n", n);
        return NULL;
    }

    FILE* log_file = fopen("audit_log.txt", "a");
    if (!log_file) {
        perror("Failed to open audit log file");
        return NULL;
    }

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    NFAPI_CRC_INDICATION_PDU_T* pdu_array = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_array) {
        perror("Failed to allocate memory");
        fclose(log_file);
        return NULL;
    }

    for (int i = 0; i < n; i++) {
        int rnti = rand() % (MAX_RNTI + 1);
        int crc_flag = rand() % 2;

        if (rnti > MAX_RNTI) {
            fprintf(stderr, "Invalid RNTI value: %d\n", rnti);
            continue;
        }

        pthread_mutex_lock(&mutex);
        pdu_array[i].rnti = rnti;
        pdu_array[i].crc_flag = crc_flag;

        char buffer[256];
        snprintf(buffer, sizeof(buffer), log_format, rnti, crc_flag);
        fprintf(log_file, "%s\n", buffer);

        pthread_mutex_unlock(&mutex);
    }

    fclose(log_file);
    pthread_mutex_destroy(&mutex);

    return pdu_array;
}

void free_nfaapi_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu_array) {
    if (pdu_array) {
        free(pdu_array);
    }
}
