#define MAX_SIB1_PERIODICITY 32

typedef struct LTE_ENB_CONFIG_RRC {
    int CELL_ID;
    int TAC;
    int PCI;
    int SIB1_PERIODICITY;
} LTE_ENB_CONFIG_RRC_T;

typedef struct ListNode {
    LTE_ENB_CONFIG_RRC_T data;
    struct ListNode* next;
} ListNode;

typedef struct {
    ListNode* head;
    pthread_mutex_t lock;
} List;

void initializeList(List* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

ListNode* createNode(LTE_ENB_CONFIG_RRC_T data) {
    ListNode* node = (ListNode*)malloc(sizeof(ListNode));
    if (node == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    node->data = data;
    node->next = NULL;
    return node;
}

void addNode(List* list, LTE_ENB_CONFIG_RRC_T data) {
    pthread_mutex_lock(&list->lock);
    ListNode* newNode = createNode(data);
    if (list->head == NULL) {
        list->head = newNode;
    } else {
        ListNode* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
    pthread_mutex_unlock(&list->lock);
}

void removeNode(List* list, int CELL_ID) {
    pthread_mutex_lock(&list->lock);
    ListNode* current = list->head;
    ListNode* prev = NULL;
    while (current != NULL && current->data.CELL_ID != CELL_ID) {
        prev = current;
        current = current->next;
    }
    if (current != NULL) {
        if (prev == NULL) {
            list->head = current->next;
        } else {
            prev->next = current->next;
        }
        free(current);
    }
    pthread_mutex_unlock(&list->lock);
}

void updateNode(List* list, int CELL_ID, int newSIB1_PERIODICITY) {
    pthread_mutex_lock(&list->lock);
    ListNode* current = list->head;
    while (current != NULL && current->data.CELL_ID != CELL_ID) {
        current = current->next;
    }
    if (current != NULL) {
        current->data.SIB1_PERIODICITY = newSIB1_PERIODICITY;
    }
    pthread_mutex_unlock(&list->lock);
}

void iterateList(List* list, void (*updateFunc)(LTE_ENB_CONFIG_RRC_T*)) {
    pthread_mutex_lock(&list->lock);
    ListNode* current = list->head;
    while (current != NULL) {
        updateFunc(&current->data);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void logOperation(const char* operation, int CELL_ID) {
    FILE* logFile = fopen("log.txt", "a");
    if (logFile == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(logFile, "%s - %d\n", ctime(&now), CELL_ID);
    fclose(logFile);
}

void freeList(List* list) {
    pthread_mutex_lock(&list->lock);
    ListNode* current = list->head;
    while (current != NULL) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
