#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    int size;
    pthread_mutex_t lock;
} List;

List* list_create(int max_elements) {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;

    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void list_destroy(List* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int list_insert(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list->size >= 1000) return -1; // Max elements check
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -2; // Memory allocation failure

    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->size++;
    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

int list_remove(List* list, int index) {
    if (index < 0 || index >= list->size) return -1; // Invalid index

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* prev = NULL;

    for (int i = 0; i < index; i++) {
        prev = current;
        current = current->next;
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    if (current == list->tail) {
        list->tail = prev;
    }

    free(current);
    list->size--;
    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

NFAPI_CRC_INDICATION_PDU_T list_get(List* list, int index) {
    if (index < 0 || index >= list->size) {
        NFAPI_CRC_INDICATION_PDU_T empty = {0};
        return empty; // Invalid index
    }

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    for (int i = 0; i < index; i++) {
        current = current->next;
    }
    NFAPI_CRC_INDICATION_PDU_T data = current->data;
    pthread_mutex_unlock(&list->lock);

    return data;
}
