        memory_free(list->pdu_list);
        memory_free(list);
    }
}

bool add_to_crc_indication_list(CRC_INDICATION_LIST *list, const RX_UE_INFORMATION_TAG *rx_tag, RNTI rnti, const CRC_INDICATION_REL8_TAG *crc_tag) {
    if (list->list_size == list->allocated_size) {
        size_t new_capacity = list->allocated_size ? list->allocated_size * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_list = memory_realloc(list->pdu_list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            log_error("Failed to reallocate memory for PDU list");
            return false;
        }
        list->pdu_list = new_list;
        list->allocated_size = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_pdu = &list->pdu_list[list->list_size];
    memcpy(&new_pdu->rx_tag, rx_tag, sizeof(NFAPI_RX_UE_INFORMATION_TAG));
    new_pdu->rnti = rnti;
    memcpy(&new_pdu->crc_tag, crc_tag, sizeof(NFAPI_CRC_INDICATION_REL8_TAG));

    list->list_size++;
    return true;
}

bool remove_duplicate_rntis(CRC_INDICATION_LIST *list) {
    bool modified = false;
    for (size_t i = 0; i < list->list_size - 1; i++) {
        for (size_t j = i + 1; j < list->list_size; j++) {
            if (list->pdu_list[i].rnti == list->pdu_list[j].rnti) {
                memmove(&list->pdu_list[j], &list->pdu_list[j + 1], (list->list_size - j - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                list->list_size--;
                modified = true;
            }
        }
    }
    return modified;
}
