#define MAX_CAPACITY 10000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct List {
    Node* head;
    Node* tail;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} List;

void initList(List* list) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    list->capacity = MAX_CAPACITY;
    pthread_mutex_init(&list->lock, NULL);
}

int addToList(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) {
        Node* newNode = malloc(sizeof(Node));
        if (!newNode) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Allocation failure
        }
        newNode->data = data;
        newNode->next = NULL;
        newNode->prev = list->tail;

        if (list->tail) {
            list->tail->next = newNode;
        } else {
            list->head = newNode;
        }

        list->tail = newNode;
        list->size++;
    } else {
        Node* newNode = malloc(sizeof(Node));
        if (!newNode) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Allocation failure
        }
        newNode->data = data;
        newNode->next = list->head;
        newNode->prev = NULL;

        if (list->head) {
            list->head->prev = newNode;
        } else {
            list->tail = newNode;
        }

        list->head = newNode;
        list->size++;
    }
    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Additional functions for deletion, resizing, monitoring, and logging can be implemented here

int main() {
    List myList;
    initList(&myList);

    // Test the addToList function with edge cases
    NFAPI_CRC_INDICATION_PDU_T pdu;
    for (size_t i = 0; i < MAX_CAPACITY + 1; ++i) {
        if (addToList(&myList, pdu) != 0) {
            printf("Failed to add element %zu\n", i);
        }
    }

    // Clean up resources
    Node* current = myList.head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&myList.lock);

    return 0;
}
