typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Structure fields
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    Node* tail;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} LinkedList;

void initList(LinkedList* list, size_t initialCapacity) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    list->capacity = initialCapacity;
    pthread_mutex_init(&list->mutex, NULL);
}

int addElement(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    if (list->size >= list->capacity) {
        size_t newCapacity = list->capacity * 2;
        Node** newNodes = realloc(list->head, newCapacity * sizeof(Node));
        if (!newNodes) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Allocation failure
        }
        list->head = newNodes;
        list->tail = &newNodes[list->size];
        list->capacity = newCapacity;
    }

    Node* newNode = &list->head[list->size++];
    newNode->data = data;
    newNode->prev = list->tail;
    if (list->tail) {
        list->tail->next = newNode;
    }
    list->tail = newNode;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void deleteElement(LinkedList* list, Node* node) {
    pthread_mutex_lock(&list->mutex);
    if (node->prev) {
        node->prev->next = node->next;
    } else {
        list->head = node->next;
    }
    if (node->next) {
        node->next->prev = node->prev;
    } else {
        list->tail = node->prev;
    }
    free(node);
    pthread_mutex_unlock(&list->mutex);
}

void* threadFunction(void* arg) {
    LinkedList* list = (LinkedList*)arg;
    // Perform operations on the list
    return NULL;
}

int main() {
    LinkedList list;
    initList(&list, 100);

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, threadFunction, &list);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
