#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_SESSIONS 1000000
#define INITIAL_BUCKET_SIZE 16
#define GROWTH_FACTOR 2

typedef struct {
    char session_id[32];
    char ip_address[16];
    time_t last_active;
} Session;

typedef struct {
    Session* sessions[MAX_SESSIONS];
    int count;
    int capacity;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table() {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    table->count = 0;
    table->capacity = INITIAL_BUCKET_SIZE;
    for (int i = 0; i < table->capacity; i++) {
        table->sessions[i] = NULL;
    }
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void destroy_hash_table(HashTable* table) {
    for (int i = 0; i < table->capacity; i++) {
        if (table->sessions[i]) {
            free(table->sessions[i]);
        }
    }
    pthread_mutex_destroy(&table->lock);
    free(table);
}

unsigned int hash_function(const char* session_id, int capacity) {
    unsigned int hash = 0;
    for (int i = 0; session_id[i] != '\0'; i++) {
        hash = (hash * 31 + session_id[i]) % capacity;
    }
    return hash;
}

void resize_hash_table(HashTable* table) {
    Session** old_sessions = table->sessions;
    int old_capacity = table->capacity;
    table->capacity *= GROWTH_FACTOR;
    table->sessions = (Session**)malloc(table->capacity * sizeof(Session*));
    if (!table->sessions) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < table->capacity; i++) {
        table->sessions[i] = NULL;
    }

    pthread_mutex_lock(&table->lock);
    for (int i = 0; i < old_capacity; i++) {
        if (old_sessions[i]) {
            unsigned int new_index = hash_function(old_sessions[i]->session_id, table->capacity);
            while (table->sessions[new_index] != NULL) {
                new_index = (new_index + 1) % table->capacity;
            }
            table->sessions[new_index] = old_sessions[i];
        }
    }
    pthread_mutex_unlock(&table->lock);

    free(old_sessions);
}

void insert_session(HashTable* table, Session* session) {
    if (table->count >= table->capacity * 0.75) {
        resize_hash_table(table);
    }

    unsigned int index = hash_function(session->session_id, table->capacity);
    while (table->sessions[index] != NULL) {
        index = (index + 1) % table->capacity;
    }
    pthread_mutex_lock(&table->lock);
    table->sessions[index] = session;
    table->count++;
    pthread_mutex_unlock(&table->lock);
}

Session* find_session(HashTable* table, const char* session_id) {
    unsigned int index = hash_function(session_id, table->capacity);
    while (table->sessions[index] != NULL && strcmp(table->sessions[index]->session_id, session_id) != 0) {
        index = (index + 1) % table->capacity;
    }
    return table->sessions[index];
}

void delete_session(HashTable* table, const char* session_id) {
    unsigned int index = hash_function(session_id, table->capacity);
    while (table->sessions[index] != NULL && strcmp(table->sessions[index]->session_id, session_id) != 0) {
        index = (index + 1) % table->capacity;
    }
    if (table->sessions[index]) {
        pthread_mutex_lock(&table->lock);
        free(table->sessions[index]);
        table->sessions[index] = NULL;
        table->count--;
        pthread_mutex_unlock(&table->lock);
    }
}

int main() {
    HashTable* table = create_hash_table();

    Session* session1 = (Session*)malloc(sizeof(Session));
    strcpy(session1->session_id, "12345");
    strcpy(session1->ip_address, "192.168.1.1");
    session1->last_active = time(NULL);
    insert_session(table, session1);

    Session* found_session = find_session(table, "12345");
    if (found_session) {
        printf("Found session with ID: %s\n", found_session->session_id);
    }

    delete_session(table, "12345");

    destroy_hash_table(table);
    return 0;
}
