    pthread_mutex_t mutex;
} LTE_DL_FRAME_BUFFER;

LTE_DL_FRAME_BUFFER *lte_dl_frame_buffer_init(size_t initial_size) {
    LTE_DL_FRAME_BUFFER *buffer = (LTE_DL_FRAME_BUFFER *)malloc(sizeof(LTE_DL_FRAME_BUFFER));
    if (!buffer) return NULL;

    buffer->msgs = (LTE_DL_FRAME_MSG *)calloc(initial_size, sizeof(LTE_DL_FRAME_MSG));
    if (!buffer->msgs) {
        free(buffer);
        return NULL;
    }

    buffer->size = initial_size;
    pthread_mutex_init(&buffer->mutex, NULL);

    return buffer;
}

void lte_dl_frame_buffer_add_msg(LTE_DL_FRAME_BUFFER *buffer, LTE_DL_FRAME_MSG msg) {
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->msgs == NULL) {
        pthread_mutex_unlock(&buffer->mutex);
        fprintf(stderr, "Buffer not initialized\n");
        return;
    }

    for (size_t i = 0; i < buffer->size; ++i) {
        if (buffer->msgs[i].UE_ID == -1) { // Assuming -1 is an invalid UE_ID
            buffer->msgs[i] = msg;
            pthread_mutex_unlock(&buffer->mutex);
            return;
        }
    }

    // Handle overflow gracefully, e.g., by resizing the buffer or logging an error
    fprintf(stderr, "Buffer overflow\n");
    pthread_mutex_unlock(&buffer->mutex);
}

void lte_dl_frame_buffer_free(LTE_DL_FRAME_BUFFER *buffer) {
    if (buffer->msgs) free(buffer->msgs);
    pthread_mutex_destroy(&buffer->mutex);
    free(buffer);
}
