#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 10

typedef struct {
    MAC_PDU_T tag;
    uint8_t ci;
    size_t sdu_size;
} MAC_PDU;

typedef struct {
    MAC_PDU *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* dynamic_array_init() {
    DynamicArray *da = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!da) return NULL;

    da->array = (MAC_PDU*)calloc(INITIAL_CAPACITY, sizeof(MAC_PDU));
    if (!da->array) {
        free(da);
        return NULL;
    }

    da->capacity = INITIAL_CAPACITY;
    da->size = 0;
    pthread_mutex_init(&da->mutex, NULL);

    return da;
}

void dynamic_array_free(DynamicArray *da) {
    if (da->array) {
        free(da->array);
    }
    pthread_mutex_destroy(&da->mutex);
    free(da);
}

int dynamic_array_add(DynamicArray *da) {
    pthread_mutex_lock(&da->mutex);

    // Check for capacity and resize if necessary
    if (da->size >= da->capacity) {
        size_t new_capacity = da->capacity * 2;
        MAC_PDU *new_array = (MAC_PDU*)realloc(da->array, new_capacity * sizeof(MAC_PDU));
        if (!new_array) {
            pthread_mutex_unlock(&da->mutex);
            return -1;
        }

        da->array = new_array;
        da->capacity = new_capacity;
    }

    // Initialize new PDU with random CI and SDU size
    MAC_PDU *new_pdu = &da->array[da->size];
    new_pdu->tag = 0x01; // Example tag
    new_pdu->ci = rand() % 256; // Random CI between 0 and 255
    new_pdu->sdu_size = (rand() % 1024) + 1; // Random SDU size between 1 and 1024

    da->size++;
    pthread_mutex_unlock(&da->mutex);

    return 0;
}

// Example usage
int main() {
    srand(time(NULL)); // Seed for random number generation
    DynamicArray *array = dynamic_array_init();

    if (array) {
        for (int i = 0; i < 20; i++) {
            dynamic_array_add(array);
        }

        dynamic_array_free(array);
    }

    return 0;
}
```

### Explanation of Key Points:
1. **Dynamic Array Initialization and Freeing**: The `dynamic_array_init` function initializes the array with a predefined capacity and mutex for thread safety. The `dynamic_array_free` function cleans up all allocated resources.
2. **Thread Safety**: A mutex is used to ensure that only one thread can modify the array at a time, preventing race conditions.
3. **Memory Management**: When adding elements, the code checks if the current capacity is sufficient. If not, it doubles the capacity using `realloc`. This approach minimizes memory reallocation by avoiding frequent allocations and deallocations.
4. **Ease of Integration**: The function design avoids introducing new data structures or interfaces, allowing easy integration with existing network protocol stacks.
5. **Scalability**: By doubling the capacity when necessary, the solution ensures efficient use of memory under conditions where frequent additions are expected.

This code provides a robust foundation for managing dynamic arrays in a multithreaded environment while ensuring good performance and memory efficiency.']

