typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *buffer;
    int size;
    int count;
    pthread_mutex_t mutex;
} CRC_LIST_T;

void init_crc_list(CRC_LIST_T *list, int initial_size) {
    list->buffer = malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size = initial_size;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

int add_to_crc_list(CRC_LIST_T *list, RX_UE_INFORMATION_TAG rx_tag, CRC_INDICATION_REL8_TAG crc_tag) {
    pthread_mutex_lock(&list->mutex);

    if (list->count >= list->size) {
        NFAPI_CRC_INDICATION_PDU_T *new_buffer = realloc(list->buffer, 2 * list->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_buffer) {
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }
        list->buffer = new_buffer;
        list->size *= 2;
    }

    list->buffer[list->count].rx_tag = rx_tag;
    list->buffer[list->count].crc_tag = crc_tag;
    list->count++;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void destroy_crc_list(CRC_LIST_T *list) {
    free(list->buffer);
    pthread_mutex_destroy(&list->mutex);
