typedef struct {
    int id;
    time_t timestamp;
    char type[50];
    char metadata[256];
} NetworkEvent;

typedef struct Node {
    NetworkEvent event;
    struct Node* next;
} EventNode;

typedef struct {
    EventNode* head;
    size_t count;
} EventList;

void initEventList(EventList* list) {
    list->head = NULL;
    list->count = 0;
}

int addEvent(EventList* list, NetworkEvent event) {
    // Check for duplicate events based on id and timestamp
    for (EventNode* current = list->head; current != NULL; current = current->next) {
        if (current->event.id == event.id && current->event.timestamp == event.timestamp) {
            return 1; // Duplicate event found
        }
    }

    EventNode* newNode = (EventNode*)malloc(sizeof(EventNode));
    if (newNode == NULL) {
        return -1; // Memory allocation failed
    }
    newNode->event = event;
    newNode->next = list->head;
    list->head = newNode;
    list->count++;
    return 0; // Event added successfully
}

void freeEventList(EventList* list) {
    while (list->head != NULL) {
        EventNode* temp = list->head;
        list->head = list->head->next;
        free(temp);
    }
    list->count = 0;
}

// Additional functions for reporting, logging, and integrating with other systems can be added here

int main() {
    // Example usage
    EventList eventList;
    initEventList(&eventList);

    NetworkEvent event1 = {1, time(NULL), "Connection", "200 OK"};
    NetworkEvent event2 = {2, time(NULL), "Error", "Timeout"};

    addEvent(&eventList, event1);
    addEvent(&eventList, event2);

    // Clean up
    freeEventList(&eventList);

    return 0;
}
