#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ENTITIES 1024

typedef enum {
    STATUS_ACTIVE,
    STATUS_INACTIVE,
    STATUS_EXPIRED
} Status;

typedef struct NetworkEntity {
    int id;
    Status status;
    time_t timeout;
    pthread_cond_t cond;
} NetworkEntity;

typedef struct DynamicList {
    NetworkEntity entities[MAX_ENTITIES];
    int count;
    pthread_mutex_t mutex;
    pthread_cond_t list_updated;
} DynamicList;

void initDynamicList(DynamicList *list) {
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->list_updated, NULL);
}

int addEntity(DynamicList *list, int id, time_t timeout) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= MAX_ENTITIES) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // List is full
    }
    NetworkEntity *entity = &list->entities[list->count++];
    entity->id = id;
    entity->status = STATUS_ACTIVE;
    entity->timeout = timeout;
    pthread_cond_init(&entity->cond, NULL);
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void updateStatus(DynamicList *list) {
    pthread_mutex_lock(&list->mutex);
    time_t now = time(NULL);
    for (int i = 0; i < list->count; ++i) {
        if (list->entities[i].timeout <= now && list->entities[i].status != STATUS_EXPIRED) {
            list->entities[i].status = STATUS_EXPIRED;
            pthread_cond_signal(&list->entities[i].cond);
        }
    }
    pthread_mutex_unlock(&list->mutex);
    pthread_cond_broadcast(&list->list_updated);
}

void removeEntity(DynamicList *list, int id) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; ++i) {
        if (list->entities[i].id == id) {
            list->entities[i] = list->entities[--list->count];
            pthread_cond_signal(&list->entities[list->count].cond); // Notify the new last entity
            break;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

// External data source integration function
void fetchNetworkStatus(DynamicList *list) {
    // Simulate fetching and updating status from an external data source
    updateStatus(list);
}

// Unit tests (to be implemented in a separate test file)
```

This code provides a basic structure for managing a dynamic list of network entities with thread-safe operations. It includes functions to initialize the list, add entities, update their statuses based on expiration, and remove entities. The `updateStatus` function simulates fetching current network statuses from an external data source. Unit tests should be added in a separate test file to validate the functionality under different scenarios, including high concurrency and large-scale data handling.']

