    if (arr->count >= arr->capacity) {
        size_t new_capacity = arr->capacity ? arr->capacity * 2 : 1;
        void *new_memory = realloc(arr->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_memory) {
            pthread_mutex_unlock(&arr->mutex);
            return -1;
        }
        arr->array = (NFAPI_CRC_INDICATION_PDU_T *)new_memory;
        arr->capacity = new_capacity;
    }
    arr->array[arr->count++] = pdu;
    pthread_mutex_unlock(&arr->mutex);
    return 0;
}

