    *size = 0;
    LTE_UESRVCC_INFO_GUTI_REL15_T** array = NULL;
    return array;
}

int add_entry(LTE_UESRVCC_INFO_GUTI_REL15_T** array, int* size, uint64_t guti, uint32_t stmsi, int erab_id) {
    // Check for valid GUTI and S-TMSI values
    if (guti < MIN_GUTI || guti > MAX_GUTI || stmsi <= 0) {
        return -1; // Invalid input
    }

    // Check if S-TMSI is unique
    for (int i = 0; i < *size; i++) {
        if ((*array)[i].stmsi == stmsi) {
            return -2; // Duplicate S-TMSI
        }
    }

    // Resize array dynamically if needed
    LTE_UESRVCC_INFO_GUTI_REL15_T** new_array = realloc(*array, (*size + 1) * sizeof(LTE_UESRVCC_INFO_GUTI_REL15_T*));
    if (new_array == NULL) {
        return -3; // Memory allocation failed
    }
    *array = new_array;

    // Allocate memory for ERAB_IDs and initialize
    (*array)[*size] = malloc(sizeof(LTE_UESRVCC_INFO_GUTI_REL15_T));
    if ((*array)[*size] == NULL) {
        return -4; // Memory allocation failed
    }
    (*array)[*size]->guti = guti;
    (*array)[*size]->stmsi = stmsi;
    (*array)[*size]->erab_ids = malloc(sizeof(int));
    if ((*array)[*size]->erab_ids == NULL) {
