#include <pthread.h>
#include <stdbool.h>

#define MAX_CONNECTIONS 1000

typedef struct {
    int RNTI;
    // Other fields of NFAPI_CRC_INDICATION_PDU_T
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node** buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} HashTable;

HashTable* create_hash_table(size_t capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->buckets = (Node**)calloc(capacity, sizeof(Node*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->capacity = capacity;
    table->size = 0;
    pthread_mutex_init(&table->mutex, NULL);

    return table;
}

void destroy_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        Node* node = table->buckets[i];
        while (node) {
            Node* next = node->next;
            free(node);
            node = next;
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->mutex);
    free(table);
}

size_t hash_function(int RNTI, size_t capacity) {
    return (RNTI * 31) % capacity; // Simplified hash function
}

bool insert(HashTable* table, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&table->mutex);
    size_t index = hash_function(data.RNTI, table->capacity);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&table->mutex);
        return false;
    }

    new_node->data = data;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;
    ++table->size;

    pthread_mutex_unlock(&table->mutex);
    return true;
}

bool delete(HashTable* table, int RNTI) {
    pthread_mutex_lock(&table->mutex);
    size_t index = hash_function(RNTI, table->capacity);

    Node** node_ptr = &table->buckets[index];
    while (*node_ptr) {
        if ((*node_ptr)->data.RNTI == RNTI) {
            Node* to_delete = *node_ptr;
            *node_ptr = (*node_ptr)->next;
            free(to_delete);
            --table->size;
            pthread_mutex_unlock(&table->mutex);
            return true;
        }
        node_ptr = &(*node_ptr)->next;
    }

    pthread_mutex_unlock(&table->mutex);
    return false;
}

// Additional functions for dynamic generation, concurrent access handling,
// memory optimization, and integration with external systems can be added here.
