NAS_MESSAGE_PDU_T* fetch_nas_message_details() {
    // Hypothetical function to fetch NAS message details asynchronously
    NAS_MESSAGE_PDU_T *message = (NAS_MESSAGE_PDU_T*)malloc(sizeof(NAS_MESSAGE_PDU_T));
    if (message == NULL) {
        return NULL;
    }
    // Simulate fetching data
    message->NAS_MESSAGE_ID = 12345;
    message->SEQUENCE_NUMBER = 67890;
    message->MESSAGE_DATA = strdup("Sample Data");
    return message;
}

void process_nas_message_queue(MessageQueue *queue) {
    pthread_mutex_lock(&queue->lock);
    MessageQueueNode *current = queue->head;
    while (current != NULL) {
        NAS_MESSAGE_PDU_T *message = &current->message;

        // Simulate error validation
        if (message->NAS_MESSAGE_ID <= 0 || message->SEQUENCE_NUMBER < 0) {
            fprintf(stderr, "Invalid message ID or sequence number\n");
            free(current->message.MESSAGE_DATA);
            MessageQueueNode *temp = current;
            current = current->next;
            queue->head = current;
            if (current == NULL) {
                queue->tail = NULL;
            }
            free(temp);
            continue;
        }

        // Simulate sequence number consistency check
        static int last_sequence_number = -1;
        if (last_sequence_number != -1 && message->SEQUENCE_NUMBER <= last_sequence_number) {
            fprintf(stderr, "Sequence number out of order\n");
            free(current->message.MESSAGE_DATA);
            MessageQueueNode *temp = current;
            current = current->next;
            queue->head = current;
            if (current == NULL) {
                queue->tail = NULL;
            }
            free(temp);
            continue;
        }
        last_sequence_number = message->SEQUENCE_NUMBER;

        // Simulate data integrity verification
        if (strlen(message->MESSAGE_DATA) < 5) {
            fprintf(stderr, "Message data too short\n");
            free(current->message.MESSAGE_DATA);
            MessageQueueNode *temp = current;
            current = current->next;
            queue->head = current;
            if (current == NULL) {
                queue->tail = NULL;
            }
            free(temp);
            continue;
        }

        // Process message
        printf("Processing NAS message: ID=%d, Sequence=%d, Data=%s\n",
               message->NAS_MESSAGE_ID, message->SEQUENCE_NUMBER, message->MESSAGE_DATA);

        current = current->next;
    }
    pthread_mutex_unlock(&queue->lock);
}

void enqueue_message(MessageQueue *queue, NAS_MESSAGE_PDU_T *message) {
    pthread_mutex_lock(&queue->lock);
    MessageQueueNode *new_node = (MessageQueueNode*)malloc(sizeof(MessageQueueNode));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    new_node->message = *message;
    new_node->next = NULL;

    if (queue->tail == NULL) {
        queue->head = queue->tail = new_node;
    } else {
        queue->tail->next = new_node;
        queue->tail = new_node;
    }
    pthread_mutex_unlock(&queue->lock);
}

int main() {
    MessageQueue queue = { .lock = PTHREAD_MUTEX_INITIALIZER };
    NAS_MESSAGE_PDU_T *message;

    while ((message = fetch_nas_message_details()) != NULL) {
        enqueue_message(&queue, message);
        process_nas_message_queue(&queue);
    }

    return 0;
}
