    NetworkInterface* interface = (NetworkInterface*)malloc(sizeof(NetworkInterface));
    if (interface == NULL) {
        // Handle memory allocation failure
        return NULL;
    }

    interface->socket = socket(AF_INET, SOCK_STREAM, 0);
    if (interface->socket < 0) {
        // Handle socket creation failure
        free(interface);
        return NULL;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);

    if (inet_pton(AF_INET, ip_address, &server_addr.sin_addr) <= 0) {
        // Handle invalid IP address
        close(interface->socket);
        free(interface);
        return NULL;
    }

    if (bind(interface->socket, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        // Handle binding failure
        close(interface->socket);
        free(interface);
        return NULL;
    }

    interface->ip_address = strdup(ip_address);
    interface->port = port;

    return interface;
}

void configure_network_interface(NetworkInterface* interface) {
    if (listen(interface->socket, MAX_CONNECTIONS) < 0) {
        // Handle listening failure
        free(interface->ip_address);
        close(interface->socket);
        free(interface);
        return;
    }

    // Additional configuration steps can be added here
}

