    double value;
};

struct SYSTEM_STATE_RECORD {
    int DEVICE_ID;
    std::string OPERATIONAL_STATUS;
    CONFIGURATION_PARAMETER* parameters;
    int parameterCount;

    SYSTEM_STATE_RECORD(int id) : DEVICE_ID(id), OPERATIONAL_STATUS("UP"), parameterCount(0), parameters(nullptr) {}
    ~SYSTEM_STATE_RECORD() {
        delete[] parameters;
    }
};

// Global variables
std::vector<SYSTEM_STATE_RECORD*> networkInterfaces;
std::mutex mtx;
std::atomic<bool> isEventActive(false);
std::chrono::time_point<std::chrono::system_clock> lastEventTime;

void updateConfigurationParameters(SYSTEM_STATE_RECORD* record) {
    // Simulate updating parameters based on DEVICE_ID
    delete[] record->parameters;
    record->parameterCount = 3;
    record->parameters = new CONFIGURATION_PARAMETER[record->parameterCount];
    record->parameters[0] = {1, record->DEVICE_ID * 1.5};
    record->parameters[1] = {2, record->DEVICE_ID * 2.5};
    record->parameters[2] = {3, record->DEVICE_ID * 3.5};
}

void initializeNetworkState() {
    // Simulate initializing network interfaces
    for (int i = 0; i < 5; ++i) {
        networkInterfaces.push_back(new SYSTEM_STATE_RECORD(i));
    }

    // Start a thread to periodically update configuration parameters
    std::thread parameterUpdateThread([]() {
        while (true) {
            if (!isEventActive && std::chrono::system_clock::now() - lastEventTime >= std::chrono::minutes(15)) {
                std::lock_guard<std::mutex> lock(mtx);
                for (auto& record : networkInterfaces) {
                    updateConfigurationParameters(record);
                }
            }
            std::this_thread::sleep_for(std::chrono::seconds(60));
        }
    });
    parameterUpdateThread.detach();

    // Simulate handling network events asynchronously
    std::thread eventHandlingThread([]() {
        while (true) {
            if (!isEventActive) {
                int event = rand() % 3; // Simulate random event
                isEventActive = true;
                lastEventTime = std::chrono::system_clock::now();

                switch (event) {
                    case 0:
                        std::cout << "Handling NETWORK_TRAFFIC_INCREASE" << std::endl;
                        break;
                    case 1:
                        std::cout << "Handling SYSTEM_OVERLOAD" << std::endl;
                        break;
                    case 2:
                        std::cout << "Handling OUTAGE_RESOLUTION" << std::endl;
                        break;
                }

                // Simulate cooldown period
                std::this_thread::sleep_for(std::chrono::minutes(5));
                isEventActive = false;
            }
        }
    });
    eventHandlingThread.detach();
}

int main() {
    initializeNetworkState();

    // Simulate network traffic for demonstration purposes
    while (true) {
        std::this_thread::sleep_for(std::chrono::seconds(10));
        std::lock_guard<std::mutex> lock(mtx);
        for (auto& record : networkInterfaces) {
            std::cout << "Device " << record->DEVICE_ID << ": Status = " << record->OPERATIONAL_STATUS;
            for (int i = 0; i < record->parameterCount; ++i) {
                std::cout << ", Param " << record->parameters[i].paramId << " = " << record->parameters[i].value;
            }
            std::cout << std::endl;
        }
    }

    return 0;
}
