#include <stdbool.h>

typedef enum {
    PDU_TYPE_DATA,
    PDU_TYPE_CONTROL
} PDU_TYPE;

typedef struct {
    PDU_TYPE type;
    unsigned char data[256];
    int sequenceNumber;
} NFAPI_MESSAGE_T;

typedef struct {
    NFAPI_MESSAGE_T* messages;
    size_t capacity;
    size_t count;
    int currentSequenceNumber;
    int sequenceThreshold;
} MessageManager;

MessageManager* createMessageManager(size_t initialCapacity, int sequenceThreshold) {
    MessageManager* manager = (MessageManager*)malloc(sizeof(MessageManager));
    if (manager == NULL) {
        fprintf(stderr, "Failed to allocate memory for MessageManager\n");
        return NULL;
    }

    manager->messages = (NFAPI_MESSAGE_T*)malloc(initialCapacity * sizeof(NFAPI_MESSAGE_T));
    if (manager->messages == NULL) {
        fprintf(stderr, "Failed to allocate memory for messages\n");
        free(manager);
        return NULL;
    }

    manager->capacity = initialCapacity;
    manager->count = 0;
    manager->currentSequenceNumber = 0;
    manager->sequenceThreshold = sequenceThreshold;

    // Initialize sequence number from external source
    if (!initializeSequenceNumber(&manager->currentSequenceNumber)) {
        fprintf(stderr, "Failed to initialize sequence number\n");
        free(manager->messages);
        free(manager);
        return NULL;
    }

    return manager;
}

void destroyMessageManager(MessageManager* manager) {
    if (manager != NULL) {
        free(manager->messages);
        free(manager);
    }
}

bool addMessage(MessageManager* manager, PDU_TYPE type, const unsigned char* data, size_t dataSize) {
    if (manager == NULL || data == NULL || dataSize > sizeof(NFAPI_MESSAGE_T::data)) {
        return false;
    }

    if (manager->count >= manager->capacity) {
        manager->messages = realloc(manager->messages, 2 * manager->capacity * sizeof(NFAPI_MESSAGE_T));
        if (manager->messages == NULL) {
            fprintf(stderr, "Failed to reallocate memory for messages\n");
            return false;
        }
        manager->capacity *= 2;
    }

    NFAPI_MESSAGE_T* newMessage = &manager->messages[manager->count++];
    newMessage->type = type;
    memcpy(newMessage->data, data, dataSize);
    newMessage->sequenceNumber = manager->currentSequenceNumber++;

    // Check and reset sequence number if necessary
    if (manager->currentSequenceNumber >= manager->sequenceThreshold) {
        if (!resetSequenceNumber(&manager->currentSequenceNumber)) {
            fprintf(stderr, "Failed to reset sequence number\n");
            return false;
        }
    }

