#define SLAB_BLOCK_SIZE 4096
#define SLAB_NUM_BLOCKS 1024

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int rnti;
    // Other fields...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct SlabAllocator {
    void* blocks[SLAB_NUM_BLOCKS];
    size_t block_size;
    pthread_mutex_t lock;
    int free_count;
} SlabAllocator;

SlabAllocator slab_allocator;

void init_slab_allocator() {
    for (int i = 0; i < SLAB_NUM_BLOCKS; ++i) {
        slab_allocator.blocks[i] = malloc(SLAB_BLOCK_SIZE);
        if (!slab_allocator.blocks[i]) {
            fprintf(stderr, "Failed to allocate block %d\n", i);
            exit(1);
        }
    }
    slab_allocator.block_size = SLAB_BLOCK_SIZE;
    pthread_mutex_init(&slab_allocator.lock, NULL);
    slab_allocator.free_count = SLAB_NUM_BLOCKS;
}

void* slab_alloc() {
    pthread_mutex_lock(&slab_allocator.lock);
    if (slab_allocator.free_count > 0) {
        void* ptr = slab_allocator.blocks[--slab_allocator.free_count];
        pthread_mutex_unlock(&slab_allocator.lock);
        return ptr;
    }
    pthread_mutex_unlock(&slab_allocator.lock);
    // Handle out-of-memory condition...
    return NULL;
}

void slab_free(void* ptr) {
    pthread_mutex_lock(&slab_allocator.lock);
    if (slab_allocator.free_count < SLAB_NUM_BLOCKS) {
        slab_allocator.blocks[slab_allocator.free_count++] = ptr;
        pthread_mutex_unlock(&slab_allocator.lock);
    } else {
        pthread_mutex_unlock(&slab_allocator.lock);
        // Handle allocation failure...
    }
}

// Additional functions for list management, insertion, deletion, etc.
