typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

int init_dynamic_array(DynamicArray *da, size_t initial_size) {
    if (initial_size < 32) initial_size = 32;
    da->array = malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) return -1;
    da->capacity = initial_size;
    da->size = 0;
    pthread_mutex_init(&da->mutex, NULL);
    return 0;
}

int add_element(DynamicArray *da, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, int crc_flag) {
    pthread_mutex_lock(&da->mutex);

    if (da->size >= da->capacity * 0.75) {
        size_t new_capacity = da->capacity * 1.5;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&da->mutex);
            return -1;
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T new_element = {RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG, crc_flag};
    if (new_element.RX_UE_INFORMATION_TAG == 0) new_element.RX_UE_INFORMATION_TAG = 1; // Fallback
    if (new_element.RNTI == 0) new_element.RNTI = 1; // Fallback
    if (new_element.CRC_INDICATION_REL8_TAG == 0) new_element.CRC_INDICATION_REL8_TAG = 1; // Fallback
    da->array[da->size++] = new_element;

    pthread_mutex_unlock(&da->mutex);
    return 0;
}

void destroy_dynamic_array(DynamicArray *da) {
    pthread_mutex_lock(&da->mutex);
    free(da->array);
    pthread_mutex_destroy(&da->mutex);
}
