typedef struct MAC_TransportContext {
    int ID;
    L2_PDU_LIST *pL2PduList;
} MAC_TransportContext;

typedef struct L2_PDU {
    L2_HEADER header;
    char payload[1024]; // Adjust size as needed
    time_t timestamp;
} L2_PDU;

typedef struct L2_PDU_LIST {
    L2_PDU *pdus;
    int count;
    int capacity;
} L2_PDU_LIST;

MAC_TransportContext* initializeMACTransportContexts(int count, int pduCapacity) {
    MAC_TransportContext *contexts = (MAC_TransportContext *)malloc(count * sizeof(MAC_TransportContext));
    if (!contexts) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < count; ++i) {
        contexts[i].ID = i;
        contexts[i].pL2PduList = (L2_PDU_LIST *)malloc(sizeof(L2_PDU_LIST));
        if (!contexts[i].pL2PduList) {
            // Handle memory allocation failure for L2_PDU_LIST
            free(contexts);
            return NULL;
        }

        contexts[i].pL2PduList->pdus = (L2_PDU *)malloc(pduCapacity * sizeof(L2_PDU));
        if (!contexts[i].pL2PduList->pdus) {
            // Handle memory allocation failure for L2_PDU array
            free(contexts[i].pL2PduList);
            free(contexts);
            return NULL;
        }
        contexts[i].pL2PduList->count = 0;
        contexts[i].pL2PduList->capacity = pduCapacity;

        // Initialize L2_PDU entries
        for (int j = 0; j < pduCapacity; ++j) {
            memset(&contexts[i].pL2PduList->pdus[j], 0, sizeof(L2_PDU));
            contexts[i].pL2PduList->pdus[j].timestamp = time(NULL);
        }
    }

    return contexts;
}

// Don't forget to free the allocated memory when it's no longer needed
void freeMACTransportContexts(MAC_TransportContext *contexts, int count) {
    for (int i = 0; i < count; ++i) {
        free(contexts[i].pL2PduList->pdus);
        free(contexts[i].pL2PduList);
    }
    free(contexts);
}
