#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct MemoryNode* next;
} MemoryNode;

typedef struct MemoryPool {
    MemoryNode* freeList;
    MemoryNode* usedList;
    size_t memoryBudget;
    size_t currentMemoryUsage;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* createMemoryPool(size_t budget) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;
    pool->freeList = NULL;
    pool->usedList = NULL;
    pool->memoryBudget = budget;
    pool->currentMemoryUsage = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroyMemoryPool(MemoryPool* pool) {
    MemoryNode* node = pool->freeList;
    while (node != NULL) {
        MemoryNode* next = node->next;
        free(node);
        node = next;
    }
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

NFAPI_CRC_INDICATION_PDU_T* allocatePDU(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->currentMemoryUsage + sizeof(NFAPI_CRC_INDICATION_PDU_T) > pool->memoryBudget) {
        while (pool->freeList != NULL) {
            MemoryNode* node = pool->freeList;
            pool->freeList = node->next;
            free(node);
            pool->currentMemoryUsage -= sizeof(MemoryNode);
        }
    }

    if (pool->currentMemoryUsage + sizeof(NFAPI_CRC_INDICATION_PDU_T) <= pool->memoryBudget) {
        MemoryNode* newNode = (MemoryNode*)malloc(sizeof(MemoryNode));
        if (!newNode) return NULL;
        newNode->next = pool->usedList;
        pool->usedList = newNode;
        pool->currentMemoryUsage += sizeof(MemoryNode);
    } else {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Memory allocation failed
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = &pool->usedList->data;
    pdu->RX_UE_INFORMATION_TAG = rand() % 1000;
    pdu->RNTI = rand() % 256;
    pdu->CRC_INDICATION_REL8_TAG = rand() % 1000;
    pdu->CRCFLAG = rand() % 2;

    pthread_mutex_unlock(&pool->lock);
    return pdu;
}

void deallocatePDU(MemoryPool* pool, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&pool->lock);

    MemoryNode** prev = &pool->usedList;
    MemoryNode* current = pool->usedList;
    while (current != NULL && &current->data != pdu) {
        prev = &current->next;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&pool->lock);
        return; // PDU not found in the used list
    }

    *prev = current->next;

    MemoryNode* newNode = (MemoryNode*)malloc(sizeof(MemoryNode));
    if (!newNode) {
        pthread_mutex_unlock(&pool->lock);
        return; // Failed to allocate memory for freeing
    }
    newNode->data = *pdu;
    newNode->next = pool->freeList;
    pool->freeList = newNode;

    pool->currentMemoryUsage -= sizeof(MemoryNode);

    pthread_mutex_unlock(&pool->lock);
}

void logAllocation(MemoryPool* pool, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Implement logging logic here
}

void logDeallocation(MemoryPool* pool, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Implement logging logic here
}
