typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} CRC_LIST_T;

CRC_LIST_T crc_list;

void log_error(const char *message) {
    fprintf(stderr, "ERROR: %s\n", message);
}

void log_success(const char *message) {
    printf("SUCCESS: %s\n", message);
}

int allocate_element(NFAPI_CRC_INDICATION_PDU_T *element) {
    if (crc_list.count == crc_list.capacity) {
        size_t new_capacity = crc_list.capacity ? crc_list.capacity * 2 : 16;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(crc_list.data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            log_error("Failed to reallocate memory");
            return -1;
        }
        crc_list.data = new_data;
        crc_list.capacity = new_capacity;
    }

    pthread_mutex_lock(&crc_list.mutex);
    crc_list.data[crc_list.count++] = *element;
    pthread_mutex_unlock(&crc_list.mutex);

    return 0;
}

void populate_crc_list(size_t N) {
    pthread_mutex_init(&crc_list.mutex, NULL);
    crc_list.data = malloc(MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_list.data) {
        log_error("Failed to allocate initial memory");
        return;
    }
    crc_list.capacity = MAX_ELEMENTS;
    crc_list.count = 0;

    for (size_t i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T element;
        element.RX_UE_INFORMATION_TAG = rand() % 1000;
        element.RNTI = (unsigned short)(rand() % 65536);
        element.CRC_INDICATION_REL8_TAG = rand() % 2;

        if (allocate_element(&element)) {
            log_error("Failed to allocate memory for element");
            break;
        }
    }

    pthread_mutex_destroy(&crc_list.mutex);
}

void *network_data_transmission(void *arg) {
    // Simulate network data transmission
    sleep(1); // Simulate time taken to transmit data

    return NULL;
}

void persist_to_disk() {
    FILE *file = fopen(FILE_FORMAT, "wb");
    if (!file) {
        log_error("Failed to open file for writing");
        return;
    }

    size_t bytes_written = fwrite(crc_list.data, sizeof(NFAPI_CRC_INDICATION_PDU_T), crc_list.count, file);
    if (bytes_written != crc_list.count) {
        log_error("Failed to write data to file");
    } else {
        log_success("Data persisted to disk successfully");
    }

    fclose(file);
}

void performance_monitoring() {
    clock_t start_time = clock();
    size_t total_memory_used = crc_list.capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    printf("Memory Usage: %zu bytes\n", total_memory_used);
    printf("Processing Time: %f seconds\n", (double)(clock() - start_time) / CLOCKS_PER_SEC);

    // Additional performance monitoring metrics can be added here
}

int main() {
    srand(time(NULL));

    size_t N = 5000; // Example value, can be adjusted based on system memory and requirements

    populate_crc_list(N);
    performance_monitoring();

    pthread_t transmission_thread;
    if (pthread_create(&transmission_thread, NULL, network_data_transmission, NULL) != 0) {
        log_error("Failed to create transmission thread");
    } else {
        pthread_join(transmission_thread, NULL);
    }

    persist_to_disk();

    free(crc_list.data);

    return 0;
}
