    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef enum {
    SUCCESS,
    MEMORY_FAILURE,
    INVALID_INPUT,
    TIMEOUT
} ErrorCode;

typedef struct AllocationNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct AllocationNode* next;
} AllocationNode;

typedef struct {
    AllocationNode* freeList;
    size_t totalAllocated;
    size_t usedMemory;
    pthread_mutex_t lock;
} AllocationPool;

ErrorCode createAllocationPool(AllocationPool** pool, size_t initialSize) {
    *pool = (AllocationPool*)malloc(sizeof(AllocationPool));
    if (*pool == NULL) return MEMORY_FAILURE;

    (*pool)->freeList = NULL;
    (*pool)->totalAllocated = 0;
    (*pool)->usedMemory = 0;
    pthread_mutex_init(&(*pool)->lock, NULL);

    for (size_t i = 0; i < initialSize; ++i) {
        AllocationNode* newNode = (AllocationNode*)malloc(sizeof(AllocationNode));
        if (newNode == NULL) return MEMORY_FAILURE;

        newNode->next = (*pool)->freeList;
        (*pool)->freeList = newNode;
    }

    (*pool)->totalAllocated = initialSize;
    return SUCCESS;
}

ErrorCode allocatePDU(AllocationPool* pool, NFAPI_CRC_INDICATION_PDU_T** pdu) {
    pthread_mutex_lock(&pool->lock);

    if (pool->freeList == NULL) {
        AllocationNode* newNode = (AllocationNode*)malloc(sizeof(AllocationNode));
        if (newNode == NULL) {
            pthread_mutex_unlock(&pool->lock);
            return MEMORY_FAILURE;
        }

        newNode->next = pool->freeList;
        pool->freeList = newNode;
        pool->totalAllocated++;
    }

    AllocationNode* node = pool->freeList;
    *pdu = &node->data;

    pool->freeList = node->next;
    node->next = NULL;
    pool->usedMemory++;

    pthread_mutex_unlock(&pool->lock);
    return SUCCESS;
}

ErrorCode deallocatePDU(AllocationPool* pool, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    AllocationNode* node = (AllocationNode*)pdu;

    pthread_mutex_lock(&pool->lock);

    node->next = pool->freeList;
    pool->freeList = node;
    pool->usedMemory--;

    pthread_mutex_unlock(&pool->lock);
    return SUCCESS;
}

void destroyAllocationPool(AllocationPool** pool) {
    AllocationNode* current = (*pool)->freeList;
    while (current != NULL) {
        AllocationNode* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&(*pool)->lock);
    free(*pool);
    *pool = NULL;
}
