#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_PAYLOAD_SIZE 1024 * 1024 // 1MB
#define MAX_MEMORY_LIMIT (2 * 1024 * 1024) // 2MB

typedef enum {
    PAYLOAD_TYPE_A,
    PAYLOAD_TYPE_B,
    PAYLOAD_TYPE_C
} PayloadType;

typedef struct PacketHeader {
    PayloadType payload_type;
    time_t timestamp;
    unsigned char* payload_data;
    size_t payload_size;
} PacketHeader;

typedef struct PacketCollection {
    PacketHeader** headers;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} PacketCollection;

void init_packet_collection(PacketCollection* collection) {
    collection->headers = NULL;
    collection->count = 0;
    collection->capacity = 0;
    pthread_mutex_init(&collection->lock, NULL);
    pthread_cond_init(&collection->cond, NULL);
}

void destroy_packet_collection(PacketCollection* collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->headers[i]->payload_data);
        free(collection->headers[i]);
    }
    free(collection->headers);
    pthread_mutex_destroy(&collection->lock);
    pthread_cond_destroy(&collection->cond);
}

int add_packet_header(PacketCollection* collection, PayloadType payload_type, const unsigned char* payload_data, size_t payload_size) {
    if (payload_size > MAX_PAYLOAD_SIZE) return -1;

    pthread_mutex_lock(&collection->lock);

    while (collection->count + 1 > collection->capacity && (collection->headers = realloc(collection->headers, sizeof(PacketHeader*) * (collection->capacity * 2))) == NULL) {
        pthread_cond_wait(&collection->cond, &collection->lock);
    }

    PacketHeader* header = malloc(sizeof(PacketHeader));
    if (!header) {
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }
    header->payload_type = payload_type;
    header->timestamp = time(NULL);
    header->payload_data = malloc(payload_size);
    if (!header->payload_data) {
        free(header);
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }
    memcpy(header->payload_data, payload_data, payload_size);
    header->payload_size = payload_size;

    collection->headers[collection->count++] = header;
    pthread_cond_signal(&collection->cond);
    pthread_mutex_unlock(&collection->lock);

    return 0;
}

void iterate_packet_collection(PacketCollection* collection, void (*callback)(PacketHeader*)) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        callback(collection->headers[i]);
    }

    pthread_mutex_unlock(&collection->lock);
}

// Additional functions and structures can be added as needed
