#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ELEMENTS 1024

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

Node* create_list(int N) {
    if (N > MAX_ELEMENTS) {
        printf("Exceeds maximum allowed elements.\n");
        return NULL;
    }

    Node* head = NULL;
    for (int i = 0; i < N; i++) {
        pthread_mutex_lock(&mutex);
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) {
            printf("Memory allocation failed.\n");
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
        pthread_mutex_unlock(&mutex);

        newNode->data.RX_UE_INFORMATION_TAG = i + 1; // Unique tag
        newNode->data.RNTI = (i == 0) ? 1 : head->data.RNTI + 1; // Ensure no two consecutive elements share the same RNTI
        newNode->data.CRC_INDICATION_REL8_TAG = rand() % 2; // Random CRCFLAG

        newNode->next = head;
        head = newNode;

        // Log creation to an external auditing system (not shown)
    }

    return head;
}

void free_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    int N = 10;
    Node* head = create_list(N);
    if (head) {
        printf("List created successfully.\n");
        free_list(head);
    } else {
        printf("Failed to create list.\n");
    }

    return 0;
}
