} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;
    array->elements = NULL;
    array->capacity = 0;
    array->size = 0;
    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    if (array) {
        free(array->elements);
        free(array);
    }
}

int add_element(DynamicArray* array, LTEPHY_RLC_STATUS_PDU_T element) {
    if (!array) return -1;
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 8;
        LTEPHY_RLC_STATUS_PDU_T* new_elements = (LTEPHY_RLC_STATUS_PDU_T*)realloc(array->elements, new_capacity * sizeof(LTEPHY_RLC_STATUS_PDU_T));
        if (!new_elements) return -1;
        array->elements = new_elements;
        array->capacity = new_capacity;
    }
    array->elements[array->size++] = element;
    return 0;
}

int update_element(DynamicArray* array, size_t index, LTEPHY_RLC_STATUS_PDU_T new_value) {
    if (!array || index >= array->size) return -1;
    array->elements[index] = new_value;
    return 0;
}

int remove_element(DynamicArray* array, size_t index) {
    if (!array || index >= array->size) return -1;
    memmove(&array->elements[index], &array->elements[index + 1], (array->size - index - 1) * sizeof(LTEPHY_RLC_STATUS_PDU_T));
    array->size--;
    return 0;
}

void process_external_updates(DynamicArray* array, ExternalDataProcessor* processor) {
