#define MAX_PACKETS 10000

typedef enum {
    PAYLOAD_TYPE_A,
    PAYLOAD_TYPE_B,
    // Add more payload types as needed
} PayloadType;

typedef struct {
    PayloadType type;
    unsigned long timestamp;
    unsigned char *payloadData;
    size_t payloadSize;
} PacketHeader;

typedef struct {
    PacketHeader headers[MAX_PACKETS];
    int count;
    pthread_mutex_t lock;
} NFAPIPacketArray;

void initializeNFAPIPacketArray(NFAPIPacketArray *array) {
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
}

void addPacketCallback(void (*callback)(const PacketHeader *), NFAPIPacketArray *array) {
    pthread_mutex_lock(&array->lock);
    for (int i = 0; i < array->count; i++) {
        callback(&array->headers[i]);
    }
    pthread_mutex_unlock(&array->lock);
}

void addNewPacket(NFAPIPacketArray *array, PayloadType type, unsigned long timestamp, size_t payloadSize) {
    if (array->count >= MAX_PACKETS) return;
    pthread_mutex_lock(&array->lock);
    PacketHeader *newPacket = &array->headers[array->count++];
    newPacket->type = type;
    newPacket->timestamp = timestamp;
    newPacket->payloadData = (unsigned char *)malloc(payloadSize);
    if (newPacket->payloadData == NULL) {
        array->count--; // Rollback allocation
        pthread_mutex_unlock(&array->lock);
        return;
    }
    memset(newPacket->payloadData, 0, payloadSize);
    newPacket->payloadSize = payloadSize;
    pthread_mutex_unlock(&array->lock);
}

void freeNFAPIPacketArray(NFAPIPacketArray *array) {
    for (int i = 0; i < array->count; i++) {
        free(array->headers[i].payloadData);
    }
    pthread_mutex_destroy(&array->lock);
}
```

