void* process_cell_info(void* arg) {
    while (1) {
        sem_wait(&cell_info_sem);
        if (current_element_count == MAX_ELEMENTS) {
            sem_post(&cell_info_sem);
            break;
        }

        int index = __sync_fetch_and_add(&current_element_count, 1);
        if (index >= MAX_ELEMENTS) {
            current_element_count--;
            sem_post(&cell_info_sem);
            continue;
        }

        // Simulate processing time
        usleep(500);

        // Process cell info element
        // Example: Calculate signal strength values

        sem_post(&cell_info_sem);
    }
    return NULL;
}

void init_cell_info_processor() {
    sem_init(&cell_info_sem, 0, CONCURRENCY_LEVEL);
    cell_info_list = (NFAPI_CELL_INFO_PDU_T**)malloc(MAX_ELEMENTS * sizeof(NFAPI_CELL_INFO_PDU_T*));
    for (int i = 0; i < MAX_ELEMENTS; i++) {
        cell_info_list[i] = (NFAPI_CELL_INFO_PDU_T*)malloc(sizeof(NFAPI_CELL_INFO_PDU_T));
    }

    pthread_t threads[CONCURRENCY_LEVEL];
    for (int i = 0; i < CONCURRENCY_LEVEL; i++) {
        pthread_create(&threads[i], NULL, process_cell_info, NULL);
    }
}

void destroy_cell_info_processor() {
    sem_destroy(&cell_info_sem);
    for (int i = 0; i < MAX_ELEMENTS; i++) {
        free(cell_info_list[i]);
    }
    free(cell_info_list);
}

void add_cell_info(int CELL_ID, int PCI, int RSRP, int RSRQ) {
    sem_wait(&cell_info_sem);
    if (current_element_count >= MAX_ELEMENTS) {
        sem_post(&cell_info_sem);
        return;
    }

    int index = __sync_fetch_and_add(&current_element_count, 1);
    cell_info_list[index]->CELL_ID = CELL_ID;
    cell_info_list[index]->PCI = PCI;
    cell_info_list[index]->RSRP = RSRP;
    cell_info_list[index]->RSRQ = RSRQ;

    sem_post(&cell_info_sem);
}
