    void join() { if (thread_.joinable()) thread_.join(); }

private:
    void run() {
        while (!stop_) {
            RequestData request;
            {
                std::unique_lock<std::mutex> lock(mutex_);
                condition_.wait(lock, [this] { return !queue_.empty() || stop_; });
                if (stop_ && queue_.empty()) break;
                request = std::move(queue_.front());
                queue_.pop();
            }
            worker_(request);
        }
    }

    void addRequest(const RequestData& request) {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            queue_.push(request);
        }
        condition_.notify_one();
    }

    std::thread thread_;
    std::function<void(const RequestData&)> worker_;
    std::queue<RequestData> queue_;
    std::mutex mutex_;
    std::condition_variable condition_;
    bool stop_;
};

class ThreadPool {
public:
    ThreadPool(size_t num_workers) : workers_(num_workers), stop_(false) {
        for (size_t i = 0; i < num_workers; ++i) {
            workers_.emplace_back([this](const RequestData& request) { processRequest(request); });
            workers_[i].start();
        }
    }

    ~ThreadPool() {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            stop_ = true;
        }
        condition_.notify_all();
        for (auto& worker : workers_) worker.join();
    }

    void addRequest(const RequestData& request) {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            if (stop_) throw std::runtime_error("ThreadPool is stopped");
            requests_.push(request);
        }
        condition_.notify_one();
    }

private:
    void processRequest(const RequestData& request) {
        auto start = std::chrono::high_resolution_clock::now();
        // Process the request
        auto end = std::chrono::high_resolution_clock::now();
        auto duration = std::chrono::duration_cast<std::chrono::microseconds>(end - start).count();

        // Log the request processing
        logRequest(request, duration);
    }

    void logRequest(const RequestData& request, long duration) {
        // Implement logging logic here
        printf("Request to %s processed in %ld microseconds\n", request.url.c_str(), duration);
    }

    std::vector<WorkerThread> workers_;
    std::queue<RequestData> requests_;
    std::mutex mutex_;
    std::condition_variable condition_;
    bool stop_;
};
