    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* structures[MAX_CONCURRENT_CALLS][MAX_STRUCTURES];
int structure_counts[MAX_CONCURRENT_CALLS] = {0};

void initialize_structures(int call_id, int n) {
    if (call_id < 0 || call_id >= MAX_CONCURRENT_CALLS || n <= 0 || n > MAX_STRUCTURES - structure_counts[call_id]) {
        printf("Invalid parameters for initialization.\n");
        return;
    }

    srand(time(NULL));

    for (int i = 0; i < n; i++) {
        structures[call_id][structure_counts[call_id]] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (structures[call_id][structure_counts[call_id]] == NULL) {
            printf("Memory allocation failed.\n");
            return;
        }

        structures[call_id][structure_counts[call_id]].RX_UE_INFORMATION_TAG = rand() % 1000;
        structures[call_id][structure_counts[call_id]].RNTI = rand() % 256;
        structures[call_id][structure_counts[call_id]].CRC_INDICATION_REL8_TAG = rand() % 1000;
        structures[call_id][structure_counts[call_id]].CRCFLAG = (rand() % 2) << 7; // Randomly generate a compressed CRCFLAG

        structure_counts[call_id]++;
    }

    printf("Structures initialized for call ID: %d\n", call_id);
}

void cleanup_structures(int call_id) {
    if (call_id < 0 || call_id >= MAX_CONCURRENT_CALLS) {
        printf("Invalid call ID.\n");
        return;
    }

    for (int i = 0; i < structure_counts[call_id]; i++) {
        free(structures[call_id][i]);
        structures[call_id][i] = NULL;
    }
    structure_counts[call_id] = 0;

    printf("Structures cleaned up for call ID: %d\n", call_id);
}

int main() {
    int call_id = 0;
    int n = 1000;

    initialize_structures(call_id, n);

    // Simulate processing
    // ...

    cleanup_structures(call_id);

    return 0;
}
