#include <time.h>
#include <pthread.h>

#define MAX_UE_CONTEXTS 1024
#define MAX_MEASUREMENT_REPORTS 64

typedef struct {
    int ue_id;
    int cell_id;
} ServingCell;

typedef struct {
    int timestamp;
    float snr;
} MeasurementReport;

typedef struct {
    ServingCell serving_cells[MAX_SERVING_CELLS];
    MeasurementReport measurement_reports[MAX_MEASUREMENT_REPORTS];
    int num_serving_cells;
    int num_measurement_reports;
    pthread_mutex_t mutex;
} LTEUEContext;

LTEUEContext ue_contexts[MAX_UE_CONTEXTS];

void initialize_ue_context(int ue_id, int cell_id) {
    if (ue_id < 0 || ue_id >= MAX_UE_CONTEXTS) return;
    LTEUEContext *ctx = &ue_contexts[ue_id];
    ctx->ue_id = ue_id;
    ctx->cell_id = cell_id;
    ctx->num_serving_cells = 1;
    ctx->num_measurement_reports = 0;
    pthread_mutex_init(&ctx->mutex, NULL);
}

void add_serving_cell(int ue_id, int cell_id) {
    if (ue_id < 0 || ue_id >= MAX_UE_CONTEXTS) return;
    LTEUEContext *ctx = &ue_contexts[ue_id];
    if (ctx->num_serving_cells >= MAX_SERVING_CELLS) return;
    ctx->serving_cells[ctx->num_serving_cells].cell_id = cell_id;
    ctx->num_serving_cells++;
}

void add_measurement_report(int ue_id, int snr_range_min, int snr_range_max) {
    if (ue_id < 0 || ue_id >= MAX_UE_CONTEXTS) return;
    LTEUEContext *ctx = &ue_contexts[ue_id];
    pthread_mutex_lock(&ctx->mutex);
    if (ctx->num_measurement_reports >= MAX_MEASUREMENT_REPORTS) {
        pthread_mutex_unlock(&ctx->mutex);
        return;
    }
    MeasurementReport report;
    time_t now = time(NULL);
    report.timestamp = (int)now;
    report.snr = snr_range_min + (rand() / (float)RAND_MAX * (snr_range_max - snr_range_min));
    ctx->measurement_reports[ctx->num_measurement_reports] = report;
    ctx->num_measurement_reports++;
    pthread_mutex_unlock(&ctx->mutex);
}

int main() {
    srand(time(NULL));

    initialize_ue_context(0, 1);
    add_serving_cell(0, 2);

    for (int i = 0; i < 50; i++) {
        add_measurement_report(0, -10, 30);
    }

    return 0;
}
