#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Metadata {
    int64_t timestamp;
    int sequence_number;
    int reference_count;
} Metadata;

typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    Metadata meta;
    struct ListNode* next;
} ListNode;

typedef struct CRCList {
    ListNode* head;
    size_t count;
    pthread_mutex_t mutex;
    int crc_enabled;
} CRCList;

void init_crc_list(CRCList* list, int enable_crc) {
    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    list->crc_enabled = enable_crc;
}

void destroy_crc_list(CRCList* list) {
    ListNode* current = list->head;
    while (current != NULL) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
}

int add_to_crc_list(CRCList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
    if (new_node == NULL) {
        perror("Failed to allocate memory for new node");
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    new_node->data = data;
    new_node->meta.timestamp = get_current_timestamp();
    new_node->meta.sequence_number = ++list->count;
    new_node->meta.reference_count = 1;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void update_metadata(CRCList* list, int sequence_number, Metadata new_meta) {
    pthread_mutex_lock(&list->mutex);
    ListNode* current = list->head;
    while (current != NULL) {
        if (current->meta.sequence_number == sequence_number) {
            current->meta = new_meta;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

Metadata get_metadata(CRCList* list, int sequence_number) {
    Metadata meta = {0};
    pthread_mutex_lock(&list->mutex);
    ListNode* current = list->head;
    while (current != NULL) {
        if (current->meta.sequence_number == sequence_number) {
            meta = current->meta;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    return meta;
}

int enable_crc(CRCList* list, int enable) {
    pthread_mutex_lock(&list->mutex);
    int old_state = list->crc_enabled;
    list->crc_enabled = enable;
    pthread_mutex_unlock(&list->mutex);
    return old_state;
}
