typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode* next;
} ListNode;

typedef struct {
    ListNode* head;
    int size;
} DynamicList;

DynamicList* initDynamicList() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->head = NULL;
    list->size = 0;
    return list;
}

void freeDynamicList(DynamicList* list) {
    ListNode* current = list->head;
    while (current) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

void addElementToList(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T newElement) {
    if (list->size >= MAX_STRUCTURES) {
        printf("Error: List has reached its maximum capacity.\n");
        return;
    }

    ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
    if (!newNode) {
        printf("Error: Failed to allocate memory for new node.\n");
        return;
    }

    newNode->data = newElement;
    newNode->next = list->head;
    list->head = newNode;
    list->size++;
}

void printList(DynamicList* list) {
