        newElement.RNTI = rand() % 1024;
        newElement.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
        time(&newElement.timestamp);

        addElementToList(list, newElement);
    }

    printList(list);

    freeDynamicList(list);
    return 0;
}
