NFAPI_CRC_INDICATION_PDU_T* create_and_populate_linked_list(int N, int max_size) {
    if (N > max_size) {
        fprintf(stderr, "Error: List size exceeds maximum allowed size.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *head = NULL;
    NFAPI_CRC_INDICATION_PDU_T **current = &head;

    for (int i = 0; i < N; ++i) {
        *current = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (*current == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory.\n");
            return head;
        }

        int rnti = rand() % (65536 + 1);
        if (rnti < 0 || rnti > 65535) {
            fprintf(stderr, "Error: Generated RNTI is out of valid range. Skipping.\n");
            free(*current);
            continue;
        }

        (*current)->RX_UE_INFORMATION_TAG = i + 1;
        (*current)->RNTI = rnti;
        (*current)->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG

        current = &(*current)->next;
    }
    *current = NULL;

    return head;
}

// Example usage
