    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T *list = create_and_populate_linked_list(10, 100);
    // Process the linked list as needed

    // Free memory
    while (list != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *temp = list;
        list = list->next;
        free(temp);
    }

    return 0;
}
