    int max;

public:
    RandomValueGenerator(int minValue, int maxValue) : min(minValue), max(maxValue) {}

    int GenerateRandomInt() {
        return rand() % (max - min + 1) + min;
    }

    float GenerateRandomFloat() {
        return ((float)rand()) / RAND_MAX * (max - min) + min;
    }

    void ToString(char* buffer, size_t bufferSize) const {
        snprintf(buffer, bufferSize, "Range: [%d, %d]", min, max);
    }
};

NFAPI_CRC_INDICATION_PDU_T* generateNfarecPduList(int numPDUs, int targetNetworkEnvironment, int minRntiGap) {
    if (numPDUs <= 0 || targetNetworkEnvironment < 1 || minRntiGap <= 0) {
        return NULL; // Handle invalid input parameters
    }

    NFAPI_CRC_INDICATION_PDU_T* pduList = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numPDUs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pduList) {
        return NULL; // Handle memory allocation failure
    }

    RandomValueGenerator crcGen(0, 1); // Example range for CRCFLAG

    int currentRnti = 1;
    for (int i = 0; i < numPDUs; ++i) {
        pduList[i].rxUeInfo.rnti = currentRnti;
        pduList[i].crcIndication.crcFlag = crcGen.GenerateRandomInt();

        // Generate next RNTI ensuring minimum gap
        int nextRnti = currentRnti + minRntiGap + (rand() % minRntiGap);
        if (nextRnti > 65535) { // Assuming a maximum RNTI value of 65535
            nextRnti = 1;
        }
        currentRnti = nextRnti;
    }

    return pduList;
}
