    data.RNTI = rand() % (max_rnti - min_rnti + 1) + min_rnti;
    data.CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set to 0 or 1
    return data;
}

Node* create_random_list(int size, int min_rnti, int max_rnti) {
