    srand(time(0));
    for (int i = 0; i < size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T data = generate_random_data(min_rnti, max_rnti);
        insert_node(&head, data);
        log_creation(data);
    }
    return head;
}

