#include <stdlib.h>
#include <stdio.h>

// Define the structure for CRC Indication PDU
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to create a new node with random values
NFAPI_CRC_INDICATION_PDU_T* createNewNode(int RX_UE_INFORMATION_TAG, int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T* newNode = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newNode) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    newNode->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newNode->RNTI = RNTI;
    newNode->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    newNode->next = NULL;
    return newNode;
}

// Function to insert a new node in the list while ensuring uniqueness of RX_UE_INFORMATION_TAG
NFAPI_CRC_INDICATION_PDU_T* insertNode(NFAPI_CRC_INDICATION_PDU_T** head, int RX_UE_INFORMATION_TAG, int RNTI) {
    if (!(*head)) {
        *head = createNewNode(RX_UE_INFORMATION_TAG, RNTI);
        return *head;
    }
    NFAPI_CRC_INDICATION_PDU_T* current = *head;
    while (current->next != NULL && current->RX_UE_INFORMATION_TAG != RX_UE_INFORMATION_TAG) {
        if (current->RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            fprintf(stderr, "Duplicate RX_UE_INFORMATION_TAG found\n");
            return *head; // Duplicate tag found, do not insert
        }
        current = current->next;
    }
    if (current->RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
        fprintf(stderr, "Duplicate RX_UE_INFORMATION_TAG found\n");
        return *head; // Duplicate tag found, do not insert
    }
    NFAPI_CRC_INDICATION_PDU_T* newNode = createNewNode(RX_UE_INFORMATION_TAG, RNTI);
    current->next = newNode;
    return *head;
}

// Function to print the list
void printList(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d\n",
               current->RX_UE_INFORMATION_TAG, current->RNTI, current->CRC_INDICATION_REL8_TAG);
        current = current->next;
    }
}

// Function to free the list
void freeList(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}
