#include <pthread.h>

#define MAX_UE_INDEX 1024
#define BSR_MAX_SIZE 128

typedef struct LTE_PHY_TEST_RX_PDU_T {
    int UE_INDEX;
    float RX_POWER;
    uint8_t BSR_PDU[BSR_MAX_SIZE];
} LTE_PHY_TEST_RX_PDU_T;

typedef struct {
    LTE_PHY_TEST_RX_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} LTE_PHY_LIST_T;

LTE_PHY_LIST_T* create_lte_phy_list() {
    LTE_PHY_LIST_T *list = (LTE_PHY_LIST_T *)malloc(sizeof(LTE_PHY_LIST_T));
    if (!list) return NULL;
    list->data = NULL;
    list->size = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_lte_phy_list(LTE_PHY_LIST_T *list) {
    if (list->data) free(list->data);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_to_list(LTE_PHY_LIST_T *list, LTE_PHY_TEST_RX_PDU_T *pdu) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        LTE_PHY_TEST_RX_PDU_T *new_data = (LTE_PHY_TEST_RX_PDU_T *)realloc(list->data, new_capacity * sizeof(LTE_PHY_TEST_RX_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }
    list->data[list->size++] = *pdu;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void update_rx_power(LTE_PHY_LIST_T *list, float scale_factor) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 1; i < list->size; ++i) {
        list->data[i].RX_POWER *= scale_factor;
    }
    pthread_mutex_unlock(&list->lock);
}
