            current->next = new_node;
        }
        current = new_node;

        // Check for duplicate RNTI
        NFAPI_CRC_INDICATION_PDU_T *temp = head;
        while (temp != new_node) {
            if (temp->RNTI == new_node->RNTI) {
                fprintf(stderr, "Duplicate RNTI detected: %d\n", new_node->RNTI);
