        temp = current;
        current = current->next;
        free(temp);
    }
}

int generate_unique_RNTI(NFAPI_CRC_INDICATION_PDU_T **head) {
    int RNTI;
    do {
        RNTI = rand();
    } while (is_RNTI_duplicate(RNTI, head));

    return RNTI;
}

int is_RNTI_duplicate(int RNTI, NFAPI_CRC_INDICATION_PDU_T *head) {
    NFAPI_CRC_INDICATION_PDU_T *current = head;

    while (current != NULL) {
        if (current->RNTI == RNTI)
            return 1;
        current = current->next;
    }

    return 0;
}
