NFAPI_CRC_INDICATION_PDU_T *allocate_structs(int num_structs) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    static NFAPI_CRC_INDICATION_PDU_T *buffer = NULL;
    static int allocated_count = 0;

    pthread_mutex_lock(&mutex);

    if (num_structs + allocated_count > MAX_STRUCTS) {
        printf("Error: Exceeding maximum number of structures.\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_buffer = realloc(buffer, (allocated_count + num_structs) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_buffer) {
        printf("Error: Memory allocation failed.\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    buffer = new_buffer;

    for (int i = 0; i < num_structs; i++) {
