        buffer[allocated_count + i].RNTI = rand() % 1024;                // Example range
        buffer[allocated_count + i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    allocated_count += num_structs;

    pthread_mutex_unlock(&mutex);
    return buffer;
}

void free_structs() {
