#include <time.h>

// Define the FrameStatistics structure
typedef struct FrameStatistics {
    time_t timestamp;
    int *measurementReports;
    int reportCount;
    int congestionFlag;
} FrameStatistics;

// Function to create a new FrameStatistics node
FrameStatistics* createFrameStatistics(int reportCount) {
    FrameStatistics *node = (FrameStatistics*)malloc(sizeof(FrameStatistics));
    if (!node) {
        return NULL; // Handle memory allocation failure
    }
    node->timestamp = time(NULL);
    node->measurementReports = (int*)malloc(reportCount * sizeof(int));
    if (!node->measurementReports) {
        free(node); // Clean up in case of measurement reports allocation failure
        return NULL;
    }
    node->reportCount = reportCount;
    node->congestionFlag = 0; // Initialize congestion flag to false
    return node;
}

// Function to populate the FrameStatistics node with random data
void populateFrameStatistics(FrameStatistics *node) {
    if (node == NULL || node->measurementReports == NULL) {
        return; // Handle invalid input
    }
    srand(time(NULL)); // Seed for randomness
    for (int i = 0; i < node->reportCount; i++) {
        node->measurementReports[i] = rand(); // Randomly generate measurements
    }
}

// Function to add a FrameStatistics node to the linked list
void addToLinkedList(FrameStatistics **head, FrameStatistics *node) {
    if (node == NULL) {
        return; // Handle invalid input
    }
    node->next = *head;
    *head = node;
}

// Example usage
int main() {
    FrameStatistics *head = NULL;
    int reportCount = 10;

    for (int i = 0; i < 5; i++) { // Create and add multiple nodes
        FrameStatistics *newNode = createFrameStatistics(reportCount);
        if (newNode) {
            populateFrameStatistics(newNode);
            addToLinkedList(&head, newNode);
        }
    }

    // Example of processing the linked list (pseudo-code)
    while (head != NULL) {
        printf("Timestamp: %ld\n", head->timestamp);
        printf("Measurement Reports:\n");
        for (int i = 0; i < head->reportCount; i++) {
            printf("%d ", head->measurementReports[i]);
        }
        printf("\nCongestion Flag: %d\n", head->congestionFlag);
        FrameStatistics *temp = head;
        head = head->next;
        free(temp->measurementReports); // Clean up measurement reports
        free(temp); // Free the node
    }

    return 0;
}
