    new_node->next = NULL;

    total_allocated_memory += sizeof(LTE_NAS_SECURITY_CONTEXT) + DEFAULT_KEY_SIZE;
    return new_node;
}

void add_security_context(uint32_t id, uint32_t version) {
    pthread_mutex_lock(&list_mutex);
    LTE_NAS_SECURITY_CONTEXT *new_node = create_security_context(id, version);
    if (new_node) {
        new_node->next = head;
        head = new_node;
    }
    pthread_mutex_unlock(&list_mutex);
}

void free_security_context(LTE_NAS_SECURITY_CONTEXT *node) {
    free(node->ENCRYPTION_KEY);
    total_allocated_memory -= sizeof(LTE_NAS_SECURITY_CONTEXT) + node->key_size;
    free(node);
}

