    pthread_mutex_lock(&list_mutex);
    LTE_NAS_SECURITY_CONTEXT *current = head;
    while (current) {
        LTE_NAS_SECURITY_CONTEXT *next = current->next;
        free_security_context(current);
        current = next;
    }
    head = NULL;
    pthread_mutex_unlock(&list_mutex);
}

size_t get_total_allocated_memory() {
    return total_allocated_memory;
}
