char* generate_tag(int index) {
    static const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    time_t now = time(NULL);
    srand(now + index); // Seed with current time and index for uniqueness
    char *tag = (char *)malloc(MAX_RX_UE_INFORMATION_TAG_LENGTH * sizeof(char));
    if (tag == NULL) {
        return NULL; // Handle memory allocation failure
    }
    for (int i = 0; i < MAX_RX_UE_INFORMATION_TAG_LENGTH - 1; ++i) {
        tag[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    tag[MAX_RX_UE_INFORMATION_TAG_LENGTH - 1] = '\0';
    return tag;
}

int validate_rnti(int RNTI) {
