NFAPI_CRC_INDICATION_PDU_T* allocate_NFAPI_crc_indication_pdu_array(int N) {
    if (N <= 0) {
        printf("Error: Invalid input value for N. Must be greater than zero.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array == NULL) {
        printf("Memory allocation failed for array of %d elements.\n", N);
        return NULL;
    }

    for (int i = 0; i < N; ++i) {
        char* tag = generate_tag(i);
        if (tag == NULL) {
            printf("Failed to generate unique RX_UE_INFORMATION_TAG for index %d.\n", i);
            // Free previously allocated elements
            for (int j = 0; j < i; ++j) {
                free(array[j].tag);
            }
            free(array);
            return NULL;
        }

        array[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG

        if (!validate_rnti(i)) { // Assuming RNTI is equal to index for simplicity
            printf("Invalid RNTI value for element at index %d. Using zero instead.\n", i);
            array[i].RNTI = 0;
        } else {
            array[i].RNTI = i; // Assign valid RNTI value
        }

        array[i].tag = tag;
    }

    printf("Successfully allocated memory for array of %d elements.\n", N);
    return array;
}

void free_NFAPI_crc_indication_pdu_array(NFAPI_CRC_INDICATION_PDU_T *array, int N) {
    if (array == NULL) {
        printf("Error: Attempted to free a null pointer.\n");
        return;
    }

    for (int i = 0; i < N; ++i) {
        free(array[i].tag);
    }
    free(array);

    printf("Memory freed successfully for array of %d elements.\n", N);
}

// Example usage
