} NFAPI_CRC_INDICATION_PDU_T;

typedef enum CRCFLAG { CRC_OK, CRC_ERROR } CRCFLAG;

typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode* next;
} ListNode;

typedef struct LinkedList {
    ListNode* head;
    pthread_mutex_t mutex;
} LinkedList;

ListNode* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    ListNode* node = (ListNode*)malloc(sizeof(ListNode));
    if (node == NULL) return NULL;
    node->data = data;
    node->next = NULL;
    return node;
}

bool add_entry(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T new_data) {
    pthread_mutex_lock(&list->mutex);
    ListNode* new_node = create_node(new_data);
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return false;
    }

    if (list->head == NULL) {
        list->head = new_node;
    } else {
        ListNode* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    pthread_mutex_unlock(&list->mutex);
    return true;
}

LinkedList* init_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (list == NULL) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void free_list(LinkedList* list) {
    pthread_mutex_lock(&list->mutex);
    ListNode* current = list->head;
    while (current != NULL) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

NFAPI_CRC_INDICATION_PDU_T generate_data() {
    NFAPI_CRC_INDICATION_PDU_T data;
    // Generate RNTI and other fields...
    return data;
}

bool is_valid_crc_flag(CRCFLAG new_flag, CRCFLAG last_flag) {
    // Check if the new flag is different from the last one
    return new_flag != last_flag;
}

LinkedList* populate_list(int N, int max_entries) {
    LinkedList* list = init_list();
    if (list == NULL) return NULL;

    srand(time(NULL)); // Seed for random number generation

    CRCFLAG last_crc_flag = CRC_OK; // Initial flag
    for (int i = 0; i < N && list->head != NULL && list->head->next != NULL && list->head->next->data.RNTI != list->head->data.RNTI; i++) {
        NFAPI_CRC_INDICATION_PDU_T data = generate_data();
        CRCFLAG new_crc_flag = (CRCFLAG)(rand() % 2); // Randomly set CRCFLAG
        if (!is_valid_crc_flag(new_crc_flag, last_crc_flag)) continue;

        data.CRC_INDICATION_REL8_TAG.CRCFLAG = new_crc_flag;
        add_entry(list, data);
        last_crc_flag = new_crc_flag;

        if (list->head != NULL && list->head->next != NULL) {
            if (list->head->data.RNTI == list->head->next->data.RNTI) break;
        }

        if (i >= max_entries - 1) {
            free_list(list);
            return NULL; // Reached maximum entries
        }
    }

    pthread_mutex_lock(&list->mutex);
    ListNode* current = list->head;
    while (current != NULL) {
        ListNode* next = current->next;
        if (next == NULL || current->data.RNTI != next->data.RNTI) {
            free(current);
            current = next;
        } else {
            break;
        }
    }
    pthread_mutex_unlock(&list->mutex);

    return list;
}
