typedef struct MemoryPool {
    void* pool;
    size_t block_size;
    size_t num_blocks;
    size_t free_index;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    pool->free_index = 0;
    pool->pool = malloc(block_size * num_blocks);
    if (!pool->pool) {
        free(pool);
        return NULL;
    }

    return pool;
}

void* memory_pool_alloc(MemoryPool* pool) {
    if (pool->free_index >= pool->num_blocks) return NULL;

    void* block = (char*)pool->pool + (pool->block_size * pool->free_index);
    pool->free_index++;
    return block;
}

void memory_pool_free(MemoryPool* pool, void* block) {
    size_t index = ((char*)block - (char*)pool->pool) / pool->block_size;
    if (index < pool->free_index) {
        pool->free_index = index;
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_cnf_indication_pdu(MemoryPool* pool, int N) {
    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)memory_pool_alloc(pool);
    if (!pdus) return NULL;

    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        pdus[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        pdus[i].RNTI = rand() % 1024;
        pdus[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    return pdus;
}

void free_cnf_indication_pdu(MemoryPool* pool, NFAPI_CRC_INDICATION_PDU_T* pdus) {
