};

void InitializeNode(Node* node) {
    pthread_mutex_init(&node->Lock, NULL);
    node->SID = 0;
    InitializeHead(&node->DataStreamsList);
}

void InitializeHead(Head* head) {
    head->Next = NULL;
}

Node* CreateNetworkInterface() {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for network interface");
        return NULL;
    }
    InitializeNode(new_node);
    return new_node;
}

DataStreamConfig* CreateDataStreamConfig(int StreamID, const char* SessionTag, size_t BufferSize, int FlowControlEnabled) {
