    if (!config) {
        perror("Failed to allocate memory for data stream configuration");
        return NULL;
    }
    config->StreamID = StreamID;
    snprintf(config->SessionTag, sizeof(config->SessionTag), "%s", SessionTag);
    config->BufferSize = BufferSize;
    config->FlowControlEnabled = FlowControlEnabled;
    return config;
}

void AddDataStreamToInterface(Node* interface, DataStreamConfig* config) {
    pthread_mutex_lock(&interface->Lock);
    // Code to add data stream to the interface
    pthread_mutex_unlock(&interface->Lock);
}

void RemoveDataStreamFromInterface(Node* interface, int StreamID) {
    pthread_mutex_lock(&interface->Lock);
    // Code to remove data stream from the interface
    pthread_mutex_unlock(&interface->Lock);
}

void CleanupNetworkInterface(Node* interface) {
    pthread_mutex_destroy(&interface->Lock);
    // Code to clean up all associated resources
    free(interface);
}

