#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_STREAMS 1024

typedef struct {
    char session_tag[64];
    int stream_id;
    size_t buffer_size;
    int flow_control;
} DataStreamConfig;

typedef struct {
    DataStreamConfig *streams;
    int num_streams;
    int max_streams;
    pthread_mutex_t lock;
} NetworkInterface;

NetworkInterface* initialize_network_interface() {
    NetworkInterface *ni = (NetworkInterface*)malloc(sizeof(NetworkInterface));
    if (!ni) {
        perror("Failed to allocate memory for NetworkInterface");
        return NULL;
    }

    ni->max_streams = MAX_STREAMS;
    ni->num_streams = 0;
    ni->streams = (DataStreamConfig*)calloc(ni->max_streams, sizeof(DataStreamConfig));
    if (!ni->streams) {
        perror("Failed to allocate memory for DataStreamConfig list");
        free(ni);
        return NULL;
    }

    pthread_mutex_init(&ni->lock, NULL);
    return ni;
}

void configure_stream(NetworkInterface *ni, const char *session_tag, int stream_id, size_t buffer_size, int flow_control) {
    if (pthread_mutex_lock(&ni->lock)) {
        perror("Failed to lock mutex");
        return;
    }

    if (ni->num_streams >= ni->max_streams) {
        fprintf(stderr, "Maximum number of streams reached\n");
        pthread_mutex_unlock(&ni->lock);
        return;
    }

    DataStreamConfig *stream = &ni->streams[ni->num_streams++];
    strncpy(stream->session_tag, session_tag, sizeof(stream->session_tag) - 1);
    stream->session_tag[sizeof(stream->session_tag) - 1] = '\0';
    stream->stream_id = stream_id;
    stream->buffer_size = buffer_size;
    stream->flow_control = flow_control;

    pthread_mutex_unlock(&ni->lock);
}

void destroy_network_interface(NetworkInterface *ni) {
    if (pthread_mutex_lock(&ni->lock)) {
        perror("Failed to lock mutex");
        return;
    }

    free(ni->streams);
    ni->num_streams = 0;
    pthread_mutex_unlock(&ni->lock);
    pthread_mutex_destroy(&ni->lock);
    free(ni);
}
