} CRC_Indication;

typedef struct {
    UE_Info *ue_info;
    CRC_Indication *crc_indication;
    int size;
    int capacity;
    pthread_mutex_t list_mutex;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_nfaip_pdu_list() {
    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) return NULL;

    list->ue_info = (UE_Info *)calloc(MAX_STRUCTURES, sizeof(UE_Info));
    list->crc_indication = (CRC_Indication *)calloc(MAX_STRUCTURES, sizeof(CRC_Indication));
    if (!list->ue_info || !list->crc_indication) {
        free(list->ue_info);
        free(list->crc_indication);
        free(list);
        return NULL;
    }

    list->size = 0;
    list->capacity = MAX_STRUCTURES;
    pthread_mutex_init(&list->list_mutex, NULL);

    for (int i = 0; i < MAX_STRUCTURES; i++) {
        pthread_mutex_init(&list->crc_indication[i].mutex, NULL);
    }

    return list;
}

void destroy_nfaip_pdu_list(NFAPI_CRC_INDICATION_PDU_T *list) {
    if (!list) return;

    for (int i = 0; i < list->size; i++) {
        pthread_mutex_destroy(&list->crc_indication[i].mutex);
    }

    free(list->ue_info);
    free(list->crc_indication);
    pthread_mutex_destroy(&list->list_mutex);
    free(list);
}

void add_nfaip_pdu(NFAPI_CRC_INDICATION_PDU_T *list, RX_UE_INFORMATION_TAG ue_info, RNTI rnti, CRCFLAG crc_flag) {
    if (!list || list->size >= list->capacity) return;

    pthread_mutex_lock(&list->list_mutex);
    int index = list->size++;

    list->ue_info[index].ue_info = ue_info;
    list->ue_info[index].rnti = rnti;

    pthread_mutex_t *mutex = &list->crc_indication[index].mutex;
    pthread_mutex_init(mutex, NULL);

    list->crc_indication[index].crc_indication.crcflag = crc_flag;
    pthread_mutex_lock(mutex);
    pthread_mutex_unlock(mutex);

    pthread_mutex_unlock(&list->list_mutex);
}

bool get_nfaip_pdu(NFAPI_CRC_INDICATION_PDU_T *list, int index, RX_UE_INFORMATION_TAG *ue_info, RNTI *rnti, CRCFLAG *crc_flag) {
    if (!list || index < 0 || index >= list->size) return false;

    pthread_mutex_lock(&list->list_mutex);
    pthread_mutex_t *mutex = &list->crc_indication[index].mutex;

    pthread_mutex_lock(mutex);

    if (ue_info) *ue_info = list->ue_info[index].ue_info;
    if (rnti) *rnti = list->ue_info[index].rnti;
    if (crc_flag) *crc_flag = list->crc_indication[index].crc_indication.crcflag;

    pthread_mutex_unlock(mutex);
    pthread_mutex_unlock(&list->list_mutex);

    return true;
}
