    pthread_mutex_lock(&collection->mutex);
    if (index >= 0 && index < collection->array_size) {
        collection->indication_array[index] = new_value;
    }
    pthread_mutex_unlock(&collection->mutex);
}

void update_bandwidth_usage(NFAPIDynamicCollection_T* collection, int connection_id, float packet_size) {
    pthread_mutex_lock(&collection->mutex);
    for (int i = 0; i < collection->array_size; i++) {
        if (collection->connection_state_array[i].connection_id == connection_id) {
            collection->connection_state_array[i].bandwidth_usage += packet_size;
            if (collection->connection_state_array[i].bandwidth_usage > TRAFFIC_LIMIT) {
                // Handle traffic limit exceeded
            }
            break;
        }
    }
    pthread_mutex_unlock(&collection->mutex);
}

void handle_overflow(NFAPIDynamicCollection_T* collection) {
    pthread_mutex_lock(&collection->mutex);
    if (is_overflow(collection)) {
        // Handle overflow, e.g., free space or log error
    }
    pthread_mutex_unlock(&collection->mutex);
