}

void destroyMemoryPool(MemoryPool *pool) {
    free(pool->pool_start);
    free(pool);
}

void *allocateFromPool(MemoryPool *pool, size_t size) {
    if (size > pool->block_size - sizeof(DataPacket)) {
        return NULL; // Not enough space for payload
    }

    void *block = (char *)pool->pool_start + pool->blocks_allocated * pool->block_size;
    pool->blocks_allocated++;
    return block;
}

void initializeDataPackets(MemoryPool *pool, DataPacket **packets, int num_packets) {
    for (int i = 0; i < num_packets; i++) {
        packets[i] = (DataPacket *)allocateFromPool(pool, sizeof(DataPacket));
        if (!packets[i]) {
            fprintf(stderr, "Failed to allocate memory for packet %d\n", i);
            continue;
        }

        packets[i]->packet_id = i + 1;
        packets[i]->payload = (char *)allocateFromPool(pool, MAX_PAYLOAD_SIZE);
        if (!packets[i]->payload) {
            fprintf(stderr, "Failed to allocate payload buffer for packet %d\n", i);
            free(packets[i]);
            continue;
        }

        // Initialize payload data and compute checksum
        packets[i]->checksum = calculateChecksum(packets[i]->payload, strlen(packets[i]->payload));
    }
}

unsigned int calculateChecksum(const char *data, size_t length) {
    unsigned int sum = CHECKSUM_SEED;
    for (size_t i = 0; i < length; i++) {
        sum += data[i];
    }
    return sum;
}
```

