#define MAX_MESSAGES 1024
#define CHECKSUM_SIZE 4

typedef enum {
    RRC_TYPE_UNKNOWN,
    RRC_TYPE_CONFIG,
    RRC_TYPE_STATUS,
    // Add more message types as needed
} RRC_MESSAGE_TYPE;

typedef struct {
    RRC_MESSAGE_TYPE type;
    int instance_id;
    unsigned char checksum[CHECKSUM_SIZE];
} NFAPI_RRC_MSG;

NFAPI_RRC_MSG messages[MAX_MESSAGES];
int message_count = 0;
pthread_mutex_t mutex;

void generate_random_message(NFAPI_RRC_MSG *msg) {
    msg->type = (RRC_MESSAGE_TYPE)(rand() % (RRC_TYPE_STATUS + 1));
    msg->instance_id = rand() % 1000; // Random ID for demonstration
}

unsigned int calculate_checksum(const NFAPI_RRC_MSG *msg) {
    unsigned char data[CHECKSUM_SIZE];
    memcpy(data, &msg->type, sizeof(RRC_MESSAGE_TYPE));
    memcpy(&data[sizeof(RRC_MESSAGE_TYPE)], &msg->instance_id, sizeof(int));

    unsigned int checksum = 0;
    for (int i = 0; i < CHECKSUM_SIZE; i++) {
        checksum += data[i];
    }
    return checksum;
}

void verify_message(const NFAPI_RRC_MSG *msg) {
    if (calculate_checksum(msg) != msg->checksum[0]) {
        printf("Checksum error detected!\n");
    } else {
        printf("Message verified successfully.\n");
    }
}

void* insert_messages(void *arg) {
    int count = *(int*)arg;
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < count; i++) {
        if (message_count < MAX_MESSAGES) {
            NFAPI_RRC_MSG msg;
            generate_random_message(&msg);
            msg.checksum[0] = calculate_checksum(&msg);
            messages[message_count++] = msg;
        } else {
            printf("No more space to insert messages.\n");
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

int main() {
    srand(time(NULL));
    pthread_t threads[4];
    int thread_counts[] = {256, 256, 256, 256};

    pthread_mutex_init(&mutex, NULL);

    for (int i = 0; i < 4; i++) {
        if (pthread_create(&threads[i], NULL, insert_messages, &thread_counts[i]) != 0) {
            printf("Failed to create thread %d.\n", i);
        }
    }

    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }

    for (int i = 0; i < message_count; i++) {
        verify_message(&messages[i]);
    }

    pthread_mutex_destroy(&mutex);

    return 0;
}
