#include <time.h>

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T data;
    uint32_t sequence_number;
    timestamp_t timestamp;
} CircularBufferElement;

typedef struct {
    CircularBufferElement *buffer;
    size_t max_size;
    size_t head;
    size_t tail;
    size_t count;
    pthread_mutex_t mutex;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} CircularBuffer;

CircularBuffer* create_circular_buffer(size_t max_size) {
    CircularBuffer *cb = malloc(sizeof(CircularBuffer));
    if (!cb) return NULL;

    cb->buffer = malloc(max_size * sizeof(CircularBufferElement));
    if (!cb->buffer) {
        free(cb);
        return NULL;
    }

    cb->max_size = max_size;
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
    pthread_mutex_init(&cb->mutex, NULL);
    pthread_cond_init(&cb->not_full, NULL);
    pthread_cond_init(&cb->not_empty, NULL);

    return cb;
}

void destroy_circular_buffer(CircularBuffer *cb) {
    free(cb->buffer);
    pthread_mutex_destroy(&cb->mutex);
    pthread_cond_destroy(&cb->not_full);
    pthread_cond_destroy(&cb->not_empty);
    free(cb);
}

int add_to_buffer(CircularBuffer *cb, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&cb->mutex);

    while (cb->count == cb->max_size) {
        pthread_cond_wait(&cb->not_full, &cb->mutex);
    }

    CircularBufferElement element;
    element.data = data;
    element.sequence_number = ++cb->sequence_number;
    clock_gettime(CLOCK_MONOTONIC, &element.timestamp);

    cb->buffer[cb->tail] = element;
    cb->tail = (cb->tail + 1) % cb->max_size;
    cb->count++;

    pthread_cond_signal(&cb->not_empty);
    pthread_mutex_unlock(&cb->mutex);

    return 0;
}

int remove_from_buffer(CircularBuffer *cb, NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&cb->mutex);

    while (cb->count == 0) {
        pthread_cond_wait(&cb->not_empty, &cb->mutex);
    }

    *data = cb->buffer[cb->head];
    cb->head = (cb->head + 1) % cb->max_size;
    cb->count--;

    pthread_cond_signal(&cb->not_full);
    pthread_mutex_unlock(&cb->mutex);

    return 0;
}
