#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>

typedef struct {
    char RX_UE_INFORMATION_TAG[256];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[10];
} NFAPI_CRC_INDICATION_PDU_T;

void populateRxIndicationsAndResolveDNS(NFAPI_CRC_INDICATION_PDU_T *indicators, int count) {
    for (int i = 0; i < count; ++i) {
        // Simulate setting RX_UE_INFORMATION_TAG and RNTI
        snprintf(indicators[i].RX_UE_INFORMATION_TAG, sizeof(indicators[i].RX_UE_INFORMATION_TAG), "UE-%d", i);
        indicators[i].RNTI = 100 + i;

        // Set a random CRCFLAG
        snprintf(indicators[i].CRC_INDICATION_REL8_TAG, sizeof(indicators[i].CRC_INDICATION_REL8_TAG), "%d", (rand() % 2 == 0) ? 1 : 0);

        // Resolve DNS for the hostname using asynchronous resolution
        struct addrinfo hints, *res, *p;
        memset(&hints, 0, sizeof(hints));
        hints.ai_family = AF_UNSPEC;
        hints.ai_socktype = SOCK_STREAM;

        int status = getaddrinfo(indicators[i].RX_UE_INFORMATION_TAG, "80", &hints, &res);
        if (status != 0) {
            fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
            continue;
        }

        // Process the resolved addresses
        for (p = res; p != NULL; p = p->ai_next) {
            char ipstr[INET6_ADDRSTRLEN];
            void *addr;

            if (p->ai_family == AF_INET) {
                struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
                addr = &(ipv4->sin_addr);
            } else { // AF_INET6
                struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
                addr = &(ipv6->sin6_addr);
            }

            inet_ntop(p->ai_family, addr, ipstr, sizeof(ipstr));
            printf("Hostname: %s -> IP Address: %s\n", indicators[i].RX_UE_INFORMATION_TAG, ipstr);
        }

        freeaddrinfo(res); // Free the linked list
    }
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T indicators[10];
    srand(time(0));
    populateRxIndicationsAndResolveDNS(indicators, 10);
    return 0;
}
