void populateRxIndicationsAndResolveNetworkStatus(std::vector<NFAPI_CRC_INDICATION_PDU_T>& indications) {
    static std::mutex mtx;
    static NetworkStatusService networkService;
    static std::pair<int, int> cachedMetrics{0, 0};
    static bool isFetching = false;
    static int retryCount = 0;

    auto now = std::chrono::system_clock::now();
    auto lastPollTime = std::chrono::system_clock::to_time_t(now) - std::chrono::seconds(35);
    auto cooldownEnds = std::chrono::system_clock::to_time_t(now) - std::chrono::seconds(12);

    if (std::chrono::system_clock::to_time_t(now) >= lastPollTime && !isFetching) {
        isFetching = true;
        while (true) {
            try {
                if (networkService.IsAvailable()) {
                    auto metrics = networkService.GetMetrics();
                    cachedMetrics = metrics;
                    retryCount = 0;
                    break;
                } else {
                    throw std::runtime_error("Network status service unavailable");
                }
            } catch (...) {
                if (++retryCount >= 3) {
                    // Degrade gracefully
                    std::cerr << "Failed to fetch network metrics after multiple retries. Using cached values." << std::endl;
                    break;
                }
                std::this_thread::sleep_for(std::chrono::seconds(1));
            }
        }
        isFetching = false;
    }

    if (std::chrono::system_clock::to_time_t(now) >= cooldownEnds) {
        std::lock_guard<std::mutex> lock(mtx);
        indications.clear();
