    int instance_id;
    unsigned char checksum[4];
} NFAPI_RRC_MSG;

typedef struct {
    int rx_ue_information_tag;
    int rnti;
    int crc_indication_rel8_tag;
    unsigned char crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_RRC_MSG *messages[MAX_MESSAGES];
NFAPI_CRC_INDICATION_PDU_T *crc_indications[MAX_MESSAGES];

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void populate_message(NFAPI_RRC_MSG *msg) {
    msg->type = (RRC_MESSAGE_TYPE)(rand() % RRC_MESSAGE_TYPE_2 + 1);
    msg->instance_id = rand();
    // Calculate checksum based on type and instance ID
    msg->checksum[0] = (unsigned char)((msg->type & 0xFF) ^ (msg->instance_id & 0xFF));
    msg->checksum[1] = (unsigned char)(((msg->type >> 8) & 0xFF) ^ ((msg->instance_id >> 8) & 0xFF));
    msg->checksum[2] = (unsigned char)(((msg->type >> 16) & 0xFF) ^ ((msg->instance_id >> 16) & 0xFF));
    msg->checksum[3] = (unsigned char)(((msg->type >> 24) & 0xFF) ^ ((msg->instance_id >> 24) & 0xFF));
}

void populate_crc_indication(NFAPI_CRC_INDICATION_PDU_T *indication, int rnti) {
    indication->rx_ue_information_tag = rand();
    indication->rnti = rnti;
    indication->crc_indication_rel8_tag = rand();
    indication->crcflag = (rand() % 2 == 0) ? 1 : 0; // Randomly set CRCFLAG
}

void *message_manager(void *arg) {
    int N = *(int *)arg;
    if (N > MAX_MESSAGES) {
        N = MAX_MESSAGES;
    }

    for (int i = 0; i < N; i++) {
        pthread_mutex_lock(&mutex);
        messages[i] = malloc(sizeof(NFAPI_RRC_MSG));
        crc_indications[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!messages[i] || !crc_indications[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            free(messages[i]);
            free(crc_indications[i]);
            pthread_mutex_unlock(&mutex);
            continue;
        }
        populate_message(messages[i]);
        populate_crc_indication(crc_indications[i], i + 1); // Ensure unique RNTI
        pthread_mutex_unlock(&mutex);

        // Simulate processing time
        usleep(rand() % 1000);
    }

    return NULL;
}

void free_resources(int N) {
    for (int i = 0; i < N; i++) {
        if (messages[i]) {
            free(messages[i]);
        }
        if (crc_indications[i]) {
            free(crc_indications[i]);
        }
    }
}

int main() {
    srand(time(NULL));
    int N = MAX_MESSAGES;
    pthread_t thread;

    if (pthread_create(&thread, NULL, message_manager, &N) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return EXIT_FAILURE;
    }

    pthread_join(thread, NULL);

    free_resources(N);
    return EXIT_SUCCESS;
}
