#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    struct NFAPI_CRC_INDICATION_PDU_T *prev, *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head, *tail;
    pthread_mutex_t lock;
} CRC_LIST_T;

void init_crc_list(CRC_LIST_T *list) {
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void add_to_list(CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *new_item) {
    pthread_mutex_lock(&list->lock);
    if (list->tail) {
        list->tail->next = new_item;
        new_item->prev = list->tail;
        list->tail = new_item;
    } else {
        list->head = list->tail = new_item;
    }
    pthread_mutex_unlock(&list->lock);
}

void remove_from_list(CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&list->lock);
    if (item->prev) item->prev->next = item->next;
    else list->head = item->next;
    if (item->next) item->next->prev = item->prev;
    else list->tail = item->prev;
    pthread_mutex_unlock(&list->lock);
