} NFAPI_CRC_INDICATION_PDU;

typedef struct NFAPI_CRC_LIST {
    NFAPI_CRC_INDICATION_PDU* head;
    NFAPI_CRC_INDICATION_PDU* tail;
    pthread_mutex_t lock;
    uint32_t size;
    custom_memory_pool_t pool; // Custom memory pool for efficient memory management
} NFAPI_CRC_LIST;

NFAPI_CRC_LIST* nfapi_crc_list_init(uint32_t initial_size) {
    NFAPI_CRC_LIST* list = (NFAPI_CRC_LIST*)custom_malloc(sizeof(NFAPI_CRC_LIST));
    if (!list) return NULL;

    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;
    list->pool = custom_memory_pool_init(initial_size); // Initialize custom memory pool

    return list;
}

void nfapi_crc_list_add(NFAPI_CRC_LIST* list, NFAPI_CRC_INDICATION_PDU* pdu) {
    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = list->tail = pdu;
    } else {
        pdu->prev = list->tail;
        list->tail->next = pdu;
        list->tail = pdu;
    }
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

void nfapi_crc_list_remove(NFAPI_CRC_LIST* list, NFAPI_CRC_INDICATION_PDU* pdu) {
    pthread_mutex_lock(&list->lock);
    if (pdu->prev) {
        pdu->prev->next = pdu->next;
    } else {
        list->head = pdu->next;
    }
    if (pdu->next) {
        pdu->next->prev = pdu->prev;
    } else {
        list->tail = pdu->prev;
    }
    custom_free(pdu, &list->pool); // Use custom memory pool for deallocation
    list->size--;
    pthread_mutex_unlock(&list->lock);
}

void nfapi_crc_list_iterate(NFAPI_CRC_LIST* list, void (*callback)(NFAPI_CRC_INDICATION_PDU*)) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU* current = list->head;
    while (current) {
        callback(current);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void nfapi_crc_list_destroy(NFAPI_CRC_LIST* list) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU* current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU* next = current->next;
        custom_free(current, &list->pool); // Use custom memory pool for deallocation
        current = next;
    }
    pthread_mutex_unlock(&list->lock);
    custom_memory_pool_destroy(&list->pool); // Destroy custom memory pool
    pthread_mutex_destroy(&list->lock);
    free(list);
}

