} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
} CRC_LIST_T;

void crc_list_init(CRC_LIST_T *list) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = list->tail = NULL;
}

void crc_list_add(CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = list->tail = pdu;
    } else {
        list->tail->next = pdu;
        pdu->prev = list->tail;
        list->tail = pdu;
    }
    pthread_mutex_unlock(&list->lock);
}

void crc_list_remove(CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->lock);
    if (pdu == list->head) {
        list->head = pdu->next;
    }
    if (pdu == list->tail) {
        list->tail = pdu->prev;
    }
    if (pdu->prev != NULL) {
        pdu->prev->next = pdu->next;
    }
    if (pdu->next != NULL) {
        pdu->next->prev = pdu->prev;
    }
    pthread_mutex_unlock(&list->lock);
}

void crc_list_iterate(CRC_LIST_T *list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        callback(current);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

