int allocate_structs(int n) {
    pthread_mutex_lock(&lock);
    if (n > MAX_STRUCTS || n <= 0) {
        pthread_mutex_unlock(&lock);
        return -1; // Invalid number of structures
    }
    array = realloc(array, n * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!array) {
        pthread_mutex_unlock(&lock);
        return -2; // Memory allocation failed
    }
    for (int i = 0; i < n; i++) {
        array[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!array[i]) {
            free_memory();
            pthread_mutex_unlock(&lock);
            return -3; // Individual structure allocation failed
