        array[i]->RNTI = rand() % 65536;
        array[i]->CRC_INDICATION_REL8_TAG = rand() % 256;
        array[i]->CRCFLAG = (rand() % 2) ? 'Y' : 'N';
    }
    pthread_mutex_unlock(&lock);
    return n; // Success
