void log_message(const char* format, ...) {
    va_list args;
    va_start(args, format);
    vprintf(format, args);
    va_end(args);
}

int allocate_structures(int N) {
    pthread_mutex_lock(&lock);
    if (current_size + N > MAX_STRUCTS) {
        pthread_mutex_unlock(&lock);
        log_message("Error: Not enough space to allocate %d structures\n", N);
        return -1;
    }
    for (int i = 0; i < N; i++) {
        structures[current_size + i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!structures[current_size + i]) {
            pthread_mutex_unlock(&lock);
            log_message("Error: Failed to allocate memory for structure %d\n", current_size + i);
            return -1;
        }
        structures[current_size + i]->RX_UE_INFORMATION_TAG = rand();
        structures[current_size + i]->RNTI = rand() % 65536;
        structures[current_size + i]->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    }
    current_size += N;
    pthread_mutex_unlock(&lock);
    log_message("Allocated %d structures successfully\n", N);
    return 0;
}

void garbage_collect(int timeout) {
    struct timespec now, deadline;
    clock_gettime(CLOCK_REALTIME, &now);
    deadline.tv_sec = now.tv_sec + timeout;
    deadline.tv_nsec = now.tv_nsec;

    while (clock_nanosleep(CLOCK_REALTIME, TIMER_ABSTIME, &deadline, NULL) == 0) {
        pthread_mutex_lock(&lock);
        for (int i = current_size - 1; i >= 0; i--) {
            if (!structures[i]) continue;
            // Implement custom logic to determine if structure is inactive
            // Free the structure and reduce current_size if it's inactive
            free(structures[i]);
            structures[i] = NULL;
            current_size--;
        }
        pthread_mutex_unlock(&lock);
    }
}

void* garbage_collector_thread(void* arg) {
    int timeout = 10; // Set desired timeout in seconds
    while (1) {
        garbage_collect(timeout);
        sleep(60); // Check every minute
    }
    return NULL;
}
