const axios = require('axios');
const FormData = require('form-data');

async function uploadFile(url) {
  let apiKey = 'initial_api_key';
  const maxRetries = 3;
  let retryCount = 0;

  while (retryCount < maxRetries) {
    try {
      const form = new FormData();
      // Append file data to form
      form.append('file', fs.createReadStream(url));

      const response = await axios.post('https://api.filestorage.com/upload', form, {
        headers: {
          'Authorization': `Bearer ${apiKey}`,
          ...form.getHeaders()
        }
      });

      console.log(`Upload successful. URL: ${response.data.url}`);
      return response.data.url;
    } catch (error) {
      if (error.response && error.response.status === 401) {
        // Rotate API key
        apiKey = rotateApiKey();
        retryCount++;
        continue;
      }

      const waitInterval = calculateRetryInterval(retryCount);
      console.log(`Upload failed. Retrying in ${waitInterval}ms...`);
      await new Promise(resolve => setTimeout(resolve, waitInterval));
      retryCount++;
    }
  }

  throw new Error('Max retries reached. File upload failed.');
}

function rotateApiKey() {
  // Implement API key rotation logic
  return 'new_api_key';
}

function calculateRetryInterval(retryCount) {
  // Implement exponential backoff logic for rate limiting
  return Math.pow(2, retryCount) * 1000;
}
