LinkedListNode* create_linked_list(int max_elements, int allocation_limit) {
    srand(time(0));
    LinkedListNode *head = NULL, *tail = NULL;
    int current_rnti = 1;

    for (int i = 0; i < max_elements && allocation_limit > 0; ++i) {
        if (!(allocation_limit--)) break;

        LinkedListNode *new_node = malloc(sizeof(LinkedListNode));
        if (!new_node) return NULL;

        new_node->data.RX_UE_INFORMATION_TAG = rand();
        new_node->data.RNTI = current_rnti;
        new_node->data.CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
        new_node->next = NULL;

        if (!head) head = tail = new_node;
        else {
            tail->next = new_node;
            tail = new_node;
        }

        current_rnti++;
        if (current_rnti > 100) current_rnti = 1; // Cycle RNTI values
    }

    return head;
}

