        size_t newCapacity = array->capacity * 2;
        LTE_DL_FRAMEINFO *newFrames = (LTE_DL_FRAMEINFO *)realloc(array->frames, newCapacity * sizeof(LTE_DL_FRAMEINFO));
        if (!newFrames) {
            // Handle memory reallocation failure
