        array->frames = newFrames;
        array->capacity = newCapacity;
    }

    array->frames[array->size].PHY_RRC_UE_ID = UE_ID;
    array->frames[array->size].PHYCELLID = cellID;
    array->frames[array->size].PHY_TXPWR_CMD = txPwrCmd;
