#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_STRUCTS 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void generateNfaliteIndications(NFAPI_CRC_INDICATION_PDU_T *indicationArray, int numStructs) {
    if (numStructs <= 0 || numStructs > MAX_STRUCTS) {
        fprintf(stderr, "Invalid number of structures. Must be between 1 and %d\n", MAX_STRUCTS);
        return;
    }

    srand(time(NULL));
    unsigned short rntiArray[65535];
    int rntiCount = 0;

    // Initialize RNTI array
    for (int i = 1; i <= 65535; i++) {
        rntiArray[rntiCount++] = i;
    }

    // Shuffle RNTI array
    for (int i = 0; i < numStructs; i++) {
        int randomIndex = rand() % rntiCount;
        indicationArray[i].RX_UE_INFORMATION_TAG = i + 1;
        indicationArray[i].RNTI = rntiArray[randomIndex];
        indicationArray[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() & 0x01) ^ ((i > 0) ? indicationArray[i - 1].CRC_INDICATION_REL8_TAG.CRCFLAG : 0);

        // Remove used RNTI
        rntiArray[randomIndex] = rntiArray[--rntiCount];
    }
}

