#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int id;
    time_t timestamp;
    size_t payload_size;
} DataPacket;

typedef struct {
    DataPacket* packets;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} PacketManager;

void initPacketManager(PacketManager* manager, size_t initial_capacity) {
    manager->packets = (DataPacket*)malloc(initial_capacity * sizeof(DataPacket));
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->mutex, NULL);
}

void destroyPacketManager(PacketManager* manager) {
    pthread_mutex_lock(&manager->mutex);
    free(manager->packets);
    pthread_mutex_unlock(&manager->mutex);
    pthread_mutex_destroy(&manager->mutex);
}

bool addPacket(PacketManager* manager, DataPacket packet) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->size == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        DataPacket* new_packets = (DataPacket*)realloc(manager->packets, new_capacity * sizeof(DataPacket));
        if (!new_packets) {
            pthread_mutex_unlock(&manager->mutex);
            return false;
        }
        manager->packets = new_packets;
        manager->capacity = new_capacity;
    }
    manager->packets[manager->size++] = packet;
    pthread_mutex_unlock(&manager->mutex);
    return true;
}

bool removePacketById(PacketManager* manager, int id) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->packets[i].id == id) {
            for (size_t j = i; j < manager->size - 1; ++j) {
                manager->packets[j] = manager->packets[j + 1];
            }
            --manager->size;
            pthread_mutex_unlock(&manager->mutex);
            return true;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
    return false;
}

size_t getPacketCount(const PacketManager* manager) {
    pthread_mutex_lock(&manager->mutex);
    size_t count = manager->size;
    pthread_mutex_unlock(&manager->mutex);
    return count;
}
```

