#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_ENTRIES 1000

typedef struct {
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T entries[MAX_ENTRIES];
    int count;
    pthread_mutex_t lock;
    time_t last_cleanup_time;
    int max_idle_timeout_seconds;
} NFAPICRCArrayManager;

void initNFAPICRCArrayManager(NFAPICRCArrayManager *manager, int max_idle_timeout_seconds) {
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    manager->last_cleanup_time = time(NULL);
    manager->max_idle_timeout_seconds = max_idle_timeout_seconds;
}

int addEntry(NFAPICRCArrayManager *manager, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= MAX_ENTRIES) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Array is full
    }
    manager->entries[manager->count++] = entry;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int updateEntry(NFAPICRCArrayManager *manager, uint16_t RNTI, NFAPI_CRC_INDICATION_PDU_T new_entry) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; ++i) {
        if (manager->entries[i].RNTI == RNTI) {
            manager->entries[i] = new_entry;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Entry not found
}

int removeEntry(NFAPICRCArrayManager *manager, uint16_t RNTI) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; ++i) {
        if (manager->entries[i].RNTI == RNTI) {
            for (; i < manager->count - 1; ++i) {
                manager->entries[i] = manager->entries[i + 1];
            }
            manager->count--;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Entry not found
}

void cleanUpInactiveEntries(NFAPICRCArrayManager *manager) {
    pthread_mutex_lock(&manager->lock);
    time_t now = time(NULL);
    if (now - manager->last_cleanup_time > manager->max_idle_timeout_seconds) {
        int new_count = 0;
        for (int i = 0; i < manager->count; ++i) {
            if ((now - manager->entries[i].RNTI) <= manager->max_idle_timeout_seconds) {
                manager->entries[new_count++] = manager->entries[i];
            }
        }
        manager->count = new_count;
        manager->last_cleanup_time = now;
    }
    pthread_mutex_unlock(&manager->lock);
}

int serializeToArray(NFAPICRCArrayManager *manager, FILE *file) {
    if (fwrite(&manager->count, sizeof(int), 1, file) != 1) return -1;
    for (int i = 0; i < manager->count; ++i) {
        if (fwrite(&manager->entries[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) != 1) return -1;
    }
    return 0;
}

int deserializeFromArray(NFAPICRCArrayManager *manager, FILE *file) {
    int new_count;
    if (fread(&new_count, sizeof(int), 1, file) != 1) return -1;
    if (new_count > MAX_ENTRIES) return -1;
    for (int i = 0; i < new_count; ++i) {
        if (fread(&manager->entries[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) != 1) return -1;
    }
    manager->count = new_count;
    return 0;
}

void exportToJson(NFAPICRCArrayManager *manager, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) return;
    fprintf(file, "[\n");
    for (int i = 0; i < manager->count; ++i) {
        if (i > 0) fprintf(file, ",\n");
        fprintf(file, "{ \"RNTI\": %d, \"CRCFLAG\": %d }\n", manager->entries[i].RNTI, manager->entries[i].CRCFLAG);
    }
    fprintf(file, "]\n");
    fclose(file);
}

void *monitorAndLog(void *arg) {
    NFAPICRCArrayManager *manager = (NFAPICRCArrayManager *)arg;
    while (1) {
        pthread_mutex_lock(&manager->lock);
        time_t now = time(NULL);
        printf("Operation count: %d, Last cleanup at: %ld\n", manager->count, manager->last_cleanup_time);
        pthread_mutex_unlock(&manager->lock);
        sleep(10); // Log every 10 seconds
    }
    return NULL;
}
