#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_CONCURRENT_CONNECTIONS 100

typedef struct {
    int rnti;
    // other fields...
} RX_UE_INFORMATION_TAG;

typedef struct {
    // CRC_INDICATION_REL8_TAG fields...
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    NFAPI_CRC_INDICATION_PDU_T crc_indication;
    pthread_mutex_t lock;
} Element;

Element* elements[MAX_CONCURRENT_CONNECTIONS];
int element_count = 0;
pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;

void add_element(int rnti) {
    pthread_mutex_lock(&global_lock);
    if (element_count >= MAX_CONCURRENT_CONNECTIONS) {
        printf("Error: Maximum concurrent connections reached.\n");
        pthread_mutex_unlock(&global_lock);
        return;
    }
    Element* new_element = (Element*)malloc(sizeof(Element));
    if (!new_element) {
        printf("Error: Allocation failed.\n");
        pthread_mutex_unlock(&global_lock);
        return;
    }
    new_element->rx_ue_info.rnti = rnti;
    // Initialize other fields...
    new_element->crc_indication.crcflag = rand() % 2; // Randomly set CRCFLAG
    pthread_mutex_init(&new_element->lock, NULL);
    elements[element_count++] = new_element;
    pthread_mutex_unlock(&global_lock);
}

void close_element(int id) {
    pthread_mutex_lock(&global_lock);
    if (id < 0 || id >= element_count) {
        printf("Error: Invalid ID for closure.\n");
        pthread_mutex_unlock(&global_lock);
        return;
    }
    free(elements[id]);
    elements[id] = NULL;
    // Shift remaining elements...
    for (int i = id; i < element_count - 1; i++) {
        elements[i] = elements[i + 1];
    }
    element_count--;
    pthread_mutex_unlock(&global_lock);
}

void update_crc_indication(int id, int crcflag) {
    pthread_mutex_lock(&elements[id]->lock);
    if (id < 0 || id >= element_count) {
        printf("Error: Invalid ID for update.\n");
        pthread_mutex_unlock(&elements[id]->lock);
        return;
    }
    elements[id]->crc_indication.crcflag = crcflag;
    pthread_mutex_unlock(&elements[id]->lock);
}
