int add_element(ArrayManager* manager, NFAPI_CRC_INDICATION_PDU_T newElement) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->size >= manager->capacity) {
        size_t newCapacity = manager->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* newData = realloc(manager->data, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newData) {
            pthread_mutex_unlock(&manager->mutex);
            return -1; // Memory allocation failed
        }
        manager->data = newData;
        manager->capacity = newCapacity;
    }
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->data[i].RNTI == newElement.RNTI) {
            pthread_mutex_unlock(&manager->mutex);
            return -2; // Duplicate RNTI
        }
    }
    manager->data[manager->size++] = newElement;
    pthread_mutex_unlock(&manager->mutex);
    return 0; // Success
}

int remove_element(ArrayManager* manager, int RNTI) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->data[i].RNTI == RNTI) {
            for (size_t j = i; j < manager->size - 1; ++j) {
                manager->data[j] = manager->data[j + 1];
            }
            --manager->size;
            pthread_mutex_unlock(&manager->mutex);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&manager->mutex);
    return -1; // RNTI not found
}

int modify_element(ArrayManager* manager, int RNTI, NFAPI_CRC_INDICATION_PDU_T newElement) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->data[i].RNTI == RNTI) {
            if (manager->data[i].RNTI != newElement.RNTI && check_for_duplicate(manager, newElement)) {
                pthread_mutex_unlock(&manager->mutex);
                return -2; // Duplicate RNTI
            }
            manager->data[i] = newElement;
            pthread_mutex_unlock(&manager->mutex);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&manager->mutex);
    return -1; // RNTI not found
}

int check_for_duplicate(ArrayManager* manager, NFAPI_CRC_INDICATION_PDU_T element) {
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->data[i].RNTI == element.RNTI && &manager->data[i] != &element) {
            return 1; // Duplicate RNTI found
        }
    }
    return 0; // No duplicate RNTI
}
