typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *users[MAX_USERS];
    pthread_mutex_t lock;
} CRC_Array_Manager;

CRC_Array_Manager* create_crc_array_manager() {
    CRC_Array_Manager* manager = (CRC_Array_Manager*)malloc(sizeof(CRC_Array_Manager));
    if (!manager) return NULL;

    if (pthread_mutex_init(&manager->lock, NULL) != 0) {
        free(manager);
        return NULL;
    }

    for (int i = 0; i < MAX_USERS; ++i) {
        manager->users[i] = NULL;
    }
    return manager;
}

void destroy_crc_array_manager(CRC_Array_Manager* manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < MAX_USERS; ++i) {
        free(manager->users[i]);
    }
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indication_pdu(uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;

    srand(time(NULL));
    pdu->CRCFLAG = rand() % 256; // Randomly generate CRCFLAG
    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    return pdu;
}

int assign_crc_indication_pdu(CRC_Array_Manager* manager, uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    if (!manager || RX_UE_INFORMATION_TAG >= MAX_USERS) return -1; // Handle invalid input size

    NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_crc_indication_pdu(RX_UE_INFORMATION_TAG, RNTI);
    if (!pdu) return -1; // Handle memory allocation failure

    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < MAX_USERS; ++i) {
        if (!manager->users[i]) {
            manager->users[i] = pdu;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);

    free(pdu); // No available slot, clean up allocated memory
    return -1; // Return an error indicating no available slot
}

int release_crc_indication_pdu(CRC_Array_Manager* manager, uint32_t RX_UE_INFORMATION_TAG) {
    if (!manager || RX_UE_INFORMATION_TAG >= MAX_USERS) return -1; // Handle invalid input size

    pthread_mutex_lock(&manager->lock);
    if (manager->users[RX_UE_INFORMATION_TAG]) {
        free(manager->users[RX_UE_INFORMATION_TAG]);
        manager->users[RX_UE_INFORMATION_TAG] = NULL;
        pthread_mutex_unlock(&manager->lock);
        return 0;
    }
    pthread_mutex_unlock(&manager->lock);

    return -1; // Return an error indicating no PDU to release
}
