    if (active_users >= MAX_USERS) {
        pthread_mutex_unlock(&session_lock);
        return -1; // User limit reached
    }

    NFAPI_CRC_INDICATION_PDU_T* session = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!session) {
        pthread_mutex_unlock(&session_lock);
        return -2; // Memory allocation failed
