    session->RNTI = rnti;
    session->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG

    user_sessions[active_users] = session;
    active_users++;
    pthread_mutex_unlock(&session_lock);
    return 0;
}

void destroy_user_session(uint32_t ue_tag) {
    pthread_mutex_lock(&session_lock);
    for (int i = 0; i < active_users; i++) {
        if (user_sessions[i]->RX_UE_INFORMATION_TAG == ue_tag) {
            free(user_sessions[i]);
            for (int j = i; j < active_users - 1; j++) {
                user_sessions[j] = user_sessions[j + 1];
            }
            active_users--;
            break;
        }
    }
    pthread_mutex_unlock(&session_lock);
