#define MAX_USERS 2048
#define MIN_RESIZE 512
#define RESIZE_INCREMENT 512

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    uint32_t crcflag;
