NFAPI_CRC_INDICATION_PDU_T *user_array = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int current_users = 0;

int allocate_user(NFAPI_CRC_INDICATION_PDU_T *new_user) {
    pthread_mutex_lock(&mutex);
    if (current_users >= MAX_USERS) {
        pthread_mutex_unlock(&mutex);
        return -1; // Maximum users reached
    }

    if (user_array == NULL || current_users % RESIZE_INCREMENT == 0 && current_users > MIN_RESIZE) {
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(user_array, (current_users + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_array == NULL) {
            pthread_mutex_unlock(&mutex);
            return -2; // Memory allocation failed
        }
        user_array = new_array;
    }

    user_array[current_users++] = *new_user;
    pthread_mutex_unlock(&mutex);
    return 0;
}

void free_user(int index) {
    pthread_mutex_lock(&mutex);
    if (index < 0 || index >= current_users) {
        pthread_mutex_unlock(&mutex);
        return; // Invalid index
    }

    if (current_users > MIN_RESIZE + RESIZE_INCREMENT && current_users - 1 <= MIN_RESIZE) {
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(user_array, current_users * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_array != NULL) {
            user_array = new_array;
        }
    }

    for (int i = index; i < current_users - 1; i++) {
        user_array[i] = user_array[i + 1];
    }
    current_users--;
    pthread_mutex_unlock(&mutex);
}

// Example usage:
