#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int signalStrength;
    float errorRate;
    time_t timestamp;
} FrameStatistics;

typedef struct {
    FrameStatistics *frames;
    size_t count;
    size_t capacity;
    FILE *dbFile; // External database file for persistent storage
} FrameManager;

FrameManager* createFrameManager(size_t initialCapacity) {
    FrameManager *manager = (FrameManager*)malloc(sizeof(FrameManager));
    if (!manager) return NULL;

    manager->frames = (FrameStatistics*)malloc(initialCapacity * sizeof(FrameStatistics));
    if (!manager->frames) {
        free(manager);
        return NULL;
    }

    manager->count = 0;
    manager->capacity = initialCapacity;
    manager->dbFile = fopen("frame_data.db", "w+b");
    if (!manager->dbFile) {
        free(manager->frames);
        free(manager);
        return NULL;
    }

    // Initialize the database file
    fwrite(&manager->count, sizeof(size_t), 1, manager->dbFile);
    fflush(manager->dbFile);

    return manager;
}

void destroyFrameManager(FrameManager *manager) {
    if (manager) {
        fclose(manager->dbFile);
        free(manager->frames);
        free(manager);
    }
}

void addOrUpdateFrame(FrameManager *manager, FrameStatistics frame) {
    if (manager->count >= manager->capacity) {
        size_t newCapacity = manager->capacity * 2;
        FrameStatistics *newFrames = (FrameStatistics*)realloc(manager->frames, newCapacity * sizeof(FrameStatistics));
        if (!newFrames) return;
        manager->frames = newFrames;
        manager->capacity = newCapacity;
    }

    manager->frames[manager->count++] = frame;
    fwrite(&frame, sizeof(FrameStatistics), 1, manager->dbFile);
    fflush(manager->dbFile);
}

double calculateAverageSignalStrength(FrameManager *manager) {
    double total = 0;
    for (size_t i = 0; i < manager->count; i++) {
        total += manager->frames[i].signalStrength;
    }
    return total / manager->count;
}

float findMaxErrorRate(FrameManager *manager) {
    float maxRate = 0;
    for (size_t i = 0; i < manager->count; i++) {
        if (manager->frames[i].errorRate > maxRate) {
            maxRate = manager->frames[i].errorRate;
        }
    }
    return maxRate;
}
```

