        if (!new_data) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Memory allocation failed
        }
        list->data = new_data;
        list->capacity *= 2;
    }

    int current_crc_sum = 0;
    for (size_t i = 0; i < list->count; ++i) {
        current_crc_sum += list->data[i].CRCFLAG;
    }

    if (current_crc_sum + CRCFLAG > MAX_CRC_SUM) {
        pthread_mutex_unlock(&list->mutex);
        return -2; // Exceeds CRC sum limit
    }

    list->data[list->count].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    list->data[list->count].RNTI = RNTI;
    list->data[list->count].CRCFLAG = CRCFLAG;
    ++list->count;

    pthread_mutex_unlock(&list->mutex);
    return 0; // Success
