    if (manager == NULL) {
        return NULL;
    }
    manager->array = (NFAPI_CRC_INDICATION_PDU_T *)calloc(max_elements, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (manager->array == NULL) {
        free(manager);
        return NULL;
    }
    manager->count = 0;
    manager->max_count = max_elements;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void destroy_array_manager(ArrayManager *manager) {
