    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

int add_element_to_array(ArrayManager *manager, NFAPI_CRC_INDICATION_PDU_T new_element) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->count >= manager->max_count) {
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }
    for (size_t i = 0; i < manager->count; i++) {
        if (manager->array[i].RNTI == new_element.RNTI || 
            (i > 0 && manager->array[i-1].CRCFLAG == new_element.CRCFLAG)) {
            pthread_mutex_unlock(&manager->mutex);
            return -1;
        }
    }
    size_t sum = 0;
    for (size_t i = 0; i < manager->count; i++) {
        sum += manager->array[i].CRCFLAG;
    }
    if (sum + new_element.CRCFLAG > MAX_CRC_SUM) {
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }
