#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_RRC_UE_CONTEXT {
    int UE_ID;
    // Other configurable parameters
} NFAPI_RRC_UE_CONTEXT;

typedef struct Node {
    NFAPI_RRC_UE_CONTEXT context;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
} DynamicArray;

void initializeDynamicArray(DynamicArray* array) {
    array->head = NULL;
    pthread_mutex_init(&array->mutex, NULL);
}

void addContext(DynamicArray* array, NFAPI_RRC_UE_CONTEXT context) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->context = context;
    newNode->next = array->head;
    pthread_mutex_lock(&array->mutex);
    array->head = newNode;
    pthread_mutex_unlock(&array->mutex);
}

void deleteContext(DynamicArray* array, int UE_ID) {
    pthread_mutex_lock(&array->mutex);
    Node* current = array->head;
    Node* previous = NULL;

    while (current != NULL && current->context.UE_ID != UE_ID) {
        previous = current;
        current = current->next;
    }

    if (current != NULL) {
        if (previous == NULL)
            array->head = current->next;
        else
            previous->next = current->next;

        free(current);
    }
    pthread_mutex_unlock(&array->mutex);
}

NFAPI_RRC_UE_CONTEXT* getContext(DynamicArray* array, int UE_ID) {
    NFAPI_RRC_UE_CONTEXT* context = NULL;
    pthread_mutex_lock(&array->mutex);
    Node* current = array->head;

    while (current != NULL && current->context.UE_ID != UE_ID)
        current = current->next;

    if (current != NULL)
        context = &current->context;

    pthread_mutex_unlock(&array->mutex);
    return context;
}

void generatePDU(NFAPI_CRC_INDICATION_PDU_T* pdu, NFAPI_RX_UE_INFORMATION_TAG rxTag, int RNTI) {
    pdu->rx_ue_information_tag = rxTag;
    pdu->rnti = RNTI;
    pdu->crc_indication_rel8_tag.crcflag = rand() % 2; // Randomly set CRCFLAG
}

void* externalDataUpdater(void* arg) {
    DynamicArray* array = (DynamicArray*)arg;

    // Simulate real-time updates
    while (1) {
        NFAPI_RRC_UE_CONTEXT context;
        generateContext(&context); // Function to generate new context from external data source

        pthread_mutex_lock(&array->mutex);
        addContext(array, context);
        pthread_mutex_unlock(&array->mutex);

        sleep(1); // Simulate delay in data update
    }

    return NULL;
}

int main() {
    DynamicArray array;
    initializeDynamicArray(&array);

    pthread_t updaterThread;
    pthread_create(&updaterThread, NULL, externalDataUpdater, &array);

    // Example usage of the dynamic array and PDU generation
    NFAPI_RRC_UE_CONTEXT* context = getContext(&array, 1234);
    if (context != NULL) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        generatePDU(&pdu, RX_TAG, context->UE_ID);

        // Process the PDU
    }

    pthread_join(updaterThread, NULL);

    return 0;
}
