typedef struct LTE_Uplink_NAS_Transport_PDU {
    char NAS_Message[256];
    int UE_ID;
    uint32_t PDCP_SN;
    int SRB_ID;
} LTE_Uplink_NAS_Transport_PDU;

typedef struct DynamicArray {
    LTE_Uplink_NAS_Transport_PDU *data;
    size_t capacity;
    size_t size;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->data = (LTE_Uplink_NAS_Transport_PDU*)calloc(initial_capacity, sizeof(LTE_Uplink_NAS_Transport_PDU));
    array->capacity = initial_capacity;
    array->size = 0;
    return array;
}

void resize_dynamic_array(DynamicArray *array) {
    size_t new_capacity = array->capacity * 2;
    LTE_Uplink_NAS_Transport_PDU *new_data = (LTE_Uplink_NAS_Transport_PDU*)realloc(array->data, new_capacity * sizeof(LTE_Uplink_NAS_Transport_PDU));
    if (new_data) {
        array->data = new_data;
        array->capacity = new_capacity;
    }
}

void insert_dynamic_array(DynamicArray *array, LTE_Uplink_NAS_Transport_PDU item) {
    if (array->size == array->capacity) {
        resize_dynamic_array(array);
    }
    array->data[array->size++] = item;
}

void delete_dynamic_array(DynamicArray *array, int index) {
    if (index < 0 || index >= array->size) return;
    for (size_t i = index; i < array->size - 1; ++i) {
        array->data[i] = array->data[i + 1];
    }
    array->size--;
}

LTE_Uplink_NAS_Transport_PDU* get_dynamic_array(DynamicArray *array, int index) {
    if (index >= 0 && index < array->size) {
        return &array->data[index];
    }
    return NULL;
}

void free_dynamic_array(DynamicArray *array) {
    free(array->data);
    free(array);
}
