UE_CONTEXT_MANAGER* create_ue_context_manager() {
    UE_CONTEXT_MANAGER* manager = (UE_CONTEXT_MANAGER*)malloc(sizeof(UE_CONTEXT_MANAGER));
    if (!manager) return NULL;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_ue_context_manager(UE_CONTEXT_MANAGER* manager) {
    if (!manager) return;
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->contexts[i]);
    }
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_ue_context(UE_CONTEXT_MANAGER* manager, NFAPI_RRC_UE_CONTEXT* context) {
    if (!manager || !context) return -1;
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= MAX_UE_CONTEXTS) {
        pthread_mutex_unlock(&manager->lock);
        return -2; // Manager full
    }
    manager->contexts[manager->count++] = context;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int remove_ue_context(UE_CONTEXT_MANAGER* manager, uint32_t UE_ID) {
    if (!manager) return -1;
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->contexts[i]->UE_ID == UE_ID) {
            free(manager->contexts[i]);
            for (; i + 1 < manager->count; ++i) {
                manager->contexts[i] = manager->contexts[i + 1];
            }
            manager->count--;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -2; // Context not found
}

NFAPI_RRC_UE_CONTEXT* get_ue_context(UE_CONTEXT_MANAGER* manager, uint32_t UE_ID) {
    if (!manager) return NULL;
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->contexts[i]->UE_ID == UE_ID) {
            NFAPI_RRC_UE_CONTEXT* context = manager->contexts[i];
            pthread_mutex_unlock(&manager->lock);
            return context;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

