void populateList(NFAPI_CRC_INDICATION_PDU_T** head, int RX_UE_INFO, int RNTI, int networkMetric) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);

    NFAPI_CRC_INDICATION_PDU_T* newNode = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newNode == NULL) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&lock);
        return;
    }

    newNode->RX_UE_INFORMATION_TAG = RX_UE_INFO;
    newNode->RNTI = RNTI;
    newNode->CRCFLAG = networkMetric > threshold ? 1 : 0; // Example logic for setting CRCFLAG
    newNode->next = *head;

    *head = newNode;
    pthread_mutex_unlock(&lock);
}

int verifyList(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    int duplicateCount = 0;

    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        while (next != NULL) {
            if (current->RX_UE_INFORMATION_TAG == next->RX_UE_INFORMATION_TAG && 
                current->RNTI == next->RNTI) {
                duplicateCount++;
                printf("Duplicate entry found: RX_UE_INFORMATION_TAG=%d, RNTI=%d\n", current->RX_UE_INFORMATION_TAG, current->RNTI);
            }
            next = next->next;
        }
        current = current->next;
    }

    return duplicateCount;
}

void logList(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;

    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n", 
               current->RX_UE_INFORMATION_TAG, current->RNTI, current->CRCFLAG);
        current = current->next;
    }
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;

    // Simulate network metrics and populate list
    for (int i = 0; i < 100; i++) {
        populateList(&head, i, i * 2, rand());
    }

    // Verify list for duplicates
    int duplicates = verifyList(head);
    printf("Number of duplicate entries: %d\n", duplicates);

    // Log the list contents
    logList(head);

    return 0;
}
