    NFAPI_CRC_INDICATION_PDU_T** elements;
    size_t size;
    size_t capacity;
} NFAPDUList;

NFAPDUList* create_NFAPDUList(size_t initialCapacity) {
    NFAPDUList* list = (NFAPDUList*)malloc(sizeof(NFAPDUList));
    if (!list) {
        log_error("Failed to allocate memory for NFAPDUList");
        return NULL;
    }
    list->elements = (NFAPI_CRC_INDICATION_PDU_T**)calloc(initialCapacity, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!list->elements) {
        log_error("Failed to allocate memory for elements in NFAPDUList");
        free(list);
        return NULL;
    }
    list->size = 0;
    list->capacity = initialCapacity;
    return list;
}

void destroy_NFAPDUList(NFAPDUList* list) {
    if (list) {
        for (size_t i = 0; i < list->size; ++i) {
            free(list->elements[i]);
        }
        free(list->elements);
        free(list);
    }
}

int add_NFAPDU(NFAPDUList* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (list->size >= list->capacity) {
        size_t newCapacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T** newElements = (NFAPI_CRC_INDICATION_PDU_T**)realloc(list->elements, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (!newElements) {
            log_error("Failed to reallocate memory for elements in NFAPDUList");
            return -1;
        }
        list->elements = newElements;
        list->capacity = newCapacity;
    }
    list->elements[list->size++] = pdu;
    return 0;
}

int ensure_unique_NFAPDU(NFAPDUList* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    for (size_t i = 0; i < list->size; ++i) {
        if (list->elements[i]->RNTI == pdu->RNTI) {
            log_warning("Duplicate RNTI detected, skipping insertion");
            return -1;
        }
    }
    return add_NFAPDU(list, pdu);
}

void populate_with_random_data(NFAPDUList* list, size_t N) {
    srand(time(NULL));
    for (size_t i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            log_error("Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T");
            break;
        }
        pdu->RX_UE_INFORMATION_TAG = generate_RX_UE_INFORMATION_TAG();
        pdu->RNTI = rand() % 65536; // Example RNTI generation
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2 == 0) ? NFAPI_CRC_INDICATION_PASS : NFAPI_CRC_INDICATION_FAIL;
        ensure_unique_NFAPDU(list, pdu);
    }
}
