int custom_checksum(void* data, size_t size) {
    // Implement a simple checksum function
    unsigned char* ptr = (unsigned char*)data;
    unsigned int sum = 0;
    for(size_t i = 0; i < size; i++) {
        sum += ptr[i];
    }
    return (int)(sum % 256);
}

NFAPI_CRC_INDICATION_PDU_T** generate_and_populate_pdus(int N) {
    NFAPI_CRC_INDICATION_PDU_T** pdus = NULL;
    int attempts = 0;

    while(attempts < MAX_ATTEMPTS) {
        pdus = (NFAPI_CRC_INDICATION_PDU_T**)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if(pdus == NULL) {
            attempts++;
            continue;
        }

        for(int i = 0; i < N; i++) {
            pdus[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if(pdus[i] == NULL) {
                for(int j = 0; j < i; j++) {
                    free(pdus[j]);
                }
                free(pdus);
                attempts++;
                break;
            }

            // Populate structure with unique values and random CRCFLAG
            pdus[i]->RX_UE_INFORMATION_TAG = i + 1;
            pdus[i]->RNTI = rand() % 65535; // Random RNTI between 0 and 65534
            pdus[i]->CRC_INDICATION_REL8_TAG = i * 2;
            pdus[i]->CRCFLAG = rand() % 2;

            // Custom checksum validation
            if(custom_checksum(pdus[i], sizeof(NFAPI_CRC_INDICATION_PDU_T)) != 0) {
                for(int j = 0; j <= i; j++) {
                    free(pdus[j]);
                }
                free(pdus);
                attempts++;
                break;
            }
        }

        if(attempts >= MAX_ATTEMPTS || pdus != NULL && *(pdus + N - 1) != NULL) {
            break;
        }
    }

    return pdus;
}
