#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ALLOCATION 1024

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

Node* queue[MAX_ALLOCATION];
int front = -1, rear = -1;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t not_full = PTHREAD_COND_INITIALIZER;
pthread_cond_t not_empty = PTHREAD_COND_INITIALIZER;

void enqueue(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&mutex);
    while ((rear + 1) % MAX_ALLOCATION == front) {
        pthread_cond_wait(&not_full, &mutex);
    }
    if (front == -1)
        front = rear = 0;
    else
        rear = (rear + 1) % MAX_ALLOCATION;
    queue[rear] = (Node*)malloc(sizeof(Node));
    queue[rear]->data = data;
    pthread_cond_signal(&not_empty);
    pthread_mutex_unlock(&mutex);
}

NFAPI_CRC_INDICATION_PDU_T dequeue() {
    pthread_mutex_lock(&mutex);
    while (front == -1) {
        pthread_cond_wait(&not_empty, &mutex);
    }
    NFAPI_CRC_INDICATION_PDU_T data = queue[front]->data;
    free(queue[front]);
    if (front == rear)
        front = rear = -1;
    else
        front = (front + 1) % MAX_ALLOCATION;
    pthread_cond_signal(&not_full);
    pthread_mutex_unlock(&mutex);
    return data;
}

int allocate_and_populate_array(int N, uint32_t max_rx_tag, uint16_t max_rnti) {
    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % max_rx_tag;
        pdu.RNTI = rand() % max_rnti;
        pdu.CRC_INDICATION_REL8_TAG = rand() & 1;

        enqueue(pdu);
    }
    return N;
}

int main() {
    srand(time(NULL));
    allocate_and_populate_array(5, 100, 256);

    for (int i = 0; i < 5; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu = dequeue();
        printf("Dequeued: RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRC_INDICATION_REL8_TAG=%d\n",
               pdu.RX_UE_INFORMATION_TAG, pdu.RNTI, pdu.CRC_INDICATION_REL8_TAG);
    }

    return 0;
}
