typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *items;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} ResizableList;

ResizableList* create_list(size_t initial_capacity) {
    ResizableList *list = malloc(sizeof(ResizableList));
    if (!list) return NULL;

    list->items = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->items) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void destroy_list(ResizableList *list) {
    pthread_mutex_lock(&list->mutex);
    free(list->items);
    pthread_mutex_unlock(&list->mutex);
    free(list);
}

bool resize_list(ResizableList *list, size_t new_capacity) {
    pthread_mutex_lock(&list->mutex);

    NFAPI_CRC_INDICATION_PDU_T *new_items = realloc(list->items, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_items) {
        pthread_mutex_unlock(&list->mutex);
        return false;
    }

    list->items = new_items;
    list->capacity = new_capacity;

    pthread_mutex_unlock(&list->mutex);
    return true;
}

bool add_item(ResizableList *list, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&list->mutex);

    if (list->size >= list->capacity && !resize_list(list, list->capacity * 2)) {
        pthread_mutex_unlock(&list->mutex);
        return false;
    }

    for (size_t i = 0; i < list->size; ++i) {
        if (list->items[i].RNTI == item.RNTI) {
            pthread_mutex_unlock(&list->mutex);
            return false; // Duplicate RNTI found, not adding
        }
    }

    list->items[list->size++] = item;

    pthread_mutex_unlock(&list->mutex);
    return true;
}

// Example usage:
int main() {
    ResizableList *list = create_list(10);
    if (!list) {
        // Handle error
        return 1;
    }

    NFAPI_CRC_INDICATION_PDU_T item = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 2, .CRC_INDICATION_REL8_TAG = true };
    if (!add_item(list, item)) {
        // Handle error
        destroy_list(list);
        return 1;
    }

    // Continue adding items as needed

    destroy_list(list);
    return 0;
}
