#include <stdlib.h>
#include <pthread.h>

typedef struct LTE_NAS_Message {
    uint32_t NAS_MME_ID;
    uint8_t NAS_PDU[1024];
    uint32_t NAS_Transaction_ID;
    struct LTE_NAS_Message* prev;
    struct LTE_NAS_Message* next;
} LTE_NAS_Message;

typedef struct {
    pthread_mutex_t lock;
    LTE_NAS_Message* head;
    LTE_NAS_Message* tail;
} DoublyLinkedList;

void init_list(DoublyLinkedList* list) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->tail = NULL;
}

int add_message_to_list(DoublyLinkedList* list, uint32_t NAS_MME_ID, const uint8_t* NAS_PDU, size_t pdu_size, uint32_t NAS_Transaction_ID) {
    pthread_mutex_lock(&list->lock);

    LTE_NAS_Message* new_message = (LTE_NAS_Message*)malloc(sizeof(LTE_NAS_Message));
    if (!new_message) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Out of memory
    }

    new_message->NAS_MME_ID = NAS_MME_ID;
    memcpy(new_message->NAS_PDU, NAS_PDU, pdu_size);
    new_message->NAS_Transaction_ID = NAS_Transaction_ID;
    new_message->prev = list->tail;
    new_message->next = NULL;

    if (list->tail) {
        list->tail->next = new_message;
    } else {
        list->head = new_message;
    }
    list->tail = new_message;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void free_list(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);

    LTE_NAS_Message* current = list->head;
    while (current) {
        LTE_NAS_Message* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->tail = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
