#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct ThreadSafeLinkedList {
    Node* head;
    pthread_mutex_t mutex;
    size_t size;
    size_t max_size;
} ThreadSafeLinkedList;

ThreadSafeLinkedList* create_thread_safe_linked_list(size_t max_size) {
    ThreadSafeLinkedList* list = (ThreadSafeLinkedList*)malloc(sizeof(ThreadSafeLinkedList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    list->size = 0;
    list->max_size = max_size;

    return list;
}

bool add_to_list(ThreadSafeLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list->size >= list->max_size) return false; // Check for size limit

    pthread_mutex_lock(&list->mutex);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return false;
    }

    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;
    pthread_mutex_unlock(&list->mutex);

    // Log addition
    printf("Added CRC indication with RNTI: %d\n", data.RNTI);
    return true;
}

void clear_list(ThreadSafeLinkedList* list) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->size = 0;
    pthread_mutex_unlock(&list->mutex);

    // Log clearing
    printf("Cleared the list\n");
}

void destroy_thread_safe_linked_list(ThreadSafeLinkedList* list) {
    clear_list(list);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}
