    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

// Function to insert a node into the linked list
void insertNode(Node** head, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = createNode(data);
    if (!newNode) return;

    // Insert in ascending order of RNTI
    if (*head == NULL || (*head)->data.RNTI > newNode->data.RNTI) {
        newNode->next = *head;
        *head = newNode;
    } else {
        Node* current = *head;
        while (current->next != NULL && current->next->data.RNTI < newNode->data.RNTI) {
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }
}

// Function to check for duplicate RNTI values
bool hasDuplicateRNTI(Node* head, int RNTI) {
    Node* current = head;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            return true;
        }
        current = current->next;
    }
    return false;
}

// Function to generate a random CRCFLAG
bool generateRandomCRCFLAG() {
    return rand() % 2 == 0; // Simplified for demonstration purposes
}

// Main function to manage the list of NFAPI_CRC_INDICATION_PDU_T structures
void manageNFAPIList(NFAPI_CRC_INDICATION_PDU_T* data, int size) {
    if (data == NULL || size <= 0) {
        fprintf(stderr, "Invalid input data\n");
        return;
    }

    Node* head = NULL;

    for (int i = 0; i < size; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu = data[i];
        if (!hasDuplicateRNTI(head, pdu.RNTI)) {
            pdu.CRCFLAG = generateRandomCRCFLAG();
            insertNode(&head, pdu);
        } else {
            fprintf(stderr, "Duplicate RNTI detected: %d\n", pdu.RNTI);
        }
    }

    // Print the sorted list (for demonstration purposes)
    Node* current = head;
    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n",
               current->data.RX_UE_INFORMATION_TAG,
               current->data.RNTI,
               current->data.CRCFLAG);
        current = current->next;
    }

    // Free the linked list memory
    while (head != NULL) {
        Node* temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    // Example usage
    NFAPI_CRC_INDICATION_PDU_T data[] = {
        {1, 10, false},
        {2, 20, false},
        {3, 15, false}
    };
    int size = sizeof(data) / sizeof(data[0]);
    manageNFAPIList(data, size);
    return 0;
}
