typedef struct {
    uint32_t ue_id;
    // Add other fields as per QoS settings
} LTE_UE_Context;

typedef struct {
    LTE_UE_Context *contexts;
    size_t capacity;
    size_t size;
} UE_List;

void initialize_ue_list(UE_List *list, size_t initial_capacity) {
    list->contexts = (LTE_UE_Context *)malloc(initial_capacity * sizeof(LTE_UE_Context));
    if (!list->contexts) {
        // Handle memory allocation failure
        list->capacity = 0;
        list->size = 0;
    } else {
        list->capacity = initial_capacity;
        list->size = 0;
    }
}

void destroy_ue_list(UE_List *list) {
    free(list->contexts);
    list->contexts = NULL;
    list->capacity = 0;
    list->size = 0;
}

bool add_ue_context(UE_List *list, LTE_UE_Context context) {
    if (list->size == list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        LTE_UE_Context *new_contexts = (LTE_UE_Context *)realloc(list->contexts, new_capacity * sizeof(LTE_UE_Context));
        if (!new_contexts) {
            // Handle memory allocation failure
            return false;
        }
        list->contexts = new_contexts;
        list->capacity = new_capacity;
    }
    list->contexts[list->size++] = context;
    return true;
}

bool remove_ue_context(UE_List *list, uint32_t ue_id) {
    for (size_t i = 0; i < list->size; ++i) {
        if (list->contexts[i].ue_id == ue_id) {
            // Shift elements to fill the gap
            for (size_t j = i + 1; j < list->size; ++j) {
                list->contexts[j - 1] = list->contexts[j];
            }
            --list->size;
            return true;
        }
    }
    return false;
}

void update_ue_context(UE_List *list, uint32_t ue_id, LTE_UE_Context new_context) {
    for (size_t i = 0; i < list->size; ++i) {
        if (list->contexts[i].ue_id == ue_id) {
            list->contexts[i] = new_context;
            return;
        }
    }
}

void iterate_ue_list(UE_List *list, void (*callback)(LTE_UE_Context *)) {
    for (size_t i = 0; i < list->size; ++i) {
        callback(&list->contexts[i]);
    }
}
