    for (size_t i = 0; i < array->size; i++) {
        free(array->packets[i]->payload);
        free(array->packets[i]);
    }
    free(array->packets);
    pthread_mutex_destroy(&array->lock);
}

void resize_packet_array(PacketArray *array) {
    size_t new_capacity = array->capacity * 2;
    DataPacket **new_packets = (DataPacket **)realloc(array->packets, new_capacity * sizeof(DataPacket *));
    if (new_packets == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->packets = new_packets;
    array->capacity = new_capacity;
}

