#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define the NetworkDevice struct
typedef struct {
    int device_id;
    char ip_address[16];
    // Add other statistics fields here
} NetworkDevice;

// Define the DevicePool struct
typedef struct {
    NetworkDevice *devices;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DevicePool;

// Initialize the device pool with default configurations
void init_device_pool(DevicePool *pool, size_t initial_capacity) {
    pool->devices = malloc(initial_capacity * sizeof(NetworkDevice));
    if (pool->devices == NULL) {
        perror("Failed to allocate memory for device pool");
        exit(EXIT_FAILURE);
    }
    pool->capacity = initial_capacity;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

// Add a new network device to the pool
void add_device(DevicePool *pool, NetworkDevice device) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count >= pool->capacity) {
        // Double the capacity and reallocate memory
        size_t new_capacity = pool->capacity * 2;
        NetworkDevice *new_devices = realloc(pool->devices, new_capacity * sizeof(NetworkDevice));
        if (new_devices == NULL) {
            perror("Failed to allocate more memory for device pool");
            pthread_mutex_unlock(&pool->lock);
            exit(EXIT_FAILURE);
        }
        pool->devices = new_devices;
        pool->capacity = new_capacity;
    }
    pool->devices[pool->count] = device;
    pool->count++;
    pthread_mutex_unlock(&pool->lock);
}

// Update an existing network device in the pool
void update_device(DevicePool *pool, int device_id, NetworkDevice new_device) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->count; i++) {
        if (pool->devices[i].device_id == device_id) {
            pool->devices[i] = new_device;
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

// Delete a network device from the pool
void delete_device(DevicePool *pool, int device_id) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->count; i++) {
        if (pool->devices[i].device_id == device_id) {
            // Shift elements to fill the gap
            for (size_t j = i; j < pool->count - 1; j++) {
                pool->devices[j] = pool->devices[j + 1];
            }
            pool->count--;
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

// Cleanup the device pool
void cleanup_device_pool(DevicePool *pool) {
    pthread_mutex_lock(&pool->lock);
    free(pool->devices);
    pool->devices = NULL;
    pool->capacity = 0;
    pool->count = 0;
    pthread_mutex_destroy(&pool->lock);
}
```

This code defines a basic structure for managing a dynamic pool of network device configurations. It includes functions to initialize, add, update, and delete devices in the pool, as well as cleanup resources when done. The use of mutexes ensures thread safety during concurrent access and modification of the pool.']

