void log_crc_creation(int count) {
    FILE *log_file = fopen("crc_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open crc_log.txt for writing");
        return;
    }
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);
    fprintf(log_file, "Successfully created %d structures.\n", count);
    fclose(log_file);
    pthread_mutex_unlock(&lock);
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_indications(int N, int *override_crcflag) {
    if (N <= 0 || N > MAX_ENTRIES) {
        fprintf(stderr, "Invalid number of entries requested.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *indicators = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (indicators == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < N; i++) {
        indicators[i].RX_UE_INFORMATION_TAG = rand();
        indicators[i].RNTI = rand() % 1024; // Assuming RNTI is a 10-bit value
        indicators[i].CRC_INDICATION_REL8_TAG = rand();

        if (override_crcflag != NULL) {
            indicators[i].CRCFLAG = *override_crcflag;
        } else {
