#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RNTI;
    time_t timestamp;
    uint32_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list;
    size_t count;
    pthread_mutex_t mutex;
} CRC_List;

CRC_List* create_crc_list(size_t initial_size) {
    CRC_List *crc_list = (CRC_List*) malloc(sizeof(CRC_List));
    if (!crc_list) return NULL;

    crc_list->count = 0;
    crc_list->list = (NFAPI_CRC_INDICATION_PDU_T*) realloc(crc_list->list, initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_list->list) {
        free(crc_list);
        return NULL;
    }

    pthread_mutex_init(&crc_list->mutex, NULL);
    return crc_list;
}

void destroy_crc_list(CRC_List *crc_list) {
    pthread_mutex_destroy(&crc_list->mutex);
    free(crc_list->list);
    free(crc_list);
}

void add_crc_indication(CRC_List *crc_list, NFAPI_CRC_INDICATION_PDU_T *indication) {
    pthread_mutex_lock(&crc_list->mutex);

    if (crc_list->count == 0 || crc_list->count % 100 == 0) {
        crc_list->list = (NFAPI_CRC_INDICATION_PDU_T*) realloc(crc_list->list, (crc_list->count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!crc_list->list) {
            pthread_mutex_unlock(&crc_list->mutex);
            return;
        }
    }

    crc_list->list[crc_list->count++] = *indication;

    pthread_mutex_unlock(&crc_list->mutex);
}

void* simulate_crc_indications(void *arg) {
    CRC_List *crc_list = (CRC_List*) arg;

    NFAPI_CRC_INDICATION_PDU_T indication;
    for (int i = 0; i < 100; ++i) {
        indication.RNTI = rand() % 65536; // Random RNTI
        time(&indication.timestamp);
        indication.CRCFLAG = rand(); // Random CRCFLAG

        add_crc_indication(crc_list, &indication);

        usleep(1000); // Simulate varying packet sizes and delays
    }

    return NULL;
}

int main() {
    CRC_List *crc_list = create_crc_list(100);
    if (!crc_list) return 1;

    pthread_t threads[10];
    for (int i = 0; i < 10; ++i) {
        if (pthread_create(&threads[i], NULL, simulate_crc_indications, crc_list)) {
            destroy_crc_list(crc_list);
            return 1;
        }
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_crc_list(crc_list);

    return 0;
