#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_CONNECTIONS 100000
#define DEFAULT_TIMEOUT 600 // 10 minutes in seconds

typedef struct {
    int id;
    char remote_ip[INET_ADDRSTRLEN];
    char local_ip[INET_ADDRSTRLEN];
    int remote_port;
    int local_port;
    time_t last_activity;
    size_t byte_count;
} TCP_ConnectionState;

TCP_ConnectionState *connection_pool = NULL;
size_t pool_size = 0;
time_t timeout;

void init_connection_pool(size_t max_connections) {
    connection_pool = (TCP_ConnectionState *)malloc(max_connections * sizeof(TCP_ConnectionState));
    if (!connection_pool) {
        fprintf(stderr, "Failed to allocate memory for connection pool.\n");
        exit(EXIT_FAILURE);
    }
    pool_size = max_connections;
}

void destroy_connection_pool() {
    free(connection_pool);
}

int allocate_connection(int id, const char *remote_ip, const char *local_ip, int remote_port, int local_port) {
    if (id < 0 || id >= pool_size) {
        fprintf(stderr, "Invalid connection ID.\n");
        return -1;
    }
    TCP_ConnectionState *conn = &connection_pool[id];
    conn->id = id;
    strcpy(conn->remote_ip, remote_ip);
    strcpy(conn->local_ip, local_ip);
    conn->remote_port = remote_port;
    conn->local_port = local_port;
    conn->last_activity = time(NULL);
    conn->byte_count = 0;
    return 0;
}

void deallocate_connection(int id) {
    if (id < 0 || id >= pool_size) {
        fprintf(stderr, "Invalid connection ID.\n");
        return;
    }
    // Reset the connection state
    memset(&connection_pool[id], 0, sizeof(TCP_ConnectionState));
}

void update_connection_activity(int id) {
    if (id < 0 || id >= pool_size) {
        fprintf(stderr, "Invalid connection ID.\n");
        return;
    }
    connection_pool[id].last_activity = time(NULL);
}

int is_connection_stale(int id) {
    if (id < 0 || id >= pool_size) {
        fprintf(stderr, "Invalid connection ID.\n");
        return -1;
    }
    TCP_ConnectionState *conn = &connection_pool[id];
    return difftime(time(NULL), conn->last_activity) > timeout;
}

void detect_and_recover_stale_connections() {
    for (size_t i = 0; i < pool_size; ++i) {
        if (is_connection_stale(i)) {
            deallocate_connection(i);
        }
    }
}

// Example usage
int main() {
    init_connection_pool(MAX_CONNECTIONS);
    setenv("CONNECTION_TIMEOUT", "600", 1); // Set timeout from environment variable
    timeout = atoi(getenv("CONNECTION_TIMEOUT"));

    allocate_connection(0, "192.168.1.1", "192.168.1.2", 80, 8080);
    update_connection_activity(0);

    detect_and_recover_stale_connections();

    destroy_connection_pool();
    return 0;
}
