typedef struct {
    Node* head;
    pthread_mutex_t mutex;
    int max_active_ues;
    int current_active_ues;
} UE_Collection;

UE_Collection* create_collection(int max_active_ues) {
    UE_Collection* collection = (UE_Collection*)malloc(sizeof(UE_Collection));
    if (!collection) return NULL;

    collection->head = NULL;
    pthread_mutex_init(&collection->mutex, NULL);
    collection->max_active_ues = max_active_ues;
    collection->current_active_ues = 0;

    return collection;
}

void destroy_collection(UE_Collection* collection) {
    Node* current = collection->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}

int add_packet(UE_Collection* collection, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&collection->mutex);

    if (collection->current_active_ues >= collection->max_active_ues) {
        pthread_mutex_unlock(&collection->mutex);
        return -1; // Resource exhaustion
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&collection->mutex);
        return -2; // Memory allocation failure
    }
    new_node->pdu = pdu;
    new_node->next = collection->head;
    collection->head = new_node;
    collection->current_active_ues++;

    pthread_mutex_unlock(&collection->mutex);
    return 0;
}

void* process_packets(void* arg) {
    UE_Collection* collection = (UE_Collection*)arg;

    while (1) {
        pthread_mutex_lock(&collection->mutex);

        if (!collection->head) {
            pthread_mutex_unlock(&collection->mutex);
            sleep(1); // Wait for packets
            continue;
        }

        Node* current = collection->head;
        collection->head = current->next;
        collection->current_active_ues--;

        pthread_mutex_unlock(&collection->mutex);

        // Process packet: Implement prioritization and CRC quality check
        // Example:
        if (current->pdu.crcflag == 0) {
            // Handle CRC error
        } else {
            // Process valid packet
        }

        free(current);
    }

    return NULL;
}

int main() {
    UE_Collection* collection = create_collection(100);
    if (!collection) {
        perror("Failed to create collection");
        return 1;
    }

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, process_packets, collection) != 0) {
        perror("Failed to create processing thread");
        destroy_collection(collection);
        return 1;
