typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
    char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct PDU_List_T {
    NFAPI_CRC_INDICATION_PDU_T** PDUs;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} PDU_List_T;

void init_pdu_list(PDU_List_T* list, size_t initial_capacity) {
    list->PDUs = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->mutex, NULL);
}

void free_pdu_list(PDU_List_T* list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->PDUs[i]);
    }
    free(list->PDUs);
    pthread_mutex_destroy(&list->mutex);
}

int add_pdu_to_list(PDU_List_T* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list->mutex);
    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T** new_pdus = realloc(list->PDUs, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (!new_pdus) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Memory allocation failed
        }
        list->PDUs = new_pdus;
        list->capacity = new_capacity;
    }
    list->PDUs[list->count++] = pdu;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(int RX_UE_INFORMATION_TAG, unsigned short RNTI) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        return NULL; // Memory allocation failed
    }
    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    // Set CRCFLAG using the proprietary binary module function
    pdu->CRCFLAG = generate_secure_random_number(2); // Example function call
    return pdu;
}

void process_pdu_list(PDU_List_T* list) {
    for (size_t i = 0; i < list->count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = list->PDUs[i];
        if (pdu->RX_UE_INFORMATION_TAG < 0 || pdu->RX_UE_INFORMATION_TAG > MAX_RX_UE_INFORMATION_TAG ||
            pdu->RNTI < MIN_RNTI || pdu->RNTI > MAX_RNTI) {
            // Log error and handle gracefully
            continue;
        }
        if (pdu->CRC_INDICATION_REL8_TAG != RX_UE_INFORMATION_TAG || pdu->CRCFLAG != 0) {
            // Log warning and skip processing for this PDU
            continue;
        }
        // Process the PDU using the proprietary binary module function
        verify_crc_indication(pdu); // Example function call
    }
}

int main() {
    PDU_List_T pdu_list;
    init_pdu_list(&pdu_list, 10);

    // Producer thread code
