#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct LTE_RRC_SRB1_MESSAGE_T {
    int SRB_ID;
    int MME_CODE;
    // Other fields...
} LTE_RRC_SRB1_MESSAGE_T;

typedef struct DynamicArray {
    LTE_RRC_SRB1_MESSAGE_T** messages;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* dynamic_array_init() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (array == NULL) {
        return NULL;
    }
    array->messages = NULL;
    array->size = 0;
    array->capacity = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void dynamic_array_free(DynamicArray* array) {
    if (array != NULL) {
        for (size_t i = 0; i < array->size; ++i) {
            free(array->messages[i]);
        }
        free(array->messages);
        pthread_mutex_destroy(&array->mutex);
        free(array);
    }
}

int dynamic_array_add(DynamicArray* array, LTE_RRC_SRB1_MESSAGE_T* message) {
    if (array == NULL || message == NULL) {
        return -1;
    }

    pthread_mutex_lock(&array->mutex);

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity == 0 ? 1 : array->capacity * 2;
        LTE_RRC_SRB1_MESSAGE_T** new_messages = (LTE_RRC_SRB1_MESSAGE_T**)realloc(array->messages, new_capacity * sizeof(LTE_RRC_SRB1_MESSAGE_T*));
        if (new_messages == NULL) {
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
        array->messages = new_messages;
        array->capacity = new_capacity;
    }

    array->messages[array->size++] = message;

    pthread_mutex_unlock(&array->mutex);

    return 0;
}

LTE_RRC_SRB1_MESSAGE_T* dynamic_array_update(DynamicArray* array, int SRB_ID, LTE_RRC_SRB1_MESSAGE_T* new_message) {
    if (array == NULL || new_message == NULL) {
        return NULL;
    }

    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->size; ++i) {
        if (array->messages[i]->SRB_ID == SRB_ID) {
            LTE_RRC_SRB1_MESSAGE_T* old_message = array->messages[i];
            array->messages[i] = new_message;
            pthread_mutex_unlock(&array->mutex);
            return old_message;
        }
    }

    pthread_mutex_unlock(&array->mutex);

    return NULL;
}

int dynamic_array_remove(DynamicArray* array, int SRB_ID) {
    if (array == NULL) {
        return -1;
    }

    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->size; ++i) {
        if (array->messages[i]->SRB_ID == SRB_ID) {
            free(array->messages[i]);
            for (size_t j = i; j < array->size - 1; ++j) {
                array->messages[j] = array->messages[j + 1];
            }
            array->size--;
            pthread_mutex_unlock(&array->mutex);
            return 0;
        }
    }

    pthread_mutex_unlock(&array->mutex);

    return -1;
}

void dynamic_array_serialize(DynamicArray* array, const char* filename) {
    if (array == NULL || filename == NULL) {
        return;
    }

    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        return;
    }

    fwrite(&array->size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < array->size; ++i) {
        fwrite(array->messages[i], sizeof(LTE_RRC_SRB1_MESSAGE_T), 1, file);
    }

    fclose(file);
}

int dynamic_array_deserialize(DynamicArray* array, const char* filename) {
    if (array == NULL || filename == NULL) {
        return -1;
    }

    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        return -1;
    }

    size_t size;
    fread(&size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < size; ++i) {
        LTE_RRC_SRB1_MESSAGE_T* message = (LTE_RRC_SRB1_MESSAGE_T*)malloc(sizeof(LTE_RRC_SRB1_MESSAGE_T));
        if (message == NULL) {
            fclose(file);
            return -1;
        }
        fread(message, sizeof(LTE_RRC_SRB1_MESSAGE_T), 1, file);
        dynamic_array_add(array, message);
    }

    fclose(file);

    return 0;
}
