#define MAX_MESSAGES 1000

typedef struct {
    time_t timestamp;
    int id;
    char *payload;
} Message;

typedef struct {
    Message messages[MAX_MESSAGES];
    int count;
    pthread_mutex_t mutex;
} MessageQueue;

MessageQueue message_queue = { .count = 0, .mutex = PTHREAD_MUTEX_INITIALIZER };

void add_message(int id, const char *payload) {
    pthread_mutex_lock(&message_queue.mutex);
    if (message_queue.count < MAX_MESSAGES) {
        Message new_msg = {
            .timestamp = time(NULL),
            .id = id,
            .payload = strdup(payload)
        };
        message_queue.messages[message_queue.count++] = new_msg;
    }
    pthread_mutex_unlock(&message_queue.mutex);
}

Message* get_message(int id) {
    pthread_mutex_lock(&message_queue.mutex);
    for (int i = 0; i < message_queue.count; i++) {
        if (message_queue.messages[i].id == id) {
            pthread_mutex_unlock(&message_queue.mutex);
            return &message_queue.messages[i];
        }
    }
    pthread_mutex_unlock(&message_queue.mutex);
    return NULL;
}

void remove_message(int id) {
    pthread_mutex_lock(&message_queue.mutex);
    for (int i = 0; i < message_queue.count; i++) {
        if (message_queue.messages[i].id == id) {
            free(message_queue.messages[i].payload);
            for (int j = i; j < message_queue.count - 1; j++) {
                message_queue.messages[j] = message_queue.messages[j + 1];
            }
            message_queue.count--;
            pthread_mutex_unlock(&message_queue.mutex);
            return;
        }
    }
    pthread_mutex_unlock(&message_queue.mutex);
}

void *update_thread(void *arg) {
    while (1) {
        // Simulate external data source update
        sleep(5); // Periodic check every 5 seconds

        pthread_mutex_lock(&message_queue.mutex);
        for (int i = 0; i < message_queue.count; i++) {
            // Update logic here
            printf("Updating message with ID: %d\n", message_queue.messages[i].id);
        }
        pthread_mutex_unlock(&message_queue.mutex);
    }
    return NULL;
}

int main() {
    pthread_t update_tid;

    if (pthread_create(&update_tid, NULL, update_thread, NULL) != 0) {
        perror("Failed to create update thread");
        return EXIT_FAILURE;
    }

    add_message(1, "Hello, World!");
    add_message(2, "This is a test message.");

    Message *msg = get_message(1);
    if (msg) {
        printf("Retrieved message with ID %d: %s\n", msg->id, msg->payload);
    }

    remove_message(1);

    pthread_join(update_tid, NULL);
    return EXIT_SUCCESS;
}
