    NAS_PDU_TYPE_2,
    // Add more types as needed
} NAS_MESSAGE_TYPE_TAG;

typedef struct LTE_RRC_NotifyMsg {
    NAS_MESSAGE_TYPE_TAG type;
    uint8_t NAS_PDU[1024]; // Assuming max PDU size of 1024 bytes
    int RRC_Procedure_ID;
    // Add other fields as needed
} LTE_RRC_NotifyMsg;

typedef struct MessageQueue {
    LTE_RRC_NotifyMsg messages[MAX_MESSAGES];
    int front, rear;
    int count;
} MessageQueue;

void initMessageQueue(MessageQueue *queue) {
    queue->front = 0;
    queue->rear = -1;
    queue->count = 0;
}

int isEmpty(MessageQueue *queue) {
    return queue->count == 0;
}

int isFull(MessageQueue *queue) {
    return queue->count == MAX_MESSAGES;
}

void enqueueMessage(MessageQueue *queue, LTE_RRC_NotifyMsg message) {
    if (isFull(queue)) {
        fprintf(stderr, "Error: Queue is full\n");
        return;
    }
    queue->rear = (queue->rear + 1) % MAX_MESSAGES;
    queue->messages[queue->rear] = message;
    queue->count++;
}

LTE_RRC_NotifyMsg dequeueMessage(MessageQueue *queue) {
    if (isEmpty(queue)) {
        fprintf(stderr, "Error: Queue is empty\n");
        LTE_RRC_NotifyMsg emptyMessage = {0};
        return emptyMessage;
    }
    LTE_RRC_NotifyMsg message = queue->messages[queue->front];
    queue->front = (queue->front + 1) % MAX_MESSAGES;
    queue->count--;
    return message;
}

int findMessageByRRCProcID(MessageQueue *queue, int RRC_Procedure_ID) {
    for (int i = queue->front; i != (queue->rear + 1) % MAX_MESSAGES; i = (i + 1) % MAX_MESSAGES) {
        if (queue->messages[i].RRC_Procedure_ID == RRC_Procedure_ID) {
            return i;
        }
    }
    return -1;
}

void removeMessageByRRCProcID(MessageQueue *queue, int RRC_Procedure_ID) {
    int index = findMessageByRRCProcID(queue, RRC_Procedure_ID);
    if (index != -1) {
        for (int i = index; i != (queue->rear + 1) % MAX_MESSAGES; i = (i + 1) % MAX_MESSAGES) {
            queue->messages[i] = queue->messages[(i + 1) % MAX_MESSAGES];
        }
        queue->rear--;
        queue->count--;
    } else {
        fprintf(stderr, "Error: Message with RRC_Procedure_ID %d not found\n", RRC_Procedure_ID);
    }
}

int checkMessageTypeInQueue(MessageQueue *queue, NAS_MESSAGE_TYPE_TAG type) {
    for (int i = queue->front; i != (queue->rear + 1) % MAX_MESSAGES; i = (i + 1) % MAX_MESSAGES) {
        if (queue->messages[i].type == type) {
            return 1;
        }
    }
    return 0;
}
