#include <pthread.h>
#include <time.h>

#define MAX_PDUS 1000
#define THRESHOLD 90

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *pdu_list = NULL;
int current_size = 0;
int max_size = MAX_PDUS;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* allocate_memory(void* arg) {
    int n = *(int*)arg;
    pthread_mutex_lock(&mutex);
    if (current_size + n > max_size) {
        // Reallocate memory
        NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(pdu_list, (max_size + n) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_list == NULL) {
            printf("Memory reallocation failed\n");
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
        pdu_list = new_list;
        max_size += n;
    }
    for (int i = 0; i < n; i++) {
        pdu_list[current_size + i].RX_UE_INFORMATION_TAG = rand() % 100;
        pdu_list[current_size + i].RNTI = rand() % 100;
        pdu_list[current_size + i].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
        time(&pdu_list[current_size + i].timestamp);
    }
    current_size += n;
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void monitor_memory_usage() {
    double usage = (double)current_size / max_size * 100;
    if (usage > THRESHOLD) {
        printf("Memory usage is at %.2f%%. Consider reallocating memory.\n", usage);
    }
}

int main() {
    int num_pdus = 500;
    srand(time(NULL));

    // Initialize the PDU list
    pdu_list = malloc(max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu_list == NULL) {
        printf("Memory allocation failed\n");
        return 1;
    }

    // Allocate memory for PDUs
    pthread_t thread;
    int result = pthread_create(&thread, NULL, allocate_memory, &num_pdus);
    if (result != 0) {
        printf("Thread creation failed\n");
        free(pdu_list);
        return 1;
    }
    pthread_join(thread, NULL);

    // Monitor memory usage
    monitor_memory_usage();

    // Free the allocated memory
    free(pdu_list);

    return 0;
}
