#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the structure for CRC indication PDU
typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    unsigned char crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a hash table entry
typedef struct {
    RNTI key;
    NFAPI_CRC_INDICATION_PDU_T value;
    struct HashTableEntry *next;
} HashTableEntry;

// Define the hash table structure
typedef struct {
    HashTableEntry **buckets;
    size_t size;
} HashTable;

// Initialize the hash table
HashTable* hash_table_init(size_t size) {
    HashTable *ht = (HashTable*)malloc(sizeof(HashTable));
    ht->buckets = (HashTableEntry**)calloc(size, sizeof(HashTableEntry*));
    ht->size = size;
    return ht;
}

// Hash function to determine bucket index
size_t hash_function(RNTI key, size_t size) {
    return key % size;
}

// Insert or update an entry in the hash table
void hash_table_put(HashTable *ht, RNTI key, NFAPI_CRC_INDICATION_PDU_T value) {
    size_t index = hash_function(key, ht->size);
    HashTableEntry *entry = ht->buckets[index];

    while (entry != NULL) {
        if (entry->key == key) {
            entry->value = value;
            return;
        }
        entry = entry->next;
    }

    entry = (HashTableEntry*)malloc(sizeof(HashTableEntry));
    entry->key = key;
    entry->value = value;
    entry->next = ht->buckets[index];
    ht->buckets[index] = entry;
}

// Retrieve an entry from the hash table
NFAPI_CRC_INDICATION_PDU_T* hash_table_get(HashTable *ht, RNTI key) {
    size_t index = hash_function(key, ht->size);
    HashTableEntry *entry = ht->buckets[index];

    while (entry != NULL) {
        if (entry->key == key) {
            return &(entry->value);
        }
        entry = entry->next;
    }

    return NULL;
}

// Remove an entry from the hash table
void hash_table_remove(HashTable *ht, RNTI key) {
    size_t index = hash_function(key, ht->size);
    HashTableEntry *entry = ht->buckets[index];
    HashTableEntry *prev = NULL;

    while (entry != NULL) {
        if (entry->key == key) {
            if (prev == NULL) {
                ht->buckets[index] = entry->next;
            } else {
                prev->next = entry->next;
            }
            free(entry);
            return;
        }
        prev = entry;
        entry = entry->next;
    }
}

// Iterate over the hash table and print each entry
void hash_table_print(HashTable *ht) {
    for (size_t i = 0; i < ht->size; i++) {
        HashTableEntry *entry = ht->buckets[i];
        while (entry != NULL) {
            printf("RNTI: %d, CRCFLAG: %d\n", entry->value.rnti, entry->value.crcflag);
            entry = entry->next;
        }
    }
}

// Free the memory allocated for the hash table
void hash_table_free(HashTable *ht) {
    for (size_t i = 0; i < ht->size; i++) {
        HashTableEntry *entry = ht->buckets[i];
        while (entry != NULL) {
            HashTableEntry *next = entry->next;
            free(entry);
            entry = next;
        }
    }
    free(ht->buckets);
    free(ht);
}

int main() {
    // Example usage
    HashTable *ht = hash_table_init(100);

    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.rnti = 12345;
    pdu.crcflag = 1;
    hash_table_put(ht, 12345, pdu);

    NFAPI_CRC_INDICATION_PDU_T *retrieved_pdu = hash_table_get(ht, 12345);
    if (retrieved_pdu != NULL) {
        printf("Retrieved CRCFLAG: %d\n", retrieved_pdu->crcflag);
    }

    hash_table_remove(ht, 12345);
    hash_table_print(ht);

    hash_table_free(ht);

    return 0;
}
