typedef struct {
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} DynamicArray;

void initDynamicArray(DynamicArray *da, size_t initialCapacity) {
    da->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        perror("Failed to allocate memory for dynamic array");
        exit(EXIT_FAILURE);
    }
    da->capacity = initialCapacity;
    da->count = 0;
    pthread_mutex_init(&da->mutex, NULL);
}

void freeDynamicArray(DynamicArray *da) {
    pthread_mutex_lock(&da->mutex);
    if (da->array) {
        free(da->array);
        da->array = NULL;
    }
    da->capacity = 0;
    da->count = 0;
    pthread_mutex_unlock(&da->mutex);
    pthread_mutex_destroy(&da->mutex);
}

void populateDynamicArray(DynamicArray *da, void (*allocateMemory)(size_t), void (*freeMemory)(void *)) {
    pthread_mutex_lock(&da->mutex);
    for (size_t i = 0; i < da->capacity; ++i) {
        if (i == 0 || da->array[i - 1].CRCFLAG != rand() % 2) { // Ensure no two consecutive CRCFLAGS are the same
            da->array[i].CRCFLAG = rand() % 2;
        } else {
            --i; // Retry to ensure randomness
        }
    }
    pthread_mutex_unlock(&da->mutex);
}

void addElementToDynamicArray(DynamicArray *da, void (*allocateMemory)(size_t), void (*freeMemory)(void *)) {
    pthread_mutex_lock(&da->mutex);
    if (da->count < da->capacity) {
        populateDynamicArray(da, allocateMemory, freeMemory);
        ++da->count;
    } else {
        printf("Dynamic array is at capacity\n");
    }
    pthread_mutex_unlock(&da->mutex);
}

void iterateForwardDynamicArray(DynamicArray *da) {
    for (size_t i = 0; i < da->count; ++i) {
        printf("CRCFLAG: %d\n", da->array[i].CRCFLAG);
    }
}

void iterateBackwardDynamicArray(DynamicArray *da) {
    for (ssize_t i = da->count - 1; i >= 0; --i) {
        printf("CRCFLAG: %d\n", da->array[i].CRCFLAG);
    }
}

void clearDynamicArray(DynamicArray *da, void (*freeMemory)(void *)) {
    pthread_mutex_lock(&da->mutex);
    for (size_t i = 0; i < da->count; ++i) {
        freeMemory(da->array + i); // Custom memory deallocation if needed
    }
    da->count = 0;
    pthread_mutex_unlock(&da->mutex);
}
