} NFAPI_CRC_INDICATION_PDU_T;

// Function to initialize a single NFAPI_CRC_INDICATION_PDU_T structure
void init_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->RX_UE_INFORMATION_TAG = rand();
    pdu->RNTI = rand() % 4096; // Simulating RNTI values between 0 and 4095
    pdu->CRC_INDICATION_REL8_TAG = 1;
    pdu->CRCFLAG = rand() % 2; // Randomly setting CRCFLAG to 0 or 1
}

// Function to populate an array of NFAPI_CRC_INDICATION_PDU_T structures
void populate_pdus(NFAPI_CRC_INDICATION_PDU_T **pdus, int N) {
    *pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*pdus == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    for (int i = 0; i < N; i++) {
        init_pdu(&(*pdus)[i]);
    }
}

// Function to print detailed information about each entry in the array
void print_pdus(NFAPI_CRC_INDICATION_PDU_T *pdus, int N) {
    for (int i = 0; i < N; i++) {
        printf("Entry %d:\n", i);
        printf("RX_UE_INFORMATION_TAG: %u\n", pdus[i].RX_UE_INFORMATION_TAG);
        printf("RNTI: %u\n", pdus[i].RNTI);
        printf("CRC_INDICATION_REL8_TAG: %u\n", pdus[i].CRC_INDICATION_REL8_TAG);
        printf("CRCFLAG: %d\n", pdus[i].CRCFLAG);
    }
}

// Function to free the dynamically allocated memory
void free_pdus(NFAPI_CRC_INDICATION_PDU_T *pdus) {
    free(pdus);
}

