#include <stdlib.h>
#include <pthread.h>
#include <stdio.h>

#define MAX_ELEMENTS 10000

typedef struct {
    // Define your NFAPI_CRC_INDICATION_PDU_T structure here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
} List;

void initializeList(List* list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

int addElement(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        perror("Failed to allocate memory for new node");
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    newNode->data = data;
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int removeElement(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    Node* previous = NULL;
    while (current != NULL) {
        if (current->data == data) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    return -1;
}

void destroyList(List* list) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}
