typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} NFAPI_CRC_ARRAY;

NFAPI_CRC_ARRAY* nfa_crc_array_create(size_t initial_capacity) {
    NFAPI_CRC_ARRAY *array = (NFAPI_CRC_ARRAY*)malloc(sizeof(NFAPI_CRC_ARRAY));
    if (!array) return NULL;

    array->size = 0;
    array->capacity = initial_capacity;
    array->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        free(array);
        return NULL;
    }

    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void nfa_crc_array_destroy(NFAPI_CRC_ARRAY *array) {
    if (array) {
        pthread_mutex_lock(&array->lock);
        free(array->array);
        pthread_mutex_unlock(&array->lock);
        pthread_mutex_destroy(&array->lock);
        free(array);
    }
}

int nfa_crc_array_append(NFAPI_CRC_ARRAY *array, NFAPI_CRC_INDICATION_PDU_T item) {
    if (!array) return -1;

    pthread_mutex_lock(&array->lock);
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
        array->array = new_array;
        array->capacity = new_capacity;
    }
    array->array[array->size++] = item;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* nfa_crc_array_get(NFAPI_CRC_ARRAY *array, size_t index) {
    if (!array || index >= array->size) return NULL;

    pthread_mutex_lock(&array->lock);
    NFAPI_CRC_INDICATION_PDU_T *item = &array->array[index];
    pthread_mutex_unlock(&array->lock);
    return item;
}

int nfa_crc_array_set(NFAPI_CRC_ARRAY *array, size_t index, NFAPI_CRC_INDICATION_PDU_T new_item) {
    if (!array || index >= array->size) return -1;

    pthread_mutex_lock(&array->lock);
    array->array[index] = new_item;
    pthread_mutex_unlock(&array->lock);
    return 0;
}
