        if (array[i] == NULL) {
            perror("Error: Memory allocation failed for individual structure.");
            // Free previously allocated structures
            for (int j = 0; j < i; j++) {
                free(array[j]);
            }
            free(array);
            pthread_mutex_destroy(&mutex);
            return NULL;
