        // Lock for thread safety during initialization
        pthread_mutex_lock(&mutex);
        // Perform any additional initialization or caching strategies here
        pthread_mutex_unlock(&mutex);
    }

    // Initialize mutex for future access patterns
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void free_array(NFAPI_CRC_INDICATION_PDU_T** array, int num_elements) {
    if (array != NULL) {
        for (int i = 0; i < num_elements; i++) {
            if (array[i] != NULL) {
                free(array[i]);
            }
        }
        free(array);
    }

    // Destroy mutex
    pthread_mutex_destroy(&array->mutex);
}
